{
  "name": "BakeMate - Smart Bakery Manager",
  "description": "A comprehensive management system for bakeries to track sales, inventory, expenses, and get AI-powered business insights using Gemini."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  stock: number;
}

export interface Sale {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  totalPrice: number;
  date: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  category: 'Raw Material' | 'Utilities' | 'Rent' | 'Staff' | 'Other';
  date: string;
}

export enum View {
  DASHBOARD = 'DASHBOARD',
  SALES = 'SALES',
  INVENTORY = 'INVENTORY',
  EXPENSES = 'EXPENSES',
  AI_INSIGHTS = 'AI_INSIGHTS'
}

import { GoogleGenAI } from "@google/genai";
import { Product, Sale, Expense } from "../types";

export const getBusinessInsights = async (
  products: Product[],
  sales: Sale[],
  expenses: Expense[]
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const totalSales = sales.reduce((acc, s) => acc + s.totalPrice, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalSales - totalExpenses;

  const prompt = `
    As a professional bakery business consultant, analyze the following data for my bakery called "BakeMate".

    Data Summary:
    - Total Products: ${products.length}
    - Total Sales Revenue: ৳${totalSales}
    - Total Expenses: ৳${totalExpenses}
    - Net Profit/Loss: ৳${profit}

    Products: ${JSON.stringify(products)}
    Recent Sales History: ${JSON.stringify(sales.slice(-10))}
    Recent Expenses: ${JSON.stringify(expenses.slice(-10))}

    Please provide:
    1. A summary of current performance.
    2. Top 3 recommendations to increase profit.
    3. Warning if expenses are too high or stock is low.
    4. A prediction for the next month.

    Answer in a friendly tone. Use Bengali for the advice if possible, as the user is a Bengali speaker, but use English for technical terms.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.7,
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Insight Error:", error);
    return "Could not generate insights at this time. Please check your data or try again later.";
  }
};

import React, { useState, useEffect } from 'react';
import { Product, Sale, Expense, View } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import AIInsights from './components/AIInsights';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Sparkles,
  UtensilsCrossed
} from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);

  // Persistence using LocalStorage
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Milk Bread', category: 'Bread', price: 60, stock: 20 },
      { id: '2', name: 'Chocolate Cake', category: 'Cake', price: 450, stock: 5 },
      { id: '3', name: 'Butter Cookies', category: 'Cookies', price: 120, stock: 50 },
    ];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('expenses');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('sales', JSON.stringify(sales));
  }, [sales]);

  useEffect(() => {
    localStorage.setItem('expenses', JSON.stringify(expenses));
  }, [expenses]);

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    // Deduct from inventory
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'ইনভেন্টরি' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.AI_INSIGHTS, label: 'AI Insights', icon: <Sparkles size={20} />, bangla: 'এআই পরামর্শ' },
  ];

  return (
    <div className="min-h-screen flex bg-slate-50">
      {/* Sidebar */}
      <aside className="w-64 bg-orange-800 text-white flex flex-col fixed h-full shadow-xl">
        <div className="p-6 flex items-center gap-3 border-b border-orange-700">
          <UtensilsCrossed className="text-orange-300" />
          <h1 className="text-2xl font-bold tracking-tight">BakeMate</h1>
        </div>

        <nav className="flex-1 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-6 py-4 transition-colors ${
                currentView === item.id 
                  ? 'bg-orange-700 border-r-4 border-orange-300' 
                  : 'hover:bg-orange-700'
              }`}
            >
              {item.icon}
              <div className="flex flex-col items-start">
                <span className="font-medium text-sm">{item.label}</span>
                <span className="text-xs opacity-70">{item.bangla}</span>
              </div>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-orange-700 text-xs text-center opacity-60">
          &copy; 2024 BakeMate Management
        </div>
      </aside>

      {/* Main Content */}
      <main className="ml-64 flex-1 p-8">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-bold text-slate-800">
              {navItems.find(n => n.id === currentView)?.label}
            </h2>
            <p className="text-slate-500">
              {navItems.find(n => n.id === currentView)?.bangla} - আপনার বেকারির স্মার্ট ম্যানেজমেন্ট
            </p>
          </div>
          <div className="flex gap-4">
             <div className="bg-white px-4 py-2 rounded-lg shadow-sm border border-slate-200">
                <p className="text-xs text-slate-500">Total Profit</p>
                <p className="font-bold text-green-600">
                  ৳ {(sales.reduce((a, b) => a + b.totalPrice, 0) - expenses.reduce((a, b) => a + b.amount, 0)).toLocaleString()}
                </p>
             </div>
          </div>
        </header>

        <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {currentView === View.DASHBOARD && (
            <Dashboard 
              products={products} 
              sales={sales} 
              expenses={expenses} 
            />
          )}
          {currentView === View.INVENTORY && (
            <Inventory 
              products={products} 
              onAdd={addProduct} 
              onUpdate={updateProduct} 
              onDelete={deleteProduct} 
            />
          )}
          {currentView === View.SALES && (
            <SalesView 
              products={products} 
              sales={sales} 
              onAddSale={addSale} 
            />
          )}
          {currentView === View.EXPENSES && (
            <ExpensesView 
              expenses={expenses} 
              onAdd={addExpense} 
            />
          )}
          {currentView === View.AI_INSIGHTS && (
            <AIInsights 
              products={products} 
              sales={sales} 
              expenses={expenses} 
            />
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { Product, Sale, Expense } from '../types';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from 'recharts';
import { TrendingUp, TrendingDown, Package, CreditCard } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  expenses: Expense[];
}

const Dashboard: React.FC<Props> = ({ products, sales, expenses }) => {
  const totalSales = sales.reduce((acc, s) => acc + s.totalPrice, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalSales - totalExpenses;

  const lowStockCount = products.filter(p => p.stock <= 5).length;

  // Prepare chart data (daily sales)
  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    const daySales = sales
      .filter(s => s.date.startsWith(dateStr))
      .reduce((acc, curr) => acc + curr.totalPrice, 0);
    return { name: dateStr.split('-').slice(1).join('/'), sales: daySales };
  }).reverse();

  const COLORS = ['#ea580c', '#fb923c', '#fdba74', '#fed7aa', '#ffedd5'];

  return (
    <div className="space-y-6">
      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Total Revenue" 
          value={`৳ ${totalSales.toLocaleString()}`} 
          icon={<TrendingUp className="text-green-600" />} 
          subtitle="সর্বমোট বিক্রয়"
        />
        <StatCard 
          title="Total Expenses" 
          value={`৳ ${totalExpenses.toLocaleString()}`} 
          icon={<TrendingDown className="text-red-600" />} 
          subtitle="সর্বমোট খরচ"
        />
        <StatCard 
          title="Net Profit" 
          value={`৳ ${profit.toLocaleString()}`} 
          icon={<CreditCard className="text-blue-600" />} 
          subtitle="নিট লাভ"
          highlight={profit >= 0 ? 'text-green-600' : 'text-red-600'}
        />
        <StatCard 
          title="Low Stock Items" 
          value={lowStockCount.toString()} 
          icon={<Package className="text-orange-600" />} 
          subtitle="কম স্টক আইটেম"
          highlight={lowStockCount > 0 ? 'text-orange-600' : 'text-slate-600'}
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold mb-4">Sales Trend (Last 7 Days)</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={last7Days}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="sales" fill="#ea580c" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold mb-4">Product Category Stock</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={products.map(p => ({ name: p.name, value: p.stock }))}
                  cx="50%"
                  cy="50%"
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                  label
                >
                  {products.map((_, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ 
  title: string; 
  value: string; 
  icon: React.ReactNode; 
  subtitle: string;
  highlight?: string;
}> = ({ title, value, icon, subtitle, highlight }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-between">
    <div className="flex justify-between items-start mb-2">
      <span className="text-sm font-medium text-slate-500 uppercase tracking-wider">{title}</span>
      <div className="p-2 bg-slate-50 rounded-lg">{icon}</div>
    </div>
    <div>
      <h4 className={`text-2xl font-bold ${highlight || 'text-slate-800'}`}>{value}</h4>
      <p className="text-xs text-slate-400 mt-1">{subtitle}</p>
    </div>
  </div>
);

export default Dashboard;

import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Edit2, Trash2, Search } from 'lucide-react';

interface Props {
  products: Product[];
  onAdd: (product: Product) => void;
  onUpdate: (product: Product) => void;
  onDelete: (id: string) => void;
}

const Inventory: React.FC<Props> = ({ products, onAdd, onUpdate, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    category: 'Bread',
    price: 0,
    stock: 0
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      onUpdate({ ...formData, id: editingId } as Product);
      setEditingId(null);
    } else {
      onAdd({ ...formData, id: Date.now().toString() } as Product);
    }
    setFormData({ name: '', category: 'Bread', price: 0, stock: 0 });
    setIsAdding(false);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search products... (খুঁজুন)" 
            className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-orange-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-600 hover:bg-orange-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors"
        >
          <Plus size={18} /> Add Product (পণ্য যোগ করুন)
        </button>
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-md">
          <h3 className="text-lg font-semibold mb-4">{editingId ? 'Edit Product' : 'Add New Product'}</h3>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Name</label>
              <input 
                required
                type="text" 
                className="w-full p-2 border rounded-md" 
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Category</label>
              <select 
                className="w-full p-2 border rounded-md"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value})}
              >
                <option>Bread</option>
                <option>Cake</option>
                <option>Cookies</option>
                <option>Pastry</option>
                <option>Other</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Price (৳)</label>
              <input 
                required
                type="number" 
                className="w-full p-2 border rounded-md" 
                value={formData.price}
                onChange={e => setFormData({...formData, price: Number(e.target.value)})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Stock</label>
              <input 
                required
                type="number" 
                className="w-full p-2 border rounded-md" 
                value={formData.stock}
                onChange={e => setFormData({...formData, stock: Number(e.target.value)})}
              />
            </div>
            <div className="md:col-span-4 flex justify-end gap-2">
              <button 
                type="button" 
                onClick={() => {setIsAdding(false); setEditingId(null);}} 
                className="px-4 py-2 text-slate-600"
              >
                Cancel
              </button>
              <button 
                type="submit" 
                className="bg-orange-600 text-white px-6 py-2 rounded-md hover:bg-orange-700"
              >
                {editingId ? 'Update' : 'Save'}
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b">
            <tr>
              <th className="px-6 py-4 text-sm font-semibold text-slate-600">Product Name</th>
              <th className="px-6 py-4 text-sm font-semibold text-slate-600">Category</th>
              <th className="px-6 py-4 text-sm font-semibold text-slate-600">Price</th>
              <th className="px-6 py-4 text-sm font-semibold text-slate-600">Stock</th>
              <th className="px-6 py-4 text-sm font-semibold text-slate-600 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredProducts.map(p => (
              <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 font-medium">{p.name}</td>
                <td className="px-6 py-4 text-slate-600 text-sm">{p.category}</td>
                <td className="px-6 py-4">৳ {p.price}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                    p.stock <= 5 ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
                  }`}>
                    {p.stock} units
                  </span>
                </td>
                <td className="px-6 py-4 text-right flex justify-end gap-2">
                  <button 
                    onClick={() => {
                      setFormData(p);
                      setEditingId(p.id);
                      setIsAdding(true);
                    }}
                    className="p-1 hover:text-orange-600 text-slate-400"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button 
                    onClick={() => onDelete(p.id)}
                    className="p-1 hover:text-red-600 text-slate-400"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredProducts.length === 0 && (
          <div className="p-12 text-center text-slate-400">
            No products found. Start by adding one!
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState } from 'react';
import { Product, Sale } from '../types';
import { ShoppingBag, Calendar, User, Hash } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale }) => {
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState(1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.id === selectedProductId);
    if (!product) return;

    if (product.stock < quantity) {
      alert("Not enough stock! (স্টক নেই)");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      productId: product.id,
      productName: product.name,
      quantity,
      totalPrice: product.price * quantity,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setSelectedProductId('');
    setQuantity(1);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* New Sale Form */}
      <div className="lg:col-span-1">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm sticky top-8">
          <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
            <ShoppingBag className="text-orange-600" />
            New Sale (নতুন বিক্রয়)
          </h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1 text-slate-600">Select Product</label>
              <select 
                required
                className="w-full p-3 border rounded-lg bg-slate-50 focus:ring-2 focus:ring-orange-500 outline-none"
                value={selectedProductId}
                onChange={e => setSelectedProductId(e.target.value)}
              >
                <option value="">Choose item...</option>
                {products.map(p => (
                  <option key={p.id} value={p.id} disabled={p.stock === 0}>
                    {p.name} (৳{p.price}) - {p.stock} in stock
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1 text-slate-600">Quantity</label>
              <input 
                required
                type="number" 
                min="1"
                className="w-full p-3 border rounded-lg bg-slate-50 focus:ring-2 focus:ring-orange-500 outline-none"
                value={quantity}
                onChange={e => setQuantity(Number(e.target.value))}
              />
            </div>

            {selectedProductId && (
               <div className="p-4 bg-orange-50 rounded-lg">
                  <div className="flex justify-between text-sm mb-1">
                    <span>Unit Price:</span>
                    <span>৳ {products.find(p => p.id === selectedProductId)?.price}</span>
                  </div>
                  <div className="flex justify-between font-bold text-lg border-t border-orange-100 pt-2 mt-2">
                    <span>Total:</span>
                    <span className="text-orange-700">৳ {Number(products.find(p => p.id === selectedProductId)?.price || 0) * quantity}</span>
                  </div>
               </div>
            )}

            <button 
              type="submit" 
              className="w-full bg-orange-600 hover:bg-orange-700 text-white font-bold py-3 rounded-lg transition-all shadow-lg shadow-orange-100 active:scale-95"
            >
