import React, { useState, useEffect } from 'react';
import { Product, Sale, Expense, View } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import AIInsights from './components/AIInsights';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Sparkles,
  UtensilsCrossed,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);

  // Check auth on load
  useEffect(() => {
    const auth = sessionStorage.getItem('bakeMate_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('bakeMate_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    sessionStorage.removeItem('bakeMate_auth');
  };

  // Persistence using LocalStorage
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Milk Bread', category: 'Bread', price: 60, stock: 20 },
      { id: '2', name: 'Chocolate Cake', category: 'Cake', price: 450, stock: 5 },
      { id: '3', name: 'Butter Cookies', category: 'Cookies', price: 120, stock: 50 },
    ];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('expenses');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('sales', JSON.stringify(sales));
  }, [sales]);

  useEffect(() => {
    localStorage.setItem('expenses', JSON.stringify(expenses));
  }, [expenses]);

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'ইনভেন্টরি' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.AI_INSIGHTS, label: 'AI Insights', icon: <Sparkles size={20} />, bangla: 'এআই পরামর্শ' },
  ];

  return (
    <div className="min-h-screen flex bg-slate-50">
      {/* Sidebar */}
      <aside className="w-64 bg-orange-800 text-white flex flex-col fixed h-full shadow-xl">
        <div className="p-6 flex items-center gap-3 border-b border-orange-700">
          <UtensilsCrossed className="text-orange-300" />
          <h1 className="text-2xl font-bold tracking-tight">BakeMate</h1>
        </div>

        <nav className="flex-1 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-6 py-4 transition-colors ${
                currentView === item.id 
                  ? 'bg-orange-700 border-r-4 border-orange-300' 
                  : 'hover:bg-orange-700'
              }`}
            >
              {item.icon}
              <div className="flex flex-col items-start">
                <span className="font-medium text-sm">{item.label}</span>
                <span className="text-xs opacity-70">{item.bangla}</span>
              </div>
            </button>
          ))}
        </nav>

        <div className="mt-auto p-4 border-t border-orange-700">
           <div className="flex items-center gap-3 mb-4 px-2">
              <div className="w-8 h-8 rounded-full bg-orange-400 flex items-center justify-center font-bold text-orange-900">
                 {currentUser[0]?.toUpperCase()}
              </div>
              <div className="flex flex-col overflow-hidden">
                <span className="text-sm font-medium truncate">{currentUser}</span>
                <span className="text-xs opacity-60">Manager</span>
              </div>
           </div>
           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-2 px-4 py-2 text-sm bg-orange-900/50 hover:bg-red-700 rounded-lg transition-colors"
           >
             <LogOut size={16} /> Logout (লগআউট)
           </button>
        </div>

        <div className="p-4 text-[10px] text-center opacity-40 uppercase tracking-widest">
          v1.0 Powered by Gemini
        </div>
      </aside>

      {/* Main Content */}
      <main className="ml-64 flex-1 p-8">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-bold text-slate-800">
              {navItems.find(n => n.id === currentView)?.label}
            </h2>
            <p className="text-slate-500">
              {navItems.find(n => n.id === currentView)?.bangla} - আপনার বেকারির স্মার্ট ম্যানেজমেন্ট
            </p>
          </div>
          <div className="flex gap-4">
             <div className="bg-white px-4 py-2 rounded-lg shadow-sm border border-slate-200">
                <p className="text-xs text-slate-500">Total Profit</p>
                <p className="font-bold text-green-600">
                  ৳ {(sales.reduce((a, b) => a + b.totalPrice, 0) - expenses.reduce((a, b) => a + b.amount, 0)).toLocaleString()}
                </p>
             </div>
          </div>
        </header>

        <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {currentView === View.DASHBOARD && (
            <Dashboard 
              products={products} 
              sales={sales} 
              expenses={expenses} 
            />
          )}
          {currentView === View.INVENTORY && (
            <Inventory 
              products={products} 
              onAdd={addProduct} 
              onUpdate={updateProduct} 
              onDelete={deleteProduct} 
            />
          )}
          {currentView === View.SALES && (
            <SalesView 
              products={products} 
              sales={sales} 
              onAddSale={addSale} 
            />
          )}
          {currentView === View.EXPENSES && (
            <ExpensesView 
              expenses={expenses} 
              onAdd={addExpense} 
            />
          )}
          {currentView === View.AI_INSIGHTS && (
            <AIInsights 
              products={products} 
              sales={sales} 
              expenses={expenses} 
            />
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

{
  "name": "Sweet Live Bakery - Smart Manager",
  "description": "A comprehensive management system for Sweet Live Bakery to track sales, inventory, expenses, and get AI-powered business insights using Gemini.",
  "requestFramePermissions": []
}

import { GoogleGenAI } from "@google/genai";
import { Product, Sale, Expense } from "../types";

export const getBusinessInsights = async (
  products: Product[],
  sales: Sale[],
  expenses: Expense[]
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const totalSales = sales.reduce((acc, s) => acc + s.totalPrice, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalSales - totalExpenses;

  const prompt = `
    As a professional bakery business consultant, analyze the following data for my bakery called "Sweet Live Bakery".

    Data Summary:
    - Total Products: ${products.length}
    - Total Sales Revenue: ৳${totalSales}
    - Total Expenses: ৳${totalExpenses}
    - Net Profit/Loss: ৳${profit}

    Products: ${JSON.stringify(products)}
    Recent Sales History: ${JSON.stringify(sales.slice(-10))}
    Recent Expenses: ${JSON.stringify(expenses.slice(-10))}

    Please provide:
    1. A summary of current performance.
    2. Top 3 recommendations to increase profit.
    3. Warning if expenses are too high or stock is low.
    4. A prediction for the next month.

    Answer in a friendly tone. Use Bengali for the advice if possible, as the user is a Bengali speaker, but use English for technical terms.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.7,
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Insight Error:", error);
    return "Could not generate insights at this time. Please check your data or try again later.";
  }
};

