import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import AIInsights from './components/AIInsights';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Sparkles,
  UtensilsCrossed,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);

  // Check auth on load
  useEffect(() => {
    const auth = sessionStorage.getItem('bakeMate_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('bakeMate_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    sessionStorage.removeItem('bakeMate_auth');
  };

  // Persistence using LocalStorage
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Milk Bread', category: 'Bread', price: 60, stock: 20 },
      { id: '2', name: 'Chocolate Cake', category: 'Cake', price: 450, stock: 5 },
      { id: '3', name: 'Butter Cookies', category: 'Cookies', price: 120, stock: 50 },
    ];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('expenses');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('sales', JSON.stringify(sales));
  }, [sales]);

  useEffect(() => {
    localStorage.setItem('expenses', JSON.stringify(expenses));
  }, [expenses]);

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'ইনভেন্টরি' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.AI_INSIGHTS, label: 'AI Insights', icon: <Sparkles size={20} />, bangla: 'এআই পরামর্শ' },
  ];

  return (
    <div className="min-h-screen flex bg-slate-50">
      {/* Sidebar */}
      <aside className="w-64 bg-orange-800 text-white flex flex-col fixed h-full shadow-xl">
        <div className="p-6 flex items-center gap-3 border-b border-orange-700">
          <UtensilsCrossed className="text-orange-300 shrink-0" />
          <h1 className="text-xl font-bold tracking-tight leading-tight">Sweet Live Bakery</h1>
        </div>

        <nav className="flex-1 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-6 py-4 transition-colors ${
                currentView === item.id 
                  ? 'bg-orange-700 border-r-4 border-orange-300' 
                  : 'hover:bg-orange-700'
              }`}
            >
              {item.icon}
              <div className="flex flex-col items-start">
                <span className="font-medium text-sm">{item.label}</span>
                <span className="text-xs opacity-70">{item.bangla}</span>
              </div>
            </button>
          ))}
        </nav>

        <div className="mt-auto p-4 border-t border-orange-700">
           <div className="flex items-center gap-3 mb-4 px-2">
              <div className="w-8 h-8 rounded-full bg-orange-400 flex items-center justify-center font-bold text-orange-900">
                 {currentUser[0]?.toUpperCase()}
              </div>
              <div className="flex flex-col overflow-hidden">
                <span className="text-sm font-medium truncate">{currentUser}</span>
                <span className="text-xs opacity-60">Manager</span>
              </div>
           </div>
           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-2 px-4 py-2 text-sm bg-orange-900/50 hover:bg-red-700 rounded-lg transition-colors"
           >
             <LogOut size={16} /> Logout (লগআউট)
           </button>
        </div>

        <div className="p-4 text-[10px] text-center opacity-40 uppercase tracking-widest">
          Sweet Live Bakery v1.0
        </div>
      </aside>

      {/* Main Content */}
      <main className="ml-64 flex-1 p-8">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-bold text-slate-800">
              {navItems.find(n => n.id === currentView)?.label}
            </h2>
            <p className="text-slate-500">
              {navItems.find(n => n.id === currentView)?.bangla} - Sweet Live Bakery স্মার্ট ম্যানেজমেন্ট
            </p>
          </div>
          <div className="flex gap-4">
             <div className="bg-white px-4 py-2 rounded-lg shadow-sm border border-slate-200">
                <p className="text-xs text-slate-500">Total Profit</p>
                <p className="font-bold text-green-600">
                  ৳ {(sales.reduce((a, b) => a + b.totalPrice, 0) - expenses.reduce((a, b) => a + b.amount, 0)).toLocaleString()}
                </p>
             </div>
          </div>
        </header>

        <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {currentView === View.DASHBOARD && (
            <Dashboard 
              products={products} 
              sales={sales} 
              expenses={expenses} 
            />
          )}
          {currentView === View.INVENTORY && (
            <Inventory 
              products={products} 
              onAdd={addProduct} 
              onUpdate={updateProduct} 
              onDelete={deleteProduct} 
            />
          )}
          {currentView === View.SALES && (
            <SalesView 
              products={products} 
              sales={sales} 
              onAddSale={addSale} 
            />
          )}
          {currentView === View.EXPENSES && (
            <ExpensesView 
              expenses={expenses} 
              onAdd={addExpense} 
            />
          )}
          {currentView === View.AI_INSIGHTS && (
            <AIInsights 
              products={products} 
              sales={sales} 
              expenses={expenses} 
            />
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UtensilsCrossed, Lock, User, ArrowRight } from 'lucide-react';

interface Props {
  onLogin: (username: string) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isSignup) {
      // Signup Logic
      localStorage.setItem('bakeMate_user', JSON.stringify({ username, password }));
      alert('Account created successfully! Please login. (অ্যাকাউন্ট তৈরি হয়েছে!)');
      setIsSignup(false);
    } else {
      // Login Logic
      const savedUser = localStorage.getItem('bakeMate_user');
      if (savedUser) {
        const { username: savedName, password: savedPass } = JSON.parse(savedUser);
        if (username === savedName && password === savedPass) {
          onLogin(username);
        } else {
          setError('Invalid username or password! (ভুল ইউজারনেম বা পাসওয়ার্ড)');
        }
      } else {
        setError('No account found. Please sign up first. (কোন অ্যাকাউন্ট পাওয়া যায়নি)');
      }
    }
  };

  return (
    <div className="min-h-screen bg-orange-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl overflow-hidden">
        <div className="bg-orange-600 p-8 text-white text-center">
          <div className="inline-flex p-4 bg-orange-500 rounded-full mb-4">
            <UtensilsCrossed size={40} />
          </div>
          <h1 className="text-3xl font-bold">Sweet Live Bakery</h1>
          <p className="text-orange-100 mt-2">আপনার বেকারির স্মার্ট হিসাবরক্ষক</p>
        </div>

        <div className="p-8">
          <h2 className="text-xl font-bold text-slate-800 mb-6">
            {isSignup ? 'Create Account (নতুন অ্যাকাউন্ট)' : 'Welcome Back (লগইন করুন)'}
          </h2>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-slate-600 mb-1">Username (ইউজারনেম)</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  required
                  type="text"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-orange-500 outline-none transition-all"
                  placeholder="Username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-600 mb-1">Password (পাসওয়ার্ড)</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  required
                  type="password"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-orange-500 outline-none transition-all"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            {error && <p className="text-red-500 text-sm font-medium">{error}</p>}

            <button
              type="submit"
              className="w-full bg-orange-600 hover:bg-orange-700 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg active:scale-[0.98]"
            >
              {isSignup ? 'Sign Up' : 'Login'} <ArrowRight size={18} />
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-100 text-center">
            <button
              onClick={() => setIsSignup(!isSignup)}
              className="text-orange-600 font-semibold hover:underline"
            >
              {isSignup ? 'Already have an account? Login' : "Don't have an account? Sign Up"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { UtensilsCrossed, Lock, User, ArrowRight, UserPlus, LogIn } from 'lucide-react';

interface Props {
  onLogin: (username: string) => void;
}

interface UserData {
  username: string;
  password: string;
  role: string;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const getUsers = (): UserData[] => {
    const users = localStorage.getItem('sweetBakery_users');
    return users ? JSON.parse(users) : [];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const users = getUsers();

    if (isSignup) {
      // Signup Logic
      if (username.length < 3) {
        setError('Username must be at least 3 characters. (ইউজারনেম অন্তত ৩ অক্ষরের হতে হবে)');
        return;
      }
      if (password.length < 4) {
        setError('Password must be at least 4 characters. (পাসওয়ার্ড অন্তত ৪ অক্ষরের হতে হবে)');
        return;
      }

      const userExists = users.some(u => u.username.toLowerCase() === username.toLowerCase());
      if (userExists) {
        setError('Username already taken! (এই ইউজারনেমটি ইতিমধ্যে ব্যবহার করা হয়েছে)');
        return;
      }

      const newUser: UserData = { username, password, role: 'Manager' };
      localStorage.setItem('sweetBakery_users', JSON.stringify([...users, newUser]));

      setSuccess('Registration successful! Now login. (রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন)');
      setIsSignup(false);
      setPassword(''); // Clear password after signup
    } else {
      // Login Logic
      const user = users.find(u => u.username === username && u.password === password);
      if (user) {
        onLogin(user.username);
      } else {
        setError('Invalid username or password! (ভুল ইউজারনেম বা পাসওয়ার্ড)');
      }
    }
  };

  return (
    <div className="min-h-screen bg-orange-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl overflow-hidden border border-orange-100">
        {/* Header Section */}
        <div className="bg-orange-600 p-8 text-white text-center relative overflow-hidden">
          <div className="absolute top-[-20px] right-[-20px] opacity-10">
            <UtensilsCrossed size={120} />
          </div>
          <div className="inline-flex p-4 bg-orange-500 rounded-full mb-4 relative z-10 shadow-inner">
            <UtensilsCrossed size={40} />
          </div>
          <h1 className="text-3xl font-bold relative z-10">Sweet Live Bakery</h1>
          <p className="text-orange-100 mt-2 relative z-10">আপনার বেকারির স্মার্ট হিসাবরক্ষক</p>
        </div>

        {/* Form Section */}
        <div className="p-8">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-bold text-slate-800">
              {isSignup ? 'Create Account (রেজিস্ট্রেশন)' : 'Welcome Back (লগইন করুন)'}
            </h2>
            {isSignup ? <UserPlus className="text-orange-500" /> : <LogIn className="text-orange-500" />}
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-slate-600 mb-1">Username (ইউজারনেম)</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  required
                  type="text"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-orange-500 outline-none transition-all bg-slate-50"
                  placeholder="আপনার নাম বা ইউজারনেম"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-600 mb-1">Password (পাসওয়ার্ড)</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  required
                  type="password"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-orange-500 outline-none transition-all bg-slate-50"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm font-medium border border-red-100 animate-shake">
                {error}
              </div>
            )}

            {success && (
              <div className="bg-green-50 text-green-600 p-3 rounded-lg text-sm font-medium border border-green-100">
                {success}
              </div>
            )}

            <button
              type="submit"
              className="w-full bg-orange-600 hover:bg-orange-700 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-orange-100 active:scale-[0.98]"
            >
              {isSignup ? 'Register (অ্যাকাউন্ট খুলুন)' : 'Login (প্রবেশ করুন)'} <ArrowRight size={18} />
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-100 text-center">
            <p className="text-slate-500 text-sm mb-2">
              {isSignup ? 'Already have an account?' : "Don't have an account?"}
            </p>
            <button
              onClick={() => {
                setIsSignup(!isSignup);
                setError('');
                setSuccess('');
              }}
              className="text-orange-600 font-bold hover:text-orange-700 transition-colors"
            >
              {isSignup ? 'Log In (লগইন করুন)' : 'Register Now (নতুন অ্যাকাউন্ট খুলুন)'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { Product, Sale, Expense, View } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import AIInsights from './components/AIInsights';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Sparkles,
  UtensilsCrossed,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);

  // Check auth on load
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('sweetBakery_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    sessionStorage.removeItem('sweetBakery_auth');
  };

  // Persistence using LocalStorage
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Milk Bread', category: 'Bread', price: 60, stock: 20 },
      { id: '2', name: 'Chocolate Cake', category: 'Cake', price: 450, stock: 5 },
      { id: '3', name: 'Butter Cookies', category: 'Cookies', price: 120, stock: 50 },
    ];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('expenses');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('sales', JSON.stringify(sales));
  }, [sales]);

  useEffect(() => {
    localStorage.setItem('expenses', JSON.stringify(expenses));
  }, [expenses]);

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'ইনভেন্টরি' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.AI_INSIGHTS, label: 'AI Insights', icon: <Sparkles size={20} />, bangla: 'এআই পরামর্শ' },
  ];

  return (
    <div className="min-h-screen flex bg-slate-50">
      {/* Sidebar */}
      <aside className="w-64 bg-orange-800 text-white flex flex-col fixed h-full shadow-xl">
        <div className="p-6 flex items-center gap-3 border-b border-orange-700">
          <UtensilsCrossed className="text-orange-300 shrink-0" />
          <h1 className="text-xl font-bold tracking-tight leading-tight">Sweet Live Bakery</h1>
        </div>

        <nav className="flex-1 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-6 py-4 transition-colors ${
                currentView === item.id 
                  ? 'bg-orange-700 border-r-4 border-orange-300' 
                  : 'hover:bg-orange-700'
              }`}
            >
              {item.icon}
