import React, { useState } from 'react';
import { UtensilsCrossed, Lock, User, ArrowRight, UserPlus, LogIn, ChevronRight } from 'lucide-react';

interface Props {
  onLogin: (username: string) => void;
}

interface UserData {
  username: string;
  password: string;
  role: string;
}

const Login: React.FC<Props> = ({ onLogin }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const getUsers = (): UserData[] => {
    const users = localStorage.getItem('sweetBakery_users');
    return users ? JSON.parse(users) : [];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const users = getUsers();

    if (isSignup) {
      if (username.length < 3) {
        setError('Username must be at least 3 characters. (ইউজারনেম অন্তত ৩ অক্ষরের হতে হবে)');
        return;
      }
      if (password.length < 4) {
        setError('Password must be at least 4 characters. (পাসওয়ার্ড অন্তত ৪ অক্ষরের হতে হবে)');
        return;
      }

      const userExists = users.some(u => u.username.toLowerCase() === username.toLowerCase());
      if (userExists) {
        setError('Username already taken! (এই ইউজারনেমটি ইতিমধ্যে ব্যবহার করা হয়েছে)');
        return;
      }

      const newUser: UserData = { username, password, role: 'Manager' };
      localStorage.setItem('sweetBakery_users', JSON.stringify([...users, newUser]));

      setSuccess('Registration successful! Now login. (রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন)');
      setIsSignup(false);
      setPassword('');
    } else {
      const user = users.find(u => u.username === username && u.password === password);
      if (user) {
        onLogin(user.username);
      } else {
        setError('Invalid username or password! (ভুল ইউজারনেম বা পাসওয়ার্ড)');
      }
    }
  };

  return (
    <div className="min-h-screen bg-[#0a1120] flex flex-col items-center justify-center p-6">
      {/* Branding Section */}
      <div className="mb-10 text-center flex flex-col items-center">
        <div className="w-24 h-24 bg-[#161d31] rounded-2xl flex items-center justify-center relative shadow-[0_0_30px_rgba(249,115,22,0.1)] mb-6 overflow-hidden border border-[#2e374d]">
          <div className="absolute inset-0 bg-gradient-to-t from-orange-500/20 to-transparent"></div>
          <div className="relative p-4 bg-orange-500/10 rounded-xl">
             <UtensilsCrossed size={48} className="text-orange-500" />
          </div>
        </div>
        <h1 className="text-4xl font-extrabold text-white tracking-tight mb-2">Sweet Live Bakery</h1>
        <p className="text-[#94a3b8] text-lg">আপনার অ্যাকাউন্টে লগইন করুন</p>
      </div>

      {/* Auth Card */}
      <div className="max-w-md w-full bg-[#161d31] rounded-[2rem] shadow-2xl p-8 border border-[#2e374d]">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-bold text-white flex items-center gap-2">
            {isSignup ? 'Register (রেজিস্ট্রেশন)' : 'Login (লগইন)'}
          </h2>
          <div className="p-2 bg-[#1e293b] rounded-lg text-orange-500">
            {isSignup ? <UserPlus size={24} /> : <LogIn size={24} />}
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[#94a3b8] block px-1">Username (ইউজারনেম)</label>
            <div className="relative group">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-[#475569] group-focus-within:text-orange-500 transition-colors" size={20} />
              <input
                required
                type="text"
                className="w-full pl-12 pr-4 py-4 rounded-2xl bg-[#0a1120] border border-[#2e374d] text-white placeholder-[#475569] focus:ring-2 focus:ring-orange-500/50 outline-none transition-all"
                placeholder="ইউজারনেম দিন"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-semibold text-[#94a3b8] block px-1">Password (পাসওয়ার্ড)</label>
            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-[#475569] group-focus-within:text-orange-500 transition-colors" size={20} />
              <input
                required
                type="password"
                className="w-full pl-12 pr-4 py-4 rounded-2xl bg-[#0a1120] border border-[#2e374d] text-white placeholder-[#475569] focus:ring-2 focus:ring-orange-500/50 outline-none transition-all font-mono"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>
          </div>

          {error && (
            <div className="bg-red-500/10 text-red-400 p-4 rounded-xl text-sm font-medium border border-red-500/20">
              {error}
            </div>
          )}

          {success && (
            <div className="bg-emerald-500/10 text-emerald-400 p-4 rounded-xl text-sm font-medium border border-emerald-500/20">
              {success}
            </div>
          )}

          <button
            type="submit"
            className="w-full bg-[#f59e0b] hover:bg-[#fb923c] text-[#0a1120] font-bold py-4 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-[0_10px_20px_rgba(245,158,11,0.2)] active:scale-[0.98] text-lg"
          >
            {isSignup ? 'অ্যাকাউন্ট খুলুন' : 'লগইন করুন'}
          </button>
        </form>

        <div className="mt-8 pt-6 border-t border-[#2e374d] text-center">
          <button
            onClick={() => {
              setIsSignup(!isSignup);
              setError('');
              setSuccess('');
            }}
            className="group flex items-center justify-center gap-2 w-full text-[#94a3b8] hover:text-white transition-colors"
          >
            <span className="text-sm">
              {isSignup ? 'Already have an account? Login' : "Don't have an account? Register Now"}
            </span>
            <ChevronRight size={16} className="group-hover:translate-x-1 transition-transform" />
          </button>
        </div>
      </div>

      <p className="mt-12 text-[#475569] text-xs uppercase tracking-[0.2em]">Sweet Live Bakery System v1.2</p>
    </div>
  );
};

