            className="w-full pl-12 pr-4 py-3.5 rounded-2xl bg-[#161d31] border border-slate-800 text-white placeholder-slate-500 focus:ring-2 focus:ring-orange-500/50 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
