          onClick={() => setIsAdding(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3.5 rounded-2xl font-bold flex items-center gap-2 transition-all shadow-[0_10px_20px_rgba(249,115,22,0.2)] active:scale-95"
        >
          <Plus size={20} /> Add Product (পণ্য যোগ করুন)
