                onChange={e => setSelectedProductId(e.target.value)}
              >
                <option value="">Choose item...</option>
                {products.map(p => (
                  <option key={p.id} value={p.id} disabled={p.stock === 0} className="bg-[#161d31]">
                    {p.name} (৳{p.price}) - {p.stock} units
                  </option>
                ))}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-400 block px-1">Quantity</label>
