import React from 'react';
import { Product, Sale, Expense } from '../types';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  LineChart,
  Line,
  Cell
} from 'recharts';
import { FileDown, Download, ShoppingCart, Package, ReceiptIndianRupee } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  expenses: Expense[];
}

const Dashboard: React.FC<Props> = ({ products, sales, expenses }) => {
  const totalSales = sales.reduce((acc, s) => acc + s.totalPrice, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalSales - totalExpenses;

  // Prepared data for Product Wise Sales
  const productPerformanceData = products.map((p, idx) => {
    const soldCount = sales
      .filter(s => s.productId === p.id)
      .reduce((acc, s) => acc + s.quantity, 0);
    return {
      name: p.name,
      value: soldCount * p.price,
      color: idx % 2 === 0 ? '#f59e0b' : '#10b981'
    };
  });

  // Preparing Sales Trend Data (Last 7 Days)
  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    const daySales = sales
      .filter(s => s.date.startsWith(dateStr))
      .reduce((acc, curr) => acc + curr.totalPrice, 0);
    return { 
      name: d.toLocaleDateString([], { month: 'numeric', day: 'numeric' }), 
      sales: daySales 
    };
  }).reverse();

  // Helper function to download CSV
  const downloadCSV = (data: any[], filename: string, headers: string[]) => {
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(header => {
        const value = row[header] || '';
        return `"${String(value).replace(/"/g, '""')}"`;
      }).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `${filename}_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSales = () => {
    const formattedData = sales.map(s => ({
      'Date': new Date(s.date).toLocaleString(),
      'Product Name': s.productName,
      'Quantity': s.quantity,
      'Total Price': s.totalPrice
    }));
    downloadCSV(formattedData, 'Bakery_Sales_Report', ['Date', 'Product Name', 'Quantity', 'Total Price']);
  };

  const handleDownloadStock = () => {
    const formattedData = products.map(p => ({
      'Product Name': p.name,
      'Category': p.category,
      'Price': p.price,
      'Current Stock': p.stock
    }));
    downloadCSV(formattedData, 'Bakery_Stock_Report', ['Product Name', 'Category', 'Price', 'Current Stock']);
  };

  const handleDownloadExpenses = () => {
    const formattedData = expenses.map(e => ({
      'Date': new Date(e.date).toLocaleDateString(),
      'Description': e.description,
      'Category': e.category,
      'Amount': e.amount
    }));
    downloadCSV(formattedData, 'Bakery_Expense_Report', ['Date', 'Description', 'Category', 'Amount']);
  };

  return (
    <div className="space-y-8">
      {/* Top Stat Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard 
          title="Total Revenue (মোট আয়)" 
          value={totalSales} 
          subtitle=""
          type="revenue"
        />
        <StatCard 
          title="Total Expenses (মোট খরচ)" 
          value={totalExpenses} 
          subtitle=""
          type="expense"
        />
        <StatCard 
          title="Net Profit (নিট লাভ)" 
          value={profit} 
          subtitle=""
          type="profit"
        />
      </div>

      {/* Download Reports Section */}
      <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
            <FileDown size={24} />
          </div>
          <h3 className="text-xl font-bold text-slate-200">Download Reports (রিপোর্ট ডাউনলোড)</h3>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <button 
            onClick={handleDownloadSales}
            className="flex items-center justify-center gap-3 bg-[#0a1120] hover:bg-orange-500/10 border border-slate-800 hover:border-orange-500/50 p-4 rounded-2xl transition-all group"
          >
            <ShoppingCart size={20} className="text-orange-500 group-hover:scale-110 transition-transform" />
            <span className="font-bold text-sm">Sales Report (বিক্রয়)</span>
          </button>
          <button 
            onClick={handleDownloadStock}
            className="flex items-center justify-center gap-3 bg-[#0a1120] hover:bg-emerald-500/10 border border-slate-800 hover:border-emerald-500/50 p-4 rounded-2xl transition-all group"
          >
            <Package size={20} className="text-emerald-500 group-hover:scale-110 transition-transform" />
            <span className="font-bold text-sm">Stock Report (মজুদ)</span>
          </button>
          <button 
            onClick={handleDownloadExpenses}
            className="flex items-center justify-center gap-3 bg-[#0a1120] hover:bg-red-500/10 border border-slate-800 hover:border-red-500/50 p-4 rounded-2xl transition-all group"
          >
            <ReceiptIndianRupee size={20} className="text-red-500 group-hover:scale-110 transition-transform" />
            <span className="font-bold text-sm">Expense Report (খরচ)</span>
          </button>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Sales Performance Bar Chart */}
        <div className="bg-[#161d31] p-8 rounded-3xl border border-slate-800 shadow-xl">
          <h3 className="text-xl font-bold mb-8 text-slate-200">Sales Performance (Product Wise)</h3>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={productPerformanceData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dx={-10} />
                <Tooltip 
                   contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '12px', color: '#fff' }}
                   itemStyle={{ color: '#fff' }}
                />
                <Bar dataKey="value" radius={[12, 12, 0, 0]} barSize={40}>
                  {productPerformanceData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Daily Sales Trend Line Chart */}
        <div className="bg-[#161d31] p-8 rounded-3xl border border-slate-800 shadow-xl">
          <h3 className="text-xl font-bold mb-8 text-slate-200">Daily Sales Trend (Last 7 Days)</h3>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={last7Days}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dx={-10} />
                <Tooltip 
                   contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '12px', color: '#fff' }}
                   itemStyle={{ color: '#fff' }}
                />
                <Line 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#f59e0b" 
                  strokeWidth={4} 
                  dot={{ fill: '#f59e0b', strokeWidth: 2, r: 6 }} 
                  activeDot={{ r: 8, strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ 
  title: string; 
  value: number; 
  subtitle: string;
  type: 'revenue' | 'expense' | 'profit';
}> = ({ title, value, type }) => {
  const isNegative = value < 0;
  const displayValue = Math.abs(value).toLocaleString();

  const getValueColor = () => {
    if (type === 'profit') return isNegative ? 'text-red-400' : 'text-emerald-400';
    return 'text-white';
  };

  return (
    <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-lg group hover:border-orange-500/30 transition-all duration-300">
      <h4 className="text-[#94a3b8] font-semibold text-sm mb-4 tracking-wide uppercase">{title}</h4>
      <div className="flex items-baseline gap-1">
        <span className={`text-4xl font-extrabold ${getValueColor()}`}>৳</span>
        <span className={`text-5xl font-extrabold tracking-tight ${getValueColor()}`}>
          {isNegative ? '-' : ''}{displayValue}
        </span>
      </div>
    </div>
  );
};

