interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale }) => {
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.id === selectedProductId);
    if (!product) return;

    if (product.stock < quantity) {
      alert("Not enough stock! (স্টক নেই)");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      productId: product.id,
      productName: product.name,
      quantity,
      totalPrice: product.price * quantity,
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setSelectedProductId('');
    setQuantity(1);
    setPaymentMethod('Cash');
  };

  const recentSales = [...sales].reverse().slice(0, 8);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
      {/* New Sale Form */}
      <div className="lg:col-span-4">
        <div className="bg-[#1a2236] p-8 rounded-[1.5rem] shadow-xl border border-slate-800">
          <h3 className="text-xl font-bold mb-8 text-white">Record New Sale (বিক্রয় লিখুন)</h3>
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-300 block px-1">Select Product</label>
              <select 
                required
                className="w-full p-3.5 rounded-xl bg-[#2e374d] border border-orange-500 text-slate-200 focus:ring-2 focus:ring-orange-500/50 outline-none transition-all appearance-none cursor-pointer"
                value={selectedProductId}
                onChange={e => setSelectedProductId(e.target.value)}
              >
                <option value="">Choose a product...</option>
                {products.map(p => (
                  <option key={p.id} value={p.id} disabled={p.stock === 0}>
                    {p.name} (৳{p.price})
                  </option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-300 block px-1">Quantity</label>
                <input 
                  required
                  type="number" 
                  min="1"
                  className="w-full p-3.5 rounded-xl bg-[#2e374d] border border-slate-700 text-white focus:ring-2 focus:ring-orange-500/50 outline-none transition-all"
                  value={quantity}
                  onChange={e => setQuantity(Number(e.target.value))}
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-300 block px-1">Payment</label>
                <select 
                  className="w-full p-3.5 rounded-xl bg-[#2e374d] border border-slate-700 text-white focus:ring-2 focus:ring-orange-500/50 outline-none transition-all cursor-pointer"
                  value={paymentMethod}
                  onChange={e => setPaymentMethod(e.target.value as 'Cash' | 'Mobile Payment')}
                >
                  <option value="Cash">Cash</option>
                  <option value="Mobile Payment">Mobile Payment</option>
                </select>
              </div>
            </div>

            <button 
              type="submit" 
              className="w-full bg-[#f59e0b] hover:bg-[#fb923c] text-white font-bold py-4 rounded-xl transition-all shadow-[0_10px_30px_rgba(245,158,11,0.2)] active:scale-95 text-lg mt-4"
            >
              Complete Sale
            </button>
          </form>
        </div>
      </div>

      {/* Sales History */}
      <div className="lg:col-span-8">
        <div className="bg-[#1a2236] rounded-[1.5rem] shadow-xl border border-slate-800 overflow-hidden">
          <div className="px-8 py-6 flex items-center justify-between border-b border-slate-800">
            <h3 className="text-xl font-bold text-white">Recent Sales History</h3>
            <span className="text-[10px] font-bold text-slate-500 tracking-widest uppercase">Last 8 Records</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-[10px] uppercase text-slate-500 font-bold tracking-[0.15em]">
                  <th className="px-8 py-5">Date</th>
                  <th className="px-8 py-5">Item</th>
                  <th className="px-8 py-5 text-center">Method</th>
                  <th className="px-8 py-5 text-center">Qty</th>
                  <th className="px-8 py-5 text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {recentSales.map(s => (
                  <tr key={s.id} className="hover:bg-slate-800/20 transition-colors">
                    <td className="px-8 py-5 text-sm text-slate-400">
                      {new Date(s.date).toLocaleDateString()}
                    </td>
                    <td className="px-8 py-5 font-bold text-slate-200">{s.productName}</td>
                    <td className="px-8 py-5 text-center">
                       <span className={`inline-block px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                         s.paymentMethod === 'Cash' 
                           ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' 
                           : 'bg-purple-500/10 text-purple-400 border border-purple-500/20'
                       }`}>
                          {s.paymentMethod}
                       </span>
                    </td>
                    <td className="px-8 py-5 text-center">
                       <span className="text-slate-400 font-medium">{s.quantity}</span>
                    </td>
                    <td className="px-8 py-5 text-right font-bold text-white text-lg">৳{s.totalPrice.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {sales.length === 0 && (
              <div className="p-20 text-center text-slate-500">
                <ShoppingCart size={48} className="mx-auto mb-4 opacity-10" />
                <p className="text-xl">No sales recorded yet.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

