          </div>
        </div>
      </div>
    </div>
  );
};

export default ExpensesView;

import React, { useState } from 'react';
import { Staff, Attendance } from '../types';
import { 
  Plus, 
  Calendar, 
  CheckCircle2, 
  UserPlus,
  History,
  Users,
  Banknote
} from 'lucide-react';

interface Props {
  staff: Staff[];
  attendance: Attendance[];
  onAddStaff: (s: Staff) => void;
  onUpdateAttendance: (a: Attendance) => void;
  onPaySalary: (staffId: string, amount: number) => void;
}

const StaffView: React.FC<Props> = ({ staff, attendance, onAddStaff, onUpdateAttendance, onPaySalary }) => {
  const [activeTab, setActiveTab] = useState<'attendance' | 'salary'>('attendance');
  const [isAdding, setIsAdding] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  const [staffFormData, setStaffFormData] = useState({
    name: '',
    designation: '',
    monthlySalary: 0
  });

  const handleAddStaff = (e: React.FormEvent) => {
    e.preventDefault();
    onAddStaff({
      ...staffFormData,
      id: Date.now().toString(),
      joinDate: new Date().toISOString()
    });
    setStaffFormData({ name: '', designation: '', monthlySalary: 0 });
    setIsAdding(false);
  };

  const getStatus = (staffId: string) => {
    const record = attendance.find(a => a.staffId === staffId && a.date === selectedDate);
    return record?.status || 'Not Marked';
  };

  const recentAttendance = [...attendance]
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice(0, 10);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Top Header Row */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-2">
        <div className="flex bg-[#161d31] p-1 rounded-2xl border border-slate-800">
          <button 
            onClick={() => setActiveTab('attendance')}
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'attendance' ? 'bg-[#2e374d] text-white' : 'text-slate-400 hover:text-white'}`}
          >
            Attendance (হাজিরা)
          </button>
          <button 
            onClick={() => setActiveTab('salary')}
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'salary' ? 'bg-[#2e374d] text-white' : 'text-slate-400 hover:text-white'}`}
          >
            Salaries (বেতন)
          </button>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative group">
            <input 
              type="date" 
              className="bg-[#1a2236] border border-slate-800 p-3 px-5 rounded-xl text-white outline-none focus:ring-2 focus:ring-orange-500/50 appearance-none"
              value={selectedDate}
              onChange={e => setSelectedDate(e.target.value)}
            />
            <Calendar className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={18} />
          </div>
          <button 
            onClick={() => setIsAdding(!isAdding)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg active:scale-95"
          >
            <Plus size={20} /> Add Staff
          </button>
        </div>
      </div>

      {/* Register Staff Modal/Form */}
      {isAdding && (
        <div className="bg-[#1a2236] p-8 rounded-[2rem] border border-slate-800 shadow-xl animate-in fade-in zoom-in duration-300">
          <h3 className="text-xl font-bold mb-6 text-white flex items-center gap-2">
            <UserPlus size={20} className="text-orange-500" /> Register Staff Member
          </h3>
          <form onSubmit={handleAddStaff} className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Full Name</label>
              <input 
                required
                type="text" 
                className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.name}
                onChange={e => setStaffFormData({...staffFormData, name: e.target.value})}
                placeholder="e.g. shuvo"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Designation</label>
              <input 
                required
                type="text" 
                className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.designation}
                onChange={e => setStaffFormData({...staffFormData, designation: e.target.value})}
                placeholder="e.g. carigor"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Monthly Salary (৳)</label>
              <input 
                required
                type="number" 
                className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.monthlySalary}
                onChange={e => setStaffFormData({...staffFormData, monthlySalary: Number(e.target.value)})}
                placeholder="20000"
              />
            </div>
            <div className="md:col-span-3 flex justify-end gap-4">
              <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-2 text-slate-400 font-semibold">Cancel</button>
              <button type="submit" className="bg-orange-500 text-white px-10 py-3.5 rounded-xl font-bold">Save Staff</button>
            </div>
          </form>
        </div>
      )}

      {activeTab === 'attendance' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          {/* Main Attendance List */}
          <div className="lg:col-span-7">
            <div className="bg-[#1a2236] rounded-[1.5rem] border border-slate-800 overflow-hidden shadow-xl">
              <div className="px-8 py-6 border-b border-slate-800">
                <h3 className="text-xl font-bold text-white">Attendance for {new Date(selectedDate).toLocaleDateString()}</h3>
              </div>
              <div className="p-4 space-y-4">
                {staff.map(s => {
                  const status = getStatus(s.id);
                  return (
                    <div key={s.id} className="flex items-center justify-between p-4 px-6 bg-[#212a3e]/30 rounded-2xl border border-slate-800/50 hover:bg-[#212a3e]/50 transition-all">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-full bg-slate-700 flex items-center justify-center text-slate-400 font-bold text-lg">
                          {s.name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <h4 className="font-bold text-lg text-white">{s.name}</h4>
                          <p className="text-xs text-slate-500 font-medium uppercase">{s.designation}</p>
                        </div>
                      </div>

                      <button 
                        onClick={() => onUpdateAttendance({ 
                          id: Date.now().toString(), 
                          staffId: s.id, 
                          date: selectedDate, 
                          status: status === 'Present' ? 'Absent' : 'Present' 
                        })}
                        className={`px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 ${
                          status === 'Present' 
                            ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 shadow-inner' 
                            : 'bg-[#1a2236] text-slate-500 border border-slate-700 hover:border-emerald-500/30'
                        }`}
                      >
                        {status === 'Present' ? (
                          <>Present (হাজিরা সম্পন্ন)</>
                        ) : (
                          <>Mark Present</>
                        )}
                      </button>
                    </div>
                  );
                })}
                {staff.length === 0 && (
                  <div className="p-12 text-center text-slate-500">
                    <Users size={40} className="mx-auto mb-4 opacity-20" />
                    <p>No staff added yet.</p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* History Sidebar */}
          <div className="lg:col-span-5">
            <div className="bg-[#1a2236] rounded-[1.5rem] border border-slate-800 overflow-hidden shadow-xl">
              <div className="px-8 py-6 flex items-center justify-between border-b border-slate-800">
                <h3 className="text-lg font-bold text-white">Recent Attendance Records</h3>
                <span className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">History</span>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-[10px] uppercase text-slate-600 font-bold border-b border-slate-800">
                      <th className="px-8 py-4">Date</th>
                      <th className="px-8 py-4">Name</th>
                      <th className="px-8 py-4 text-right">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {recentAttendance.map(a => {
                      const staffMember = staff.find(s => s.id === a.staffId);
                      return (
                        <tr key={a.id} className="text-sm">
                          <td className="px-8 py-4 text-slate-500">{new Date(a.date).toLocaleDateString()}</td>
                          <td className="px-8 py-4 font-bold text-slate-300">{staffMember?.name || 'Unknown'}</td>
                          <td className="px-8 py-4 text-right">
                            <span className={`text-[10px] font-bold uppercase ${a.status === 'Present' ? 'text-emerald-500' : 'text-red-500'}`}>
                              {a.status}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      ) : (
        /* Salaries View */
        <div className="bg-[#1a2236] p-10 rounded-[2.5rem] border border-slate-800 shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {staff.map(s => (
              <div key={s.id} className="bg-[#0a1120] p-8 rounded-3xl border border-slate-800 hover:border-orange-500 transition-all text-center">
                <div className="w-16 h-16 bg-orange-500/10 rounded-2xl flex items-center justify-center text-orange-500 mx-auto mb-4">
                  <Banknote size={32} />
                </div>
                <h4 className="text-xl font-bold mb-1">{s.name}</h4>
                <p className="text-slate-500 text-xs font-bold uppercase mb-4">{s.designation}</p>
                <div className="text-2xl font-black text-white mb-6">৳{s.monthlySalary.toLocaleString()}</div>

                <button 
                  onClick={() => {
                    if(window.confirm(`${s.name} কে ৳${s.monthlySalary} প্রদান করতে চান?`)) {
                      onPaySalary(s.id, s.monthlySalary);
                    }
                  }}
                  className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all"
                >
                  Pay Salary
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default StaffView;

import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Edit2, Trash2, Search, Package, X } from 'lucide-react';

interface Props {
  products: Product[];
  onAdd: (product: Product) => void;
  onUpdate: (product: Product) => void;
  onDelete: (id: string) => void;
}

const Inventory: React.FC<Props> = ({ products, onAdd, onUpdate, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'name_asc' | 'name_desc' | 'price_asc' | 'price_desc'>('name_asc');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    category: 'Bread',
    price: 0,
    stock: 0
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      onUpdate({ ...formData, id: editingId } as Product);
      setEditingId(null);
    } else {
      onAdd({ ...formData, id: Date.now().toString() } as Product);
    }
    setFormData({ name: '', category: 'Bread', price: 0, stock: 0 });
    setIsAdding(false);
  };

  const handleEdit = (p: Product) => {
    setFormData(p);
    setEditingId(p.id);
    setIsAdding(true);
  };

  const filteredProducts = products
    .filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => {
      if (sortBy === 'name_asc') return a.name.localeCompare(b.name);
      if (sortBy === 'name_desc') return b.name.localeCompare(a.name);
      if (sortBy === 'price_asc') return a.price - b.price;
      if (sortBy === 'price_desc') return b.price - a.price;
      return 0;
    });

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-white mb-1">Inventory Status (মজুদ তালিকা)</h2>
          <p className="text-slate-400 text-sm">Manage your bakery items and stock levels.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3.5 rounded-xl font-bold flex items-center gap-2 transition-all shadow-[0_10px_20px_rgba(249,115,22,0.2)] active:scale-95"
        >
          <Plus size={20} /> Add New Product
        </button>
      </div>

      {/* Filter & Sort Bar */}
      <div className="bg-[#1a2236] p-4 rounded-3xl border border-slate-800 flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
          <input 
            type="text" 
            placeholder="Search products by name..." 
            className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-[#212a3e]/50 border border-orange-500/50 text-white placeholder-slate-500 focus:ring-2 focus:ring-orange-500/30 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest whitespace-nowrap">Sort By:</span>
          <select 
            className="bg-[#212a3e]/50 border border-slate-700 p-3.5 px-6 rounded-xl text-white outline-none focus:ring-2 focus:ring-orange-500/30 cursor-pointer w-full md:w-48 text-sm"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
          >
            <option value="name_asc">Name (A-Z)</option>
            <option value="name_desc">Name (Z-A)</option>
            <option value="price_asc">Price (Low-High)</option>
            <option value="price_desc">Price (High-Low)</option>
          </select>
        </div>
      </div>

      {/* Form Modal (Overlay style) */}
      {isAdding && (
        <div className="fixed inset-0 bg-[#0a1120]/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-[#1a2236] p-8 rounded-[2rem] border border-slate-800 shadow-2xl w-full max-w-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold flex items-center gap-3">
                 <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                   <Package size={20} />
                 </div>
                 {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={() => {setIsAdding(false); setEditingId(null);}} className="text-slate-500 hover:text-white">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Product Name</label>
                <input 
                  required
                  type="text" 
                  className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none transition-all" 
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  placeholder="e.g. Cake Chocolate Cup"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Category</label>
                <select 
                  className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none transition-all appearance-none cursor-pointer"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value})}
                >
                  <option value="Bread">Bread</option>
                  <option value="Cake">Cake</option>
                  <option value="Cookies">Cookies</option>
                  <option value="Pastry">Pastry</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Price (৳)</label>
                <input 
                  required
                  type="number" 
                  className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none transition-all" 
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: Number(e.target.value)})}
                  placeholder="25"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Stock (pcs)</label>
                <input 
                  required
                  type="number" 
                  className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none transition-all" 
                  value={formData.stock}
                  onChange={e => setFormData({...formData, stock: Number(e.target.value)})}
                  placeholder="75"
                />
              </div>
              <div className="md:col-span-2 flex justify-end gap-4 mt-6">
                <button 
                  type="button" 
                  onClick={() => {setIsAdding(false); setEditingId(null);}} 
                  className="px-8 py-3 text-slate-400 hover:text-white font-semibold"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="bg-orange-500 hover:bg-orange-600 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg transition-all"
                >
                  {editingId ? 'Update Product' : 'Save Product'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Grid of Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredProducts.map(p => (
          <div key={p.id} className="bg-[#1a2236] p-8 rounded-[1.5rem] border border-slate-800 relative group hover:border-orange-500/30 transition-all duration-300">
            {/* Delete button (the X in top right) */}
            <button 
              onClick={() => {if(window.confirm('Delete this product?')) onDelete(p.id)}}
              className="absolute top-4 right-4 text-slate-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
            >
              <X size={18} />
