            {/* Category Tag */}
            <div className="mb-4">
              <span className="bg-[#212a3e] text-slate-400 px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-widest border border-slate-700">
                {p.category}
              </span>
            </div>

            {/* Price section */}
            <div className="absolute top-8 right-8 text-right">
               <div className="flex items-baseline justify-end gap-1 text-orange-400">
                 <span className="text-lg font-bold">৳</span>
                 <span className="text-3xl font-black">{p.price}</span>
               </div>
               <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">per pcs</p>
            </div>

            {/* Product Name */}
            <div className="mb-10 mt-2">
              <h4 className="text-2xl font-bold text-white group-hover:text-orange-500 transition-colors cursor-pointer" onClick={() => handleEdit(p)}>
                {p.name.toLowerCase()}
              </h4>
            </div>

            {/* Stock Section */}
            <div className="space-y-3">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500 font-semibold">Available Stock</span>
                <span className="text-white font-bold">{p.stock} pcs</span>
              </div>
              {/* Progress Bar */}
              <div className="h-3 w-full bg-[#0a1120] rounded-full overflow-hidden border border-slate-800/50">
                <div 
                  className={`h-full transition-all duration-1000 ${
                    p.stock <= 5 ? 'bg-red-500' : 'bg-orange-500'
                  }`}
                  style={{ width: `${Math.min(100, (p.stock / 100) * 100)}%` }}
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      {filteredProducts.length === 0 && (
        <div className="p-20 text-center text-slate-500 bg-[#1a2236]/30 rounded-[2rem] border-2 border-dashed border-slate-800/50">
          <Package size={48} className="mx-auto mb-4 opacity-10" />
          <p className="text-xl font-bold">No products found.</p>
          <p className="text-sm">Try changing your search or add a new product.</p>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import AIInsights from './components/AIInsights';
import StaffView from './components/StaffView';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  Bot,
  LogOut,
  Moon,
  UtensilsCrossed
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);

  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('sweetBakery_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    sessionStorage.removeItem('sweetBakery_auth');
  };

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Full Bread', category: 'Bread', price: 60, stock: 20 },
      { id: '2', name: 'Cake Chocolate Cup', category: 'Cake', price: 125, stock: 15 },
    ];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('expenses');
    return saved ? JSON.parse(saved) : [];
  });

  const [staff, setStaff] = useState<Staff[]>(() => {
    const saved = localStorage.getItem('staff');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('attendance');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('sales', JSON.stringify(sales));
  }, [sales]);

  useEffect(() => {
    localStorage.setItem('expenses', JSON.stringify(expenses));
  }, [expenses]);

  useEffect(() => {
    localStorage.setItem('staff', JSON.stringify(staff));
  }, [staff]);

  useEffect(() => {
    localStorage.setItem('attendance', JSON.stringify(attendance));
  }, [attendance]);

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.AI_ADVISOR, label: 'AI Advisor', icon: <Bot size={20} />, bangla: 'পরামর্শ' },
  ];

  return (
    <div className="min-h-screen flex bg-[#0a1120] text-white">
      {/* Sidebar */}
      <aside className="w-64 bg-[#0a1120] border-r border-slate-800 flex flex-col fixed h-full z-20">
        <div className="p-8 flex items-center gap-3">
          <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
             <UtensilsCrossed size={20} className="text-white" />
          </div>
          <h1 className="text-xl font-bold text-orange-500">Sweet Live</h1>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
              }`}
            >
              {item.icon}
              <div className="flex items-baseline gap-1">
                <span className="font-semibold text-sm">{item.label}</span>
                {item.bangla && <span className="text-[10px] opacity-60">({item.bangla})</span>}
              </div>
            </button>
          ))}
        </nav>

        <div className="p-6">
           <div className="bg-[#161d31] p-5 rounded-2xl border border-slate-800 mb-6">
              <p className="text-[10px] text-orange-500 uppercase tracking-widest font-bold mb-1">Bakery Status</p>
              <h4 className="text-sm font-semibold">System v2.4.0 Live</h4>
           </div>
           <div className="text-[10px] text-slate-500 text-center font-medium uppercase tracking-wider">
             © 2026 Designed & Built by MD SHAMIM || All Rights Reserved
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="ml-64 flex-1 p-8">
        {/* Header */}
        <header className="mb-10 flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 bg-[#161d31] rounded-2xl border border-slate-800 flex items-center justify-center">
               <UtensilsCrossed size={32} className="text-orange-500" />
            </div>
            <div>
              <h2 className="text-3xl font-extrabold tracking-tight">sweet live bakery</h2>
              <p className="text-slate-400 text-sm font-medium">Bakery Management <span className="text-orange-500 ml-1">• Pro App</span></p>
            </div>
          </div>

          <div className="flex items-center gap-3">
             <button className="w-12 h-12 flex items-center justify-center bg-[#161d31] border border-slate-800 rounded-xl text-yellow-400 hover:bg-[#1e293b] transition-colors">
                <Moon size={20} />
             </button>
             <button 
               onClick={handleLogout}
               className="px-6 py-3 bg-[#161d31] border border-slate-800 rounded-xl text-red-500 font-bold flex items-center gap-2 hover:bg-red-500/10 transition-colors"
             >
               <LogOut size={18} /> Logout
             </button>
          </div>
        </header>

        {/* View Rendering */}
        <section className="animate-in fade-in duration-700">
          {currentView === View.DASHBOARD && (
            <Dashboard products={products} sales={sales} expenses={expenses} />
          )}
          {currentView === View.INVENTORY && (
            <Inventory products={products} onAdd={addProduct} onUpdate={updateProduct} onDelete={deleteProduct} />
          )}
          {currentView === View.SALES && (
            <SalesView products={products} sales={sales} onAddSale={addSale} />
          )}
          {currentView === View.EXPENSES && (
            <ExpensesView expenses={expenses} onAdd={addExpense} />
          )}
          {currentView === View.AI_ADVISOR && (
            <AIInsights products={products} sales={sales} expenses={expenses} />
          )}
          {currentView === View.STAFF && (
            <StaffView 
              staff={staff} 
              attendance={attendance} 
              expenses={expenses}
              onAddStaff={addStaffMember} 
              onUpdateAttendance={updateAttendance} 
              onPaySalary={paySalary}
            />
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Staff, Attendance, Expense } from '../types';
import { 
  Plus, 
  Calendar, 
  CheckCircle2, 
  UserPlus,
  History,
  Users,
  Banknote,
  PiggyBank
} from 'lucide-react';

interface Props {
  staff: Staff[];
  attendance: Attendance[];
  expenses: Expense[];
  onAddStaff: (s: Staff) => void;
  onUpdateAttendance: (a: Attendance) => void;
  onPaySalary: (staffId: string, amount: number) => void;
}

const StaffView: React.FC<Props> = ({ staff, attendance, expenses, onAddStaff, onUpdateAttendance, onPaySalary }) => {
  const [activeTab, setActiveTab] = useState<'attendance' | 'salary'>('attendance');
  const [isAdding, setIsAdding] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  const [staffFormData, setStaffFormData] = useState({
    name: '',
    designation: '',
    monthlySalary: 0
  });

  const handleAddStaff = (e: React.FormEvent) => {
    e.preventDefault();
    onAddStaff({
      ...staffFormData,
      id: Date.now().toString(),
      joinDate: new Date().toISOString()
    });
    setStaffFormData({ name: '', designation: '', monthlySalary: 0 });
    setIsAdding(false);
  };

  const getStatus = (staffId: string) => {
    const record = attendance.find(a => a.staffId === staffId && a.date === selectedDate);
    return record?.status || 'Not Marked';
  };

  const calculateTotalPaid = (staffName: string) => {
    return expenses
      .filter(e => e.category === 'Salary' && e.description.includes(staffName))
      .reduce((sum, e) => sum + e.amount, 0);
  };

  const recentAttendance = [...attendance]
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice(0, 10);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Top Header Row */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-2">
        <div className="flex bg-[#161d31] p-1 rounded-2xl border border-slate-800">
          <button 
            onClick={() => setActiveTab('attendance')}
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'attendance' ? 'bg-[#2e374d] text-white' : 'text-slate-400 hover:text-white'}`}
          >
            Attendance (হাজিরা)
          </button>
          <button 
            onClick={() => setActiveTab('salary')}
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'salary' ? 'bg-[#2e374d] text-white' : 'text-slate-400 hover:text-white'}`}
          >
            Salaries (বেতন)
          </button>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative group">
            <input 
              type="date" 
              className="bg-[#1a2236] border border-slate-800 p-3 px-5 rounded-xl text-white outline-none focus:ring-2 focus:ring-orange-500/50 appearance-none"
              value={selectedDate}
              onChange={e => setSelectedDate(e.target.value)}
            />
            <Calendar className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={18} />
          </div>
          <button 
            onClick={() => setIsAdding(!isAdding)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg active:scale-95"
          >
            <Plus size={20} /> Add Staff
          </button>
        </div>
      </div>

      {/* Register Staff Modal/Form */}
      {isAdding && (
        <div className="bg-[#1a2236] p-8 rounded-[2rem] border border-slate-800 shadow-xl animate-in fade-in zoom-in duration-300">
          <h3 className="text-xl font-bold mb-6 text-white flex items-center gap-2">
            <UserPlus size={20} className="text-orange-500" /> Register Staff Member
          </h3>
          <form onSubmit={handleAddStaff} className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Full Name</label>
              <input 
                required
                type="text" 
                className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.name}
                onChange={e => setStaffFormData({...staffFormData, name: e.target.value})}
                placeholder="e.g. shuvo"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Designation</label>
              <input 
                required
                type="text" 
                className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.designation}
                onChange={e => setStaffFormData({...staffFormData, designation: e.target.value})}
                placeholder="e.g. carigor"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Monthly Salary (৳)</label>
              <input 
                required
                type="number" 
                className="w-full p-4 rounded-xl bg-[#0a1120] border border-slate-800 text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.monthlySalary}
                onChange={e => setStaffFormData({...staffFormData, monthlySalary: Number(e.target.value)})}
                placeholder="20000"
              />
            </div>
            <div className="md:col-span-3 flex justify-end gap-4">
              <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-2 text-slate-400 font-semibold">Cancel</button>
              <button type="submit" className="bg-orange-500 text-white px-10 py-3.5 rounded-xl font-bold">Save Staff</button>
            </div>
          </form>
        </div>
      )}

      {activeTab === 'attendance' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          {/* Main Attendance List */}
          <div className="lg:col-span-7">
            <div className="bg-[#1a2236] rounded-[1.5rem] border border-slate-800 overflow-hidden shadow-xl">
              <div className="px-8 py-6 border-b border-slate-800">
                <h3 className="text-xl font-bold text-white">Attendance for {new Date(selectedDate).toLocaleDateString()}</h3>
              </div>
              <div className="p-4 space-y-4">
                {staff.map(s => {
                  const status = getStatus(s.id);
                  return (
                    <div key={s.id} className="flex items-center justify-between p-4 px-6 bg-[#212a3e]/30 rounded-2xl border border-slate-800/50 hover:bg-[#212a3e]/50 transition-all">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-full bg-slate-700 flex items-center justify-center text-slate-400 font-bold text-lg">
                          {s.name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <h4 className="font-bold text-lg text-white">{s.name}</h4>
                          <p className="text-xs text-slate-500 font-medium uppercase">{s.designation}</p>
                        </div>
                      </div>

                      <button 
                        onClick={() => onUpdateAttendance({ 
                          id: Date.now().toString(), 
                          staffId: s.id, 
                          date: selectedDate, 
                          status: status === 'Present' ? 'Absent' : 'Present' 
                        })}
                        className={`px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 ${
                          status === 'Present' 
                            ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 shadow-inner' 
                            : 'bg-[#1a2236] text-slate-500 border border-slate-700 hover:border-emerald-500/30'
                        }`}
                      >
                        {status === 'Present' ? (
                          <>Present (হাজিরা সম্পন্ন)</>
                        ) : (
                          <>Mark Present</>
                        )}
                      </button>
                    </div>
                  );
                })}
                {staff.length === 0 && (
                  <div className="p-12 text-center text-slate-500">
                    <Users size={40} className="mx-auto mb-4 opacity-20" />
                    <p>No staff added yet.</p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* History Sidebar */}
          <div className="lg:col-span-5">
            <div className="bg-[#1a2236] rounded-[1.5rem] border border-slate-800 overflow-hidden shadow-xl">
              <div className="px-8 py-6 flex items-center justify-between border-b border-slate-800">
                <h3 className="text-lg font-bold text-white">Recent Attendance Records</h3>
                <span className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">History</span>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-[10px] uppercase text-slate-600 font-bold border-b border-slate-800">
                      <th className="px-8 py-4">Date</th>
                      <th className="px-8 py-4">Name</th>
                      <th className="px-8 py-4 text-right">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {recentAttendance.map(a => {
                      const staffMember = staff.find(s => s.id === a.staffId);
                      return (
                        <tr key={a.id} className="text-sm">
                          <td className="px-8 py-4 text-slate-500">{new Date(a.date).toLocaleDateString()}</td>
                          <td className="px-8 py-4 font-bold text-slate-300">{staffMember?.name || 'Unknown'}</td>
                          <td className="px-8 py-4 text-right">
                            <span className={`text-[10px] font-bold uppercase ${a.status === 'Present' ? 'text-emerald-500' : 'text-red-500'}`}>
                              {a.status}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      ) : (
        /* Salaries View */
        <div className="bg-[#1a2236] p-10 rounded-[2.5rem] border border-slate-800 shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {staff.map(s => {
              const totalPaid = calculateTotalPaid(s.name);
              return (
                <div key={s.id} className="bg-[#0a1120] p-8 rounded-3xl border border-slate-800 hover:border-orange-500 transition-all group">
                  <div className="flex justify-center mb-4">
                    <div className="w-16 h-16 bg-orange-500/10 rounded-2xl flex items-center justify-center text-orange-500 group-hover:scale-110 transition-transform">
                      <Banknote size={32} />
                    </div>
                  </div>
                  <div className="text-center mb-6">
                    <h4 className="text-xl font-bold mb-1">{s.name}</h4>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mb-4">{s.designation}</p>
                    <div className="flex flex-col gap-1 items-center">
                       <span className="text-[10px] text-slate-400 uppercase font-bold tracking-tighter">Current Salary</span>
                       <div className="text-2xl font-black text-white">৳{s.monthlySalary.toLocaleString()}</div>
                    </div>
                  </div>

                  {/* Total Paid Section */}
                  <div className="bg-[#161d31] p-4 rounded-2xl border border-slate-800/50 mb-6 flex items-center justify-between">
                     <div className="flex items-center gap-2 text-emerald-400">
                        <PiggyBank size={16} />
                        <span className="text-[10px] font-bold uppercase tracking-tight">Total Paid</span>
                     </div>
                     <div className="text-sm font-bold text-white">৳{totalPaid.toLocaleString()}</div>
                  </div>

                  <button 
                    onClick={() => {
                      if(window.confirm(`${s.name} কে ৳${s.monthlySalary} প্রদান করতে চান?`)) {
                        onPaySalary(s.id, s.monthlySalary);
                      }
                    }}
                    className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-3.5 rounded-xl shadow-lg transition-all active:scale-95"
                  >
                    Pay Salary
                  </button>
                </div>
              );
            })}
            {staff.length === 0 && (
              <div className="col-span-full py-20 text-center text-slate-500">
                <Users size={48} className="mx-auto mb-4 opacity-10" />
                <p>No staff registered.</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default StaffView;

