interface Props {
  products: Product[];
  sales: Sale[];
  expenses: Expense[];
}

const Dashboard: React.FC<Props> = ({ products, sales, expenses }) => {
  const totalSales = sales.reduce((acc, s) => acc + s.totalPrice, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalSales - totalExpenses;

  const productPerformanceData = products.map((p, idx) => {
    const soldCount = sales
      .filter(s => s.productId === p.id)
      .reduce((acc, s) => acc + s.quantity, 0);
    return {
      name: p.name,
      value: soldCount * p.price,
      color: idx % 2 === 0 ? '#f59e0b' : '#10b981'
    };
  });

  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    const daySales = sales
      .filter(s => s.date.startsWith(dateStr))
      .reduce((acc, curr) => acc + curr.totalPrice, 0);
    return { 
      name: d.toLocaleDateString([], { month: 'numeric', day: 'numeric' }), 
      sales: daySales 
    };
  }).reverse();

  const downloadCSV = (data: any[], filename: string, headers: string[]) => {
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(header => {
        const value = row[header] || '';
        return `"${String(value).replace(/"/g, '""')}"`;
      }).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `${filename}_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSales = () => {
    const formattedData = sales.map(s => ({
      'Date': new Date(s.date).toLocaleString(),
      'Product Name': s.productName,
      'Quantity': s.quantity,
      'Total Price': s.totalPrice
    }));
    downloadCSV(formattedData, 'Bakery_Sales_Report', ['Date', 'Product Name', 'Quantity', 'Total Price']);
  };

  const handleDownloadStock = () => {
    const formattedData = products.map(p => ({
      'Product Name': p.name,
      'Category': p.category,
      'Price': p.price,
      'Current Stock': p.stock
    }));
    downloadCSV(formattedData, 'Bakery_Stock_Report', ['Product Name', 'Category', 'Price', 'Current Stock']);
  };

  const handleDownloadExpenses = () => {
    const formattedData = expenses.map(e => ({
      'Date': new Date(e.date).toLocaleDateString(),
      'Description': e.description,
      'Category': e.category,
      'Amount': e.amount
    }));
    downloadCSV(formattedData, 'Bakery_Expense_Report', ['Date', 'Description', 'Category', 'Amount']);
  };

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard title="Total Revenue (মোট আয়)" value={totalSales} type="revenue" />
        <StatCard title="Total Expenses (মোট খরচ)" value={totalExpenses} type="expense" />
        <StatCard title="Net Profit (নিট লাভ)" value={profit} type="profit" />
      </div>

      <div className="bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
            <FileDown size={24} />
          </div>
          <h3 className="text-xl font-bold text-slate-900 dark:text-slate-200">Download Reports (রিপোর্ট ডাউনলোড)</h3>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <button onClick={handleDownloadSales} className="flex items-center justify-center gap-3 bg-slate-50 dark:bg-[#0a1120] hover:bg-orange-500/10 border border-slate-200 dark:border-slate-800 hover:border-orange-500/50 p-4 rounded-2xl transition-all group">
            <ShoppingCart size={20} className="text-orange-500 group-hover:scale-110 transition-transform" />
            <span className="font-bold text-sm text-slate-700 dark:text-slate-200">Sales Report</span>
          </button>
          <button onClick={handleDownloadStock} className="flex items-center justify-center gap-3 bg-slate-50 dark:bg-[#0a1120] hover:bg-emerald-500/10 border border-slate-200 dark:border-slate-800 hover:border-emerald-500/50 p-4 rounded-2xl transition-all group">
            <Package size={20} className="text-emerald-500 group-hover:scale-110 transition-transform" />
            <span className="font-bold text-sm text-slate-700 dark:text-slate-200">Stock Report</span>
          </button>
          <button onClick={handleDownloadExpenses} className="flex items-center justify-center gap-3 bg-slate-50 dark:bg-[#0a1120] hover:bg-red-500/10 border border-slate-200 dark:border-slate-800 hover:border-red-500/50 p-4 rounded-2xl transition-all group">
            <ReceiptIndianRupee size={20} className="text-red-500 group-hover:scale-110 transition-transform" />
            <span className="font-bold text-sm text-slate-700 dark:text-slate-200">Expense Report</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-[#161d31] p-8 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl">
          <h3 className="text-xl font-bold mb-8 text-slate-900 dark:text-slate-200">Sales Performance</h3>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={productPerformanceData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dx={-10} />
                <Tooltip 
                   contentStyle={{ backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px' }}
                   itemStyle={{ color: '#0f172a' }}
                />
                <Bar dataKey="value" radius={[12, 12, 0, 0]} barSize={40}>
                  {productPerformanceData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white dark:bg-[#161d31] p-8 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl">
          <h3 className="text-xl font-bold mb-8 text-slate-900 dark:text-slate-200">Daily Sales Trend</h3>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={last7Days}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} dx={-10} />
                <Tooltip 
                   contentStyle={{ backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px' }}
                />
                <Line 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#f59e0b" 
                  strokeWidth={4} 
                  dot={{ fill: '#f59e0b', strokeWidth: 2, r: 6 }} 
                  activeDot={{ r: 8, strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ 
  title: string; 
  value: number; 
  type: 'revenue' | 'expense' | 'profit';
}> = ({ title, value, type }) => {
  const isNegative = value < 0;
  const displayValue = Math.abs(value).toLocaleString();

  const getValueColor = () => {
    if (type === 'profit') return isNegative ? 'text-red-500' : 'text-emerald-500';
    return 'text-slate-900 dark:text-white';
  };

  return (
    <div className="bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-lg group hover:border-orange-500/30 transition-all duration-300">
      <h4 className="text-slate-500 dark:text-[#94a3b8] font-semibold text-sm mb-4 tracking-wide uppercase">{title}</h4>
      <div className="flex items-baseline gap-1">
        <span className={`text-4xl font-extrabold ${getValueColor()}`}>৳</span>
        <span className={`text-5xl font-extrabold tracking-tight ${getValueColor()}`}>
          {isNegative ? '-' : ''}{displayValue}
        </span>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Search, Package, X } from 'lucide-react';

interface Props {
  products: Product[];
  onAdd: (product: Product) => void;
  onUpdate: (product: Product) => void;
  onDelete: (id: string) => void;
}

const Inventory: React.FC<Props> = ({ products, onAdd, onUpdate, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'name_asc' | 'name_desc' | 'price_asc' | 'price_desc'>('name_asc');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    category: 'Bread',
    price: 0,
    stock: 0
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      onUpdate({ ...formData, id: editingId } as Product);
      setEditingId(null);
    } else {
      onAdd({ ...formData, id: Date.now().toString() } as Product);
    }
    setFormData({ name: '', category: 'Bread', price: 0, stock: 0 });
    setIsAdding(false);
  };

  const handleEdit = (p: Product) => {
    setFormData(p);
    setEditingId(p.id);
    setIsAdding(true);
  };

  const filteredProducts = products
    .filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => {
      if (sortBy === 'name_asc') return a.name.localeCompare(b.name);
      if (sortBy === 'name_desc') return b.name.localeCompare(a.name);
      if (sortBy === 'price_asc') return a.price - b.price;
      if (sortBy === 'price_desc') return b.price - a.price;
      return 0;
    });

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-1">Inventory Status</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">Manage bakery items and stock levels.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3.5 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg active:scale-95"
        >
          <Plus size={20} /> Add New Product
        </button>
      </div>

      <div className="bg-white dark:bg-[#1a2236] p-4 rounded-3xl border border-slate-200 dark:border-slate-800 flex flex-col md:flex-row gap-4 items-center shadow-sm">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
          <input 
            type="text" 
            placeholder="Search products..." 
            className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-orange-500/50 text-slate-900 dark:text-white placeholder-slate-400 focus:ring-2 focus:ring-orange-500/30 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Sort By:</span>
          <select 
            className="bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-slate-700 p-3.5 px-6 rounded-xl text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/30 cursor-pointer w-full md:w-48 text-sm"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
          >
            <option value="name_asc">Name (A-Z)</option>
            <option value="name_desc">Name (Z-A)</option>
            <option value="price_asc">Price (Low-High)</option>
            <option value="price_desc">Price (High-Low)</option>
          </select>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-[#0a1120]/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold flex items-center gap-3 text-slate-900 dark:text-white">
                 <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                   <Package size={20} />
                 </div>
                 {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={() => {setIsAdding(false); setEditingId(null);}} className="text-slate-400 hover:text-slate-900 dark:hover:text-white">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Product Name</label>
                <input required type="text" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Category</label>
                <select className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                  <option value="Bread">Bread</option>
                  <option value="Cake">Cake</option>
                  <option value="Cookies">Cookies</option>
                  <option value="Pastry">Pastry</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Price (৳)</label>
                <input required type="number" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Stock (pcs)</label>
                <input required type="number" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
              </div>
              <div className="md:col-span-2 flex justify-end gap-4 mt-6">
                <button type="button" onClick={() => {setIsAdding(false); setEditingId(null);}} className="px-8 py-3 text-slate-400 font-semibold">Cancel</button>
                <button type="submit" className="bg-orange-500 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg">Save Product</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredProducts.map(p => (
          <div key={p.id} className="bg-white dark:bg-[#1a2236] p-8 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 relative group hover:border-orange-500/30 transition-all shadow-sm hover:shadow-md">
            <button onClick={() => {if(window.confirm('Delete this product?')) onDelete(p.id)}} className="absolute top-4 right-4 text-slate-300 dark:text-slate-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
              <X size={18} />
            </button>
            <div className="mb-4">
              <span className="bg-slate-100 dark:bg-[#212a3e] text-slate-500 dark:text-slate-400 px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                {p.category}
              </span>
            </div>
            <div className="absolute top-8 right-8 text-right">
               <div className="flex items-baseline justify-end gap-1 text-orange-500 dark:text-orange-400">
                 <span className="text-lg font-bold">৳</span>
                 <span className="text-3xl font-black">{p.price}</span>
               </div>
            </div>
            <div className="mb-10 mt-2">
              <h4 className="text-2xl font-bold text-slate-900 dark:text-white group-hover:text-orange-500 transition-colors cursor-pointer" onClick={() => handleEdit(p)}>
                {p.name}
              </h4>
            </div>
            <div className="space-y-3">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-400 font-semibold">Available Stock</span>
                <span className="text-slate-900 dark:text-white font-bold">{p.stock} pcs</span>
              </div>
              <div className="h-3 w-full bg-slate-100 dark:bg-[#0a1120] rounded-full overflow-hidden border border-slate-200 dark:border-slate-800/50">
                <div className={`h-full transition-all duration-1000 ${p.stock <= 5 ? 'bg-red-500' : 'bg-orange-500'}`} style={{ width: `${Math.min(100, (p.stock / 100) * 100)}%` }} />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState } from 'react';
import { Product, Sale } from '../types';
import { ShoppingCart } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale }) => {
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product = products.find(p => p.id === selectedProductId);
    if (!product) return;

    if (product.stock < quantity) {
      alert("Not enough stock!");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      productId: product.id,
      productName: product.name,
      quantity,
      totalPrice: product.price * quantity,
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setSelectedProductId('');
    setQuantity(1);
    setPaymentMethod('Cash');
  };

  const recentSales = [...sales].reverse().slice(0, 8);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
      <div className="lg:col-span-4">
        <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[1.5rem] shadow-sm dark:shadow-xl border border-slate-200 dark:border-slate-800">
          <h3 className="text-xl font-bold mb-8 text-slate-900 dark:text-white">Record New Sale</h3>
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-500 dark:text-slate-300 block px-1">Product</label>
              <select required className="w-full p-3.5 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-orange-500 text-slate-900 dark:text-slate-200 focus:ring-2 focus:ring-orange-500/50 outline-none transition-all" value={selectedProductId} onChange={e => setSelectedProductId(e.target.value)}>
                <option value="">Choose a product...</option>
                {products.map(p => (
                  <option key={p.id} value={p.id} disabled={p.stock === 0}>{p.name} (৳{p.price})</option>
                ))}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-500 dark:text-slate-300 block px-1">Quantity</label>
                <input required type="number" min="1" className="w-full p-3.5 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={quantity} onChange={e => setQuantity(Number(e.target.value))} />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-semibold text-slate-500 dark:text-slate-300 block px-1">Payment</label>
                <select className="w-full p-3.5 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={paymentMethod} onChange={e => setPaymentMethod(e.target.value as any)}>
                  <option value="Cash">Cash</option>
                  <option value="Mobile Payment">Mobile Payment</option>
                </select>
              </div>
            </div>
            <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-4 rounded-xl transition-all shadow-lg active:scale-95 text-lg mt-4">
              Complete Sale
            </button>
          </form>
        </div>
      </div>

      <div className="lg:col-span-8">
        <div className="bg-white dark:bg-[#1a2236] rounded-[1.5rem] shadow-sm dark:shadow-xl border border-slate-200 dark:border-slate-800 overflow-hidden">
          <div className="px-8 py-6 border-b border-slate-100 dark:border-slate-800">
            <h3 className="text-xl font-bold text-slate-900 dark:text-white">Recent Sales</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-[10px] uppercase text-slate-400 font-bold tracking-widest bg-slate-50/50 dark:bg-transparent">
                  <th className="px-8 py-5">Date</th>
                  <th className="px-8 py-5">Item</th>
                  <th className="px-8 py-5 text-center">Qty</th>
                  <th className="px-8 py-5 text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                {recentSales.map(s => (
                  <tr key={s.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/20 transition-colors">
                    <td className="px-8 py-5 text-sm text-slate-500 dark:text-slate-400">{new Date(s.date).toLocaleDateString()}</td>
                    <td className="px-8 py-5 font-bold text-slate-900 dark:text-slate-200">{s.productName}</td>
