import React, { useState } from 'react';
import { UtensilsCrossed, Lock, User, UserPlus, LogIn, ChevronRight } from 'lucide-react';

interface Props {
  onLogin: (username: string) => void;
  theme: 'dark' | 'light';
}

interface UserData {
  username: string;
  password: string;
  role: string;
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const getUsers = (): UserData[] => {
    const users = localStorage.getItem('sweetBakery_users');
    return users ? JSON.parse(users) : [];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    const users = getUsers();

    if (isSignup) {
      if (username.length < 3 || password.length < 4) {
        setError('Minimum 3 chars for user and 4 for pass.');
        return;
      }
      const userExists = users.some(u => u.username.toLowerCase() === username.toLowerCase());
      if (userExists) {
        setError('Username taken!');
        return;
      }
      localStorage.setItem('sweetBakery_users', JSON.stringify([...users, { username, password, role: 'Manager' }]));
      setSuccess('Registration successful! Login now.');
      setIsSignup(false);
      setPassword('');
    } else {
      const user = users.find(u => u.username === username && u.password === password);
      if (user) {
        onLogin(user.username);
      } else {
        setError('Invalid login details.');
      }
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 transition-colors duration-300">
      <div className="mb-10 text-center flex flex-col items-center">
        <div className="w-24 h-24 bg-white dark:bg-[#161d31] rounded-2xl flex items-center justify-center shadow-md dark:shadow-[0_0_30px_rgba(249,115,22,0.1)] mb-6 border border-slate-200 dark:border-[#2e374d]">
          <div className="p-4 bg-orange-500/10 rounded-xl">
             <UtensilsCrossed size={48} className="text-orange-500" />
          </div>
        </div>
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white tracking-tight mb-2">Sweet Live Bakery</h1>
        <p className="text-slate-500 dark:text-[#94a3b8] text-lg">Secure Management Portal</p>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2rem] shadow-xl dark:shadow-2xl p-8 border border-slate-200 dark:border-[#2e374d]">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
            {isSignup ? 'Register' : 'Login'}
          </h2>
          <div className="p-2 bg-slate-50 dark:bg-[#1e293b] rounded-lg text-orange-500">
            {isSignup ? <UserPlus size={24} /> : <LogIn size={24} />}
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-500 dark:text-[#94a3b8] block px-1">Username</label>
            <div className="relative">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input required type="text" className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-[#2e374d] text-slate-900 dark:text-white placeholder-slate-400 outline-none focus:ring-2 focus:ring-orange-500/50" placeholder="Username" value={username} onChange={e => setUsername(e.target.value)} />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-500 dark:text-[#94a3b8] block px-1">Password</label>
            <div className="relative">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input required type="password" className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-[#2e374d] text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} />
            </div>
          </div>

          {error && <div className="bg-red-50 text-red-500 p-4 rounded-xl text-sm border border-red-100">{error}</div>}
          {success && <div className="bg-emerald-50 text-emerald-500 p-4 rounded-xl text-sm border border-emerald-100">{success}</div>}

          <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-4 rounded-2xl shadow-lg active:scale-[0.98] text-lg">
            {isSignup ? 'Create Account' : 'Sign In'}
          </button>
        </form>

        <div className="mt-8 pt-6 border-t border-slate-100 dark:border-[#2e374d] text-center">
          <button onClick={() => setIsSignup(!isSignup)} className="group flex items-center justify-center gap-2 w-full text-slate-400 hover:text-orange-500 transition-colors">
            <span className="text-sm">{isSignup ? 'Already have an account? Login' : "Don't have an account? Register Now"}</span>
            <ChevronRight size={16} className="group-hover:translate-x-1 transition-transform" />
          </button>
        </div>
      </div>
      <p className="mt-12 text-slate-400 text-xs uppercase tracking-[0.2em]">Sweet Live Bakery System v2.4</p>
    </div>
  );
};

