import React, { useMemo } from 'react';
import { Sale, Expense, DailyClosing } from '../types';
import { 
  Lock, 
  History, 
  TrendingUp, 
  TrendingDown, 
  CheckCircle2, 
  Calendar,
  DollarSign,
  Briefcase,
  FileDown
} from 'lucide-react';

interface Props {
  sales: Sale[];
  expenses: Expense[];
  closings: DailyClosing[];
  onCloseDay: (closing: DailyClosing) => void;
  currentUser: string;
}

const DailyClosingView: React.FC<Props> = ({ sales, expenses, closings, onCloseDay, currentUser }) => {
  const today = new Date().toISOString().split('T')[0];

  const todayStats = useMemo(() => {
    const todaySales = sales
      .filter(s => s.date.startsWith(today))
      .reduce((sum, s) => sum + s.totalPrice, 0);

    const todayExpenses = expenses
      .filter(e => e.date.startsWith(today))
      .reduce((sum, e) => sum + e.amount, 0);

    return {
      sales: todaySales,
      expenses: todayExpenses,
      profit: todaySales - todayExpenses
    };
  }, [sales, expenses, today]);

  const isAlreadyClosed = closings.some(c => c.date === today);

  const handleCloseDay = () => {
    if (window.confirm('Are you sure you want to close the accounts for today? This will create a permanent record.')) {
      const newClosing: DailyClosing = {
        id: Date.now().toString(),
        date: today,
        totalSales: todayStats.sales,
        totalExpenses: todayStats.expenses,
        netProfit: todayStats.profit,
        closedBy: currentUser,
        timestamp: new Date().toISOString()
      };
      onCloseDay(newClosing);
    }
  };

  const handleDownloadReport = () => {
    if (closings.length === 0) return;

    const headers = ['Closing Date', 'Manager', 'Total Sales', 'Total Expenses', 'Net Profit'];
    const csvContent = [
      headers.join(','),
      ...closings.map(c => [
        new Date(c.date).toLocaleDateString(),
        c.closedBy,
        c.totalSales,
        c.totalExpenses,
        c.netProfit
      ].map(val => `"${String(val).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `Daily_Closing_Report_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Current Day Closing Card */}
      <div className="bg-white dark:bg-[#161d31] p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-5">
           <Lock size={180} className="text-orange-500" />
        </div>

        <div className="relative z-10">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className="bg-orange-500/10 text-orange-500 px-4 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest border border-orange-500/20">
                  Current Status
                </span>
                <h2 className="text-3xl font-black text-slate-900 dark:text-white">Daily Closing (দৈনিক ক্লোজিং)</h2>
              </div>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Closing accounts for {new Date().toLocaleDateString('bn-BD', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
            </div>

            {isAlreadyClosed ? (
              <div className="flex items-center gap-3 bg-emerald-500/10 border border-emerald-500/20 px-8 py-4 rounded-2xl">
                <CheckCircle2 className="text-emerald-500" size={24} />
                <span className="text-emerald-400 font-bold">Closed Successfully</span>
              </div>
            ) : (
              <button 
                onClick={handleCloseDay}
                className="bg-orange-500 hover:bg-orange-600 text-white px-10 py-4 rounded-2xl font-bold flex items-center gap-3 shadow-lg active:scale-95 transition-all"
              >
                <Lock size={20} /> Close Today's Account
              </button>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-slate-50 dark:bg-[#0a1120] p-8 rounded-3xl border border-slate-200 dark:border-slate-800">
              <div className="flex items-center gap-3 mb-4 text-slate-500">
                <TrendingUp size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Today's Sales</span>
              </div>
              <div className="text-3xl font-black text-slate-900 dark:text-white">৳{todayStats.sales.toLocaleString()}</div>
            </div>

            <div className="bg-slate-50 dark:bg-[#0a1120] p-8 rounded-3xl border border-slate-200 dark:border-slate-800">
              <div className="flex items-center gap-3 mb-4 text-slate-500">
                <TrendingDown size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Today's Expenses</span>
              </div>
              <div className="text-3xl font-black text-slate-900 dark:text-white">৳{todayStats.expenses.toLocaleString()}</div>
            </div>

            <div className={`p-8 rounded-3xl border ${todayStats.profit >= 0 ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-red-500/5 border-red-500/20'}`}>
              <div className="flex items-center gap-3 mb-4 text-slate-500">
                <DollarSign size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Expected Profit</span>
              </div>
              <div className={`text-3xl font-black ${todayStats.profit >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-600 dark:text-red-400'}`}>
                ৳{todayStats.profit.toLocaleString()}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white dark:bg-[#161d31] rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl overflow-hidden">
        <div className="px-10 py-8 border-b border-slate-200 dark:border-slate-800 flex flex-col md:flex-row items-center justify-between gap-4">
          <h3 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <History size={24} className="text-orange-500" />
            Closing History (আগের ক্লোজিং রেকর্ড)
          </h3>
          <div className="flex items-center gap-4">
            <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Total: {closings.length} Days</span>
            {closings.length > 0 && (
              <button 
                onClick={handleDownloadReport}
                className="bg-orange-500/10 hover:bg-orange-500 text-orange-500 hover:text-white px-6 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 border border-orange-500/20 shadow-sm"
              >
                <FileDown size={18} /> Download Report
              </button>
            )}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] uppercase text-slate-500 font-bold tracking-[0.2em] bg-slate-50 dark:bg-transparent">
                <th className="px-10 py-6">Closing Date</th>
                <th className="px-10 py-6">Manager</th>
                <th className="px-10 py-6">Total Sales</th>
                <th className="px-10 py-6">Expenses</th>
                <th className="px-10 py-6 text-right">Net Profit</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {[...closings].reverse().map(c => (
                <tr key={c.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/20 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-orange-500/10 flex items-center justify-center text-orange-500">
                        <Calendar size={18} />
                      </div>
                      <span className="font-bold text-slate-700 dark:text-slate-200">{new Date(c.date).toLocaleDateString()}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm font-medium">
                      <Briefcase size={14} className="text-slate-400 dark:text-slate-600" />
                      {c.closedBy}
                    </div>
                  </td>
                  <td className="px-10 py-6 font-bold text-slate-600 dark:text-slate-300">৳{c.totalSales.toLocaleString()}</td>
                  <td className="px-10 py-6 font-bold text-slate-600 dark:text-slate-300">৳{c.totalExpenses.toLocaleString()}</td>
                  <td className={`px-10 py-6 text-right font-black text-xl ${c.netProfit >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-600 dark:text-red-400'}`}>
                    ৳{c.netProfit.toLocaleString()}
                  </td>
                </tr>
              ))}
              {closings.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-10 py-20 text-center">
                     <History size={48} className="mx-auto mb-4 opacity-10 text-slate-400" />
                     <p className="text-slate-500 font-medium text-lg">No closing records found.</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

