  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  // Scoped Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // Theme Synchronizer
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Initial Auth Check
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  // Load User-Specific Data
  useEffect(() => {
    if (currentUser) {
      const prefix = `${currentUser}_`;

      const savedProducts = localStorage.getItem(`${prefix}products`);
      const savedSales = localStorage.getItem(`${prefix}sales`);
      const savedExpenses = localStorage.getItem(`${prefix}expenses`);
      const savedStaff = localStorage.getItem(`${prefix}staff`);
      const savedAttendance = localStorage.getItem(`${prefix}attendance`);
      const savedClosings = localStorage.getItem(`${prefix}closings`);
      const savedDeductions = localStorage.getItem(`${prefix}deductions`);

      setProducts(savedProducts ? JSON.parse(savedProducts) : [
        { id: '1', name: 'Full Bread', category: 'Bread', price: 60, stock: 20 },
        { id: '2', name: 'Cake Chocolate Cup', category: 'Cake', price: 125, stock: 15 },
      ]);
      setSales(savedSales ? JSON.parse(savedSales) : []);
      setExpenses(savedExpenses ? JSON.parse(savedExpenses) : []);
      setStaff(savedStaff ? JSON.parse(savedStaff) : []);
      setAttendance(savedAttendance ? JSON.parse(savedAttendance) : []);
      setDailyClosings(savedClosings ? JSON.parse(savedClosings) : []);
      setDeductions(savedDeductions ? JSON.parse(savedDeductions) : []);

      setIsDataLoaded(true);
    } else {
      setIsDataLoaded(false);
    }
  }, [currentUser]);

  // Save User-Specific Data
  useEffect(() => {
    if (isDataLoaded && currentUser) {
      const prefix = `${currentUser}_`;
      localStorage.setItem(`${prefix}products`, JSON.stringify(products));
      localStorage.setItem(`${prefix}sales`, JSON.stringify(sales));
      localStorage.setItem(`${prefix}expenses`, JSON.stringify(expenses));
      localStorage.setItem(`${prefix}staff`, JSON.stringify(staff));
      localStorage.setItem(`${prefix}attendance`, JSON.stringify(attendance));
      localStorage.setItem(`${prefix}closings`, JSON.stringify(dailyClosings));
      localStorage.setItem(`${prefix}deductions`, JSON.stringify(deductions));
    }
  }, [products, sales, expenses, staff, attendance, dailyClosings, deductions, currentUser, isDataLoaded]);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('sweetBakery_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setIsDataLoaded(false);
    sessionStorage.removeItem('sweetBakery_auth');
    setProducts([]);
    setSales([]);
    setExpenses([]);
    setStaff([]);
    setAttendance([]);
    setDailyClosings([]);
    setDeductions([]);
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const addDeduction = (newDeduction: Deduction) => {
    setDeductions(prev => [...prev, newDeduction]);
  };

  const addDailyClosing = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);

    // Clear current month deductions for this staff member after payment
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    setDeductions(prev => prev.filter(d => {
      const dDate = new Date(d.date);
      return !(d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear);
    }));
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} theme={theme} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className="min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white">
      {/* Sidebar */}
      <aside className="w-64 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-20">
        <div className="p-8 flex items-center gap-3">
          <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
             <UtensilsCrossed size={20} className="text-white" />
          </div>
          <h1 className="text-xl font-bold text-orange-500">Sweet Live</h1>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-500 dark:text-slate-400 hover:text-orange-500 dark:hover:text-white hover:bg-orange-50 dark:hover:bg-slate-800/50'
              }`}
            >
              {item.icon}
              <div className="flex items-baseline gap-1">
                <span className="font-semibold text-sm">{item.label}</span>
                {item.bangla && <span className="text-[10px] opacity-60">({item.bangla})</span>}
              </div>
            </button>
          ))}
        </nav>

        <div className="p-6">
           <div className="bg-slate-100 dark:bg-[#161d31] p-5 rounded-2xl border border-slate-200 dark:border-slate-800 mb-6">
              <p className="text-[10px] text-orange-500 uppercase tracking-widest font-bold mb-1">Bakery Status</p>
              <h4 className="text-sm font-semibold text-slate-900 dark:text-white">System v2.4.0 Live</h4>
              <p className="text-[10px] text-slate-500 mt-2">Logged in: <span className="text-slate-700 dark:text-slate-300 capitalize">{currentUser}</span></p>
           </div>
           <div className="text-[10px] text-slate-400 dark:text-slate-500 text-center font-medium uppercase tracking-wider">
             © 2026 Designed & Built by MD SHAMIM
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="ml-64 flex-1 p-8">
        {/* Header */}
        <header className="mb-10 flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 bg-white dark:bg-[#161d31] rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center justify-center shadow-sm">
               <UtensilsCrossed size={32} className="text-orange-500" />
            </div>
            <div>
              <h2 className="text-3xl font-extrabold tracking-tight capitalize text-slate-900 dark:text-white">sweet live bakery</h2>
              <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">Bakery Management <span className="text-orange-500 ml-1">• Pro App</span></p>
            </div>
          </div>

          <div className="flex items-center gap-3">
             <button 
               onClick={toggleTheme}
               className="w-12 h-12 flex items-center justify-center bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-orange-500 hover:bg-orange-50 dark:hover:bg-[#1e293b] transition-colors shadow-sm"
             >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
             </button>
             <button 
               onClick={handleLogout}
               className="px-6 py-3 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-red-500 font-bold flex items-center gap-2 hover:bg-red-50 dark:hover:bg-red-500/10 transition-colors shadow-sm"
             >
               <LogOut size={18} /> Logout
             </button>
          </div>
        </header>

        {/* View Rendering */}
        <section className="animate-in fade-in duration-700">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center py-20 text-slate-500">
              <div className="w-10 h-10 border-4 border-orange-500/30 border-t-orange-500 rounded-full animate-spin mb-4"></div>
              <p>Loading your bakery records...</p>
            </div>
          ) : (
            <>
              {currentView === View.DASHBOARD && (
                <Dashboard products={products} sales={sales} expenses={expenses} />
              )}
              {currentView === View.INVENTORY && (
                <Inventory products={products} onAdd={addProduct} onUpdate={updateProduct} onDelete={deleteProduct} />
              )}
              {currentView === View.SALES && (
                <SalesView products={products} sales={sales} onAddSale={addSale} />
              )}
              {currentView === View.EXPENSES && (
                <ExpensesView expenses={expenses} onAdd={addExpense} />
              )}
              {currentView === View.DAILY_CLOSING && (
                <DailyClosingView 
                  sales={sales} 
                  expenses={expenses} 
                  closings={dailyClosings} 
                  onCloseDay={addDailyClosing} 
                  currentUser={currentUser} 
                />
              )}
              {currentView === View.MANAGER && (
                <ManagerView 
                  username={currentUser} 
                  onLogout={handleLogout} 
                  stats={{
                    products: products.length,
                    sales: sales.length,
                    expenses: expenses.length,
                    staff: staff.length
                  }}
                />
              )}
              {currentView === View.STAFF && (
                <StaffView 
                  staff={staff} 
                  attendance={attendance} 
                  expenses={expenses}
                  deductions={deductions}
                  onAddStaff={addStaffMember} 
                  onUpdateAttendance={updateAttendance} 
                  onAddDeduction={addDeduction}
                  onPaySalary={paySalary}
                />
              )}
            </>
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Staff, Attendance, Expense, Deduction } from '../types';
import { 
  Plus, 
  Calendar, 
  CheckCircle2, 
  UserPlus,
  History,
  Users,
  Banknote,
  PiggyBank,
  Clock,
  MinusCircle,
  AlertCircle,
  X
} from 'lucide-react';

interface Props {
  staff: Staff[];
  attendance: Attendance[];
  expenses: Expense[];
  deductions: Deduction[];
  onAddStaff: (s: Staff) => void;
  onUpdateAttendance: (a: Attendance) => void;
  onAddDeduction: (d: Deduction) => void;
  onPaySalary: (staffId: string, amount: number) => void;
}

const StaffView: React.FC<Props> = ({ 
  staff, 
  attendance, 
  expenses, 
  deductions,
  onAddStaff, 
  onUpdateAttendance, 
  onAddDeduction,
  onPaySalary 
}) => {
  const [activeTab, setActiveTab] = useState<'attendance' | 'salary'>('attendance');
  const [isAdding, setIsAdding] = useState(false);
  const [isDeducting, setIsDeducting] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  const [staffFormData, setStaffFormData] = useState({
    name: '',
    designation: '',
    monthlySalary: 0
  });

  const [deductionFormData, setDeductionFormData] = useState({
    amount: 0,
    reason: ''
  });

  const handleAddStaff = (e: React.FormEvent) => {
    e.preventDefault();
    onAddStaff({
      ...staffFormData,
      id: Date.now().toString(),
      joinDate: new Date().toISOString()
    });
    setStaffFormData({ name: '', designation: '', monthlySalary: 0 });
    setIsAdding(false);
  };

  const handleAddDeduction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isDeducting) return;

    onAddDeduction({
      id: Date.now().toString(),
      staffId: isDeducting,
      amount: deductionFormData.amount,
      reason: deductionFormData.reason,
      date: new Date().toISOString()
    });

    setDeductionFormData({ amount: 0, reason: '' });
    setIsDeducting(null);
  };

  const getStatus = (staffId: string) => {
    const record = attendance.find(a => a.staffId === staffId && a.date === selectedDate);
    return record?.status || 'Not Marked';
  };

  const calculateTotalPaid = (staffName: string) => {
    return expenses
      .filter(e => e.category === 'Salary' && e.description.toLowerCase().includes(staffName.toLowerCase()))
      .reduce((sum, e) => sum + e.amount, 0);
  };

  const getCurrentMonthDeductions = (staffId: string) => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    return deductions
      .filter(d => {
        const dDate = new Date(d.date);
        return d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear;
      })
      .reduce((sum, d) => sum + d.amount, 0);
  };

  const getDeductionList = (staffId: string) => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    return deductions
      .filter(d => {
        const dDate = new Date(d.date);
        return d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  };

  const getPaymentHistory = (staffName: string) => {
    return expenses
      .filter(e => e.category === 'Salary' && e.description.toLowerCase().includes(staffName.toLowerCase()))
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  };

  const recentAttendance = [...attendance]
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice(0, 10);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Top Header Row */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-2">
        <div className="flex bg-white dark:bg-[#161d31] p-1 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <button 
            onClick={() => setActiveTab('attendance')}
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'attendance' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500 dark:text-slate-400 hover:text-orange-500'}`}
          >
            Attendance (হাজিরা)
          </button>
          <button 
            onClick={() => setActiveTab('salary')}
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'salary' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500 dark:text-slate-400 hover:text-orange-500'}`}
          >
            Salaries (বেতন)
          </button>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative group">
            <input 
              type="date" 
              className="bg-white dark:bg-[#1a2236] border border-slate-200 dark:border-slate-800 p-3 px-5 rounded-xl text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50 appearance-none shadow-sm"
              value={selectedDate}
              onChange={e => setSelectedDate(e.target.value)}
            />
            <Calendar className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 pointer-events-none" size={18} />
          </div>
          <button 
            onClick={() => setIsAdding(!isAdding)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg active:scale-95"
          >
            <Plus size={20} /> Add Staff
          </button>
        </div>
      </div>

      {/* Register Staff Modal/Form */}
      {isAdding && (
        <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl animate-in fade-in zoom-in duration-300">
          <h3 className="text-xl font-bold mb-6 text-slate-900 dark:text-white flex items-center gap-2">
            <UserPlus size={20} className="text-orange-500" /> Register Staff Member
          </h3>
          <form onSubmit={handleAddStaff} className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Full Name</label>
              <input 
                required
                type="text" 
                className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.name}
                onChange={e => setStaffFormData({...staffFormData, name: e.target.value})}
                placeholder="e.g. Shuvo"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Designation</label>
              <input 
                required
                type="text" 
                className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.designation}
                onChange={e => setStaffFormData({...staffFormData, designation: e.target.value})}
                placeholder="e.g. Master Baker"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase px-1">Monthly Salary (৳)</label>
              <input 
                required
                type="number" 
                className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                value={staffFormData.monthlySalary}
                onChange={e => setStaffFormData({...staffFormData, monthlySalary: Number(e.target.value)})}
                placeholder="20000"
              />
            </div>
            <div className="md:col-span-3 flex justify-end gap-4">
              <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-2 text-slate-400 font-semibold">Cancel</button>
              <button type="submit" className="bg-orange-500 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg">Save Staff</button>
            </div>
          </form>
        </div>
      )}

      {/* Deduction Modal */}
      {isDeducting && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/60 dark:bg-[#0a1120]/80 backdrop-blur-sm">
           <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-md animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <MinusCircle size={20} className="text-red-500" /> 
                    Add Deduction (জরিমানা)
                 </h3>
                 <button onClick={() => setIsDeducting(null)} className="text-slate-400 hover:text-slate-900 dark:hover:text-white">
                    <X size={24} />
                 </button>
              </div>
              <form onSubmit={handleAddDeduction} className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase px-1">Deduction Amount (৳)</label>
                    <input required type="number" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-red-500/50 outline-none" value={deductionFormData.amount} onChange={e => setDeductionFormData({...deductionFormData, amount: Number(e.target.value)})} placeholder="Amount to deduct" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase px-1">Reason (কারণ)</label>
                    <textarea required className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-red-500/50 outline-none h-24 resize-none" value={deductionFormData.reason} onChange={e => setDeductionFormData({...deductionFormData, reason: e.target.value})} placeholder="Late attendance, breakage, etc." />
                 </div>
                 <button type="submit" className="w-full bg-red-500 hover:bg-red-600 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-95">
                    Record Deduction
                 </button>
              </form>
           </div>
        </div>
      )}

      {activeTab === 'attendance' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          {/* Main Attendance List */}
          <div className="lg:col-span-7">
            <div className="bg-white dark:bg-[#1a2236] rounded-[1.5rem] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm dark:shadow-xl">
              <div className="px-8 py-6 border-b border-slate-200 dark:border-slate-800">
                <h3 className="text-xl font-bold text-slate-900 dark:text-white">Attendance for {new Date(selectedDate).toLocaleDateString()}</h3>
              </div>
              <div className="p-4 space-y-4">
                {staff.map(s => {
                  const status = getStatus(s.id);
                  return (
                    <div key={s.id} className="flex items-center justify-between p-4 px-6 bg-slate-50 dark:bg-[#212a3e]/30 rounded-2xl border border-slate-200 dark:border-slate-800/50 hover:bg-white dark:hover:bg-[#212a3e]/50 transition-all shadow-sm">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-slate-500 dark:text-slate-400 font-bold text-lg border border-slate-300 dark:border-slate-600">
                          {s.name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <h4 className="font-bold text-lg text-slate-900 dark:text-white">{s.name}</h4>
                          <p className="text-xs text-slate-500 font-medium uppercase">{s.designation}</p>
                        </div>
                      </div>

                      <button 
                        onClick={() => onUpdateAttendance({ 
                          id: Date.now().toString(), 
                          staffId: s.id, 
                          date: selectedDate, 
                          status: status === 'Present' ? 'Absent' : 'Present' 
                        })}
                        className={`px-8 py-3 rounded-xl font-bold transition-all flex items-center gap-2 ${
                          status === 'Present' 
                            ? 'bg-emerald-500 text-white shadow-lg border border-emerald-600' 
                            : 'bg-white dark:bg-[#1a2236] text-slate-500 border border-slate-200 dark:border-slate-700 hover:border-emerald-500/50'
                        }`}
                      >
                        {status === 'Present' ? (
                          <>Present (হাজিরা সম্পন্ন)</>
                        ) : (
                          <>Mark Present</>
                        )}
                      </button>
                    </div>
                  );
                })}
                {staff.length === 0 && (
                  <div className="p-12 text-center text-slate-500">
                    <Users size={40} className="mx-auto mb-4 opacity-20" />
                    <p>No staff added yet.</p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* History Sidebar */}
          <div className="lg:col-span-5">
            <div className="bg-white dark:bg-[#1a2236] rounded-[1.5rem] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm dark:shadow-xl">
              <div className="px-8 py-6 flex items-center justify-between border-b border-slate-200 dark:border-slate-800">
                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Recent Attendance Records</h3>
                <span className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">History</span>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-[10px] uppercase text-slate-500 dark:text-slate-600 font-bold border-b border-slate-100 dark:border-slate-800">
                      <th className="px-8 py-4">Date</th>
                      <th className="px-8 py-4">Name</th>
                      <th className="px-8 py-4 text-right">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                    {recentAttendance.map(a => {
                      const staffMember = staff.find(s => s.id === a.staffId);
                      return (
                        <tr key={a.id} className="text-sm">
                          <td className="px-8 py-4 text-slate-500">{new Date(a.date).toLocaleDateString()}</td>
                          <td className="px-8 py-4 font-bold text-slate-700 dark:text-slate-300">{staffMember?.name || 'Unknown'}</td>
                          <td className="px-8 py-4 text-right">
                            <span className={`text-[10px] font-bold uppercase ${a.status === 'Present' ? 'text-emerald-500' : 'text-red-500'}`}>
                              {a.status}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      ) : (
        /* Salaries View */
        <div className="bg-white dark:bg-[#1a2236] p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {staff.map(s => {
              const totalPaid = calculateTotalPaid(s.name);
              const history = getPaymentHistory(s.name);
              const currentMonthDeductions = getCurrentMonthDeductions(s.id);
              const netPayable = s.monthlySalary - currentMonthDeductions;
              const currentMonthName = new Date().toLocaleString('default', { month: 'long' });
              const isPaidThisMonth = history.some(h => h.description.includes(currentMonthName) && h.description.includes(new Date().getFullYear().toString()));

              return (
                <div key={s.id} className="bg-slate-50 dark:bg-[#0a1120] p-8 rounded-3xl border border-slate-200 dark:border-slate-800 hover:border-orange-500 dark:hover:border-orange-500 transition-all group flex flex-col h-full shadow-sm hover:shadow-md">
                  <div className="flex justify-center mb-4 relative">
                    <div className="w-16 h-16 bg-orange-500/10 rounded-2xl flex items-center justify-center text-orange-500 group-hover:scale-110 transition-transform">
                      <Banknote size={32} />
                    </div>
                    <button 
                      onClick={() => setIsDeducting(s.id)}
                      className="absolute -top-1 -right-1 p-2 bg-red-500 text-white rounded-full shadow-lg hover:scale-110 transition-transform"
                      title="Add Deduction"
                    >
                      <MinusCircle size={16} />
                    </button>
                  </div>
                  <div className="text-center mb-6">
                    <h4 className="text-xl font-bold mb-1 text-slate-900 dark:text-white">{s.name}</h4>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mb-4">{s.designation}</p>

                    <div className="grid grid-cols-2 gap-2 mt-4">
                      <div className="bg-white dark:bg-[#161d31] p-3 rounded-xl border border-slate-200 dark:border-slate-800">
                         <span className="text-[8px] text-slate-500 uppercase font-bold tracking-tighter">Gross Salary</span>
                         <div className="text-lg font-black text-slate-900 dark:text-white">৳{s.monthlySalary.toLocaleString()}</div>
                      </div>
                      <div className="bg-red-500/5 dark:bg-red-500/5 p-3 rounded-xl border border-red-500/20">
                         <span className="text-[8px] text-red-500 uppercase font-bold tracking-tighter">Deductions</span>
                         <div className="text-lg font-black text-red-600 dark:text-red-400">৳{currentMonthDeductions.toLocaleString()}</div>
                      </div>
                    </div>

                    <div className="mt-4 p-4 bg-white dark:bg-[#161d31] rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                       <span className="text-[10px] text-emerald-600 dark:text-emerald-400 uppercase font-bold tracking-widest mb-1 block">Net Payable This Month</span>
                       <div className="text-3xl font-black text-slate-900 dark:text-white">৳{netPayable.toLocaleString()}</div>
                    </div>
                  </div>

                  <div className="space-y-3 mb-6 flex-grow">
                    {/* Total Paid Section */}
                    <div className="bg-white dark:bg-[#161d31] p-4 rounded-2xl border border-slate-200 dark:border-slate-800/50 flex items-center justify-between shadow-sm">
                       <div className="flex items-center gap-2 text-emerald-600 dark:text-emerald-400">
                          <PiggyBank size={16} />
                          <span className="text-[10px] font-bold uppercase tracking-tight">Lifetime Paid</span>
                       </div>
                       <div className="text-sm font-bold text-slate-900 dark:text-white">৳{totalPaid.toLocaleString()}</div>
                    </div>

                    {/* Deductions Breakdown for current month */}
                    {getDeductionList(s.id).length > 0 && (
                      <div className="bg-red-50 dark:bg-red-900/5 p-4 rounded-2xl border border-red-100 dark:border-red-900/20">
                         <div className="flex items-center gap-2 mb-2">
                           <AlertCircle size={14} className="text-red-500" />
                           <span className="text-[10px] font-bold uppercase tracking-widest text-red-600 dark:text-red-400">Monthly Deductions</span>
                         </div>
                         <div className="space-y-1">
                            {getDeductionList(s.id).map(d => (
                              <div key={d.id} className="flex justify-between text-[9px] text-slate-600 dark:text-slate-400">
                                <span>{d.reason}</span>
                                <span className="font-bold text-red-500">-৳{d.amount}</span>
                              </div>
                            ))}
                         </div>
                      </div>
                    )}

                    {/* This Month Indicator */}
                    <div className={`p-4 rounded-2xl border flex items-center justify-between ${
                      isPaidThisMonth ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-orange-500/5 border-orange-500/20'
                    }`}>
                       <div className="flex items-center gap-2">
                          <Calendar size={16} className={isPaidThisMonth ? 'text-emerald-500' : 'text-orange-500'} />
                          <span className="text-[10px] font-bold uppercase tracking-tight text-slate-500 dark:text-slate-400">{currentMonthName} Status</span>
                       </div>
                       <div className={`text-[10px] font-bold uppercase ${isPaidThisMonth ? 'text-emerald-600 dark:text-emerald-400' : 'text-orange-600 dark:text-orange-400'}`}>
                         {isPaidThisMonth ? 'Paid (পরিশোধিত)' : 'Unpaid (বাকি)'}
                       </div>
                    </div>

                    {/* History Section */}
                    <div className="mt-4">
                      <div className="flex items-center gap-2 mb-3 px-2">
                        <Clock size={14} className="text-slate-400" />
                        <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-500">Payment History</span>
                      </div>
                      <div className="bg-white dark:bg-[#161d31] rounded-xl border border-slate-200 dark:border-slate-800/50 overflow-hidden shadow-inner">
                        <div className="max-h-32 overflow-y-auto">
                          {history.length > 0 ? (
                            <table className="w-full text-[10px]">
                              <thead className="bg-slate-50 dark:bg-[#1a2236] text-slate-500 sticky top-0">
                                <tr>
                                  <th className="px-4 py-2 text-left">Date</th>
                                  <th className="px-4 py-2 text-right">Amount</th>
                                </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                                {history.map((h, idx) => (
                                  <tr key={idx} className="hover:bg-slate-50 dark:hover:bg-white/5 transition-colors">
                                    <td className="px-4 py-2 text-slate-500 dark:text-slate-400">{new Date(h.date).toLocaleDateString()}</td>
                                    <td className="px-4 py-2 text-right font-bold text-slate-900 dark:text-slate-200">৳{h.amount.toLocaleString()}</td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          ) : (
                            <div className="p-4 text-center text-slate-400 dark:text-slate-600 font-medium italic">No history yet</div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  <button 
                    onClick={() => {
                      if(window.confirm(`${s.name} কে নিট ৳${netPayable} (৳${currentMonthDeductions} কর্তনের পর) প্রদান করতে চান?`)) {
                        onPaySalary(s.id, netPayable);
                      }
                    }}
                    disabled={isPaidThisMonth}
                    className={`w-full font-bold py-3.5 rounded-xl shadow-lg transition-all active:scale-95 mt-auto flex items-center justify-center gap-2 ${
                      isPaidThisMonth 
                      ? 'bg-slate-200 dark:bg-slate-800 text-slate-400 cursor-not-allowed border border-slate-300 dark:border-slate-700' 
                      : 'bg-emerald-500 hover:bg-emerald-600 text-white'
                    }`}
                  >
                    {isPaidThisMonth ? <CheckCircle2 size={18} /> : <Banknote size={18} />}
                    {isPaidThisMonth ? 'Already Paid' : 'Pay Net Salary'}
                  </button>
                </div>
              );
            })}
            {staff.length === 0 && (
              <div className="col-span-full py-20 text-center text-slate-500">
                <Users size={48} className="mx-auto mb-4 opacity-10" />
                <p>No staff registered.</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default StaffView;

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  stock: number;
}

export interface Sale {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  totalPrice: number;
  amountPaid: number;
  dueAmount: number;
  customerName?: string;
  customerPhone?: string;
  paymentMethod: 'Cash' | 'Mobile Payment';
  date: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  category: 'Raw Material' | 'Utilities' | 'Rent' | 'Staff' | 'Salary' | 'Other';
  date: string;
}

export interface Staff {
  id: string;
  name: string;
  designation: string;
  monthlySalary: number;
  joinDate: string;
}

export interface Attendance {
  id: string;
  staffId: string;
  date: string; // YYYY-MM-DD
  status: 'Present' | 'Absent';
}

export interface Deduction {
  id: string;
  staffId: string;
  amount: number;
  reason: string;
  date: string;
}

export interface DailyClosing {
  id: string;
  date: string; // YYYY-MM-DD
  totalSales: number;
  totalExpenses: number;
  netProfit: number;
  closedBy: string;
  timestamp: string;
}

export enum View {
  DASHBOARD = 'DASHBOARD',
  SALES = 'SALES',
  INVENTORY = 'INVENTORY',
  EXPENSES = 'EXPENSES',
  STAFF = 'STAFF',
  MANAGER = 'MANAGER',
  DAILY_CLOSING = 'DAILY_CLOSING',
  DUES = 'DUES'
}

import React, { useState, useEffect } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  LogOut,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  // Scoped Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // Theme Synchronizer
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Initial Auth Check
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  // Load User-Specific Data
  useEffect(() => {
    if (currentUser) {
      const prefix = `${currentUser}_`;

      const savedProducts = localStorage.getItem(`${prefix}products`);
      const savedSales = localStorage.getItem(`${prefix}sales`);
      const savedExpenses = localStorage.getItem(`${prefix}expenses`);
      const savedStaff = localStorage.getItem(`${prefix}staff`);
      const savedAttendance = localStorage.getItem(`${prefix}attendance`);
      const savedClosings = localStorage.getItem(`${prefix}closings`);
      const savedDeductions = localStorage.getItem(`${prefix}deductions`);

      setProducts(savedProducts ? JSON.parse(savedProducts) : [
        { id: '1', name: 'Full Bread', category: 'Bread', price: 60, stock: 20 },
        { id: '2', name: 'Cake Chocolate Cup', category: 'Cake', price: 125, stock: 15 },
      ]);
      setSales(savedSales ? JSON.parse(savedSales) : []);
      setExpenses(savedExpenses ? JSON.parse(savedExpenses) : []);
      setStaff(savedStaff ? JSON.parse(savedStaff) : []);
      setAttendance(savedAttendance ? JSON.parse(savedAttendance) : []);
      setDailyClosings(savedClosings ? JSON.parse(savedClosings) : []);
      setDeductions(savedDeductions ? JSON.parse(savedDeductions) : []);

      setIsDataLoaded(true);
    } else {
      setIsDataLoaded(false);
    }
  }, [currentUser]);

  // Save User-Specific Data
  useEffect(() => {
    if (isDataLoaded && currentUser) {
      const prefix = `${currentUser}_`;
      localStorage.setItem(`${prefix}products`, JSON.stringify(products));
      localStorage.setItem(`${prefix}sales`, JSON.stringify(sales));
      localStorage.setItem(`${prefix}expenses`, JSON.stringify(expenses));
      localStorage.setItem(`${prefix}staff`, JSON.stringify(staff));
      localStorage.setItem(`${prefix}attendance`, JSON.stringify(attendance));
      localStorage.setItem(`${prefix}closings`, JSON.stringify(dailyClosings));
      localStorage.setItem(`${prefix}deductions`, JSON.stringify(deductions));
    }
  }, [products, sales, expenses, staff, attendance, dailyClosings, deductions, currentUser, isDataLoaded]);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('sweetBakery_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setIsDataLoaded(false);
    sessionStorage.removeItem('sweetBakery_auth');
    setProducts([]);
    setSales([]);
    setExpenses([]);
    setStaff([]);
    setAttendance([]);
    setDailyClosings([]);
    setDeductions([]);
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const addDeduction = (newDeduction: Deduction) => {
    setDeductions(prev => [...prev, newDeduction]);
  };

  const addDailyClosing = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);

    // Clear current month deductions for this staff member after payment
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    setDeductions(prev => prev.filter(d => {
      const dDate = new Date(d.date);
      return !(d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear);
    }));
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} theme={theme} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className="min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white">
      {/* Sidebar */}
      <aside className="w-64 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-20">
        <div className="p-8 flex items-center gap-3">
          <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
             <UtensilsCrossed size={20} className="text-white" />
          </div>
          <h1 className="text-xl font-bold text-orange-500">Sweet Live</h1>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-500 dark:text-slate-400 hover:text-orange-500 dark:hover:text-white hover:bg-orange-50 dark:hover:bg-slate-800/50'
              }`}
            >
              {item.icon}
