import React, { useState } from 'react';
import { Sale } from '../types';
import { Wallet, Search, Phone, User, CheckCircle2, History, X } from 'lucide-react';

interface Props {
  sales: Sale[];
  onUpdateSale: (sale: Sale) => void;
}

const DuesView: React.FC<Props> = ({ sales, onUpdateSale }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [collectingSaleId, setCollectingSaleId] = useState<string | null>(null);
  const [collectionAmount, setCollectionAmount] = useState<number | ''>('');

  const dueSales = sales.filter(s => s.dueAmount > 0);
  const totalOutstanding = dueSales.reduce((acc, s) => acc + s.dueAmount, 0);

  const filteredDues = dueSales.filter(s => 
    s.customerName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.customerPhone?.includes(searchTerm) ||
    s.productName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleCollect = (e: React.FormEvent) => {
    e.preventDefault();
    if (!collectingSaleId || collectionAmount === '') return;

    const sale = sales.find(s => s.id === collectingSaleId);
    if (!sale) return;

    const amount = Number(collectionAmount);
    if (amount > sale.dueAmount) {
      alert("Collection amount cannot exceed due amount!");
      return;
    }

    const updatedSale: Sale = {
      ...sale,
      amountPaid: sale.amountPaid + amount,
      dueAmount: sale.dueAmount - amount
    };

    onUpdateSale(updatedSale);
    setCollectingSaleId(null);
    setCollectionAmount('');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-orange-500 p-8 rounded-[2rem] shadow-lg shadow-orange-500/20 text-white md:col-span-1">
          <h4 className="text-orange-100 font-bold text-sm mb-2 uppercase tracking-widest">Total Outstanding Dues</h4>
          <div className="flex items-baseline gap-1">
            <span className="text-2xl font-bold">৳</span>
            <span className="text-5xl font-black tracking-tight">{totalOutstanding.toLocaleString()}</span>
          </div>
          <p className="mt-4 text-orange-100 text-xs font-medium">From {dueSales.length} pending transactions.</p>
        </div>

        <div className="md:col-span-2 bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 flex items-center justify-between">
           <div>
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-1">Due Management</h2>
              <p className="text-slate-500 dark:text-slate-400 text-sm">Track and collect payments from customers.</p>
           </div>
           <div className="w-16 h-16 bg-orange-500/10 rounded-2xl flex items-center justify-center text-orange-500 shadow-sm">
              <Wallet size={32} />
           </div>
        </div>
      </div>

      <div className="bg-white dark:bg-[#1a2236] p-4 rounded-3xl border border-slate-200 dark:border-slate-800 flex flex-col md:flex-row gap-4 items-center shadow-sm">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
          <input 
            type="text" 
            placeholder="Search by customer name or phone..." 
            className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white placeholder-slate-400 outline-none focus:ring-2 focus:ring-orange-500/30 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {filteredDues.map(s => (
          <div key={s.id} className="bg-white dark:bg-[#1a2236] p-8 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 relative group hover:border-orange-500/30 transition-all shadow-sm">
             <div className="flex justify-between items-start mb-6">
                <div>
                  <h4 className="text-2xl font-black text-slate-900 dark:text-white">{s.customerName}</h4>
                  <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">
                     <Phone size={14} /> {s.customerPhone || 'No Phone Recorded'}
                  </div>
                </div>
                <div className="text-right">
                   <div className="text-[10px] text-slate-400 uppercase font-bold tracking-widest mb-1">Pending Amount</div>
                   <div className="text-3xl font-black text-red-500">৳{s.dueAmount.toLocaleString()}</div>
                </div>
             </div>

             <div className="p-4 bg-slate-50 dark:bg-[#0a1120] rounded-2xl border border-slate-200 dark:border-slate-800 mb-6 space-y-3">
                <div className="flex justify-between text-xs font-bold uppercase tracking-wider">
                   <span className="text-slate-400">Original Sale ({new Date(s.date).toLocaleDateString()})</span>
                   <span className="text-slate-900 dark:text-white">{s.productName} x{s.quantity}</span>
                </div>
                <div className="flex justify-between text-xs font-bold uppercase tracking-wider">
                   <span className="text-slate-400">Total Bill</span>
                   <span className="text-slate-900 dark:text-white">৳{s.totalPrice.toLocaleString()}</span>
                </div>
                <div className="flex justify-between text-xs font-bold uppercase tracking-wider">
                   <span className="text-slate-400">Paid So Far</span>
                   <span className="text-emerald-500">৳{s.amountPaid.toLocaleString()}</span>
                </div>
             </div>

             <button 
               onClick={() => setCollectingSaleId(s.id)}
               className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2"
             >
               <CheckCircle2 size={18} /> Collect Payment
             </button>
          </div>
        ))}
        {filteredDues.length === 0 && (
          <div className="lg:col-span-2 py-20 text-center bg-white dark:bg-[#1a2236] border border-slate-200 dark:border-slate-800 rounded-[2rem]">
             <History size={48} className="mx-auto mb-4 opacity-10 text-slate-400" />
             <p className="text-slate-500 font-medium text-lg">No outstanding dues found.</p>
          </div>
        )}
      </div>

      {collectingSaleId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/60 dark:bg-[#0a1120]/80 backdrop-blur-sm">
           <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-md animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <Wallet size={20} className="text-orange-500" /> 
                    Collect Payment
                 </h3>
                 <button onClick={() => setCollectingSaleId(null)} className="text-slate-400 hover:text-slate-900 dark:hover:text-white">
                    <X size={24} />
                 </button>
              </div>
              <form onSubmit={handleCollect} className="space-y-6">
                 <div className="p-4 bg-orange-500/5 rounded-xl border border-orange-500/20 mb-2">
                    <p className="text-xs font-bold text-orange-500 uppercase mb-1">Total Outstanding</p>
                    <p className="text-2xl font-black text-slate-900 dark:text-white">৳{sales.find(s => s.id === collectingSaleId)?.dueAmount.toLocaleString()}</p>
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase px-1">Amount to Collect (৳)</label>
                    <input 
                      required 
                      type="number" 
                      autoFocus
                      className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white font-bold text-xl focus:ring-2 focus:ring-orange-500 outline-none" 
                      value={collectionAmount} 
                      onChange={e => setCollectionAmount(e.target.value === '' ? '' : Number(e.target.value))} 
                      placeholder="Enter amount..."
                    />
                 </div>
                 <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-95">
                    Confirm Payment Collection
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

