const DailyClosingView: React.FC<Props> = ({ sales, expenses, closings, onCloseDay, currentUser }) => {
  const today = new Date().toISOString().split('T')[0];

  const todayStats = useMemo(() => {
    const todaySalesEntries = sales.filter(s => s.date.startsWith(today));

    const totalSalesVolume = todaySalesEntries.reduce((sum, s) => sum + s.totalPrice, 0);
    const totalCashCollected = todaySalesEntries.reduce((sum, s) => sum + s.amountPaid, 0);

    const todayExpenses = expenses
      .filter(e => e.date.startsWith(today))
      .reduce((sum, e) => sum + e.amount, 0);

    return {
      sales: totalSalesVolume,
      cash: totalCashCollected,
      expenses: todayExpenses,
      profit: totalSalesVolume - todayExpenses
    };
  }, [sales, expenses, today]);

  const isAlreadyClosed = closings.some(c => c.date === today);

  const handleCloseDay = () => {
    if (window.confirm('Are you sure you want to close the accounts for today? This will create a permanent record.')) {
      const newClosing: DailyClosing = {
        id: Date.now().toString(),
        date: today,
        totalSales: todayStats.sales,
        totalExpenses: todayStats.expenses,
        netProfit: todayStats.profit,
        closedBy: currentUser,
        timestamp: new Date().toISOString()
      };
      onCloseDay(newClosing);
    }
  };

  const handleDownloadReport = () => {
    if (closings.length === 0) return;

    const headers = ['Closing Date', 'Manager', 'Total Sales Volume', 'Total Expenses', 'Net Profit'];
    const csvContent = [
      headers.join(','),
      ...closings.map(c => [
        new Date(c.date).toLocaleDateString(),
        c.closedBy,
        c.totalSales,
        c.totalExpenses,
        c.netProfit
      ].map(val => `"${String(val).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `Daily_Closing_Report_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Current Day Closing Card */}
      <div className="bg-white dark:bg-[#161d31] p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-5">
           <Lock size={180} className="text-orange-500" />
        </div>

        <div className="relative z-10">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className="bg-orange-500/10 text-orange-500 px-4 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest border border-orange-500/20">
