          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-slate-50 dark:bg-[#0a1120] p-8 rounded-3xl border border-slate-200 dark:border-slate-800">
              <div className="flex items-center gap-3 mb-4 text-slate-500">
                <TrendingUp size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Sales Volume</span>
              </div>
              <div className="text-3xl font-black text-slate-900 dark:text-white">৳{todayStats.sales.toLocaleString()}</div>
