                  <td className="px-10 py-6 font-bold text-slate-600 dark:text-slate-300">৳{c.totalSales.toLocaleString()}</td>
                  <td className="px-10 py-6 font-bold text-slate-600 dark:text-slate-300">৳{c.totalExpenses.toLocaleString()}</td>
