              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Price (৳)</label>
                <input required type="number" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Stock & Unit</label>
                <div className="flex gap-2">
                  <input required type="number" className="flex-1 p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  <select className="w-24 p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.unit} onChange={e => setFormData({...formData, unit: e.target.value})}>
                    <option value="pcs">pcs</option>
                    <option value="kg">kg</option>
                    <option value="gm">gm</option>
                    <option value="pkt">pkt</option>
                    <option value="ltr">ltr</option>
                  </select>
                </div>
              </div>
              <div className="md:col-span-2 flex justify-end gap-4 mt-6">
                <button type="button" onClick={() => {setIsAdding(false); setEditingId(null);}} className="px-8 py-3 text-slate-400 font-semibold">Cancel</button>
                <button type="submit" className="bg-orange-500 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg">Save Product</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredProducts.map(p => (
          <div key={p.id} className="bg-white dark:bg-[#1a2236] p-8 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 relative group hover:border-orange-500/30 transition-all shadow-sm hover:shadow-md">
            <button onClick={() => {if(window.confirm('Delete this product?')) onDelete(p.id)}} className="absolute top-4 right-4 text-slate-300 dark:text-slate-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
              <X size={18} />
            </button>
            <div className="mb-4">
              <span className="bg-slate-100 dark:bg-[#212a3e] text-slate-500 dark:text-slate-400 px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                {p.category}
              </span>
            </div>
            <div className="absolute top-8 right-8 text-right">
               <div className="flex items-baseline justify-end gap-1 text-orange-500 dark:text-orange-400">
                 <span className="text-lg font-bold">৳</span>
                 <span className="text-3xl font-black">{p.price}</span>
               </div>
               <div className="text-[10px] text-slate-400 font-bold uppercase">per {p.unit || 'pcs'}</div>
            </div>
            <div className="mb-10 mt-2">
              <h4 className="text-2xl font-bold text-slate-900 dark:text-white group-hover:text-orange-500 transition-colors cursor-pointer" onClick={() => handleEdit(p)}>
                {p.name}
              </h4>
            </div>
            <div className="space-y-3">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-400 font-semibold">Available Stock</span>
                <span className="text-slate-900 dark:text-white font-bold">{p.stock} {p.unit || 'pcs'}</span>
              </div>
              <div className="h-3 w-full bg-slate-100 dark:bg-[#0a1120] rounded-full overflow-hidden border border-slate-200 dark:border-slate-800/50">
                <div className={`h-full transition-all duration-1000 ${p.stock <= 5 ? 'bg-red-500' : 'bg-orange-500'}`} style={{ width: `${Math.min(100, (p.stock / 100) * 100)}%` }} />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Product, Sale } from '../types';
import { ShoppingCart, User, Phone, Wallet } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale }) => {
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  const selectedProduct = products.find(p => p.id === selectedProductId);
  const totalPrice = selectedProduct ? selectedProduct.price * quantity : 0;

  // Auto-fill amount paid when product/quantity changes
  useEffect(() => {
    if (totalPrice > 0) {
      setAmountPaid(totalPrice);
    }
  }, [totalPrice]);

  const dueAmount = totalPrice - (Number(amountPaid) || 0);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct) return;

    if (selectedProduct.stock < quantity) {
      alert("Not enough stock!");
      return;
    }

    if (dueAmount > 0 && !customerName) {
      alert("Please enter Customer Name for due sales.");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      productId: selectedProduct.id,
      productName: selectedProduct.name,
      quantity,
      unit: selectedProduct.unit || 'pcs',
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount,
      customerName: dueAmount > 0 ? customerName : undefined,
      customerPhone: dueAmount > 0 ? customerPhone : undefined,
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setSelectedProductId('');
    setQuantity(1);
    setAmountPaid('');
    setPaymentMethod('Cash');
    setCustomerName('');
