interface Props {
  sales: Sale[];
  expenses: Expense[];
  closings: DailyClosing[];
  onCloseDay: (closing: DailyClosing) => void;
  onDeleteClosing: (id: string) => void;
  currentUser: string;
}

const DailyClosingView: React.FC<Props> = ({ sales, expenses, closings, onCloseDay, onDeleteClosing, currentUser }) => {
  const today = new Date().toISOString().split('T')[0];

  // Find the timestamp of the very last closing done
  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  const activeStats = useMemo(() => {
    // Only include items added AFTER the last closing
    const activeSales = sales.filter(s => new Date(s.date).getTime() > lastClosingTimestamp);
    const activeExpenses = expenses.filter(e => new Date(e.date).getTime() > lastClosingTimestamp);

    const totalSalesVolume = activeSales.reduce((sum, s) => sum + s.totalPrice, 0);
    const totalCashCollected = activeSales.reduce((sum, s) => sum + s.amountPaid, 0);
    const totalExpenses = activeExpenses.reduce((sum, e) => sum + e.amount, 0);

    return {
      sales: totalSalesVolume,
      cash: totalCashCollected,
      expenses: totalExpenses,
      profit: totalSalesVolume - totalExpenses,
      count: activeSales.length + activeExpenses.length
    };
  }, [sales, expenses, lastClosingTimestamp]);

  const handleCloseDay = () => {
    // Restriction Removed: Users can now close even with 0 sales if they want to reset the clock.
    const confirmMsg = activeStats.count === 0 
      ? 'No new transactions found. Close current account anyway to start a fresh session? (নতুন কোনো হিসাব নেই। তবুও কি ক্লোজিং করতে চান?)'
      : 'Are you sure you want to close the accounts? Current totals will reset to zero. (আপনি কি নিশ্চিত? ক্লোজিং করলে বর্তমান হিসাব জিরো হয়ে যাবে)';

    if (window.confirm(confirmMsg)) {
      const newClosing: DailyClosing = {
        id: Date.now().toString(),
        date: today,
        totalSales: activeStats.sales,
        totalExpenses: activeStats.expenses,
        netProfit: activeStats.profit,
        closedBy: currentUser,
        timestamp: new Date().toISOString()
      };
      onCloseDay(newClosing);
    }
  };

  const handleDownloadReport = () => {
    if (closings.length === 0) return;

    const headers = ['Closing Date', 'Manager', 'Total Sales Volume', 'Total Expenses', 'Net Profit'];
    const csvContent = [
      headers.join(','),
      ...closings.map(c => [
        new Date(c.date).toLocaleDateString(),
        c.closedBy,
        c.totalSales,
        c.totalExpenses,
        c.netProfit
      ].map(val => `"${String(val).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `Daily_Closing_Report_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Current Day Closing Card */}
      <div className="bg-white dark:bg-[#161d31] p-6 md:p-10 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-[0.03]">
           <LockOpen size={220} className="text-orange-500" />
        </div>

        <div className="relative z-10">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className="bg-emerald-500 text-white px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest">
                  System Unlocked
                </span>
                <h2 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white tracking-tight">Daily Closing (দৈনিক ক্লোজিং)</h2>
              </div>
              <p className="text-slate-500 dark:text-slate-400 font-medium flex items-center gap-2">
                <Clock size={16} className="text-orange-500" />
                Live accounting session tracking
              </p>
            </div>

            <button 
              onClick={handleCloseDay}
              className="w-full md:w-auto bg-orange-500 hover:bg-orange-600 text-white px-10 py-4 rounded-2xl font-bold flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all group"
            >
              <Lock size={20} className="group-hover:scale-110 transition-transform" /> 
              Close Account Now
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
            <div className="bg-slate-50 dark:bg-[#0a1120] p-6 md:p-8 rounded-3xl border border-slate-200 dark:border-slate-800 hover:border-orange-500/20 transition-colors">
              <div className="flex items-center gap-3 mb-4 text-slate-500">
                <TrendingUp size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Sales Volume</span>
              </div>
              <div className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white">৳{activeStats.sales.toLocaleString()}</div>
            </div>

            <div className="bg-orange-500/5 dark:bg-orange-500/5 p-6 md:p-8 rounded-3xl border border-orange-500/20">
              <div className="flex items-center gap-3 mb-4 text-orange-500">
                <Wallet size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Cash Collected</span>
              </div>
              <div className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white">৳{activeStats.cash.toLocaleString()}</div>
            </div>

            <div className="bg-slate-50 dark:bg-[#0a1120] p-6 md:p-8 rounded-3xl border border-slate-200 dark:border-slate-800 hover:border-red-500/20 transition-colors">
              <div className="flex items-center gap-3 mb-4 text-slate-500">
