              <div className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white">৳{activeStats.expenses.toLocaleString()}</div>
            </div>

            <div className={`p-6 md:p-8 rounded-3xl border ${activeStats.profit >= 0 ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-red-500/5 border-red-500/20'}`}>
              <div className="flex items-center gap-3 mb-4 text-slate-500">
                <DollarSign size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Current Profit</span>
              </div>
              <div className={`text-2xl md:text-3xl font-black ${activeStats.profit >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-600 dark:text-red-400'}`}>
                ৳{activeStats.profit.toLocaleString()}
              </div>
            </div>
          </div>

          <div className="mt-8 p-6 bg-slate-50 dark:bg-[#0a1120]/50 rounded-2xl border border-slate-200 dark:border-slate-800 text-center flex flex-col md:flex-row items-center justify-center gap-4">
             <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
