                  : `Ensure physical cash matches ৳${activeStats.cash.toLocaleString()}. Closing will store this session and start a new one.`
                }
             </p>
          </div>
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white dark:bg-[#161d31] rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl overflow-hidden">
        <div className="px-6 md:px-10 py-8 border-b border-slate-200 dark:border-slate-800 flex flex-col md:flex-row items-center justify-between gap-4">
