  title: string; 
  value: number; 
  type: 'revenue' | 'expense' | 'profit' | 'balance' | 'neutral';
  bangla: string;
}> = ({ title, value, type, bangla }) => {
  const isNegative = value < 0;
  const displayValue = Math.abs(value).toLocaleString();

  const getStyles = () => {
    switch(type) {
      case 'revenue': return 'text-emerald-500 border-emerald-500/20';
      case 'expense': return 'text-red-500 border-red-500/20';
      case 'profit': return isNegative ? 'text-red-500 border-red-500/20' : 'text-orange-500 border-orange-500/20';
      case 'balance': return 'text-orange-500 border-orange-500/30 bg-orange-500/5';
      default: return 'text-slate-900 dark:text-white border-slate-200 dark:border-slate-800';
    }
  };

  return (
    <div className={`bg-white dark:bg-[#161d31] p-6 rounded-[2rem] border transition-all duration-300 shadow-sm ${type === 'balance' ? 'ring-2 ring-orange-500/20' : ''}`}>
      <div className="flex flex-col h-full">
        <h4 className="text-slate-400 dark:text-[#94a3b8] font-bold text-[9px] mb-1 tracking-wider uppercase">{title}</h4>
        <div className="text-[10px] font-medium text-slate-500 dark:text-slate-400 mb-3">{bangla}</div>
        <div className="mt-auto flex items-baseline gap-1">
          <span className={`text-lg font-bold ${getStyles()}`}>৳</span>
          <span className={`text-2xl md:text-3xl font-black tracking-tighter truncate ${getStyles()}`}>
            {isNegative ? '-' : ''}{displayValue}
          </span>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { Sale, Expense, DailyClosing } from '../types';
import { 
  Lock, 
  History, 
  TrendingUp, 
  TrendingDown, 
  Trash2, 
  Calendar,
  DollarSign,
  Briefcase,
  FileDown,
  Wallet,
  Clock,
  LockOpen,
  ArrowRightLeft
} from 'lucide-react';

interface Props {
  sales: Sale[];
  expenses: Expense[];
  closings: DailyClosing[];
  onCloseDay: (closing: DailyClosing) => void;
  onDeleteClosing: (id: string) => void;
  currentUser: string;
}

const DailyClosingView: React.FC<Props> = ({ sales, expenses, closings, onCloseDay, onDeleteClosing, currentUser }) => {
  const today = new Date().toISOString().split('T')[0];

  // Find the timestamp of the very last closing done
  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  const activeStats = useMemo(() => {
    // Only include items added AFTER the last closing
    const activeSales = sales.filter(s => new Date(s.date).getTime() > lastClosingTimestamp);
    const activeExpenses = expenses.filter(e => new Date(e.date).getTime() > lastClosingTimestamp);

    const totalSalesVolume = activeSales.reduce((sum, s) => sum + s.totalPrice, 0);
    const totalCashCollected = activeSales.reduce((sum, s) => sum + s.amountPaid, 0);
    const totalExpenses = activeExpenses.reduce((sum, e) => sum + e.amount, 0);
    const totalProfit = totalSalesVolume - totalExpenses;
    const mainBalance = totalCashCollected - totalExpenses;

    return {
      sales: totalSalesVolume,
      cash: totalCashCollected,
      expenses: totalExpenses,
      profit: totalProfit,
      balance: mainBalance,
      count: activeSales.length + activeExpenses.length
    };
  }, [sales, expenses, lastClosingTimestamp]);

  const handleCloseDay = () => {
    const confirmMsg = activeStats.count === 0 
      ? 'No new transactions found. Close anyway? (নতুন কোনো হিসাব নেই। তবুও কি ক্লোজিং করতে চান?)'
      : 'This will reset all dashboard counters to zero. Proceed? (ক্লোজিং করলে ড্যাশবোর্ডের হিসাব ০ হয়ে যাবে। আপনি কি নিশ্চিত?)';

    if (window.confirm(confirmMsg)) {
      const newClosing: DailyClosing = {
        id: Date.now().toString(),
        date: today,
        totalSales: activeStats.sales,
        totalExpenses: activeStats.expenses,
        netProfit: activeStats.profit,
        closedBy: currentUser,
        timestamp: new Date().toISOString()
      };
      onCloseDay(newClosing);
    }
  };

  const handleDownloadReport = () => {
    if (closings.length === 0) return;
    const headers = ['Date', 'Manager', 'Sales', 'Expenses', 'Profit'];
    const csvContent = [
      headers.join(','),
      ...closings.map(c => [
        new Date(c.date).toLocaleDateString(),
        c.closedBy,
        c.totalSales,
        c.totalExpenses,
        c.netProfit
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Closing_History.csv';
    a.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Current Day Closing Card */}
      <div className="bg-white dark:bg-[#161d31] p-6 md:p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-[0.03]">
           <LockOpen size={220} className="text-orange-500" />
        </div>

        <div className="relative z-10">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className="bg-orange-500 text-white px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest">
                  Ready to Close
                </span>
                <h2 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white tracking-tight">Daily Closing (দৈনিক ক্লোজিং)</h2>
              </div>
              <p className="text-slate-500 dark:text-slate-400 font-medium flex items-center gap-2">
                <Clock size={16} className="text-orange-500" />
                Review current session totals before resetting
              </p>
            </div>

            <button 
              onClick={handleCloseDay}
              className="w-full md:w-auto bg-orange-500 hover:bg-orange-600 text-white px-10 py-4 rounded-2xl font-bold flex items-center justify-center gap-3 shadow-[0_10px_30px_rgba(249,115,22,0.3)] active:scale-95 transition-all group"
            >
              <Lock size={20} className="group-hover:scale-110 transition-transform" /> 
              Close Account & Reset
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
            <SummaryItem title="Sales Volume" value={activeStats.sales} bangla="মোট বিক্রি" color="text-slate-600 dark:text-slate-300" />
            <SummaryItem title="Cash Collected" value={activeStats.cash} bangla="নগদ আদায়" color="text-emerald-500" />
            <SummaryItem title="Expenses" value={activeStats.expenses} bangla="মোট খরচ" color="text-red-500" />
            <SummaryItem title="Total Profit" value={activeStats.profit} bangla="মোট লাভ" color="text-orange-500" />
            <SummaryItem title="Main Balance" value={activeStats.balance} bangla="মেইন ব্যালেন্স" color="text-orange-600 dark:text-orange-400" highlight />
          </div>

          <div className="mt-10 p-6 bg-slate-50 dark:bg-[#0a1120]/50 rounded-3xl border border-slate-200 dark:border-slate-800 text-center">
             <p className="text-sm text-slate-500 italic">
                {activeStats.count === 0 
                  ? "Everything is clear. (হিসাব পরিষ্কার আছে)"
                  : `Closing will move these ৳${activeStats.cash.toLocaleString()} records to history and start a fresh session with ৳0.`
                }
             </p>
          </div>
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white dark:bg-[#161d31] rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl overflow-hidden">
        <div className="px-10 py-8 border-b border-slate-200 dark:border-slate-800 flex flex-col md:flex-row items-center justify-between gap-4">
          <h3 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
            <History size={24} className="text-orange-500" />
            Closing History (আগের ক্লোজিং রেকর্ড)
          </h3>
          <button 
            onClick={handleDownloadReport}
            className="bg-slate-100 dark:bg-slate-800 hover:bg-orange-500 hover:text-white px-6 py-2.5 rounded-xl font-bold text-xs transition-all flex items-center gap-2"
          >
            <FileDown size={16} /> Export CSV
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] uppercase text-slate-400 font-bold tracking-widest bg-slate-50 dark:bg-transparent border-b border-slate-100 dark:border-slate-800">
                <th className="px-10 py-6">Date & Time</th>
                <th className="px-10 py-6">Manager</th>
                <th className="px-10 py-6">Sales</th>
                <th className="px-10 py-6">Expenses</th>
                <th className="px-10 py-6">Net Profit</th>
                <th className="px-10 py-6 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {[...closings].reverse().map(c => (
                <tr key={c.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/20 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-700 dark:text-slate-200">{new Date(c.date).toLocaleDateString()}</span>
                      <span className="text-[10px] text-slate-400">{new Date(c.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6 font-medium text-slate-500">{c.closedBy}</td>
                  <td className="px-10 py-6 font-bold text-slate-900 dark:text-white">৳{c.totalSales.toLocaleString()}</td>
                  <td className="px-10 py-6 font-bold text-slate-600 dark:text-slate-400">৳{c.totalExpenses.toLocaleString()}</td>
                  <td className={`px-10 py-6 font-black ${c.netProfit >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>৳{c.netProfit.toLocaleString()}</td>
                  <td className="px-10 py-6 text-right">
                    <button 
                      onClick={() => onDeleteClosing(c.id)}
                      className="p-3 text-slate-300 hover:text-red-500 hover:bg-red-500/10 rounded-xl transition-all"
                      title="Unlock Transactions"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {closings.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-10 py-24 text-center">
                     <History size={64} className="mx-auto mb-4 opacity-5 text-slate-400" />
                     <p className="text-slate-500 font-bold text-lg">No closing history.</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const SummaryItem = ({ title, value, bangla, color, highlight }: any) => (
  <div className={`p-6 rounded-3xl border ${highlight ? 'bg-orange-500/5 border-orange-500/30 ring-2 ring-orange-500/10' : 'bg-slate-50 dark:bg-[#0a1120] border-slate-200 dark:border-slate-800'}`}>
    <h4 className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">{title}</h4>
    <p className="text-[10px] text-slate-500 mb-3">{bangla}</p>
