          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3.5 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg active:scale-95"
        >
          <Plus size={20} /> Add New Product
        </button>
      </div>

      <div className="bg-white dark:bg-[#1a2236] p-4 rounded-3xl border border-slate-200 dark:border-slate-800 flex flex-col md:flex-row gap-4 items-center shadow-sm">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
          <input 
            type="text" 
            placeholder="Search products by name..." 
            className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-orange-500/50 text-slate-900 dark:text-white placeholder-slate-400 focus:ring-2 focus:ring-orange-500/30 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Sort By:</span>
          <select 
            className="bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-slate-700 p-3.5 px-6 rounded-xl text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/30 cursor-pointer w-full md:w-48 text-sm"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
          >
            <option value="name_asc">Name (A-Z)</option>
            <option value="name_desc">Name (Z-A)</option>
            <option value="price_asc">Price (Low-High)</option>
            <option value="price_desc">Price (High-Low)</option>
          </select>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {confirmDeleteId && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 backdrop-blur-md z-[110] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-[#1a2236] p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-md animate-in zoom-in duration-300 text-center">
            <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-6 text-red-500">
              <AlertTriangle size={48} />
            </div>
            <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">আপনি কি নিশ্চিত?</h3>
            <p className="text-slate-500 dark:text-slate-400 mb-8">
              এই প্রোডাক্টটি ("{products.find(p => p.id === confirmDeleteId)?.name}") ডিলিট করলে এটি চিরতরে মুছে যাবে। আপনি কি নিশ্চিত যে আপনি এটি মুছে ফেলতে চান?
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={executeDelete}
                className="w-full bg-red-500 hover:bg-red-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-red-500/20 transition-all active:scale-95"
              >
                হ্যাঁ, ডিলিট করুন
              </button>
              <button 
                onClick={() => setConfirmDeleteId(null)}
                className="w-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-300 font-bold py-4 rounded-2xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-all"
              >
                না, ফিরে যান
              </button>
            </div>
          </div>
        </div>
      )}

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-[#0a1120]/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold flex items-center gap-3 text-slate-900 dark:text-white">
                 <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                   <Package size={20} />
                 </div>
                 {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={() => {setIsAdding(false); setEditingId(null);}} className="text-slate-400 hover:text-red-500 transition-colors">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Product Name</label>
                <input required type="text" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="e.g. Milk Bread" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Category</label>
                <select className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                  <option value="Bread">Bread</option>
                  <option value="Cake">Cake</option>
                  <option value="Cookies">Cookies</option>
                  <option value="Pastry">Pastry</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Price (৳) per {formData.unit}</label>
                <input required type="number" step="any" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Stock & Unit</label>
                <div className="flex gap-2">
                  <input required type="number" step="any" className="flex-1 p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  <div className="relative w-32">
                    <select 
                      className="w-full h-full p-4 pl-4 pr-10 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none appearance-none cursor-pointer" 
                      value={formData.unit} 
                      onChange={e => setFormData({...formData, unit: e.target.value})}
                    >
                      {units.map(u => <option key={u} value={u}>{u}</option>)}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
                  </div>
                </div>
              </div>
              <div className="md:col-span-2 flex justify-between items-center mt-6">
                {editingId && (
                  <button 
                    type="button" 
                    onClick={() => setConfirmDeleteId(editingId)}
                    className="flex items-center gap-2 text-red-500 font-bold hover:bg-red-50 dark:hover:bg-red-500/10 px-4 py-2 rounded-xl transition-all"
                  >
                    <Trash2 size={18} /> Delete Item
                  </button>
                )}
                <div className="flex gap-4 ml-auto">
                  <button type="button" onClick={() => {setIsAdding(false); setEditingId(null);}} className="px-8 py-3 text-slate-400 font-semibold hover:text-orange-500 transition-colors">Cancel</button>
                  <button type="submit" className="bg-orange-500 hover:bg-orange-600 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg transition-all active:scale-95">
                    {editingId ? 'Update Product' : 'Save Product'}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredProducts.map(p => (
          <div 
            key={p.id} 
            className={`bg-white dark:bg-[#1a2236] p-8 rounded-[1.5rem] border relative group transition-all shadow-sm hover:shadow-md ${
              p.stock < 10 
                ? 'border-red-500 dark:border-red-500/50 ring-2 ring-red-500/10' 
                : 'border-slate-200 dark:border-slate-800 hover:border-orange-500/30'
            }`}
          >
            <div className="flex items-center justify-between mb-4">
              <span className="bg-slate-100 dark:bg-[#212a3e] text-slate-500 dark:text-slate-400 px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                {p.category}
              </span>
              <div className="flex gap-2">
                <button 
                  onClick={() => handleEdit(p)} 
                  className="p-2.5 text-slate-400 hover:text-orange-500 transition-all bg-white dark:bg-[#0a1120] rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm active:scale-90"
                  title="Edit Product"
                >
                  <Edit3 size={16} />
                </button>
                <button 
                  onClick={() => setConfirmDeleteId(p.id)} 
                  className="p-2.5 text-red-500 hover:text-white bg-red-50 dark:bg-red-500/10 hover:bg-red-500 border border-red-100 dark:border-red-500/20 hover:border-red-500 transition-all rounded-xl shadow-sm active:scale-90"
                  title="Delete Product (মুছে ফেলুন)"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            <div className="absolute top-20 right-8 text-right">
               <div className="flex items-baseline justify-end gap-1 text-orange-500 dark:text-orange-400">
                 <span className="text-lg font-bold">৳</span>
                 <span className="text-3xl font-black">{p.price}</span>
               </div>
               <div className="text-[10px] text-slate-400 font-bold uppercase">per {p.unit || 'pcs'}</div>
            </div>

            <div className="mb-10 mt-2">
              <h4 className="text-2xl font-bold text-slate-900 dark:text-white group-hover:text-orange-500 transition-colors">
                {p.name}
              </h4>
              {p.stock < 10 && (
                <div className="flex items-center gap-1 text-red-500 font-black text-[10px] uppercase animate-pulse mt-1">
                  <AlertCircle size={12} /> Low Stock (মজুদ কম)
                </div>
              )}
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-400 font-semibold">Available Stock</span>
                <span className={`font-bold ${p.stock < 10 ? 'text-red-500' : 'text-slate-900 dark:text-white'}`}>
                  {p.stock} {p.unit || 'pcs'}
                </span>
              </div>
              <div className="h-3 w-full bg-slate-100 dark:bg-[#0a1120] rounded-full overflow-hidden border border-slate-200 dark:border-slate-800/50">
                <div 
                  className={`h-full transition-all duration-1000 ${p.stock < 10 ? 'bg-red-500' : 'bg-orange-500'}`} 
                  style={{ width: `${Math.min(100, (p.stock / 100) * 100)}%` }} 
                />
              </div>
            </div>
          </div>
        ))}
        {filteredProducts.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white dark:bg-[#1a2236] border border-slate-200 dark:border-slate-800 rounded-[2rem]">
             <Package size={48} className="mx-auto mb-4 opacity-10 text-slate-400" />
             <p className="text-slate-500 font-medium text-lg">No products found in inventory.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  LogOut,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  AlertTriangle
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  // Scoped Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // Low Stock Notification Logic
  const lowStockCount = useMemo(() => {
    return products.filter(p => p.stock < 10).length;
  }, [products]);

  // Theme Synchronizer
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Initial Auth Check
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  // Load User-Specific Data
  useEffect(() => {
    if (currentUser) {
      const prefix = `${currentUser}_`;

      const savedProducts = localStorage.getItem(`${prefix}products`);
      const savedSales = localStorage.getItem(`${prefix}sales`);
      const savedExpenses = localStorage.getItem(`${prefix}expenses`);
      const savedStaff = localStorage.getItem(`${prefix}staff`);
      const savedAttendance = localStorage.getItem(`${prefix}attendance`);
      const savedClosings = localStorage.getItem(`${prefix}closings`);
      const savedDeductions = localStorage.getItem(`${prefix}deductions`);

      setProducts(savedProducts ? JSON.parse(savedProducts) : [
        { id: '1', name: 'Full Bread', category: 'Bread', price: 60, stock: 20, unit: 'pcs' },
        { id: '2', name: 'Cake Chocolate Cup', category: 'Cake', price: 125, stock: 15, unit: 'pcs' },
        { id: '3', name: 'Atta (Flour)', category: 'Other', price: 55, stock: 100, unit: 'kg' },
      ]);
      setSales(savedSales ? JSON.parse(savedSales) : []);
      setExpenses(savedExpenses ? JSON.parse(savedExpenses) : []);
      setStaff(savedStaff ? JSON.parse(savedStaff) : []);
      setAttendance(savedAttendance ? JSON.parse(savedAttendance) : []);
      setDailyClosings(savedClosings ? JSON.parse(savedClosings) : []);
      setDeductions(savedDeductions ? JSON.parse(savedDeductions) : []);

      setIsDataLoaded(true);
    } else {
      setIsDataLoaded(false);
    }
  }, [currentUser]);

  // Save User-Specific Data
  useEffect(() => {
    if (isDataLoaded && currentUser) {
      const prefix = `${currentUser}_`;
      localStorage.setItem(`${prefix}products`, JSON.stringify(products));
      localStorage.setItem(`${prefix}sales`, JSON.stringify(sales));
      localStorage.setItem(`${prefix}expenses`, JSON.stringify(expenses));
      localStorage.setItem(`${prefix}staff`, JSON.stringify(staff));
      localStorage.setItem(`${prefix}attendance`, JSON.stringify(attendance));
      localStorage.setItem(`${prefix}closings`, JSON.stringify(dailyClosings));
      localStorage.setItem(`${prefix}deductions`, JSON.stringify(deductions));
    }
  }, [products, sales, expenses, staff, attendance, dailyClosings, deductions, currentUser, isDataLoaded]);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('sweetBakery_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setIsDataLoaded(false);
    sessionStorage.removeItem('sweetBakery_auth');
    setProducts([]);
    setSales([]);
    setExpenses([]);
    setStaff([]);
    setAttendance([]);
    setDailyClosings([]);
    setDeductions([]);
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const cancelSale = (saleId: string) => {
    const saleToCancel = sales.find(s => s.id === saleId);
    if (!saleToCancel) return;

    if (window.confirm(`আপনি কি এই বিক্রয়টি বাতিল করতে চান? (এটি বাতিল করলে "${saleToCancel.productName}" এর স্টক ফেরত যাবে)`)) {
      setSales(prev => prev.filter(s => s.id !== saleId));
      setProducts(prev => prev.map(p => 
        p.id === saleToCancel.productId 
          ? { ...p, stock: p.stock + saleToCancel.quantity } 
          : p
      ));
    }
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const updateSales = (updatedSales: Sale[]) => {
    setSales(prev => {
      const newSales = [...prev];
      updatedSales.forEach(updated => {
        const index = newSales.findIndex(s => s.id === updated.id);
        if (index !== -1) {
          newSales[index] = updated;
        }
      });
      return newSales;
    });
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    // Confirmation is now handled by the custom modal in Inventory component
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const addDeduction = (newDeduction: Deduction) => {
    setDeductions(prev => [...prev, newDeduction]);
  };

  const addDailyClosing = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
  };

  const deleteDailyClosing = (id: string) => {
    if (window.confirm('Delete this closing record? This will "Unlock" the transactions for that period. (আপনি কি নিশ্চিত? এটি ডিলিট করলে হিসাবগুলো আবার ড্যাশবোর্ডে ফিরে আসবে)')) {
      setDailyClosings(prev => prev.filter(c => c.id !== id));
    }
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);

    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    setDeductions(prev => prev.filter(d => {
      const dDate = new Date(d.date);
      return !(d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear);
    }));
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} theme={theme} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  const handleNavClick = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white ${isMobileMenuOpen ? 'overflow-hidden lg:overflow-auto' : ''}`}>
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 z-[60] lg:hidden backdrop-blur-sm animate-in fade-in duration-300"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`w-72 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-all duration-300 ease-in-out lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl shadow-orange-500/10' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
               <UtensilsCrossed size={20} className="text-white" />
            </div>
            <h1 className="text-xl font-bold text-orange-500 tracking-tight">Sweet Live</h1>
          </div>
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="lg:hidden p-2 text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-slate-800 rounded-xl transition-colors"
          >
             <X size={24} />
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-1.5 mt-2 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNavClick(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-200 group relative ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-500 dark:text-slate-400 hover:text-orange-500 dark:hover:text-white hover:bg-orange-50 dark:hover:bg-slate-800/50'
              }`}
            >
              <div className={`transition-transform duration-200 ${currentView === item.id ? 'scale-110' : 'group-hover:scale-110'}`}>
                {item.icon}
              </div>
              <div className="flex flex-col items-start leading-none flex-1">
                <span className="font-bold text-[14px]">{item.label}</span>
                {item.bangla && <span className="text-[10px] opacity-60 mt-0.5">{item.bangla}</span>}
              </div>
              {item.notification && item.notification > 0 && (
                <div className={`absolute right-4 top-1/2 -translate-y-1/2 flex items-center justify-center min-w-[20px] h-[20px] px-1 rounded-full text-[10px] font-black shadow-sm ${
                  currentView === item.id ? 'bg-white text-orange-600' : 'bg-red-500 text-white'
                }`}>
                  {item.notification}
                </div>
              )}
            </button>
          ))}
        </nav>

        <div className="p-6">
           {lowStockCount > 0 && (
             <div className="mb-4 p-4 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center gap-3 animate-pulse">
                <AlertTriangle size={18} className="text-red-500 shrink-0" />
                <p className="text-[10px] font-bold text-red-600 dark:text-red-400 uppercase leading-tight">
                  {lowStockCount} items are low on stock!
                </p>
             </div>
           )}
           <div className="bg-slate-100 dark:bg-[#161d31] p-5 rounded-2xl border border-slate-200 dark:border-slate-800 mb-6 group">
              <p className="text-[10px] text-orange-500 uppercase tracking-widest font-bold mb-1">Bakery Status</p>
              <h4 className="text-sm font-bold text-slate-900 dark:text-white">v2.4.0 <span className="text-emerald-500 ml-1">• Online</span></h4>
              <p className="text-[10px] text-slate-500 mt-2 truncate">User: <span className="text-slate-700 dark:text-slate-300 capitalize font-medium">{currentUser}</span></p>
           </div>
           <div className="text-[10px] text-slate-400 dark:text-slate-500 text-center font-bold uppercase tracking-widest opacity-60">
             © 2026 MD SHAMIM
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 w-full min-h-screen flex flex-col">
        <header className="sticky top-0 z-40 px-4 md:px-8 py-4 bg-slate-50/80 dark:bg-dark-bg/80 backdrop-blur-xl border-b border-slate-200/50 dark:border-slate-800/50 flex justify-between items-center">
          <div className="flex items-center gap-3 md:gap-4">
            <button 
              onClick={() => setIsMobileMenuOpen(true)} 
              className="lg:hidden p-2.5 text-orange-500 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm active:scale-90 transition-transform"
              aria-label="Open Menu"
            >
              <Menu size={24} />
            </button>
            <div className="hidden sm:flex w-12 h-12 md:w-14 md:h-14 bg-white dark:bg-[#161d31] rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center justify-center shadow-sm">
               <UtensilsCrossed size={24} className="text-orange-500" />
            </div>
            <div>
              <h2 className="text-xl md:text-2xl font-black tracking-tight text-slate-900 dark:text-white capitalize truncate max-w-[150px] xs:max-w-none">
                {currentView.toLowerCase().replace('_', ' ')}
              </h2>
              <p className="hidden xs:block text-slate-500 dark:text-slate-400 text-[10px] md:text-xs font-bold uppercase tracking-wider">
                Sweet Live Bakery <span className="text-orange-500 ml-1">• Pro App</span>
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-3">
             <button 
               onClick={toggleTheme}
               className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-orange-500 hover:bg-orange-50 dark:hover:bg-[#1e293b] transition-all shadow-sm active:scale-90"
               title="Toggle Theme"
             >
                {theme === 'dark' ? <SafeSun size={18} /> : <Moon size={18} />}
             </button>
             <button 
               onClick={handleLogout}
               className="h-10 md:h-12 px-4 md:px-6 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-red-500 font-bold flex items-center gap-2 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all shadow-sm text-sm active:scale-95"
             >
               <LogOut size={16} className="hidden xs:block" /> 
               <span>Logout</span>
             </button>
          </div>
        </header>

        <div className="p-4 md:p-8 flex-1">
          <section className="animate-in fade-in slide-in-from-bottom-2 duration-500 ease-out h-full">
            {!isDataLoaded ? (
              <div className="flex flex-col items-center justify-center h-96 text-slate-500">
                <div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin mb-4"></div>
                <p className="font-bold tracking-widest text-[10px] uppercase">Loading records...</p>
              </div>
            ) : (
              <>
                {currentView === View.DASHBOARD && (
                  <Dashboard products={products} sales={sales} expenses={expenses} closings={dailyClosings} />
                )}
                {currentView === View.INVENTORY && (
                  <Inventory products={products} onAdd={addProduct} onUpdate={updateProduct} onDelete={deleteProduct} />
                )}
                {currentView === View.SALES && (
                  <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={cancelSale} />
                )}
                {currentView === View.DUES && (
                  <DuesView sales={sales} onUpdateSales={updateSales} />
                )}
                {currentView === View.EXPENSES && (
                  <ExpensesView expenses={expenses} onAdd={addExpense} />
                )}
                {currentView === View.DAILY_CLOSING && (
                  <DailyClosingView 
                    sales={sales} 
                    expenses={expenses} 
                    closings={dailyClosings} 
                    onCloseDay={addDailyClosing} 
                    onDeleteClosing={deleteDailyClosing}
                    currentUser={currentUser} 
                  />
                )}
                {currentView === View.MANAGER && (
                  <ManagerView 
                    username={currentUser} 
                    onLogout={handleLogout} 
                    stats={{
                      products: products.length,
                      sales: sales.length,
                      expenses: expenses.length,
                      staff: staff.length
                    }}
                  />
                )}
                {currentView === View.STAFF && (
                  <StaffView 
                    staff={staff} 
                    attendance={attendance} 
                    expenses={expenses}
                    deductions={deductions}
                    onAddStaff={addStaffMember} 
                    onUpdateAttendance={updateAttendance} 
                    onAddDeduction={addDeduction}
                    onPaySalary={paySalary}
                  />
                )}
              </>
            )}
          </section>
        </div>
      </main>
    </div>
  );
};

const SafeSun = ({ size }: { size: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  LogOut,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  AlertTriangle
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  // Scoped Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // Low Stock Notification Logic
  const lowStockCount = useMemo(() => {
    return products.filter(p => p.stock < 10).length;
  }, [products]);

  // Theme Synchronizer
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Initial Auth Check
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth);
    }
  }, []);

  // Load User-Specific Data
  useEffect(() => {
    if (currentUser) {
      const prefix = `${currentUser}_`;

      const savedProducts = localStorage.getItem(`${prefix}products`);
      const savedSales = localStorage.getItem(`${prefix}sales`);
      const savedExpenses = localStorage.getItem(`${prefix}expenses`);
      const savedStaff = localStorage.getItem(`${prefix}staff`);
      const savedAttendance = localStorage.getItem(`${prefix}attendance`);
      const savedClosings = localStorage.getItem(`${prefix}closings`);
      const savedDeductions = localStorage.getItem(`${prefix}deductions`);

      setProducts(savedProducts ? JSON.parse(savedProducts) : [
        { id: '1', name: 'Full Bread', category: 'Bread', price: 60, stock: 20, unit: 'pcs' },
        { id: '2', name: 'Cake Chocolate Cup', category: 'Cake', price: 125, stock: 15, unit: 'pcs' },
        { id: '3', name: 'Atta (Flour)', category: 'Other', price: 55, stock: 100, unit: 'kg' },
      ]);
      setSales(savedSales ? JSON.parse(savedSales) : []);
      setExpenses(savedExpenses ? JSON.parse(savedExpenses) : []);
      setStaff(savedStaff ? JSON.parse(savedStaff) : []);
      setAttendance(savedAttendance ? JSON.parse(savedAttendance) : []);
      setDailyClosings(savedClosings ? JSON.parse(savedClosings) : []);
      setDeductions(savedDeductions ? JSON.parse(savedDeductions) : []);

      setIsDataLoaded(true);
    } else {
      setIsDataLoaded(false);
    }
  }, [currentUser]);

  // Save User-Specific Data
  useEffect(() => {
    if (isDataLoaded && currentUser) {
      const prefix = `${currentUser}_`;
      localStorage.setItem(`${prefix}products`, JSON.stringify(products));
      localStorage.setItem(`${prefix}sales`, JSON.stringify(sales));
      localStorage.setItem(`${prefix}expenses`, JSON.stringify(expenses));
      localStorage.setItem(`${prefix}staff`, JSON.stringify(staff));
      localStorage.setItem(`${prefix}attendance`, JSON.stringify(attendance));
      localStorage.setItem(`${prefix}closings`, JSON.stringify(dailyClosings));
      localStorage.setItem(`${prefix}deductions`, JSON.stringify(deductions));
    }
  }, [products, sales, expenses, staff, attendance, dailyClosings, deductions, currentUser, isDataLoaded]);

  const handleLogin = (username: string) => {
    setIsAuthenticated(true);
    setCurrentUser(username);
    sessionStorage.setItem('sweetBakery_auth', username);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setIsDataLoaded(false);
    sessionStorage.removeItem('sweetBakery_auth');
    setProducts([]);
    setSales([]);
    setExpenses([]);
    setStaff([]);
    setAttendance([]);
    setDailyClosings([]);
    setDeductions([]);
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const cancelSale = (saleId: string) => {
    const saleToCancel = sales.find(s => s.id === saleId);
    if (!saleToCancel) return;

    if (window.confirm(`আপনি কি এই বিক্রয়টি বাতিল করতে চান? (এটি বাতিল করলে "${saleToCancel.productName}" এর স্টক ফেরত যাবে)`)) {
      setSales(prev => prev.filter(s => s.id !== saleId));
      setProducts(prev => prev.map(p => 
        p.id === saleToCancel.productId 
          ? { ...p, stock: p.stock + saleToCancel.quantity } 
          : p
      ));
    }
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const updateSales = (updatedSales: Sale[]) => {
    setSales(prev => {
      const newSales = [...prev];
      updatedSales.forEach(updated => {
        const index = newSales.findIndex(s => s.id === updated.id);
        if (index !== -1) {
          newSales[index] = updated;
        }
      });
      return newSales;
    });
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    // Confirmation is now handled by the custom modal in Inventory component
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const addDeduction = (newDeduction: Deduction) => {
    setDeductions(prev => [...prev, newDeduction]);
  };

  const addDailyClosing = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
  };

  const deleteDailyClosing = (id: string) => {
    if (window.confirm('Delete this closing record? This will "Unlock" the transactions for that period. (আপনি কি নিশ্চিত? এটি ডিলিট করলে হিসাবগুলো আবার ড্যাশবোর্ডে ফিরে আসবে)')) {
      setDailyClosings(prev => prev.filter(c => c.id !== id));
    }
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);

    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    setDeductions(prev => prev.filter(d => {
      const dDate = new Date(d.date);
      return !(d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear);
    }));
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} theme={theme} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  const handleNavClick = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white ${isMobileMenuOpen ? 'overflow-hidden lg:overflow-auto' : ''}`}>
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 z-[60] lg:hidden backdrop-blur-sm animate-in fade-in duration-300"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`w-72 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-all duration-300 ease-in-out lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl shadow-orange-500/10' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
               <UtensilsCrossed size={20} className="text-white" />
            </div>
            <h1 className="text-xl font-bold text-orange-500 tracking-tight leading-tight">Sweet Live<br/><span className="text-lg">Bakery</span></h1>
          </div>
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="lg:hidden p-2 text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-slate-800 rounded-xl transition-colors"
          >
             <X size={24} />
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-1.5 mt-2 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNavClick(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-200 group relative ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-500 dark:text-slate-400 hover:text-orange-500 dark:hover:text-white hover:bg-orange-50 dark:hover:bg-slate-800/50'
              }`}
            >
              <div className={`transition-transform duration-200 ${currentView === item.id ? 'scale-110' : 'group-hover:scale-110'}`}>
                {item.icon}
              </div>
              <div className="flex flex-col items-start leading-none flex-1">
                <span className="font-bold text-[14px]">{item.label}</span>
                {item.bangla && <span className="text-[10px] opacity-60 mt-0.5">{item.bangla}</span>}
              </div>
              {item.notification && item.notification > 0 && (
                <div className={`absolute right-4 top-1/2 -translate-y-1/2 flex items-center justify-center min-w-[20px] h-[20px] px-1 rounded-full text-[10px] font-black shadow-sm ${
                  currentView === item.id ? 'bg-white text-orange-600' : 'bg-red-500 text-white'
                }`}>
                  {item.notification}
                </div>
              )}
            </button>
          ))}
        </nav>

        <div className="p-6">
           {lowStockCount > 0 && (
             <div className="mb-4 p-4 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center gap-3 animate-pulse">
                <AlertTriangle size={18} className="text-red-500 shrink-0" />
                <p className="text-[10px] font-bold text-red-600 dark:text-red-400 uppercase leading-tight">
                  {lowStockCount} items are low on stock!
                </p>
             </div>
           )}
           <div className="bg-slate-100 dark:bg-[#161d31] p-5 rounded-2xl border border-slate-200 dark:border-slate-800 mb-6 group">
              <p className="text-[10px] text-orange-500 uppercase tracking-widest font-bold mb-1">Bakery Status</p>
              <h4 className="text-sm font-bold text-slate-900 dark:text-white">v2.4.0 <span className="text-emerald-500 ml-1">• Online</span></h4>
              <p className="text-[10px] text-slate-500 mt-2 truncate">User: <span className="text-slate-700 dark:text-slate-300 capitalize font-medium">{currentUser}</span></p>
           </div>
           <div className="text-[10px] text-slate-400 dark:text-slate-500 text-center font-bold uppercase tracking-widest opacity-60">
             © 2026 MD SHAMIM
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 w-full min-h-screen flex flex-col">
        <header className="sticky top-0 z-40 px-4 md:px-8 py-4 bg-slate-50/80 dark:bg-dark-bg/80 backdrop-blur-xl border-b border-slate-200/50 dark:border-slate-800/50 flex justify-between items-center">
          <div className="flex items-center gap-3 md:gap-4">
            <button 
