interface Props {
  products: Product[];
  sales: Sale[];
  expenses: Expense[];
  closings?: DailyClosing[];
}

const Dashboard: React.FC<Props> = ({ products, sales, expenses, closings = [] }) => {
  // Find the timestamp of the very last closing done
  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  // Active Session Totals (Items added AFTER the last closing)
  const activeSessionStats = useMemo(() => {
    const activeSales = sales.filter(s => new Date(s.date).getTime() > lastClosingTimestamp);
    const activeExpenses = expenses.filter(e => new Date(e.date).getTime() > lastClosingTimestamp);

    const totalSalesVolume = activeSales.reduce((acc, s) => acc + s.totalPrice, 0);
    const totalCashCollected = activeSales.reduce((acc, s) => acc + s.amountPaid, 0);
    const totalExpenses = activeExpenses.reduce((acc, e) => acc + e.amount, 0);
    const totalDues = activeSales.reduce((acc, s) => acc + s.dueAmount, 0);

    // Main Balance = Cash in hand (Cash collected - Expenses)
    const mainBalance = totalCashCollected - totalExpenses;

    return {
      salesVolume: totalSalesVolume,
      cashCollected: totalCashCollected,
      expenses: totalExpenses,
      mainBalance: mainBalance,
      dues: totalDues
    };
  }, [sales, expenses, lastClosingTimestamp]);

  const productPerformanceData = products.map((p, idx) => {
    const soldCount = sales
      .filter(s => s.productId === p.id)
      .reduce((acc, s) => acc + s.quantity, 0);
    return {
      name: p.name,
      value: soldCount * p.price,
      color: idx % 2 === 0 ? '#f59e0b' : '#10b981'
    };
  });

  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    const daySales = sales
      .filter(s => s.date.startsWith(dateStr))
      .reduce((acc, curr) => acc + curr.totalPrice, 0);
    return { 
      name: d.toLocaleDateString([], { month: 'numeric', day: 'numeric' }), 
      sales: daySales 
    };
  }).reverse();

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Bakery Branding Welcome Section */}
      <div className="bg-white dark:bg-[#161d31] p-8 md:p-12 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm relative overflow-hidden flex flex-col md:flex-row items-center justify-between gap-8 group">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:scale-110 transition-transform duration-700">
             <UtensilsCrossed size={300} className="text-orange-500" />
          </div>
          <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 text-center md:text-left">
             <div className="w-20 h-20 bg-orange-500 rounded-3xl flex items-center justify-center shadow-lg shadow-orange-500/20">
                <UtensilsCrossed size={40} className="text-white" />
             </div>
             <div>
                <h1 className="text-3xl md:text-5xl font-black text-slate-900 dark:text-white tracking-tighter mb-2">Sweet Live Bakery</h1>
                <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-xs">Smart Management Dashboard</p>
             </div>
          </div>
          <div className="relative z-10 flex gap-4">
             <div className="bg-slate-50 dark:bg-[#0a1120] p-4 px-8 rounded-2xl border border-slate-200 dark:border-slate-800 text-center">
                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Status</div>
                <div className="text-emerald-500 font-black flex items-center gap-2">
                   <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" /> ONLINE
                </div>
             </div>
          </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-orange-500 rounded-lg text-white shadow-lg shadow-orange-500/20">
            <Clock size={18} />
          </div>
          <div>
            <h2 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Active Session (বর্তমান হিসাব)</h2>
            <p className="text-[10px] text-slate-400">Showing data since last daily closing</p>
          </div>
        </div>
      </div>

      {/* Primary Metrics Row - Updated grid to 4 columns */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <StatCard title="Sales Volume" value={activeSessionStats.salesVolume} type="neutral" bangla="মোট বিক্রি" />
        <StatCard title="Cash Collected" value={activeSessionStats.cashCollected} type="revenue" bangla="নগদ আদায়" />
        <StatCard title="Expenses" value={activeSessionStats.expenses} type="expense" bangla="মোট খরচ" />
        <StatCard title="Main Balance" value={activeSessionStats.mainBalance} type="balance" bangla="মেইন ব্যালেন্স" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Reports Section */}
        <div className="lg:col-span-4 bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl flex flex-col justify-center">
