          </div>
          <div className="space-y-3">
            <ReportButton onClick={() => {}} icon={<ShoppingCart size={18}/>} label="Sales Data" color="orange" />
            <ReportButton onClick={() => {}} icon={<Package size={18}/>} label="Stock List" color="emerald" />
            <ReportButton onClick={() => {}} icon={<ReceiptIndianRupee size={18}/>} label="Expense List" color="red" />
          </div>
        </div>

        {/* Sales Trend Chart */}
        <div className="lg:col-span-8 bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl overflow-hidden">
          <div className="flex items-center justify-between mb-8">
             <h3 className="text-xl font-bold text-slate-900 dark:text-slate-200 flex items-center gap-2">
               <TrendingUp size={20} className="text-orange-500" />
               Weekly Sales Trend
             </h3>
             <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">Last 7 Days</span>
          </div>
          <div className="h-64 md:h-72">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={last7Days}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} dx={-10} />
                <Tooltip 
                   contentStyle={{ backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px' }}
                />
                <Line 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#f59e0b" 
                  strokeWidth={4} 
                  dot={{ fill: '#f59e0b', strokeWidth: 2, r: 5 }} 
                  activeDot={{ r: 8, strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const ReportButton = ({ onClick, icon, label, color }: any) => {
  const colors: any = {
    orange: 'bg-orange-500/10 text-orange-600 dark:text-orange-400 border-orange-500/20 hover:bg-orange-500 hover:text-white',
    emerald: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20 hover:bg-emerald-500 hover:text-white',
    red: 'bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/20 hover:bg-red-500 hover:text-white'
  };

  return (
    <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl border transition-all duration-300 font-bold text-sm ${colors[color]}`}>
      {icon} <span>{label}</span>
    </button>
  );
};

const StatCard: React.FC<{ 
  title: string; 
  value: number; 
  type: 'revenue' | 'expense' | 'profit' | 'balance' | 'neutral';
  bangla: string;
}> = ({ title, value, type, bangla }) => {
  const isNegative = value < 0;
  const displayValue = Math.abs(value).toLocaleString();

  const getStyles = () => {
    switch(type) {
      case 'revenue': return 'text-emerald-500 border-emerald-500/20';
      case 'expense': return 'text-red-500 border-red-500/20';
      case 'profit': return isNegative ? 'text-red-500 border-red-500/20' : 'text-orange-500 border-orange-500/20';
      case 'balance': return 'text-orange-500 border-orange-500/30 bg-orange-500/5';
      default: return 'text-slate-900 dark:text-white border-slate-200 dark:border-slate-800';
    }
  };

  return (
    <div className={`bg-white dark:bg-[#161d31] p-6 rounded-[2rem] border transition-all duration-300 shadow-sm ${type === 'balance' ? 'ring-2 ring-orange-500/20' : ''}`}>
      <div className="flex flex-col h-full">
        <h4 className="text-slate-400 dark:text-[#94a3b8] font-bold text-[9px] mb-1 tracking-wider uppercase">{title}</h4>
        <div className="text-[10px] font-medium text-slate-500 dark:text-slate-400 mb-3">{bangla}</div>
        <div className="mt-auto flex items-baseline gap-1">
          <span className={`text-lg font-bold ${getStyles()}`}>৳</span>
          <span className={`text-2xl md:text-3xl font-black tracking-tighter truncate ${getStyles()}`}>
            {isNegative ? '-' : ''}{displayValue}
          </span>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

