            </div>
          </div>
          <div className="space-y-3">
            <ReportButton onClick={handleExportSales} icon={<ShoppingCart size={18}/>} label="Sales Data" color="orange" bangla="বিক্রয় তালিকা" />
            <ReportButton onClick={handleExportStock} icon={<Package size={18}/>} label="Stock List" color="emerald" bangla="মজুদ তালিকা" />
