import React, { useMemo } from 'react';
import { Product, Sale, Expense, DailyClosing } from '../types';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  LineChart,
  Line,
  Cell
} from 'recharts';
import { FileDown, ShoppingCart, Package, ReceiptIndianRupee, Wallet, Clock, ArrowRightLeft, TrendingUp, UtensilsCrossed, Monitor } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  expenses: Expense[];
  closings?: DailyClosing[];
  onInstall?: () => void;
  showInstallButton?: boolean;
}

const Dashboard: React.FC<Props> = ({ products, sales, expenses, closings = [], onInstall, showInstallButton }) => {
  // Find the timestamp of the very last closing done
  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  // Active Session Totals (Items added AFTER the last closing)
  const activeSessionStats = useMemo(() => {
    const activeSales = sales.filter(s => new Date(s.date).getTime() > lastClosingTimestamp);
    const activeExpenses = expenses.filter(e => new Date(e.date).getTime() > lastClosingTimestamp);

    const totalSalesVolume = activeSales.reduce((acc, s) => acc + s.totalPrice, 0);
    const totalCashCollected = activeSales.reduce((acc, s) => acc + s.amountPaid, 0);
    const totalExpenses = activeExpenses.reduce((acc, e) => acc + e.amount, 0);
    const totalDues = activeSales.reduce((acc, s) => acc + s.dueAmount, 0);

    // Main Balance = Cash in hand (Cash collected - Expenses)
    const mainBalance = totalCashCollected - totalExpenses;

    return {
      salesVolume: totalSalesVolume,
      cashCollected: totalCashCollected,
      expenses: totalExpenses,
      mainBalance: mainBalance,
      dues: totalDues
    };
  }, [sales, expenses, lastClosingTimestamp]);

  // CSV Export Logic
  const downloadCSV = (filename: string, headers: string[], rows: any[][]) => {
    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(val => `"${String(val).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `${filename}_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportSales = () => {
    if (sales.length === 0) return alert('ডাউনলোড করার জন্য কোনো বিক্রয় তথ্য নেই।');
    const headers = ['Date', 'Product', 'Quantity', 'Unit', 'Total Price', 'Paid', 'Due', 'Customer', 'Payment Method'];
    const rows = sales.map(s => [
      new Date(s.date).toLocaleDateString(),
      s.productName,
      s.quantity,
      s.unit,
      s.totalPrice,
      s.amountPaid,
      s.dueAmount,
      s.customerName || 'N/A',
      s.paymentMethod
    ]);
    downloadCSV('Sales_Report', headers, rows);
  };

  const handleExportStock = () => {
    if (products.length === 0) return alert('ডাউনলোড করার জন্য কোনো স্টোক তথ্য নেই।');
    const headers = ['Product Name', 'Category', 'Price', 'Current Stock', 'Unit'];
    const rows = products.map(p => [
      p.name,
      p.category,
      p.price,
      p.stock,
      p.unit
    ]);
    downloadCSV('Stock_Inventory_Report', headers, rows);
  };

  const handleExportExpenses = () => {
    if (expenses.length === 0) return alert('ডাউনলোড করার জন্য কোনো খরচের তথ্য নেই।');
    const headers = ['Date', 'Description', 'Category', 'Amount'];
    const rows = expenses.map(e => [
      new Date(e.date).toLocaleDateString(),
      e.description,
      e.category,
      e.amount
    ]);
    downloadCSV('Expenses_Report', headers, rows);
  };

  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    const daySales = sales
      .filter(s => s.date.startsWith(dateStr))
      .reduce((acc, curr) => acc + curr.totalPrice, 0);
    return { 
      name: d.toLocaleDateString([], { month: 'numeric', day: 'numeric' }), 
      sales: daySales 
    };
  }).reverse();

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Desktop Install Prompt - Professional Banner */}
      {showInstallButton && (
        <div className="bg-orange-500 p-6 md:p-8 rounded-[2rem] border-4 border-white/20 shadow-2xl shadow-orange-500/30 flex flex-col md:flex-row items-center justify-between gap-6 overflow-hidden relative group">
           <div className="absolute -right-10 -bottom-10 opacity-10 group-hover:scale-110 transition-transform duration-700">
              <Monitor size={200} className="text-white" />
           </div>
           <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 text-center md:text-left">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md">
                 <Monitor size={32} className="text-white" />
              </div>
              <div>
                 <h2 className="text-xl md:text-2xl font-black text-white tracking-tight">Install Desktop Application</h2>
                 <p className="text-orange-50 font-medium text-sm">আপনার পিসিতে সফটওয়্যার হিসেবে সেভ করুন এবং দ্রুত কাজ করুন।</p>
              </div>
           </div>
           <button 
             onClick={onInstall}
             className="relative z-10 w-full md:w-auto bg-white text-orange-500 hover:bg-orange-50 px-10 py-4 rounded-2xl font-black shadow-lg transition-all active:scale-95 flex items-center justify-center gap-3"
           >
              INSTALL APP (সেভ করুন)
           </button>
        </div>
      )}

      {/* Bakery Branding Welcome Section */}
      <div className="bg-white dark:bg-[#161d31] p-8 md:p-12 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm relative overflow-hidden flex flex-col md:flex-row items-center justify-between gap-8 group">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:scale-110 transition-transform duration-700">
             <UtensilsCrossed size={300} className="text-orange-500" />
          </div>
          <div className="relative z-10 flex flex-col md:flex-row items-center gap-6 text-center md:text-left">
             <div className="w-20 h-20 bg-orange-500 rounded-3xl flex items-center justify-center shadow-lg shadow-orange-500/20">
                <UtensilsCrossed size={40} className="text-white" />
             </div>
             <div>
                <h1 className="text-3xl md:text-5xl font-black text-slate-900 dark:text-white tracking-tighter mb-2">Sweet Live Bakery</h1>
                <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-xs">Smart Management Dashboard</p>
             </div>
          </div>
          <div className="relative z-10 flex gap-4">
             <div className="bg-slate-50 dark:bg-[#0a1120] p-4 px-8 rounded-2xl border border-slate-200 dark:border-slate-800 text-center">
                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Status</div>
                <div className="text-emerald-500 font-black flex items-center gap-2">
                   <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" /> ONLINE
                </div>
             </div>
          </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-orange-500 rounded-lg text-white shadow-lg shadow-orange-500/20">
            <Clock size={18} />
          </div>
          <div>
            <h2 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Active Session (বর্তমান হিসাব)</h2>
            <p className="text-[10px] text-slate-400">Showing data since last daily closing</p>
          </div>
        </div>
      </div>

      {/* Primary Metrics Row - Updated grid to 4 columns */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <StatCard title="Sales Volume" value={activeSessionStats.salesVolume} type="neutral" bangla="মোট বিক্রি" />
        <StatCard title="Cash Collected" value={activeSessionStats.cashCollected} type="revenue" bangla="নগদ আদায়" />
        <StatCard title="Expenses" value={activeSessionStats.expenses} type="expense" bangla="মোট খরচ" />
        <StatCard title="Main Balance" value={activeSessionStats.mainBalance} type="balance" bangla="মেইন ব্যালেন্স" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Reports Section - Updated with working download functions */}
        <div className="lg:col-span-4 bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl flex flex-col justify-center">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-3 bg-orange-500/10 rounded-2xl text-orange-500">
              <FileDown size={28} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900 dark:text-200">Download Reports</h3>
              <p className="text-xs text-slate-500 font-medium">রিপোর্ট ডাউনলোড করুন</p>
            </div>
          </div>
          <div className="space-y-3">
            <ReportButton onClick={handleExportSales} icon={<ShoppingCart size={18}/>} label="Sales Data" color="orange" bangla="বিক্রয় তালিকা" />
            <ReportButton onClick={handleExportStock} icon={<Package size={18}/>} label="Stock List" color="emerald" bangla="মজুদ তালিকা" />
            <ReportButton onClick={handleExportExpenses} icon={<ReceiptIndianRupee size={18}/>} label="Expense List" color="red" bangla="খরচের তালিকা" />
          </div>
        </div>

        {/* Sales Trend Chart */}
        <div className="lg:col-span-8 bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl overflow-hidden">
          <div className="flex items-center justify-between mb-8">
             <h3 className="text-xl font-bold text-slate-900 dark:text-slate-200 flex items-center gap-2">
               <TrendingUp size={20} className="text-orange-500" />
               Weekly Sales Trend
             </h3>
             <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">Last 7 Days</span>
          </div>
          <div className="h-64 md:h-72">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={last7Days}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} dx={-10} />
                <Tooltip 
                   contentStyle={{ backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px' }}
                />
                <Line 
                  type="monotone" 
                  dataKey="sales" 
                  stroke="#f59e0b" 
                  strokeWidth={4} 
                  dot={{ fill: '#f59e0b', strokeWidth: 2, r: 5 }} 
                  activeDot={{ r: 8, strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const ReportButton = ({ onClick, icon, label, color, bangla }: any) => {
  const colors: any = {
    orange: 'bg-orange-500/10 text-orange-600 dark:text-orange-400 border-orange-500/20 hover:bg-orange-500 hover:text-white',
    emerald: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20 hover:bg-emerald-500 hover:text-white',
    red: 'bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/20 hover:bg-red-500 hover:text-white'
  };

  return (
    <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl border transition-all duration-300 font-bold ${colors[color]}`}>
      <div className="p-2 bg-white/20 dark:bg-black/10 rounded-lg">
        {icon}
      </div>
      <div className="flex flex-col items-start leading-tight">
        <span className="text-sm">{label}</span>
        {bangla && <span className="text-[9px] opacity-70 font-medium">{bangla}</span>}
      </div>
    </button>
  );
};

const StatCard: React.FC<{ 
  title: string; 
  value: number; 
  type: 'revenue' | 'expense' | 'profit' | 'balance' | 'neutral';
  bangla: string;
}> = ({ title, value, type, bangla }) => {
  const isNegative = value < 0;
  const displayValue = Math.abs(value).toLocaleString();

  const getStyles = () => {
    switch(type) {
      case 'revenue': return 'text-emerald-500 border-emerald-500/20';
      case 'expense': return 'text-red-500 border-red-500/20';
      case 'profit': return isNegative ? 'text-red-500 border-red-500/20' : 'text-orange-500 border-orange-500/20';
      case 'balance': return 'text-orange-500 border-orange-500/30 bg-orange-500/5';
      default: return 'text-slate-900 dark:text-white border-slate-200 dark:border-slate-800';
    }
  };

  return (
    <div className={`bg-white dark:bg-[#161d31] p-6 rounded-[2rem] border transition-all duration-300 shadow-sm ${type === 'balance' ? 'ring-2 ring-orange-500/20' : ''}`}>
      <div className="flex flex-col h-full">
        <h4 className="text-slate-400 dark:text-[#94a3b8] font-bold text-[9px] mb-1 tracking-wider uppercase">{title}</h4>
        <div className="text-[10px] font-medium text-slate-500 dark:text-slate-400 mb-3">{bangla}</div>
        <div className="mt-auto flex items-baseline gap-1">
          <span className={`text-lg font-bold ${getStyles()}`}>৳</span>
          <span className={`text-2xl md:text-3xl font-black tracking-tighter truncate ${getStyles()}`}>
            {isNegative ? '-' : ''}{displayValue}
          </span>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

