import React, { useMemo } from 'react';
import { Sale, Expense, DailyClosing } from '../types';
import { 
  Lock, 
  History, 
  Trash2, 
  Clock,
  LockOpen,
  FileDown,
  RotateCcw
} from 'lucide-react';

interface Props {
  sales: Sale[];
  expenses: Expense[];
  closings: DailyClosing[];
  onCloseDay: (closing: DailyClosing) => void;
  onDeleteClosing: (id: string) => void;
  currentUser: string;
}

const DailyClosingView: React.FC<Props> = ({ sales, expenses, closings, onCloseDay, onDeleteClosing, currentUser }) => {
  const today = new Date().toISOString().split('T')[0];

  // Find the timestamp of the very last closing done
  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  const activeStats = useMemo(() => {
    // Only include items added AFTER the last closing
    const activeSales = sales.filter(s => new Date(s.date).getTime() > lastClosingTimestamp);
    const activeExpenses = expenses.filter(e => new Date(e.date).getTime() > lastClosingTimestamp);

    const totalSalesVolume = activeSales.reduce((sum, s) => sum + s.totalPrice, 0);
    const totalCashCollected = activeSales.reduce((sum, s) => sum + s.amountPaid, 0);
    const totalExpenses = activeExpenses.reduce((sum, e) => sum + e.amount, 0);
    const totalProfit = totalSalesVolume - totalExpenses;
    const mainBalance = totalCashCollected - totalExpenses;

    return {
      sales: totalSalesVolume,
      cash: totalCashCollected,
      expenses: totalExpenses,
      profit: totalProfit,
      balance: mainBalance,
      count: activeSales.length + activeExpenses.length
    };
  }, [sales, expenses, lastClosingTimestamp]);

  const handleCloseDay = () => {
    const confirmMsg = activeStats.count === 0 
      ? 'No new transactions found. Close anyway? (নতুন কোনো হিসাব নেই। তবুও কি ক্লোজিং করতে চান?)'
      : 'This will reset all dashboard counters to zero. Proceed? (ক্লোজিং করলে ড্যাশবোর্ডের হিসাব ০ হয়ে যাবে। আপনি কি নিশ্চিত?)';

    if (window.confirm(confirmMsg)) {
      const newClosing: DailyClosing = {
        id: Date.now().toString(),
        date: today,
        totalSales: activeStats.sales,
        totalExpenses: activeStats.expenses,
        netProfit: activeStats.profit,
        closedBy: currentUser,
        timestamp: new Date().toISOString()
      };
      onCloseDay(newClosing);
    }
  };

  const handleUndoLast = () => {
    if (closings.length === 0) return;
    const lastClosing = [...closings].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];
    if (window.confirm(`আপনি কি শেষ ক্লোজিংটি (${new Date(lastClosing.timestamp).toLocaleTimeString()}) বাতিল করতে চান? এটি করলে আগের সব হিসাব আবার ফিরে আসবে।`)) {
      onDeleteClosing(lastClosing.id);
    }
  };

  const handleDownloadHistory = () => {
    if (closings.length === 0) return;
    const headers = ['Date', 'Manager', 'Sales', 'Expenses'];
    const csvContent = [
      headers.join(','),
      ...closings.map(c => [
        new Date(c.date).toLocaleDateString(),
        c.closedBy,
        c.totalSales,
        c.totalExpenses
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Closing_History.csv';
    a.click();
  };

  const handleDownloadActiveSummary = () => {
    const headers = ['Report Item', 'Amount (BDT)'];
    const rows = [
      ['Total Sales Volume', activeStats.sales],
      ['Cash Collected', activeStats.cash],
      ['Total Expenses', activeStats.expenses],
      ['Main Balance (Cash in Hand)', activeStats.balance],
      ['Report Date', new Date().toLocaleString()],
      ['Manager', currentUser]
    ];

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Daily_Closing_Summary_${today}.csv`;
    a.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Current Day Closing Card */}
      <div className="bg-white dark:bg-[#161d31] p-6 md:p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-[0.03]">
           <LockOpen size={220} className="text-orange-500" />
        </div>

        <div className="relative z-10">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className="bg-orange-500 text-white px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest">
                  Ready to Close
                </span>
                <h2 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white tracking-tight">Daily Closing (দৈনিক ক্লোজিং)</h2>
              </div>
              <p className="text-slate-500 dark:text-slate-400 font-medium flex items-center gap-2">
                <Clock size={16} className="text-orange-500" />
                Review current session totals before resetting
              </p>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
              {closings.length > 0 && (
                <button 
                  onClick={handleUndoLast}
                  className="w-full sm:w-auto bg-red-500/10 hover:bg-red-500 text-red-500 hover:text-white px-6 py-4 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all border border-red-500/20"
                  title="Unlock previous closing"
                >
                  <RotateCcw size={18} /> Undo Last (আনলক)
                </button>
              )}
              <button 
                onClick={handleDownloadActiveSummary}
                className="w-full sm:w-auto bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 px-6 py-4 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all"
              >
                <FileDown size={18} /> Download Summary
              </button>
              <button 
                onClick={handleCloseDay}
                className="w-full md:w-auto bg-orange-500 hover:bg-orange-600 text-white px-10 py-4 rounded-2xl font-bold flex items-center justify-center gap-3 shadow-[0_10px_30px_rgba(249,115,22,0.3)] active:scale-95 transition-all group"
              >
                <Lock size={20} className="group-hover:scale-110 transition-transform" /> 
                Close Account & Reset
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <SummaryItem title="Sales Volume" value={activeStats.sales} bangla="মোট বিক্রি" color="text-slate-600 dark:text-slate-300" />
            <SummaryItem title="Cash Collected" value={activeStats.cash} bangla="নগদ আদায়" color="text-emerald-500" />
            <SummaryItem title="Expenses" value={activeStats.expenses} bangla="মোট খরচ" color="text-red-500" />
            <SummaryItem title="Main Balance" value={activeStats.balance} bangla="মেইন ব্যালেন্স" color="text-orange-600 dark:text-orange-400" highlight />
          </div>

          <div className="mt-10 p-6 bg-slate-50 dark:bg-[#0a1120]/50 rounded-3xl border border-slate-200 dark:border-slate-800 text-center">
             <p className="text-sm text-slate-500 italic">
                {activeStats.count === 0 
                  ? "Everything is clear. (হিসাব পরিষ্কার আছে)"
                  : `Closing will move these ৳${activeStats.cash.toLocaleString()} records to history and start a fresh session with ৳0.`
                }
             </p>
          </div>
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white dark:bg-[#161d31] rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm dark:shadow-xl overflow-hidden">
        <div className="px-10 py-8 border-b border-slate-200 dark:border-slate-800 flex flex-col md:flex-row items-center justify-between gap-4">
          <h3 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-3">
