                  <td className="px-10 py-6 font-bold text-slate-900 dark:text-white">৳{c.totalSales.toLocaleString()}</td>
                  <td className="px-10 py-6 font-bold text-slate-600 dark:text-slate-400">৳{c.totalExpenses.toLocaleString()}</td>
                  <td className="px-10 py-6 text-right">
                    <button 
