import React, { useState } from 'react';
import { UtensilsCrossed, Lock, User, UserPlus, LogIn, ChevronRight, AlertCircle } from 'lucide-react';

interface Props {
  onLogin: (username: string) => void;
  theme: 'dark' | 'light';
}

interface UserData {
  username: string;
  password: string;
  role: string;
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const getUsers = (): UserData[] => {
    const users = localStorage.getItem('sweetBakery_users');
    return users ? JSON.parse(users) : [];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // Normalize username to lowercase to prevent case conflicts
    const normalizedUsername = username.trim().toLowerCase();
    const users = getUsers();

    if (isSignup) {
      if (normalizedUsername.length < 3 || password.length < 4) {
        setError('ইউজারনেম অন্তত ৩ অক্ষর এবং পাসওয়ার্ড ৪ অক্ষরের হতে হবে।');
        return;
      }

      const userExists = users.some(u => u.username === normalizedUsername);
      if (userExists) {
        setError('এই ইউজারনেমটি ইতিমধ্যে ব্যবহার করা হয়েছে। অন্য নাম চেষ্টা করুন।');
        return;
      }

      const newUser: UserData = { 
        username: normalizedUsername, 
        password, 
        role: 'Manager' 
      };

      localStorage.setItem('sweetBakery_users', JSON.stringify([...users, newUser]));
      setSuccess('রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন।');
      setIsSignup(false);
      setPassword('');
      // Reset form
      setUsername('');
    } else {
      const user = users.find(u => u.username === normalizedUsername && u.password === password);
      if (user) {
        // Success: Trigger login
        onLogin(normalizedUsername);
      } else {
        setError('ইউজারনেম বা পাসওয়ার্ড সঠিক নয়। দয়া করে আবার চেষ্টা করুন।');
      }
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 transition-colors duration-300">
      <div className="mb-10 text-center flex flex-col items-center">
        <div className="w-24 h-24 bg-white dark:bg-[#161d31] rounded-2xl flex items-center justify-center shadow-md dark:shadow-[0_0_30px_rgba(249,115,22,0.1)] mb-6 border border-slate-200 dark:border-[#2e374d]">
          <div className="p-4 bg-orange-500/10 rounded-xl">
             <UtensilsCrossed size={48} className="text-orange-500" />
          </div>
        </div>
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white tracking-tight mb-2">Sweet Live Bakery</h1>
        <p className="text-slate-500 dark:text-[#94a3b8] text-lg font-medium">Smart Business Manager</p>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2rem] shadow-xl dark:shadow-2xl p-8 md:p-10 border border-slate-200 dark:border-[#2e374d] relative overflow-hidden">
        {/* Subtle background glow */}
        <div className="absolute top-0 right-0 w-32 h-32 bg-orange-500/5 blur-3xl rounded-full -mr-16 -mt-16"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-white">
                {isSignup ? 'নতুন একাউন্ট' : 'লগইন করুন'}
              </h2>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">
                {isSignup ? 'Create Manager Profile' : 'Access your dashboard'}
              </p>
            </div>
            <div className="p-3 bg-orange-500/10 rounded-2xl text-orange-500 border border-orange-500/20 shadow-inner">
              {isSignup ? <UserPlus size={28} /> : <LogIn size={28} />}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 dark:text-[#94a3b8] uppercase tracking-widest px-1">Username / মোবাইল নং</label>
              <div className="relative group">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                <input 
                  required 
                  type="text" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-[#2e374d] text-slate-900 dark:text-white placeholder-slate-400 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 transition-all font-bold" 
                  placeholder="আপনার নাম বা নম্বর" 
                  value={username} 
                  onChange={e => setUsername(e.target.value)} 
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 dark:text-[#94a3b8] uppercase tracking-widest px-1">Password</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                <input 
                  required 
                  type="password" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-[#2e374d] text-slate-900 dark:text-white outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 transition-all" 
                  placeholder="••••••••" 
                  value={password} 
                  onChange={e => setPassword(e.target.value)} 
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-50 dark:bg-red-500/10 text-red-500 p-4 rounded-2xl text-xs border border-red-100 dark:border-red-500/20 flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
                <AlertCircle size={18} className="shrink-0" />
                <span className="font-bold">{error}</span>
              </div>
            )}

            {success && (
              <div className="bg-emerald-50 dark:bg-emerald-500/10 text-emerald-500 p-4 rounded-2xl text-xs border border-emerald-100 dark:border-emerald-500/20 flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
                <AlertCircle size={18} className="shrink-0" />
                <span className="font-bold">{success}</span>
              </div>
            )}

            <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-4.5 rounded-2xl shadow-[0_10px_25px_rgba(249,115,22,0.3)] active:scale-[0.98] text-lg transition-all flex items-center justify-center gap-3 group">
              {isSignup ? 'রেজিস্ট্রেশন করুন' : 'সাইন ইন'}
              <ChevronRight size={20} className="group-hover:translate-x-1 transition-transform" />
            </button>
          </form>

          <div className="mt-10 pt-8 border-t border-slate-100 dark:border-[#2e374d] text-center">
            <button onClick={() => { setIsSignup(!isSignup); setError(''); setSuccess(''); }} className="group inline-flex items-center gap-2 text-slate-400 hover:text-orange-500 transition-colors font-bold">
              <span className="text-sm">{isSignup ? 'ইতিমধ্যে একাউন্ট আছে? লগইন করুন' : "নতুন একাউন্ট খুলতে চান? এখানে চাপ দিন"}</span>
            </button>
          </div>
        </div>
      </div>
      <p className="mt-12 text-slate-400 dark:text-slate-600 text-[10px] font-black uppercase tracking-[0.3em] opacity-80">
        © 2026 SWEET LIVE BAKERY SYSTEM
      </p>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction, Wastage } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  LogOut,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  AlertTriangle,
  Monitor,
  Trash2
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  // PWA Install State
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Scoped Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // Install Event Listener
  useEffect(() => {
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
    }
  };

  // Low Stock Notification Logic
  const lowStockCount = useMemo(() => {
    return products.filter(p => p.stock < 10).length;
  }, [products]);

  // Theme Synchronizer
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Initial Auth Check
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth.toLowerCase());
    }
  }, []);

  // Load User-Specific Data
  useEffect(() => {
    if (currentUser) {
      setIsDataLoaded(false);
      const prefix = `bakery_v3_${currentUser.toLowerCase()}_`;

      const savedProducts = localStorage.getItem(`${prefix}products`);
      const savedSales = localStorage.getItem(`${prefix}sales`);
      const savedExpenses = localStorage.getItem(`${prefix}expenses`);
      const savedWastage = localStorage.getItem(`${prefix}wastage`);
      const savedStaff = localStorage.getItem(`${prefix}staff`);
      const savedAttendance = localStorage.getItem(`${prefix}attendance`);
      const savedClosings = localStorage.getItem(`${prefix}closings`);
      const savedDeductions = localStorage.getItem(`${prefix}deductions`);

      setProducts(savedProducts ? JSON.parse(savedProducts) : [
        { id: '1', name: 'Full Bread', category: 'Bread', price: 60, stock: 20, unit: 'pcs' },
        { id: '2', name: 'Cake Chocolate Cup', category: 'Cake', price: 125, stock: 15, unit: 'pcs' },
        { id: '3', name: 'Atta (Flour)', category: 'Other', price: 55, stock: 100, unit: 'kg' },
      ]);
      setSales(savedSales ? JSON.parse(savedSales) : []);
      setExpenses(savedExpenses ? JSON.parse(savedExpenses) : []);
      setWastage(savedWastage ? JSON.parse(savedWastage) : []);
      setStaff(savedStaff ? JSON.parse(savedStaff) : []);
      setAttendance(savedAttendance ? JSON.parse(savedAttendance) : []);
      setDailyClosings(savedClosings ? JSON.parse(savedClosings) : []);
      setDeductions(savedDeductions ? JSON.parse(savedDeductions) : []);

      setIsDataLoaded(true);
    } else {
      setIsDataLoaded(false);
    }
  }, [currentUser]);

  // Save User-Specific Data
  useEffect(() => {
    if (isDataLoaded && currentUser) {
      const prefix = `bakery_v3_${currentUser.toLowerCase()}_`;
      localStorage.setItem(`${prefix}products`, JSON.stringify(products));
      localStorage.setItem(`${prefix}sales`, JSON.stringify(sales));
      localStorage.setItem(`${prefix}expenses`, JSON.stringify(expenses));
      localStorage.setItem(`${prefix}wastage`, JSON.stringify(wastage));
      localStorage.setItem(`${prefix}staff`, JSON.stringify(staff));
      localStorage.setItem(`${prefix}attendance`, JSON.stringify(attendance));
      localStorage.setItem(`${prefix}closings`, JSON.stringify(dailyClosings));
      localStorage.setItem(`${prefix}deductions`, JSON.stringify(deductions));
    }
  }, [products, sales, expenses, wastage, staff, attendance, dailyClosings, deductions, currentUser, isDataLoaded]);

  const handleLogin = (username: string) => {
    const normalizedUsername = username.toLowerCase();
    setCurrentUser(normalizedUsername);
    setIsAuthenticated(true);
    sessionStorage.setItem('sweetBakery_auth', normalizedUsername);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setIsDataLoaded(false);
    sessionStorage.removeItem('sweetBakery_auth');
    setProducts([]);
    setSales([]);
    setExpenses([]);
    setWastage([]);
    setStaff([]);
    setAttendance([]);
    setDailyClosings([]);
    setDeductions([]);
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const cancelSale = (saleId: string) => {
    const saleToCancel = sales.find(s => s.id === saleId);
    if (!saleToCancel) return;

    if (window.confirm(`আপনি কি এই বিক্রয়টি বাতিল করতে চান? (এটি বাতিল করলে "${saleToCancel.productName}" এর স্টক ফেরত যাবে)`)) {
      setSales(prev => prev.filter(s => s.id !== saleId));
      setProducts(prev => prev.map(p => 
        p.id === saleToCancel.productId 
          ? { ...p, stock: p.stock + saleToCancel.quantity } 
          : p
      ));
    }
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const updateSales = (updatedSales: Sale[]) => {
    setSales(prev => {
      const newSales = [...prev];
      updatedSales.forEach(updated => {
        const index = newSales.findIndex(s => s.id === updated.id);
        if (index !== -1) {
          newSales[index] = updated;
        }
      });
      return newSales;
    });
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addWastage = (newWastage: Wastage) => {
    setWastage(prev => [...prev, newWastage]);
    setProducts(prev => prev.map(p => 
      p.id === newWastage.productId 
        ? { ...p, stock: Math.max(0, p.stock - newWastage.quantity) } 
        : p
    ));
  };

  const deleteWastage = (id: string) => {
    const item = wastage.find(w => w.id === id);
    if (!item) return;

    if (window.confirm(`এটি ডিলিট করলে "${item.productName}" এর স্টক ফেরত যাবে। আপনি কি নিশ্চিত?`)) {
      setWastage(prev => prev.filter(w => w.id !== id));
      setProducts(prev => prev.map(p => 
        p.id === item.productId 
          ? { ...p, stock: p.stock + item.quantity } 
          : p
      ));
    }
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const addDeduction = (newDeduction: Deduction) => {
    setDeductions(prev => [...prev, newDeduction]);
  };

  const addDailyClosing = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
    setCurrentView(View.DASHBOARD);
    alert('ডেইলি ক্লোজিং সফল হয়েছে! ড্যাশবোর্ডের সমস্ত হিসাব রিসেট করা হয়েছে।');
  };

  const deleteDailyClosing = (id: string) => {
    if (window.confirm('Delete this closing record? This will "Unlock" the transactions for that period. (আপনি কি নিশ্চিত? এটি ডিলিট করলে হিসাবগুলো আবার ড্যাশবোর্ডে ফিরে আসবে)')) {
      setDailyClosings(prev => prev.filter(c => c.id !== id));
    }
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);

    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    setDeductions(prev => prev.filter(d => {
      const dDate = new Date(d.date);
      return !(d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear);
    }));
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} theme={theme} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  const handleNavClick = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white ${isMobileMenuOpen ? 'overflow-hidden lg:overflow-auto' : ''}`}>
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 z-[60] lg:hidden backdrop-blur-sm animate-in fade-in duration-300"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`w-72 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-all duration-300 ease-in-out lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl shadow-orange-500/10' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
               <UtensilsCrossed size={20} className="text-white" />
            </div>
            <h1 className="text-xl font-bold text-orange-500 tracking-tight leading-tight">Sweet Live<br/><span className="text-lg">Bakery</span></h1>
          </div>
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="lg:hidden p-2 text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-slate-800 rounded-xl transition-colors"
          >
             <X size={24} />
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-1.5 mt-2 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNavClick(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-200 group relative ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-500 dark:text-slate-400 hover:text-orange-500 dark:hover:text-white hover:bg-orange-50 dark:hover:bg-slate-800/50'
              }`}
            >
              <div className={`transition-transform duration-200 ${currentView === item.id ? 'scale-110' : 'group-hover:scale-110'}`}>
                {item.icon}
              </div>
              <div className="flex flex-col items-start leading-none flex-1">
                <span className="font-bold text-[14px]">{item.label}</span>
                {item.bangla && <span className="text-[10px] opacity-60 mt-0.5">{item.bangla}</span>}
              </div>
              {item.notification && item.notification > 0 && (
                <div className={`absolute right-4 top-1/2 -translate-y-1/2 flex items-center justify-center min-w-[20px] h-[20px] px-1 rounded-full text-[10px] font-black shadow-sm ${
                  currentView === item.id ? 'bg-white text-orange-600' : 'bg-red-500 text-white'
                }`}>
                  {item.notification}
                </div>
              )}
            </button>
          ))}
        </nav>

        <div className="p-6">
           {deferredPrompt && (
             <button 
              onClick={handleInstallClick}
              className="w-full mb-4 p-4 bg-orange-500/10 border border-orange-500/20 rounded-2xl flex items-center gap-3 hover:bg-orange-500 hover:text-white transition-all group"
             >
                <Monitor size={18} className="text-orange-500 group-hover:text-white shrink-0" />
                <p className="text-[10px] font-bold uppercase leading-tight text-left">
                  Install Desktop App (পিসিতে সেভ করুন)
                </p>
             </button>
           )}
           <div className="bg-slate-100 dark:bg-[#161d31] p-5 rounded-2xl border border-slate-200 dark:border-slate-800 mb-6 group">
              <p className="text-[10px] text-orange-500 uppercase tracking-widest font-bold mb-1">Bakery Status</p>
              <h4 className="text-sm font-bold text-slate-900 dark:text-white">v3.0.1 <span className="text-emerald-500 ml-1">• Pro Isolation</span></h4>
              <p className="text-[10px] text-slate-500 mt-2 truncate">User: <span className="text-slate-700 dark:text-slate-300 capitalize font-medium">{currentUser}</span></p>
           </div>
           <div className="text-[10px] text-slate-400 dark:text-slate-500 text-center font-bold uppercase tracking-widest opacity-60">
             © 2026 MD SHAMIM
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 w-full min-h-screen flex flex-col">
        <header className="sticky top-0 z-40 px-4 md:px-8 py-4 bg-slate-50/80 dark:bg-dark-bg/80 backdrop-blur-xl border-b border-slate-200/50 dark:border-slate-800/50 flex justify-between items-center">
          <div className="flex items-center gap-3 md:gap-4">
            <button 
              onClick={() => setIsMobileMenuOpen(true)} 
              className="lg:hidden p-2.5 text-orange-500 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm active:scale-90 transition-transform"
              aria-label="Open Menu"
            >
              <Menu size={24} />
            </button>
            <div className="hidden sm:flex w-12 h-12 md:w-14 md:h-14 bg-white dark:bg-[#161d31] rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center justify-center shadow-sm">
               <UtensilsCrossed size={24} className="text-orange-500" />
            </div>
            <div>
              <h2 className="text-xl md:text-2xl font-black tracking-tight text-slate-900 dark:text-white capitalize truncate max-w-[150px] xs:max-w-none">
                {currentView === View.DASHBOARD ? 'Sweet Live Bakery' : currentView.toLowerCase().replace('_', ' ')}
              </h2>
              <p className="hidden xs:block text-slate-500 dark:text-slate-400 text-[10px] md:text-xs font-bold uppercase tracking-wider">
                Desktop Management <span className="text-orange-500 ml-1">• Offline Pro</span>
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-3">
             <button 
               onClick={toggleTheme}
               className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-orange-500 hover:bg-orange-50 dark:hover:bg-[#1e293b] transition-all shadow-sm active:scale-90"
               title="Toggle Theme"
             >
                {theme === 'dark' ? <SafeSun size={18} /> : <Moon size={18} />}
             </button>
             <button 
               onClick={handleLogout}
               className="h-10 md:h-12 px-4 md:px-6 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-red-500 font-bold flex items-center gap-2 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all shadow-sm text-sm active:scale-95"
             >
               <LogOut size={16} className="hidden xs:block" /> 
               <span>Logout</span>
             </button>
          </div>
        </header>

        <div className="p-4 md:p-8 flex-1">
          <section className="animate-in fade-in slide-in-from-bottom-2 duration-500 ease-out h-full">
            {!isDataLoaded ? (
              <div className="flex flex-col items-center justify-center h-96 text-slate-500">
                <div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin mb-4"></div>
                <p className="font-bold tracking-widest text-[10px] uppercase">Loading Secure Data...</p>
              </div>
            ) : (
              <>
                {currentView === View.DASHBOARD && (
                  <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onInstall={handleInstallClick} showInstallButton={!!deferredPrompt} />
                )}
                {currentView === View.INVENTORY && (
                  <Inventory products={products} onAdd={addProduct} onUpdate={updateProduct} onDelete={deleteProduct} onMarkWastage={(p, qty, reason) => addWastage({ id: Date.now().toString(), productId: p.id, productName: p.name, quantity: qty, unit: p.unit, lossValue: p.price * qty, reason, date: new Date().toISOString() })} />
                )}
                {currentView === View.SALES && (
                  <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={cancelSale} closings={dailyClosings} />
                )}
                {currentView === View.DUES && (
                  <DuesView sales={sales} onUpdateSales={updateSales} />
                )}
                {currentView === View.WASTAGE && (
                  <WastageView wastage={wastage} products={products} onAdd={addWastage} onDelete={deleteWastage} closings={dailyClosings} />
                )}
                {currentView === View.EXPENSES && (
                  <ExpensesView expenses={expenses} onAdd={addExpense} closings={dailyClosings} />
                )}
                {currentView === View.DAILY_CLOSING && (
                  <DailyClosingView 
                    sales={sales} 
                    expenses={expenses} 
                    wastage={wastage}
                    closings={dailyClosings} 
                    onCloseDay={addDailyClosing} 
                    onDeleteClosing={deleteDailyClosing}
                    currentUser={currentUser} 
                  />
                )}
                {currentView === View.MANAGER && (
                  <ManagerView 
                    username={currentUser} 
                    onLogout={handleLogout} 
                    stats={{
                      products: products.length,
                      sales: sales.length,
                      expenses: expenses.length,
                      staff: staff.length
                    }}
                  />
                )}
                {currentView === View.STAFF && (
                  <StaffView 
                    staff={staff} 
                    attendance={attendance} 
                    expenses={expenses}
                    deductions={deductions}
                    onAddStaff={addStaffMember} 
                    onUpdateAttendance={updateAttendance} 
                    onAddDeduction={addDeduction}
                    onPaySalary={paySalary}
                  />
                )}
              </>
            )}
          </section>
        </div>
      </main>
    </div>
  );
};

const SafeSun = ({ size }: { size: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction, Wastage } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  LogOut,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  AlertTriangle,
  Monitor,
  Trash2
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  // PWA Install State
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Scoped Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // Install Event Listener
  useEffect(() => {
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
    }
  };

  // Low Stock Notification Logic
  const lowStockCount = useMemo(() => {
    return products.filter(p => p.stock < 10).length;
  }, [products]);

  // Theme Synchronizer
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Initial Auth Check
  useEffect(() => {
    const auth = sessionStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth.toLowerCase());
    }
  }, []);

  // Load User-Specific Data
  useEffect(() => {
    if (currentUser) {
      setIsDataLoaded(false);
      const prefix = `bakery_v3_${currentUser.toLowerCase()}_`;

      const savedProducts = localStorage.getItem(`${prefix}products`);
      const savedSales = localStorage.getItem(`${prefix}sales`);
      const savedExpenses = localStorage.getItem(`${prefix}expenses`);
      const savedWastage = localStorage.getItem(`${prefix}wastage`);
      const savedStaff = localStorage.getItem(`${prefix}staff`);
      const savedAttendance = localStorage.getItem(`${prefix}attendance`);
      const savedClosings = localStorage.getItem(`${prefix}closings`);
      const savedDeductions = localStorage.getItem(`${prefix}deductions`);

      // Changed default products from 3 items to an empty array
      setProducts(savedProducts ? JSON.parse(savedProducts) : []);
      setSales(savedSales ? JSON.parse(savedSales) : []);
      setExpenses(savedExpenses ? JSON.parse(savedExpenses) : []);
      setWastage(savedWastage ? JSON.parse(savedWastage) : []);
      setStaff(savedStaff ? JSON.parse(savedStaff) : []);
      setAttendance(savedAttendance ? JSON.parse(savedAttendance) : []);
      setDailyClosings(savedClosings ? JSON.parse(savedClosings) : []);
      setDeductions(savedDeductions ? JSON.parse(savedDeductions) : []);

      setIsDataLoaded(true);
    } else {
      setIsDataLoaded(false);
    }
  }, [currentUser]);

  // Save User-Specific Data
  useEffect(() => {
    if (isDataLoaded && currentUser) {
      const prefix = `bakery_v3_${currentUser.toLowerCase()}_`;
      localStorage.setItem(`${prefix}products`, JSON.stringify(products));
      localStorage.setItem(`${prefix}sales`, JSON.stringify(sales));
      localStorage.setItem(`${prefix}expenses`, JSON.stringify(expenses));
      localStorage.setItem(`${prefix}wastage`, JSON.stringify(wastage));
      localStorage.setItem(`${prefix}staff`, JSON.stringify(staff));
      localStorage.setItem(`${prefix}attendance`, JSON.stringify(attendance));
      localStorage.setItem(`${prefix}closings`, JSON.stringify(dailyClosings));
      localStorage.setItem(`${prefix}deductions`, JSON.stringify(deductions));
    }
  }, [products, sales, expenses, wastage, staff, attendance, dailyClosings, deductions, currentUser, isDataLoaded]);

  const handleLogin = (username: string) => {
    const normalizedUsername = username.toLowerCase();
    setCurrentUser(normalizedUsername);
    setIsAuthenticated(true);
    sessionStorage.setItem('sweetBakery_auth', normalizedUsername);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setIsDataLoaded(false);
    sessionStorage.removeItem('sweetBakery_auth');
    setProducts([]);
    setSales([]);
    setExpenses([]);
    setWastage([]);
    setStaff([]);
    setAttendance([]);
    setDailyClosings([]);
    setDeductions([]);
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    setProducts(prev => prev.map(p => 
      p.id === newSale.productId 
        ? { ...p, stock: Math.max(0, p.stock - newSale.quantity) } 
        : p
    ));
  };

  const cancelSale = (saleId: string) => {
    const saleToCancel = sales.find(s => s.id === saleId);
    if (!saleToCancel) return;

    if (window.confirm(`আপনি কি এই বিক্রয়টি বাতিল করতে চান? (এটি বাতিল করলে "${saleToCancel.productName}" এর স্টক ফেরত যাবে)`)) {
      setSales(prev => prev.filter(s => s.id !== saleId));
      setProducts(prev => prev.map(p => 
        p.id === saleToCancel.productId 
          ? { ...p, stock: p.stock + saleToCancel.quantity } 
          : p
      ));
    }
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const updateSales = (updatedSales: Sale[]) => {
    setSales(prev => {
      const newSales = [...prev];
      updatedSales.forEach(updated => {
        const index = newSales.findIndex(s => s.id === updated.id);
        if (index !== -1) {
          newSales[index] = updated;
        }
      });
      return newSales;
    });
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
  };

  const updateProduct = (product: Product) => {
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
  };

  const addWastage = (newWastage: Wastage) => {
    setWastage(prev => [...prev, newWastage]);
    setProducts(prev => prev.map(p => 
      p.id === newWastage.productId 
        ? { ...p, stock: Math.max(0, p.stock - newWastage.quantity) } 
        : p
    ));
  };

  const deleteWastage = (id: string) => {
    const item = wastage.find(w => w.id === id);
    if (!item) return;

    if (window.confirm(`এটি ডিলিট করলে "${item.productName}" এর স্টক ফেরত যাবে। আপনি কি নিশ্চিত?`)) {
      setWastage(prev => prev.filter(w => w.id !== id));
      setProducts(prev => prev.map(p => 
        p.id === item.productId 
          ? { ...p, stock: p.stock + item.quantity } 
          : p
      ));
    }
  };

  const addStaffMember = (newStaff: Staff) => {
    setStaff(prev => [...prev, newStaff]);
  };

  const updateAttendance = (newAttendance: Attendance) => {
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  };

  const addDeduction = (newDeduction: Deduction) => {
    setDeductions(prev => [...prev, newDeduction]);
  };

  const addDailyClosing = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
    setCurrentView(View.DASHBOARD);
    alert('ডেইলি ক্লোজিং সফল হয়েছে! ড্যাশবোর্ডের সমস্ত হিসাব রিসেট করা হয়েছে।');
  };

  const deleteDailyClosing = (id: string) => {
    if (window.confirm('Delete this closing record? This will "Unlock" the transactions for that period. (আপনি কি নিশ্চিত? এটি ডিলিট করলে হিসাবগুলো আবার ড্যাশবোর্ডে ফিরে আসবে)')) {
      setDailyClosings(prev => prev.filter(c => c.id !== id));
    }
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;

    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${new Date().toLocaleString('default', { month: 'long' })} ${new Date().getFullYear()})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);

    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    setDeductions(prev => prev.filter(d => {
      const dDate = new Date(d.date);
      return !(d.staffId === staffId && dDate.getMonth() === currentMonth && dDate.getFullYear() === currentYear);
    }));
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} theme={theme} />;
  }

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  const handleNavClick = (view: View) => {
    setCurrentView(view);
    setIsMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white ${isMobileMenuOpen ? 'overflow-hidden lg:overflow-auto' : ''}`}>
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 z-[60] lg:hidden backdrop-blur-sm animate-in fade-in duration-300"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`w-72 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-all duration-300 ease-in-out lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl shadow-orange-500/10' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-orange-500 rounded-full flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.4)]">
               <UtensilsCrossed size={20} className="text-white" />
            </div>
            <h1 className="text-xl font-bold text-orange-500 tracking-tight leading-tight">Sweet Live<br/><span className="text-lg">Bakery</span></h1>
          </div>
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="lg:hidden p-2 text-slate-400 hover:text-orange-500 hover:bg-orange-50 dark:hover:bg-slate-800 rounded-xl transition-colors"
          >
             <X size={24} />
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-1.5 mt-2 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNavClick(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-200 group relative ${
                currentView === item.id 
                  ? 'bg-orange-500 text-white shadow-[0_8px_20px_rgba(249,115,22,0.2)]' 
                  : 'text-slate-500 dark:text-slate-400 hover:text-orange-500 dark:hover:text-white hover:bg-orange-50 dark:hover:bg-slate-800/50'
              }`}
            >
              <div className={`transition-transform duration-200 ${currentView === item.id ? 'scale-110' : 'group-hover:scale-110'}`}>
                {item.icon}
              </div>
              <div className="flex flex-col items-start leading-none flex-1">
                <span className="font-bold text-[14px]">{item.label}</span>
                {item.bangla && <span className="text-[10px] opacity-60 mt-0.5">{item.bangla}</span>}
              </div>
              {item.notification && item.notification > 0 && (
                <div className={`absolute right-4 top-1/2 -translate-y-1/2 flex items-center justify-center min-w-[20px] h-[20px] px-1 rounded-full text-[10px] font-black shadow-sm ${
                  currentView === item.id ? 'bg-white text-orange-600' : 'bg-red-500 text-white'
                }`}>
                  {item.notification}
                </div>
              )}
            </button>
          ))}
        </nav>

        <div className="p-6">
           {deferredPrompt && (
             <button 
              onClick={handleInstallClick}
              className="w-full mb-4 p-4 bg-orange-500/10 border border-orange-500/20 rounded-2xl flex items-center gap-3 hover:bg-orange-500 hover:text-white transition-all group"
             >
                <Monitor size={18} className="text-orange-500 group-hover:text-white shrink-0" />
                <p className="text-[10px] font-bold uppercase leading-tight text-left">
                  Install Desktop App (পিসিতে সেভ করুন)
                </p>
             </button>
           )}
           <div className="bg-slate-100 dark:bg-[#161d31] p-5 rounded-2xl border border-slate-200 dark:border-slate-800 mb-6 group">
              <p className="text-[10px] text-orange-500 uppercase tracking-widest font-bold mb-1">Bakery Status</p>
              <h4 className="text-sm font-bold text-slate-900 dark:text-white">v3.0.1 <span className="text-emerald-500 ml-1">• Pro Isolation</span></h4>
              <p className="text-[10px] text-slate-500 mt-2 truncate">User: <span className="text-slate-700 dark:text-slate-300 capitalize font-medium">{currentUser}</span></p>
           </div>
           <div className="text-[10px] text-slate-400 dark:text-slate-500 text-center font-bold uppercase tracking-widest opacity-60">
             © 2026 MD SHAMIM
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 w-full min-h-screen flex flex-col">
        <header className="sticky top-0 z-40 px-4 md:px-8 py-4 bg-slate-50/80 dark:bg-dark-bg/80 backdrop-blur-xl border-b border-slate-200/50 dark:border-slate-800/50 flex justify-between items-center">
          <div className="flex items-center gap-3 md:gap-4">
            <button 
              onClick={() => setIsMobileMenuOpen(true)} 
              className="lg:hidden p-2.5 text-orange-500 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm active:scale-90 transition-transform"
              aria-label="Open Menu"
            >
              <Menu size={24} />
            </button>
            <div className="hidden sm:flex w-12 h-12 md:w-14 md:h-14 bg-white dark:bg-[#161d31] rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center justify-center shadow-sm">
               <UtensilsCrossed size={24} className="text-orange-500" />
            </div>
            <div>
              <h2 className="text-xl md:text-2xl font-black tracking-tight text-slate-900 dark:text-white capitalize truncate max-w-[150px] xs:max-w-none">
                {currentView === View.DASHBOARD ? 'Sweet Live Bakery' : currentView.toLowerCase().replace('_', ' ')}
              </h2>
              <p className="hidden xs:block text-slate-500 dark:text-slate-400 text-[10px] md:text-xs font-bold uppercase tracking-wider">
                Desktop Management <span className="text-orange-500 ml-1">• Offline Pro</span>
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-3">
             <button 
               onClick={toggleTheme}
               className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-orange-500 hover:bg-orange-50 dark:hover:bg-[#1e293b] transition-all shadow-sm active:scale-90"
               title="Toggle Theme"
             >
                {theme === 'dark' ? <SafeSun size={18} /> : <Moon size={18} />}
             </button>
             <button 
               onClick={handleLogout}
               className="h-10 md:h-12 px-4 md:px-6 bg-white dark:bg-[#161d31] border border-slate-200 dark:border-slate-800 rounded-xl text-red-500 font-bold flex items-center gap-2 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all shadow-sm text-sm active:scale-95"
             >
               <LogOut size={16} className="hidden xs:block" /> 
               <span>Logout</span>
             </button>
          </div>
        </header>

        <div className="p-4 md:p-8 flex-1">
          <section className="animate-in fade-in slide-in-from-bottom-2 duration-500 ease-out h-full">
            {!isDataLoaded ? (
              <div className="flex flex-col items-center justify-center h-96 text-slate-500">
                <div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin mb-4"></div>
                <p className="font-bold tracking-widest text-[10px] uppercase">Loading Secure Data...</p>
              </div>
            ) : (
              <>
                {currentView === View.DASHBOARD && (
                  <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onInstall={handleInstallClick} showInstallButton={!!deferredPrompt} />
                )}
                {currentView === View.INVENTORY && (
                  <Inventory products={products} onAdd={addProduct} onUpdate={updateProduct} onDelete={deleteProduct} onMarkWastage={(p, qty, reason) => addWastage({ id: Date.now().toString(), productId: p.id, productName: p.name, quantity: qty, unit: p.unit, lossValue: p.price * qty, reason, date: new Date().toISOString() })} />
                )}
                {currentView === View.SALES && (
                  <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={cancelSale} closings={dailyClosings} />
                )}
                {currentView === View.DUES && (
                  <DuesView sales={sales} onUpdateSales={updateSales} />
                )}
                {currentView === View.WASTAGE && (
                  <WastageView wastage={wastage} products={products} onAdd={addWastage} onDelete={deleteWastage} closings={dailyClosings} />
                )}
                {currentView === View.EXPENSES && (
                  <ExpensesView expenses={expenses} onAdd={addExpense} closings={dailyClosings} />
                )}
                {currentView === View.DAILY_CLOSING && (
                  <DailyClosingView 
                    sales={sales} 
                    expenses={expenses} 
                    wastage={wastage}
                    closings={dailyClosings} 
                    onCloseDay={addDailyClosing} 
                    onDeleteClosing={deleteDailyClosing}
                    currentUser={currentUser} 
                  />
                )}
                {currentView === View.MANAGER && (
                  <ManagerView 
                    username={currentUser} 
                    onLogout={handleLogout} 
                    stats={{
                      products: products.length,
                      sales: sales.length,
                      expenses: expenses.length,
                      staff: staff.length
                    }}
                  />
                )}
                {currentView === View.STAFF && (
                  <StaffView 
                    staff={staff} 
                    attendance={attendance} 
                    expenses={expenses}
                    deductions={deductions}
                    onAddStaff={addStaffMember} 
                    onUpdateAttendance={updateAttendance} 
                    onAddDeduction={addDeduction}
                    onPaySalary={paySalary}
                  />
                )}
              </>
            )}
          </section>
        </div>
      </main>
    </div>
  );
};

const SafeSun = ({ size }: { size: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
);

export default App;

import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { Plus, Search, Package, Trash2, ChevronDown, AlertCircle, Banknote, Edit3, X, AlertTriangle, Trash } from 'lucide-react';

interface Props {
  products: Product[];
  onAdd: (product: Product) => void;
  onUpdate: (product: Product) => void;
  onDelete: (id: string) => void;
  onMarkWastage: (p: Product, qty: number, reason: string) => void;
}

const Inventory: React.FC<Props> = ({ products, onAdd, onUpdate, onDelete, onMarkWastage }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'name_asc' | 'name_desc' | 'price_asc' | 'price_desc'>('name_asc');

  // Custom Modal States
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [wastageModalProduct, setWastageModalProduct] = useState<Product | null>(null);
  const [wastageQty, setWastageQty] = useState<number | ''>('');
  const [wastageReason, setWastageReason] = useState('Expired');

  const [formData, setFormData] = useState({
    name: '',
    category: 'Bread',
    price: '' as number | '',
    stock: '' as number | '',
    unit: 'pcs'
  });

  // Calculate Total Stock Value
  const stockSummary = useMemo(() => {
    const totalValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);
    const totalItems = products.length;
    const totalQuantity = products.reduce((acc, p) => acc + p.stock, 0);
    return { totalValue, totalItems, totalQuantity };
  }, [products]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      price: Number(formData.price) || 0,
      stock: Number(formData.stock) || 0
    };

    if (editingId) {
      onUpdate({ ...finalData, id: editingId } as Product);
      setEditingId(null);
    } else {
      onAdd({ ...finalData, id: Date.now().toString() } as Product);
    }
    setFormData({ name: '', category: 'Bread', price: '', stock: '', unit: 'pcs' });
    setIsAdding(false);
  };

  const handleWastageSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (wastageModalProduct && wastageQty !== '') {
      onMarkWastage(wastageModalProduct, Number(wastageQty), wastageReason);
      setWastageModalProduct(null);
      setWastageQty('');
      setWastageReason('Expired');
    }
  };

  const handleEdit = (p: Product) => {
    setFormData({
      name: p.name,
      category: p.category,
      price: p.price,
      stock: p.stock,
      unit: p.unit
    });
    setEditingId(p.id);
    setIsAdding(true);
  };

  const executeDelete = () => {
    if (confirmDeleteId) {
      onDelete(confirmDeleteId);
      setConfirmDeleteId(null);
      if (editingId === confirmDeleteId) {
        setIsAdding(false);
        setEditingId(null);
      }
    }
  };

  const filteredProducts = products
    .filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => {
      if (sortBy === 'name_asc') return a.name.localeCompare(b.name);
      if (sortBy === 'name_desc') return b.name.localeCompare(a.name);
      if (sortBy === 'price_asc') return a.price - b.price;
      if (sortBy === 'price_desc') return b.price - a.price;
      return 0;
    });

  const units = ['pcs', 'kg', 'gm', 'pkt', 'ltr', 'box'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Stock Value Summary Card */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
        <div className="md:col-span-4 bg-emerald-600 p-8 rounded-[2.5rem] shadow-lg shadow-emerald-500/20 text-white border-4 border-white/10 relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
             <Banknote size={180} />
          </div>
          <div className="relative z-10">
            <h4 className="text-emerald-100 font-bold text-xs mb-2 uppercase tracking-widest flex items-center gap-2">
               <Banknote size={16} /> Total Stock Value
            </h4>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-bold">৳</span>
              <span className="text-5xl font-black tracking-tighter">{stockSummary.totalValue.toLocaleString()}</span>
            </div>
            <p className="mt-4 text-emerald-100/70 text-[10px] font-bold uppercase tracking-widest">মজুদ মালের মোট মূল্য</p>
          </div>
        </div>

        <div className="md:col-span-8 bg-white dark:bg-[#161d31] p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-6">
           <div className="flex-1">
              <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Inventory Analysis</h2>
