    return { 
      name: d.toLocaleDateString([], { month: 'numeric', day: 'numeric' }), 
      sales: daySales 
    };
  }).reverse();

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Installation Banner */}
      {showInstallButton && (
