import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, DailyClosing, SaleItem } from '../types';
import { ShoppingCart, User, Phone, Wallet, Trash2, Plus, Minus, Package, Trash } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
  closings?: DailyClosing[];
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale, closings = [] }) => {
  // Selection States
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');

  // Cart State
  const [cart, setCart] = useState<SaleItem[]>([]);

  // Checkout States
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  const selectedProduct = products.find(p => p.id === selectedProductId);

  // Totals Calculation
  const totalPrice = cart.reduce((acc, item) => acc + item.subTotal, 0);

  // Auto-fill amount paid when totalPrice changes (if it was previously matching)
  useEffect(() => {
    if (totalPrice > 0) {
      setAmountPaid(totalPrice);
    } else {
      setAmountPaid('');
    }
  }, [totalPrice]);

  const dueAmount = totalPrice - (Number(amountPaid) || 0);

  const addToCart = () => {
    if (!selectedProduct || quantity === '') return;

    // Check if enough stock exists overall
    const existingInCart = cart.find(item => item.productId === selectedProduct.id);
    const existingQty = existingInCart ? existingInCart.quantity : 0;
    const requestedQty = Number(quantity);

    if (selectedProduct.stock < (existingQty + requestedQty)) {
      alert(`দুঃখিত! এই প্রোডাক্টটির মজুদ (Stock) পর্যাপ্ত নয়। বর্তমান স্টক: ${selectedProduct.stock} ${selectedProduct.unit}`);
      return;
    }

    if (existingInCart) {
      setCart(prev => prev.map(item => 
        item.productId === selectedProduct.id 
          ? { ...item, quantity: item.quantity + requestedQty, subTotal: (item.quantity + requestedQty) * item.pricePerUnit } 
          : item
      ));
    } else {
      const newItem: SaleItem = {
        productId: selectedProduct.id,
        productName: selectedProduct.name,
        quantity: requestedQty,
        unit: selectedProduct.unit || 'pcs',
        pricePerUnit: selectedProduct.price,
        subTotal: requestedQty * selectedProduct.price
      };
      setCart(prev => [...prev, newItem]);
    }

    setQuantity('');
    setSelectedProductId('');
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.productId !== productId));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;

    if (dueAmount > 0.01 && !customerName) {
      alert("বাকি বিক্রয়ের ক্ষেত্রে কাস্টমারের নাম অবশ্যই দিতে হবে।");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: Math.max(0, dueAmount),
      customerName: dueAmount > 0.01 ? customerName : undefined,
      customerPhone: dueAmount > 0.01 ? customerPhone : undefined,
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);

    // Reset Everything
    setCart([]);
    setAmountPaid('');
    setPaymentMethod('Cash');
    setCustomerName('');
    setCustomerPhone('');
  };

  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  const activeSales = useMemo(() => {
    return [...sales]
      .filter(s => new Date(s.date).getTime() > lastClosingTimestamp)
      .reverse()
      .slice(0, 5);
  }, [sales, lastClosingTimestamp]);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in duration-500">

      {/* LEFT: Product Selection & Cart */}
      <div className="lg:col-span-8 space-y-6">

        {/* Selection Area */}
        <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <div className="flex flex-col md:flex-row gap-4 items-end">
             <div className="flex-1 space-y-2 w-full">
                <label className="text-xs font-black text-slate-500 uppercase px-1">Choose Product (প্রোডাক্ট)</label>
                <select 
                  className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50"
                  value={selectedProductId}
                  onChange={e => setSelectedProductId(e.target.value)}
                >
                  <option value="">Search or Select Product...</option>
                  {products.map(p => (
                    <option key={p.id} value={p.id} disabled={p.stock <= 0}>
                      {p.name} (৳{p.price}/{p.unit}) - Stock: {p.stock}
                    </option>
                  ))}
                </select>
             </div>

             <div className="w-full md:w-32 space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase px-1">Quantity</label>
                <input 
                  type="number" 
                  step="any"
                  placeholder="0"
                  className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-orange-500/50"
                  value={quantity}
                  onChange={e => setQuantity(e.target.value === '' ? '' : Number(e.target.value))}
                />
             </div>

             <button 
               onClick={addToCart}
               disabled={!selectedProductId || !quantity}
               className="w-full md:w-auto h-[60px] px-8 bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white font-black rounded-xl transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2"
             >
                <Plus size={20} /> Add to Order
             </button>
           </div>
        </div>

        {/* Cart Display */}
        <div className="bg-white dark:bg-[#1a2236] rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden min-h-[400px] flex flex-col">
           <div className="p-6 px-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2">
                 <ShoppingCart size={20} className="text-orange-500" /> Current Order Items (কার্ট)
              </h3>
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">
                 {cart.length} Item(s)
              </div>
           </div>

           <div className="flex-1 overflow-y-auto">
              <table className="w-full text-left text-sm">
                <thead>
                   <tr className="text-[10px] uppercase text-slate-400 font-bold tracking-widest bg-slate-50/50 dark:bg-transparent border-b border-slate-100 dark:border-slate-800">
                      <th className="px-8 py-4">Item Name</th>
                      <th className="px-8 py-4 text-center">Qty</th>
                      <th className="px-8 py-4 text-center">Rate</th>
                      <th className="px-8 py-4 text-right">Subtotal</th>
                      <th className="px-8 py-4 text-right">Action</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                   {cart.map(item => (
                     <tr key={item.productId} className="hover:bg-slate-50/50 dark:hover:bg-white/5 transition-colors">
                        <td className="px-8 py-5 font-bold text-slate-900 dark:text-slate-200">{item.productName}</td>
                        <td className="px-8 py-5 text-center font-bold text-orange-500">{item.quantity} {item.unit}</td>
                        <td className="px-8 py-5 text-center text-slate-500">৳{item.pricePerUnit}</td>
                        <td className="px-8 py-5 text-right font-black text-slate-900 dark:text-white">৳{item.subTotal.toLocaleString()}</td>
                        <td className="px-8 py-5 text-right">
                           <button 
                             onClick={() => removeFromCart(item.productId)}
                             className="p-2 text-slate-300 hover:text-red-500 transition-colors"
                           >
                              <Trash2 size={18} />
                           </button>
                        </td>
                     </tr>
                   ))}
                   {cart.length === 0 && (
                     <tr>
                        <td colSpan={5} className="px-8 py-20 text-center">
                           <div className="flex flex-col items-center opacity-20">
                              <Package size={64} className="mb-4" />
                              <p className="font-bold text-lg uppercase tracking-widest">Cart is Empty</p>
                              <p className="text-xs mt-1">আইটেম সিলেক্ট করে "Add to Order" চাপুন</p>
                           </div>
                        </td>
                     </tr>
                   )}
                </tbody>
              </table>
           </div>

           {cart.length > 0 && (
             <div className="p-8 bg-slate-50 dark:bg-black/20 border-t border-slate-200 dark:border-slate-800">
                <div className="flex justify-between items-center">
                   <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Order Total Amount</div>
                   <div className="text-3xl font-black text-slate-900 dark:text-white">৳{totalPrice.toLocaleString()}</div>
                </div>
             </div>
           )}
        </div>
      </div>

      {/* RIGHT: Checkout Panel */}
      <div className="lg:col-span-4 space-y-6">
        <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl">
           <h3 className="text-xl font-bold mb-8 text-slate-900 dark:text-white">Checkout (হিসাব সম্পন্ন করুন)</h3>

           <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-4">
                 <div className="space-y-2">
                    <label className="text-xs font-black text-slate-500 uppercase px-1">Payment Method</label>
                    <div className="grid grid-cols-2 gap-2">
                       <button 
                        type="button"
                        onClick={() => setPaymentMethod('Cash')}
                        className={`py-3 rounded-xl font-bold text-sm transition-all border ${paymentMethod === 'Cash' ? 'bg-orange-500 text-white border-orange-500 shadow-lg' : 'bg-slate-50 dark:bg-slate-800 text-slate-400 border-slate-200 dark:border-slate-700'}`}
                       >
                         Cash
                       </button>
                       <button 
                        type="button"
                        onClick={() => setPaymentMethod('Mobile Payment')}
                        className={`py-3 rounded-xl font-bold text-sm transition-all border ${paymentMethod === 'Mobile Payment' ? 'bg-orange-500 text-white border-orange-500 shadow-lg' : 'bg-slate-50 dark:bg-slate-800 text-slate-400 border-slate-200 dark:border-slate-700'}`}
                       >
                         Mobile Pay
                       </button>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-xs font-black text-slate-500 uppercase px-1">Amount Paid (নগদ গ্রহণ)</label>
                    <input 
                      type="number" 
                      step="any"
                      className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white font-black text-2xl outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500"
                      value={amountPaid}
                      onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value))}
                      placeholder="0.00"
                    />
                 </div>

                 {dueAmount > 0.01 && (
                    <div className="p-4 rounded-2xl bg-red-500/5 border border-red-500/10 flex justify-between items-center animate-in slide-in-from-top-2">
                       <div className="flex items-center gap-2 text-red-500 font-bold uppercase text-[10px]">
                          <Wallet size={16} /> Remaining Due
                       </div>
                       <div className="text-xl font-black text-red-500">৳{dueAmount.toLocaleString()}</div>
                    </div>
                 )}
              </div>

              {dueAmount > 0.01 && (
                 <div className="space-y-4 pt-4 border-t border-slate-100 dark:border-slate-800 animate-in fade-in">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase px-1">Customer Name</label>
                      <div className="relative">
                         <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                         <input required type="text" className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-white outline-none" placeholder="Enter Name" value={customerName} onChange={e => setCustomerName(e.target.value)} />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase px-1">Phone Number</label>
                      <div className="relative">
                         <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                         <input type="text" className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-white outline-none" placeholder="017XXXXXXXX" value={customerPhone} onChange={e => setCustomerPhone(e.target.value)} />
                      </div>
                    </div>
                 </div>
              )}

              <button 
                type="submit" 
                disabled={cart.length === 0}
                className="w-full bg-emerald-500 hover:bg-emerald-600 disabled:bg-slate-200 dark:disabled:bg-slate-800 text-white font-black py-5 rounded-2xl shadow-xl shadow-emerald-500/20 transition-all active:scale-95 flex items-center justify-center gap-3 text-lg"
              >
                <ShoppingCart size={24} /> Complete Sale
              </button>
           </form>
        </div>

        {/* Recent mini-history */}
        <div className="bg-white dark:bg-[#1a2236] rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
           <div className="p-6 border-b border-slate-100 dark:border-slate-800">
              <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Recent Orders</h4>
           </div>
           <div className="divide-y divide-slate-100 dark:divide-slate-800">
              {activeSales.map(s => (
                <div key={s.id} className="p-4 px-6 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors group">
                   <div className="flex justify-between items-start mb-1">
                      <div className="font-bold text-sm text-slate-900 dark:text-slate-200">
                         {s.items.length} Items
                      </div>
                      <div className="text-emerald-500 font-black text-sm">৳{s.totalPrice.toLocaleString()}</div>
                   </div>
                   <div className="flex justify-between items-center">
                      <div className="text-[9px] text-slate-400 font-bold uppercase truncate max-w-[120px]">
                         {s.items.map(i => i.productName).join(', ')}
                      </div>
                      <button onClick={() => onCancelSale(s.id)} className="p-1 text-slate-300 hover:text-red-500">
                         <Trash size={12} />
                      </button>
                   </div>
                </div>
              ))}
              {activeSales.length === 0 && (
                <div className="p-10 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">No Recent Sales</div>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

