import { GoogleGenAI } from "@google/genai";
import { Product, Sale, Expense } from "../types";

export const getBusinessInsights = async (
  products: Product[],
  sales: Sale[],
  expenses: Expense[]
) => {
  // Directly use process.env.API_KEY string for SDK initialization as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const totalSales = sales.reduce((acc, s) => acc + s.totalPrice, 0);
  const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
  const profit = totalSales - totalExpenses;

  const prompt = `
    As a professional bakery business consultant, analyze the following data for my bakery called "Sweet Live Bakery".

    Data Summary:
    - Total Products: ${products.length}
    - Total Sales Revenue: ৳${totalSales}
    - Total Expenses: ৳${totalExpenses}
    - Net Profit/Loss: ৳${profit}

    Products: ${JSON.stringify(products)}
    Recent Sales History: ${JSON.stringify(sales.slice(-10))}
    Recent Expenses: ${JSON.stringify(expenses.slice(-10))}

    Please provide:
    1. A summary of current performance.
    2. Top 3 recommendations to increase profit.
    3. Warning if expenses are too high or stock is low.
    4. A prediction for the next month.

    Answer in a friendly tone. Use Bengali for the advice if possible, as the user is a Bengali speaker, but use English for technical terms.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.7,
      }
    });
    // Use the .text property to access generated content as per guidelines
    return response.text;
  } catch (error) {
    console.error("Gemini Insight Error:", error);
    return "Could not generate insights at this time. Please check your data or try again later.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, DailyClosing, SaleItem } from '../types';
import { ShoppingCart, User, Phone, Wallet, Trash2, Plus, Minus, Package, Trash, Printer, X, CheckCircle2 } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
  closings?: DailyClosing[];
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale, closings = [] }) => {
  // Selection States
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');

  // Cart State
  const [cart, setCart] = useState<SaleItem[]>([]);

  // Checkout States
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Receipt State
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);

  const selectedProduct = products.find(p => p.id === selectedProductId);

  // Totals Calculation
  const totalPrice = cart.reduce((acc, item) => acc + item.subTotal, 0);

  // Auto-fill amount paid
  useEffect(() => {
    if (totalPrice > 0) {
      setAmountPaid(totalPrice);
    } else {
      setAmountPaid('');
    }
  }, [totalPrice]);

  const dueAmount = totalPrice - (Number(amountPaid) || 0);

  const addToCart = () => {
    if (!selectedProduct || quantity === '') return;

    const existingInCart = cart.find(item => item.productId === selectedProduct.id);
    const existingQty = existingInCart ? existingInCart.quantity : 0;
    const requestedQty = Number(quantity);

    if (selectedProduct.stock < (existingQty + requestedQty)) {
      alert(`দুঃখিত! এই প্রোডাক্টটির মজুদ (Stock) পর্যাপ্ত নয়। বর্তমান স্টক: ${selectedProduct.stock} ${selectedProduct.unit}`);
      return;
    }

    if (existingInCart) {
      setCart(prev => prev.map(item => 
        item.productId === selectedProduct.id 
          ? { ...item, quantity: item.quantity + requestedQty, subTotal: (item.quantity + requestedQty) * item.pricePerUnit } 
          : item
      ));
    } else {
      const newItem: SaleItem = {
        productId: selectedProduct.id,
        productName: selectedProduct.name,
        quantity: requestedQty,
        unit: selectedProduct.unit || 'pcs',
        pricePerUnit: selectedProduct.price,
        subTotal: requestedQty * selectedProduct.price
      };
      setCart(prev => [...prev, newItem]);
    }

    setQuantity('');
    setSelectedProductId('');
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.productId !== productId));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;

    if (dueAmount > 0.01 && !customerName) {
      alert("বাকি বিক্রয়ের ক্ষেত্রে কাস্টমারের নাম অবশ্যই দিতে হবে।");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: Math.max(0, dueAmount),
      customerName: dueAmount > 0.01 ? customerName : customerName || undefined,
      customerPhone: dueAmount > 0.01 ? customerPhone : customerPhone || undefined,
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setActiveReceipt(newSale); // Trigger Receipt View

    // Reset Everything
    setCart([]);
    setAmountPaid('');
    setPaymentMethod('Cash');
    setCustomerName('');
    setCustomerPhone('');
  };

  const lastClosingTimestamp = useMemo(() => {
    if (closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  const activeSales = useMemo(() => {
    return [...sales]
      .filter(s => new Date(s.date).getTime() > lastClosingTimestamp)
      .reverse()
      .slice(0, 10);
  }, [sales, lastClosingTimestamp]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in duration-500 relative">

      {/* Receipt Modal (Print View) */}
      {activeReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 no-print">
          <div className="bg-white dark:bg-[#1a2236] w-full max-w-sm rounded-[2rem] shadow-2xl overflow-hidden animate-in zoom-in duration-300">
             <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                <h3 className="font-black text-slate-900 dark:text-white flex items-center gap-2 uppercase tracking-widest text-sm">
                   <Printer size={18} className="text-orange-500" /> Sale Memo
                </h3>
                <button onClick={() => setActiveReceipt(null)} className="p-2 text-slate-400 hover:text-red-500 transition-colors">
                   <X size={20} />
                </button>
             </div>

             {/* Printable Section */}
             <div id="pos-receipt-container" className="p-8 bg-white text-black font-mono text-[12px] leading-tight">
                <div className="text-center mb-4">
                   <h2 className="text-xl font-black uppercase tracking-tighter">Sweet Live Bakery</h2>
                   <p className="text-[10px]">Quality You Can Taste</p>
                   <div className="border-b border-dashed border-black my-2"></div>
                   <p className="text-[9px]">Memo ID: {activeReceipt.id}</p>
                   <p className="text-[9px]">Date: {new Date(activeReceipt.date).toLocaleString()}</p>
                </div>

                <table className="w-full mb-4">
                   <thead>
                      <tr className="border-b border-dashed border-black">
                         <th className="text-left pb-1">Item</th>
                         <th className="text-center pb-1">Qty</th>
                         <th className="text-right pb-1">Total</th>
                      </tr>
                   </thead>
                   <tbody>
                      {activeReceipt.items.map((item, idx) => (
                        <tr key={idx}>
                           <td className="py-1">{item.productName}</td>
                           <td className="text-center">{item.quantity}</td>
                           <td className="text-right">৳{item.subTotal.toLocaleString()}</td>
                        </tr>
                      ))}
                   </tbody>
                </table>

                <div className="border-t border-dashed border-black pt-2 space-y-1">
                   <div className="flex justify-between font-bold">
                      <span>Subtotal:</span>
                      <span>৳{activeReceipt.totalPrice.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between">
                      <span>Paid ({activeReceipt.paymentMethod}):</span>
                      <span>৳{activeReceipt.amountPaid.toLocaleString()}</span>
                   </div>
                   {activeReceipt.dueAmount > 0 && (
                     <div className="flex justify-between font-black">
                        <span>Due Amount:</span>
                        <span>৳{activeReceipt.dueAmount.toLocaleString()}</span>
                     </div>
                   )}
                </div>

                {(activeReceipt.customerName || activeReceipt.customerPhone) && (
                  <div className="mt-4 pt-2 border-t border-black text-[10px]">
                     <p>Customer: {activeReceipt.customerName || 'Walk-in'}</p>
                     {activeReceipt.customerPhone && <p>Phone: {activeReceipt.customerPhone}</p>}
                  </div>
                )}

                <div className="text-center mt-6">
                   <p className="font-bold">Thank You!</p>
                   <p className="text-[8px]">Software Developed by Shamim</p>
                </div>
             </div>

             <div className="p-6 bg-slate-50 dark:bg-black/20 flex gap-3">
                <button 
                  onClick={handlePrint}
                  className="flex-1 bg-orange-500 hover:bg-orange-600 text-white font-black py-4 rounded-xl shadow-lg transition-all active:scale-95 flex items-center justify-center gap-2"
                >
                  <Printer size={18} /> Print Now
