                >
                  Close
                </button>
             </div>
          </div>
        </div>
      )}

      {/* LEFT: Product Selection & Cart */}
      <div className="lg:col-span-8 space-y-6 no-print">
        {/* Selection Area */}
        <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <div className="flex flex-col md:flex-row gap-4 items-end">
             <div className="flex-1 space-y-2 w-full">
                <label className="text-xs font-black text-slate-500 uppercase px-1">Choose Product (প্রোডাক্ট)</label>
