                  className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50"
                  value={selectedProductId}
                  onChange={e => setSelectedProductId(e.target.value)}
                >
                  <option value="">Search or Select Product...</option>
                  {products.map(p => (
                    <option key={p.id} value={p.id} disabled={p.stock <= 0}>
                      {p.name} (৳{p.price}/{p.unit}) - Stock: {p.stock}
                    </option>
                  ))}
                </select>
             </div>

             <div className="w-full md:w-32 space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase px-1">Quantity</label>
                <input 
                  type="number" 
