        <button 
          onClick={() => setActiveTab('pos')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'pos' ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-400 hover:text-orange-500'}`}
        >
          <PlusCircle size={18} /> New Sale
        </button>
        <button 
          onClick={() => setActiveTab('history')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'history' ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-400 hover:text-orange-500'}`}
        >
          <HistoryIcon size={18} /> Sales History
        </button>
      </div>

      {/* POS VIEW */}
      {activeTab === 'pos' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start no-print">
          <div className="lg:col-span-8 space-y-6">
            <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
               <div className="flex flex-col md:flex-row gap-4 items-end">
                 <div className="flex-1 space-y-2 w-full">
                    <label className="text-xs font-black text-slate-500 uppercase px-1">Choose Product (প্রোডাক্ট)</label>
                    <select 
                      className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50"
                      value={selectedProductId}
                      onChange={e => setSelectedProductId(e.target.value)}
                    >
                      <option value="">Search or Select Product...</option>
                      {products.map(p => (
                        <option key={p.id} value={p.id} disabled={p.stock <= 0}>
                          {p.name} (৳{p.price}/{p.unit}) - Stock: {p.stock}
                        </option>
                      ))}
                    </select>
                 </div>

                 <div className="w-full md:w-32 space-y-2">
                    <label className="text-xs font-black text-slate-500 uppercase px-1">Quantity</label>
                    <input 
                      type="number" 
                      step="any"
                      placeholder="0"
                      className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-orange-500/50"
                      value={quantity}
                      onChange={e => setQuantity(e.target.value === '' ? '' : Number(e.target.value))}
                    />
                 </div>

                 <button 
                   onClick={addToCart}
                   disabled={!selectedProductId || !quantity}
                   className="w-full md:w-auto h-[60px] px-8 bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white font-black rounded-xl transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2"
                 >
                    <Plus size={20} /> Add to Order
                 </button>
               </div>
            </div>

            <div className="bg-white dark:bg-[#1a2236] rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden min-h-[400px] flex flex-col">
               <div className="p-6 px-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                  <h3 className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2">
                     <ShoppingCart size={20} className="text-orange-500" /> Current Order Items (কার্ট)
                  </h3>
                  <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">
                     {cart.length} Item(s)
                  </div>
               </div>

               <div className="flex-1 overflow-y-auto custom-scrollbar">
                  <table className="w-full text-left text-sm">
                    <thead>
                       <tr className="text-[10px] uppercase text-slate-400 font-bold tracking-widest bg-slate-50/50 dark:bg-transparent border-b border-slate-100 dark:border-slate-800">
