export default SalesView;

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, DailyClosing, SaleItem } from '../types';
import { 
  ShoppingCart, 
  User, 
  Phone, 
  Wallet, 
  Trash2, 
  Plus, 
  Minus, 
  Package, 
  Search, 
  Printer, 
  X, 
  History as HistoryIcon, 
  PlusCircle, 
  RotateCcw, 
  Filter,
  CheckCircle2,
  Trash
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
  closings?: DailyClosing[];
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale, closings = [] }) => {
  // Navigation State
  const [activeTab, setActiveTab] = useState<'pos' | 'history'>('pos');

  // POS State
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [cart, setCart] = useState<SaleItem[]>([]);

  // Checkout States
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Receipt State
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);

  // History Filter States
  const [historySearch, setHistorySearch] = useState('');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');
  const [historyPaymentFilter, setHistoryPaymentFilter] = useState<'All' | 'Cash' | 'Mobile Payment'>('All');

  // Categories extraction
  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['All', ...cats];
  }, [products]);

  // Filtered Products for Grid
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase());
      const matchCat = selectedCategory === 'All' || p.category === selectedCategory;
      return matchSearch && matchCat;
    });
  }, [products, searchQuery, selectedCategory]);

  // Cart Logic
  const totalPrice = cart.reduce((acc, item) => acc + item.subTotal, 0);

  useEffect(() => {
    if (totalPrice > 0) {
      setAmountPaid(totalPrice);
    } else {
      setAmountPaid('');
    }
  }, [totalPrice]);

  const dueAmount = totalPrice - (Number(amountPaid) || 0);

  const updateCartQuantity = (productId: string, delta: number) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    setCart(prev => {
      const existing = prev.find(item => item.productId === productId);
      if (existing) {
        const newQty = existing.quantity + delta;
        if (newQty <= 0) {
          return prev.filter(item => item.productId !== productId);
        }
        if (newQty > product.stock) {
          alert(`দুঃখিত! স্টকে মাত্র ${product.stock} ${product.unit} আছে।`);
          return prev;
        }
        return prev.map(item => 
          item.productId === productId 
            ? { ...item, quantity: newQty, subTotal: newQty * item.pricePerUnit } 
            : item
        );
      } else if (delta > 0) {
        if (product.stock < 1) {
          alert("এই প্রোডাক্টটি স্টকে নেই!");
          return prev;
        }
        const newItem: SaleItem = {
          productId: product.id,
          productName: product.name,
          quantity: 1,
          unit: product.unit || 'pcs',
          pricePerUnit: product.price,
          subTotal: product.price
        };
        return [...prev, newItem];
      }
      return prev;
    });
  };

  // Submit Sale
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;

    if (dueAmount > 0.01 && !customerName) {
      alert("বাকি বিক্রয়ের ক্ষেত্রে কাস্টমারের নাম অবশ্যই দিতে হবে।");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: Math.max(0, dueAmount),
      customerName: customerName || undefined,
      customerPhone: customerPhone || undefined,
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setActiveReceipt(newSale); 

    setCart([]);
    setAmountPaid('');
    setPaymentMethod('Cash');
    setCustomerName('');
    setCustomerPhone('');
  };

  // History Logic
  const filteredHistory = useMemo(() => {
    return [...sales].filter(sale => {
      const query = historySearch.toLowerCase();
      const matchSearch = !historySearch || 
        (sale.customerName?.toLowerCase().includes(query)) ||
        (sale.customerPhone?.includes(query)) ||
        (sale.items.some(item => item.productName.toLowerCase().includes(query)));

      const saleDate = new Date(sale.date);
      saleDate.setHours(0, 0, 0, 0);

      let matchDate = true;
      if (historyStartDate) {
        const start = new Date(historyStartDate);
        start.setHours(0, 0, 0, 0);
        if (saleDate < start) matchDate = false;
      }
      if (historyEndDate) {
        const end = new Date(historyEndDate);
        end.setHours(0, 0, 0, 0);
        if (saleDate > end) matchDate = false;
      }

      const matchPayment = historyPaymentFilter === 'All' || sale.paymentMethod === historyPaymentFilter;

      return matchSearch && matchDate && matchPayment;
    }).reverse();
  }, [sales, historySearch, historyStartDate, historyEndDate, historyPaymentFilter]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* Tab Switcher */}
      <div className="flex bg-white dark:bg-[#1a2236] p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm w-fit no-print">
        <button 
          onClick={() => setActiveTab('pos')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'pos' ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-400 hover:text-orange-500'}`}
        >
          <PlusCircle size={18} /> New Order
        </button>
        <button 
          onClick={() => setActiveTab('history')}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'history' ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-400 hover:text-orange-500'}`}
        >
          <HistoryIcon size={18} /> Sales History
        </button>
      </div>

      {/* NEW ORDER (POS) VIEW */}
      {activeTab === 'pos' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start no-print">

          {/* LEFT: Product Grid */}
          <div className="lg:col-span-8 space-y-6">

            {/* Search & Category Bar */}
            <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
                <input 
                  type="text" 
                  placeholder="খাবার বা প্রোডাক্ট সার্চ করুন..." 
                  className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50"
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex flex-wrap gap-2 overflow-x-auto pb-2 custom-scrollbar">
                {categories.map(cat => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`px-5 py-2 rounded-full text-xs font-bold transition-all whitespace-nowrap border ${
                      selectedCategory === cat 
                        ? 'bg-orange-500 text-white border-orange-500 shadow-md' 
                        : 'bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700 hover:border-orange-500/50'
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>

            {/* Grid */}
