            <div className="flex gap-3"><button onClick={handleCloseDay} className="w-full md:w-auto bg-orange-500 hover:bg-orange-600 text-white px-10 py-4 rounded-2xl font-bold flex items-center justify-center gap-3 transition-all group"><Lock size={20} /> Close & Print Summary</button></div>
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8 grid grid-cols-2 md:grid-cols-4 gap-4"><SummaryItem title="Total Sales" value={activeStats.sales} bangla="মোট বিক্রি" color="text-slate-600" /><SummaryItem title="Total Expenses" value={activeStats.expenses} bangla="মোট খরচ" color="text-red-500" /><SummaryItem title="Total Wastage" value={activeStats.wastage} bangla="নষ্ট মাল" color="text-orange-500" /><SummaryItem title="System Balance" value={activeStats.balance} bangla="সিস্টেম হিসাব" color="text-emerald-500" highlight /></div>
            <div className="lg:col-span-4 bg-orange-500/5 p-8 rounded-[2rem] border-2 border-orange-500/20"><input type="number" className="w-full bg-white dark:bg-[#0a1120] border-2 border-orange-500/30 rounded-2xl p-4 text-2xl font-black text-slate-900 dark:text-white outline-none" placeholder="Actual Cash" value={actualCashInput} onChange={e => setActualCashInput(e.target.value === '' ? '' : Number(e.target.value))} /></div>
          </div>
        </div>
