                   <p className="font-bold">DAILY CLOSING REPORT</p>
                   <div className="border-b border-dashed border-black my-2"></div>
                   <div className="flex justify-between mb-4"><span>Date: {new Date(activePrintRecord.date).toLocaleDateString()}</span><span>By: {activePrintRecord.closedBy}</span></div>
                   <div className="space-y-1 text-left">
                      <div className="flex justify-between"><span>Gross Sales:</span><span>৳{activePrintRecord.totalSales.toLocaleString()}</span></div>
                      <div className="flex justify-between"><span>Cash Collected:</span><span>৳{activePrintRecord.totalCashCollected.toLocaleString()}</span></div>
                      <div className="flex justify-between"><span>Expenses:</span><span>- ৳{activePrintRecord.totalExpenses.toLocaleString()}</span></div>
                      <div className="flex justify-between"><span>Wastage Loss:</span><span>- ৳{(activePrintRecord.totalWastage || 0).toLocaleString()}</span></div>
                      <div className="border-t border-black my-1"></div>
                      <div className="flex justify-between font-black"><span>System Balance:</span><span>৳{activePrintRecord.systemBalance.toLocaleString()}</span></div>
                      <div className="flex justify-between font-black"><span>Actual Cash:</span><span>৳{activePrintRecord.actualCash.toLocaleString()}</span></div>
                      <div className="border-t border-black my-1"></div>
                      <div className="flex justify-between font-black"><span>Difference:</span><span>৳{activePrintRecord.difference.toLocaleString()}</span></div>
                   </div>
                   <div className="mt-8 border-t border-dashed border-black pt-4">
                      <p className="text-[9px]">Report Generated: {new Date(activePrintRecord.timestamp).toLocaleString()}</p>
                   </div>
                </div>
             </div>
             <div className="p-6 flex gap-3"><button onClick={handlePrint} className="flex-1 bg-orange-500 text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-2"><Printer size={18} /> Print Now</button><button onClick={() => setActivePrintRecord(null)} className="px-6 py-4 bg-slate-200 text-slate-600 font-bold rounded-xl">Close</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

