import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction, Wastage } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { supabaseService } from './services/supabaseService';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  LogOut,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  Monitor,
  Trash2,
  CloudSync
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  useEffect(() => {
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  useEffect(() => {
    const auth = localStorage.getItem('sweetBakery_auth');
    if (auth) {
      setIsAuthenticated(true);
      setCurrentUser(auth.toLowerCase());
    }
  }, []);

  // Fetch data from Supabase on login
  useEffect(() => {
    const fetchData = async () => {
      if (currentUser && isAuthenticated) {
        setIsDataLoaded(false);
        setIsSyncing(true);
        try {
          const [p, s, e, w, st, att, clos, ded] = await Promise.all([
            supabaseService.getProducts(currentUser),
            supabaseService.getSales(currentUser),
            supabaseService.getExpenses(currentUser),
            supabaseService.getWastage(currentUser),
            supabaseService.getStaff(currentUser),
            supabaseService.getAttendance(currentUser),
            supabaseService.getClosings(currentUser),
            supabaseService.getDeductions(currentUser)
          ]);

          setProducts(p || []);
          setSales(s || []);
          setExpenses(e || []);
          setWastage(w || []);
          setStaff(st || []);
          setAttendance(att || []);
          setDailyClosings(clos || []);
          setDeductions(ded || []);
        } catch (err) {
          console.error("Supabase load error:", err);
        } finally {
          setIsDataLoaded(true);
          setIsSyncing(false);
        }
      }
    };
    fetchData();
  }, [currentUser, isAuthenticated]);

  const handleLogin = (username: string) => {
    const normalizedUsername = username.toLowerCase();
    setCurrentUser(normalizedUsername);
    setIsAuthenticated(true);
    localStorage.setItem('sweetBakery_auth', normalizedUsername);
  };

  const handleLogout = () => {
    if (window.confirm("আপনি কি লগআউট করতে চান?")) {
      setIsAuthenticated(false);
      setCurrentUser('');
      setIsDataLoaded(false);
      localStorage.removeItem('sweetBakery_auth');
    }
  };

  // State Management with DB persistence
  const addSale = async (newSale: Sale) => {
    setIsSyncing(true);
    try {
      await supabaseService.addSale(currentUser, newSale);
      setSales(prev => [...prev, newSale]);

      const updatedProducts = products.map(p => {
        const itemInSale = newSale.items.find(item => item.productId === p.id);
        if (itemInSale) {
          const updatedP = { ...p, stock: Math.max(0, p.stock - itemInSale.quantity) };
          supabaseService.upsertProduct(currentUser, updatedP); // Sync product stock update
          return updatedP;
        }
        return p;
      });
      setProducts(updatedProducts);
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const cancelSale = async (saleId: string) => {
    const saleToCancel = sales.find(s => s.id === saleId);
    if (!saleToCancel) return;

    if (window.confirm(`বিক্রয় বাতিল করতে চান?`)) {
      setIsSyncing(true);
      try {
        await supabaseService.deleteSale(saleId);
        setSales(prev => prev.filter(s => s.id !== saleId));

        const updatedProducts = products.map(p => {
          const itemInSale = saleToCancel.items.find(item => item.productId === p.id);
          if (itemInSale) {
            const updatedP = { ...p, stock: p.stock + itemInSale.quantity };
            supabaseService.upsertProduct(currentUser, updatedP);
            return updatedP;
          }
          return p;
        });
        setProducts(updatedProducts);
      } catch (e) { console.error(e); } finally { setIsSyncing(false); }
    }
  };

  const updateSales = async (updatedSales: Sale[]) => {
    setIsSyncing(true);
    try {
      for (const sale of updatedSales) {
        await supabaseService.updateSale(sale);
      }
      setSales(prev => {
        const newSales = [...prev];
        updatedSales.forEach(updated => {
          const index = newSales.findIndex(s => s.id === updated.id);
          if (index !== -1) newSales[index] = updated;
        });
        return newSales;
      });
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const addProduct = async (product: Product) => {
    setIsSyncing(true);
    try {
      await supabaseService.upsertProduct(currentUser, product);
      setProducts(prev => [...prev, product]);
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const updateProduct = async (product: Product) => {
    setIsSyncing(true);
    try {
      await supabaseService.upsertProduct(currentUser, product);
      setProducts(prev => prev.map(p => p.id === product.id ? product : p));
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const deleteProduct = async (id: string) => {
    setIsSyncing(true);
    try {
      await supabaseService.deleteProduct(id);
      setProducts(prev => prev.filter(p => p.id !== id));
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const addExpense = async (expense: Expense) => {
    setIsSyncing(true);
    try {
      await supabaseService.addExpense(currentUser, expense);
      setExpenses(prev => [...prev, expense]);
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const addWastage = async (newWastage: Wastage) => {
    setIsSyncing(true);
    try {
      await supabaseService.addWastage(currentUser, newWastage);
      setWastage(prev => [...prev, newWastage]);

      const updatedProducts = products.map(p => {
        if (p.id === newWastage.productId) {
          const updatedP = { ...p, stock: Math.max(0, p.stock - newWastage.quantity) };
          supabaseService.upsertProduct(currentUser, updatedP);
          return updatedP;
        }
        return p;
      });
      setProducts(updatedProducts);
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const deleteWastage = async (id: string) => {
    const item = wastage.find(w => w.id === id);
    if (!item) return;

    if (window.confirm(`ডিলিট করতে চান?`)) {
      setIsSyncing(true);
      try {
        await supabaseService.deleteWastage(id);
        setWastage(prev => prev.filter(w => w.id !== id));

        const updatedProducts = products.map(p => {
          if (p.id === item.productId) {
            const updatedP = { ...p, stock: p.stock + item.quantity };
            supabaseService.upsertProduct(currentUser, updatedP);
            return updatedP;
          }
          return p;
        });
        setProducts(updatedProducts);
      } catch (e) { console.error(e); } finally { setIsSyncing(false); }
    }
  };

  const addStaffMember = async (newStaff: Staff) => {
    setIsSyncing(true);
    try {
      await supabaseService.addStaff(currentUser, newStaff);
      setStaff(prev => [...prev, newStaff]);
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const updateAttendance = async (newAttendance: Attendance) => {
    setIsSyncing(true);
    try {
      await supabaseService.upsertAttendance(currentUser, newAttendance);
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
        return [...filtered, newAttendance];
      });
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const addDeduction = async (newDeduction: Deduction) => {
    setIsSyncing(true);
    try {
      await supabaseService.addDeduction(currentUser, newDeduction);
      setDeductions(prev => [...prev, newDeduction]);
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const addDailyClosing = async (closing: DailyClosing) => {
    setIsSyncing(true);
    try {
      await supabaseService.addClosing(currentUser, closing);
      setDailyClosings(prev => [...prev, closing]);
      setCurrentView(View.DASHBOARD);
      alert('ডেইলি ক্লোজিং সফল হয়েছে!');
    } catch (e) { console.error(e); } finally { setIsSyncing(false); }
  };

  const deleteDailyClosing = async (id: string) => {
    if (window.confirm('মুছে ফেলতে চান?')) {
      setIsSyncing(true);
      try {
        await supabaseService.deleteClosing(id);
        setDailyClosings(prev => prev.filter(c => c.id !== id));
      } catch (e) { console.error(e); } finally { setIsSyncing(false); }
    }
  };

  const paySalary = async (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;
    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary: ${staffMember.name}`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    await addExpense(newExpense);
  };

  const lowStockCount = useMemo(() => products.filter(p => p.stock < 10).length, [products]);

  if (!isAuthenticated) return <Login onLogin={handleLogin} theme={theme} />;

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white ${isMobileMenuOpen ? 'overflow-hidden' : ''}`}>
      {isMobileMenuOpen && <div className="fixed inset-0 bg-slate-900/60 z-[60] lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />}

      <aside className={`w-72 bg-white dark:bg-dark-bg border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-transform lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3"><UtensilsCrossed size={20} className="text-orange-500" /><h1 className="text-xl font-bold text-orange-500">Sweet Live</h1></div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden"><X size={24} /></button>
        </div>
        <nav className="flex-1 px-4 space-y-1.5 overflow-y-auto">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl ${currentView === item.id ? 'bg-orange-500 text-white' : 'text-slate-500 dark:text-slate-400 hover:bg-orange-50 dark:hover:bg-slate-800'}`}>
              {item.icon} <div className="text-left"><p className="text-sm font-bold">{item.label}</p><p className="text-[9px] opacity-60">{item.bangla}</p></div>
              {item.notification > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-full">{item.notification}</span>}
            </button>
          ))}
        </nav>
        <div className="p-6">
           <div className="bg-slate-100 dark:bg-slate-800/40 p-4 rounded-xl">
             <div className="flex items-center gap-2 mb-2">
                <CloudSync size={16} className={isSyncing ? "animate-spin text-orange-500" : "text-emerald-500"} />
                <span className="text-[10px] font-bold uppercase">{isSyncing ? "Syncing Cloud..." : "Cloud Connected"}</span>
             </div>
             <p className="text-[10px] text-slate-500">User: <span className="capitalize">{currentUser}</span></p>
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 min-h-screen flex flex-col">
        <header className="px-4 md:px-8 py-4 bg-slate-50/80 dark:bg-dark-bg/80 backdrop-blur-md sticky top-0 z-40 flex justify-between items-center border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-3">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-orange-500"><Menu size={24} /></button>
            <h2 className="text-xl font-black">{currentView.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-orange-500">{theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}</button>
             <button onClick={handleLogout} className="px-4 py-2.5 bg-red-500/10 text-red-500 font-bold rounded-xl text-sm">Logout</button>
