        if (insError) throw insError;

        alert('রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন।');
        setIsSignup(false);
        setPassword('');
      } else {
        const { data: user, error: selError } = await supabase
          .from('profiles')
          .select('*')
          .eq('email', normalizedEmail)
          .eq('password', password)
