           <UtensilsCrossed size={40} className="text-orange-500" />
        </div>
        <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Sweet Live Bakery</h1>
        <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-[10px] mt-1">Bakery Management Cloud</p>
