import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction, Wastage } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { supabaseService } from './services/supabaseService';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  Trash2,
  CloudSync
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('sweetBakery_theme') as 'dark' | 'light') || 'dark';
  });

  const [isSyncing, setIsSyncing] = useState(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  useEffect(() => {
    const savedEmail = localStorage.getItem('sweetBakery_email');
    if (savedEmail) {
      setIsAuthenticated(true);
      setUserEmail(savedEmail.toLowerCase());
    }
  }, []);

  // Fetch data from Supabase on login
  useEffect(() => {
    const fetchData = async () => {
      if (userEmail && isAuthenticated) {
        setIsDataLoaded(false);
        setIsSyncing(true);
        try {
          const [p, s, e, w, st, att, clos, ded] = await Promise.all([
            supabaseService.getProducts(userEmail),
            supabaseService.getSales(userEmail),
            supabaseService.getExpenses(userEmail),
            supabaseService.getWastage(userEmail),
            supabaseService.getStaff(userEmail),
            supabaseService.getAttendance(userEmail),
            supabaseService.getClosings(userEmail),
            supabaseService.getDeductions(userEmail)
          ]);

          setProducts(p || []);
          setSales(s || []);
          setExpenses(e || []);
          setWastage(w || []);
          setStaff(st || []);
          setAttendance(att || []);
          setDailyClosings(clos || []);
          setDeductions(ded || []);
        } catch (err) {
          console.error("Supabase load error:", err);
        } finally {
          setIsDataLoaded(true);
          setIsSyncing(false);
        }
      }
    };
    fetchData();
  }, [userEmail, isAuthenticated]);

  const handleLogin = (email: string) => {
    const normalizedEmail = email.toLowerCase();
    setUserEmail(normalizedEmail);
    setIsAuthenticated(true);
    localStorage.setItem('sweetBakery_email', normalizedEmail);
  };

  const handleLogout = () => {
    if (window.confirm("আপনি কি লগআউট করতে চান?")) {
      setIsAuthenticated(false);
      setUserEmail('');
      setIsDataLoaded(false);
      localStorage.removeItem('sweetBakery_email');
    }
  };

  // Logic Wrapper for DB interactions
  const withSync = async (fn: () => Promise<void>) => {
    setIsSyncing(true);
    try {
      await fn();
    } catch (e) {
      console.error(e);
      alert('সিস্টেম ত্রুটি! ইন্টারনেট চেক করুন।');
    } finally {
      setIsSyncing(false);
    }
  };

  const addSale = (newSale: Sale) => withSync(async () => {
    await supabaseService.addSale(userEmail, newSale);
    setSales(prev => [...prev, newSale]);

    const updatedProducts = products.map(p => {
      const itemInSale = newSale.items.find(item => item.productId === p.id);
      if (itemInSale) {
        const updatedP = { ...p, stock: Math.max(0, p.stock - itemInSale.quantity) };
        supabaseService.upsertProduct(userEmail, updatedP);
        return updatedP;
      }
      return p;
    });
    setProducts(updatedProducts);
  });

  const cancelSale = (saleId: string) => {
    const saleToCancel = sales.find(s => s.id === saleId);
    if (!saleToCancel) return;

    if (window.confirm(`বিক্রয় বাতিল করতে চান?`)) {
      withSync(async () => {
        await supabaseService.deleteSale(saleId);
        setSales(prev => prev.filter(s => s.id !== saleId));

        const updatedProducts = products.map(p => {
          const itemInSale = saleToCancel.items.find(item => item.productId === p.id);
          if (itemInSale) {
            const updatedP = { ...p, stock: p.stock + itemInSale.quantity };
            supabaseService.upsertProduct(userEmail, updatedP);
            return updatedP;
          }
          return p;
        });
        setProducts(updatedProducts);
      });
    }
  };

  const updateSales = (updatedSales: Sale[]) => withSync(async () => {
    for (const sale of updatedSales) {
      await supabaseService.updateSale(sale);
    }
    setSales(prev => {
      const newSales = [...prev];
      updatedSales.forEach(updated => {
        const index = newSales.findIndex(s => s.id === updated.id);
        if (index !== -1) newSales[index] = updated;
      });
      return newSales;
    });
  });

  const addProduct = (product: Product) => withSync(async () => {
    await supabaseService.upsertProduct(userEmail, product);
    setProducts(prev => [...prev, product]);
  });

  const updateProduct = (product: Product) => withSync(async () => {
    await supabaseService.upsertProduct(userEmail, product);
    setProducts(prev => prev.map(p => p.id === product.id ? product : p));
  });

  const deleteProduct = (id: string) => withSync(async () => {
    await supabaseService.deleteProduct(id);
    setProducts(prev => prev.filter(p => p.id !== id));
  });

  const addExpense = (expense: Expense) => withSync(async () => {
    await supabaseService.addExpense(userEmail, expense);
    setExpenses(prev => [...prev, expense]);
  });

  const addWastage = (newWastage: Wastage) => withSync(async () => {
    await supabaseService.addWastage(userEmail, newWastage);
    setWastage(prev => [...prev, newWastage]);
    const updatedProducts = products.map(p => {
      if (p.id === newWastage.productId) {
        const updatedP = { ...p, stock: Math.max(0, p.stock - newWastage.quantity) };
        supabaseService.upsertProduct(userEmail, updatedP);
        return updatedP;
      }
      return p;
    });
    setProducts(updatedProducts);
  });

  const deleteWastage = (id: string) => {
    const item = wastage.find(w => w.id === id);
    if (!item) return;
    if (window.confirm(`ডিলিট করতে চান?`)) {
      withSync(async () => {
        await supabaseService.deleteWastage(id);
        setWastage(prev => prev.filter(w => w.id !== id));
        const updatedProducts = products.map(p => {
          if (p.id === item.productId) {
            const updatedP = { ...p, stock: p.stock + item.quantity };
            supabaseService.upsertProduct(userEmail, updatedP);
            return updatedP;
          }
          return p;
        });
        setProducts(updatedProducts);
      });
    }
  };

  const addStaffMember = (newStaff: Staff) => withSync(async () => {
    await supabaseService.addStaff(userEmail, newStaff);
    setStaff(prev => [...prev, newStaff]);
  });

  const updateAttendance = (newAttendance: Attendance) => withSync(async () => {
    await supabaseService.upsertAttendance(userEmail, newAttendance);
    setAttendance(prev => {
      const filtered = prev.filter(a => !(a.staffId === newAttendance.staffId && a.date === newAttendance.date));
      return [...filtered, newAttendance];
    });
  });

  const addDeduction = (newDeduction: Deduction) => withSync(async () => {
    await supabaseService.addDeduction(userEmail, newDeduction);
    setDeductions(prev => [...prev, newDeduction]);
  });

  const addDailyClosing = (closing: DailyClosing) => withSync(async () => {
    await supabaseService.addClosing(userEmail, closing);
    setDailyClosings(prev => [...prev, closing]);
    setCurrentView(View.DASHBOARD);
  });

  const deleteDailyClosing = (id: string) => withSync(async () => {
    await supabaseService.deleteClosing(id);
    setDailyClosings(prev => prev.filter(c => c.id !== id));
  });

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;
    const newExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary: ${staffMember.name}`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(newExpense);
  };

  const lowStockCount = useMemo(() => products.filter(p => p.stock < 10).length, [products]);

  if (!isAuthenticated) return <Login onLogin={handleLogin} theme={theme} />;

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white transition-colors duration-500 ${isMobileMenuOpen ? 'overflow-hidden' : ''}`}>
      {isMobileMenuOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />}

      <aside className={`w-72 bg-white dark:bg-[#0a1120] border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-all duration-300 lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-orange-500 rounded-xl shadow-lg shadow-orange-500/20">
              <UtensilsCrossed size={24} className="text-white" />
            </div>
            <h1 className="text-xl font-black text-slate-900 dark:text-white tracking-tight">Sweet Live</h1>
          </div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden p-2 text-slate-400"><X size={24} /></button>
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all ${currentView === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800/50'}`}>
              <span className={currentView === item.id ? 'text-white' : 'text-orange-500'}>{item.icon}</span>
              <div className="text-left flex-1">
                <p className={`text-sm font-bold ${currentView === item.id ? 'text-white' : 'text-slate-700 dark:text-slate-200'}`}>{item.label}</p>
                <p className="text-[9px] font-medium opacity-60 tracking-wider uppercase">{item.bangla}</p>
              </div>
              {item.notification > 0 && <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black">{item.notification}</span>}
            </button>
          ))}
        </nav>

        <div className="p-6">
           <div className="bg-slate-50 dark:bg-slate-800/20 p-5 rounded-3xl border border-slate-100 dark:border-slate-800">
             <div className="flex items-center gap-3 mb-3">
                <div className={`p-2 rounded-lg ${isSyncing ? "bg-orange-500/10" : "bg-emerald-500/10"}`}>
                  <CloudSync size={16} className={isSyncing ? "animate-spin text-orange-500" : "text-emerald-500"} />
                </div>
                <span className="text-[10px] font-black uppercase tracking-widest">{isSyncing ? "Syncing..." : "Live Cloud"}</span>
             </div>
             <p className="text-[10px] text-slate-400 font-bold truncate">ID: {userEmail}</p>
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 min-h-screen flex flex-col">
        <header className="px-6 md:px-10 py-5 bg-slate-50/80 dark:bg-dark-bg/80 backdrop-blur-xl sticky top-0 z-40 flex justify-between items-center border-b border-slate-200 dark:border-slate-800 transition-all">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2.5 bg-white dark:bg-slate-800 rounded-xl shadow-sm"><Menu size={22} className="text-orange-500" /></button>
            <div>
              <h2 className="text-xl font-black text-slate-900 dark:text-white capitalize">{currentView.replace('_', ' ').toLowerCase()}</h2>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Bakery Operations</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-orange-500 shadow-sm transition-all hover:scale-105">{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button>
             <button onClick={handleLogout} className="px-5 py-3 bg-red-500/10 text-red-500 font-black rounded-2xl text-[11px] uppercase tracking-widest transition-all hover:bg-red-500 hover:text-white">Logout</button>
          </div>
        </header>

        <div className="p-4 md:p-10 flex-1">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center h-[60vh]">
              <div className="relative">
                <div className="w-20 h-20 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div>
                <CloudSync className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-orange-500" size={24} />
              </div>
              <p className="mt-8 font-black uppercase tracking-[0.3em] text-[10px] text-slate-400 animate-pulse">Initializing Bakery Cloud...</p>
            </div>
          ) : (
            <>
              {currentView === View.DASHBOARD && <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} />}
              {currentView === View.INVENTORY && <Inventory products={products} onAdd={addProduct} onUpdate={updateProduct} onDelete={deleteProduct} onMarkWastage={(p, qty, reason) => addWastage({ id: Date.now().toString(), productId: p.id, productName: p.name, quantity: qty, unit: p.unit, lossValue: p.price * qty, reason, date: new Date().toISOString() })} />}
              {currentView === View.SALES && <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={cancelSale} closings={dailyClosings} />}
              {currentView === View.DUES && <DuesView sales={sales} onUpdateSales={updateSales} />}
              {currentView === View.WASTAGE && <WastageView wastage={wastage} products={products} onAdd={addWastage} onDelete={deleteWastage} closings={dailyClosings} />}
              {currentView === View.EXPENSES && <ExpensesView expenses={expenses} onAdd={addExpense} closings={dailyClosings} />}
              {currentView === View.DAILY_CLOSING && <DailyClosingView sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onCloseDay={addDailyClosing} onDeleteClosing={deleteDailyClosing} currentUser={userEmail} />}
              {currentView === View.STAFF && <StaffView staff={staff} attendance={attendance} expenses={expenses} deductions={deductions} onAddStaff={addStaffMember} onUpdateAttendance={updateAttendance} onAddDeduction={addDeduction} onPaySalary={paySalary} />}
              {currentView === View.MANAGER && <ManagerView username={userEmail} onLogout={handleLogout} stats={{ products: products.length, sales: sales.length, expenses: expenses.length, staff: staff.length }} />}
            </>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import { supabase } from './supabaseClient';
import { Product, Sale, Expense, Wastage, Staff, Attendance, DailyClosing, Deduction } from '../types';

export const supabaseService = {
  // Products
  async getProducts(email: string) {
    const { data, error } = await supabase.from('products').select('*').eq('username', email);
    if (error) throw error;
    return data as Product[];
  },
  async upsertProduct(email: string, product: Product) {
    const { error } = await supabase.from('products').upsert({ ...product, username: email });
    if (error) throw error;
  },
  async deleteProduct(id: string) {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) throw error;
  },

  // Sales
  async getSales(email: string) {
    const { data, error } = await supabase.from('sales').select('*').eq('username', email);
    if (error) throw error;
    return data as Sale[];
  },
  async addSale(email: string, sale: Sale) {
    const { error } = await supabase.from('sales').insert({ ...sale, username: email });
    if (error) throw error;
  },
  async updateSale(sale: Sale) {
    const { error } = await supabase.from('sales').update(sale).eq('id', sale.id);
    if (error) throw error;
  },
  async deleteSale(id: string) {
    const { error } = await supabase.from('sales').delete().eq('id', id);
    if (error) throw error;
  },

  // Expenses
  async getExpenses(email: string) {
    const { data, error } = await supabase.from('expenses').select('*').eq('username', email);
    if (error) throw error;
    return data as Expense[];
  },
  async addExpense(email: string, expense: Expense) {
    const { error } = await supabase.from('expenses').insert({ ...expense, username: email });
    if (error) throw error;
  },

  // Wastage
  async getWastage(email: string) {
    const { data, error } = await supabase.from('wastage').select('*').eq('username', email);
    if (error) throw error;
    return data as Wastage[];
  },
  async addWastage(email: string, wastage: Wastage) {
    const { error } = await supabase.from('wastage').insert({ ...wastage, username: email });
    if (error) throw error;
  },
  async deleteWastage(id: string) {
    const { error } = await supabase.from('wastage').delete().eq('id', id);
    if (error) throw error;
  },

  // Staff
  async getStaff(email: string) {
    const { data, error } = await supabase.from('staff').select('*').eq('username', email);
    if (error) throw error;
    return data as Staff[];
  },
  async addStaff(email: string, staff: Staff) {
    const { error } = await supabase.from('staff').insert({ ...staff, username: email });
    if (error) throw error;
  },

  // Attendance
  async getAttendance(email: string) {
    const { data, error } = await supabase.from('attendance').select('*').eq('username', email);
    if (error) throw error;
    return data as Attendance[];
  },
  async upsertAttendance(email: string, attendance: Attendance) {
    const { error } = await supabase.from('attendance').upsert({ ...attendance, username: email });
    if (error) throw error;
  },

  // Closings
  async getClosings(email: string) {
    const { data, error } = await supabase.from('daily_closings').select('*').eq('username', email);
    if (error) throw error;
    return data as DailyClosing[];
  },
  async addClosing(email: string, closing: DailyClosing) {
    const { error } = await supabase.from('daily_closings').insert({ ...closing, username: email });
    if (error) throw error;
  },
  async deleteClosing(id: string) {
    const { error } = await supabase.from('daily_closings').delete().eq('id', id);
    if (error) throw error;
  },

  // Deductions
  async getDeductions(email: string) {
    const { data, error } = await supabase.from('deductions').select('*').eq('username', email);
    if (error) throw error;
    return data as Deduction[];
  },
  async addDeduction(email: string, deduction: Deduction) {
    const { error } = await supabase.from('deductions').insert({ ...deduction, username: email });
    if (error) throw error;
  }
};

import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { UtensilsCrossed, Lock, Mail, UserPlus, LogIn, ChevronRight, AlertCircle, Loader2 } from 'lucide-react';

interface Props {
  onLogin: (email: string) => void;
  theme: 'dark' | 'light';
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const validateEmail = (email: string) => {
    return String(email)
      .toLowerCase()
      .match(
        /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
      );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const normalizedEmail = email.trim().toLowerCase();

    if (!validateEmail(normalizedEmail)) {
      setError('সঠিক ইমেইল অ্যাড্রেস দিন। (যেমন: user@gmail.com)');
      return;
    }

    if (password.length < 6) {
      setError('নিরাপত্তার জন্য পাসওয়ার্ড অন্তত ৬ অক্ষরের দিন।');
      return;
    }

    setLoading(true);

    try {
      if (isSignup) {
        // Use maybeSingle to avoid errors when record is not found
        const { data: existing, error: checkError } = await supabase
          .from('profiles')
          .select('email')
          .eq('email', normalizedEmail)
          .maybeSingle();

        if (checkError) {
          console.error("Supabase Check Error:", checkError);
          throw new Error("ডাটাবেস কানেকশন এরর। অনুগ্রহ করে SQL টেবিলগুলো তৈরি করেছেন কি না চেক করুন।");
        }

        if (existing) {
          setError('এই ইমেইল দিয়ে ইতিমধ্যে অ্যাকাউন্ট খোলা আছে। লগইন করার চেষ্টা করুন।');
          setLoading(false);
          return;
        }

        const { error: insError } = await supabase
          .from('profiles')
          .insert([{ email: normalizedEmail, password: password }]);

        if (insError) {
          console.error("Supabase Insert Error:", insError);
          throw new Error("রেজিস্ট্রেশন সফল হয়নি। টেবিল পারমিশন বা স্কিমা চেক করুন।");
        }

        alert('অভিনন্দন! রেজিস্ট্রেশন সফল হয়েছে। এখন আপনার ইমেইল ও পাসওয়ার্ড দিয়ে লগইন করুন।');
        setIsSignup(false);
        setPassword('');
      } else {
        const { data: user, error: selError } = await supabase
          .from('profiles')
          .select('*')
          .eq('email', normalizedEmail)
          .eq('password', password)
          .maybeSingle();

        if (selError) {
          console.error("Login Error:", selError);
          throw new Error("লগইন করা যাচ্ছে না। ইন্টারনেটে সমস্যা হতে পারে।");
        }

        if (!user) {
          setError('ইমেইল অথবা পাসওয়ার্ড ভুল। আবার চেষ্টা করুন।');
        } else {
          onLogin(normalizedEmail);
        }
      }
    } catch (err: any) {
      console.error("Auth Exception:", err);
      setError(err.message || 'সার্ভারের সাথে সংযোগ করা যাচ্ছে না। আপনার Supabase টেবিলগুলো ঠিকঠাক আছে কি না নিশ্চিত করুন।');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 transition-colors duration-500">
      <div className="mb-10 text-center flex flex-col items-center animate-in fade-in slide-in-from-top-4 duration-700">
        <div className="w-20 h-20 bg-white dark:bg-[#161d31] rounded-3xl flex items-center justify-center shadow-2xl mb-6 border border-slate-200 dark:border-slate-800">
           <UtensilsCrossed size={40} className="text-orange-500" />
        </div>
        <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Sweet Live Bakery</h1>
        <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-[10px] mt-1">Bakery Management Cloud</p>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-slate-200 dark:border-slate-800 relative overflow-hidden transition-all duration-500 animate-in zoom-in duration-500">
          <div className="absolute top-0 left-0 w-full h-2 bg-orange-500"></div>

          <div className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-white">{isSignup ? 'Create Account' : 'Welcome Back'}</h2>
              <p className="text-slate-500 dark:text-slate-400 text-xs font-medium mt-1">
                {isSignup ? 'নতুন অ্যাকাউন্ট খুলুন' : 'অ্যাকাউন্টে লগইন করুন'}
              </p>
            </div>
            <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500">
              {isSignup ? <UserPlus size={28} /> : <LogIn size={28} />}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Email Address</label>
              <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                <input 
                  required 
                  type="email" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                  placeholder="example@gmail.com" 
                  value={email} 
                  onChange={e => setEmail(e.target.value)} 
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Secure Password</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                <input 
                  required 
                  type="password" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                  placeholder="••••••••" 
                  value={password} 
                  onChange={e => setPassword(e.target.value)} 
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-4 rounded-xl text-xs font-bold flex items-center gap-3 animate-pulse">
                <AlertCircle size={18} /> {error}
              </div>
            )}

            <button 
              type="submit" 
              disabled={loading} 
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-[0_15px_30px_-10px_rgba(242,103,17,0.4)] flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-70 disabled:active:scale-100"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : (isSignup ? 'Register Now' : 'Sign In')}
              {!loading && <ChevronRight size={20} />}
            </button>
          </form>

          <div className="mt-10 flex flex-col items-center gap-4">
            <button 
              onClick={() => { setIsSignup(!isSignup); setError(''); }} 
              className="text-slate-400 hover:text-orange-500 text-sm font-bold transition-colors"
            >
              {isSignup ? 'ইতিমধ্যে অ্যাকাউন্ট আছে? লগইন করুন' : "অ্যাকাউন্ট নেই? রেজিস্ট্রেশন করুন"}
            </button>
            <p className="text-[10px] text-slate-400 uppercase tracking-widest font-black opacity-50">Sweet Live • Cloud Secure</p>
          </div>
      </div>
    </div>
  );
};

export default Login;

