  description: string;
  amount: number;
  category: 'Raw Material' | 'Utilities' | 'Rent' | 'Staff' | 'Salary' | 'Other';
  date: string;
}

export interface Wastage {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  unit: string;
  lossValue: number;
  reason: string;
  date: string;
}

export interface Staff {
  id: string;
  name: string;
  designation: string;
  monthlySalary: number;
  joinDate: string;
}

export interface Attendance {
  id: string;
  staffId: string;
  date: string; // YYYY-MM-DD
  status: 'Present' | 'Late' | 'Absent';
}

export interface Deduction {
  id: string;
  staffId: string;
  amount: number;
  reason: string;
  date: string;
}

export interface DailyClosing {
  id: string;
  date: string; // YYYY-MM-DD
  totalSales: number;
  totalCashCollected: number;
  totalExpenses: number;
  totalWastage: number;
  systemBalance: number;
  actualCash: number;
  difference: number;
  closedBy: string;
  timestamp: string;
}

export enum View {
  DASHBOARD = 'DASHBOARD',
  SALES = 'SALES',
  INVENTORY = 'INVENTORY',
  EXPENSES = 'EXPENSES',
  STAFF = 'STAFF',
  MANAGER = 'MANAGER',
  DAILY_CLOSING = 'DAILY_CLOSING',
  DUES = 'DUES',
  WASTAGE = 'WASTAGE'
}

import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { Plus, Search, Package, Trash2, ChevronDown, AlertCircle, Banknote, Edit3, X, AlertTriangle, Trash, Barcode } from 'lucide-react';

interface Props {
  products: Product[];
  onAdd: (product: Product) => void;
  onUpdate: (product: Product) => void;
  onDelete: (id: string) => void;
  onMarkWastage: (p: Product, qty: number, reason: string) => void;
}

const Inventory: React.FC<Props> = ({ products, onAdd, onUpdate, onDelete, onMarkWastage }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'name_asc' | 'name_desc' | 'price_asc' | 'price_desc'>('name_asc');

  // Custom Modal States
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [wastageModalProduct, setWastageModalProduct] = useState<Product | null>(null);
  const [wastageQty, setWastageQty] = useState<number | ''>('');
  const [wastageReason, setWastageReason] = useState('Expired');

  const [formData, setFormData] = useState({
    name: '',
    category: 'Bread',
    price: '' as number | '',
    stock: '' as number | '',
    unit: 'pcs',
    barcode: ''
  });

  // Calculate Total Stock Value
  const stockSummary = useMemo(() => {
    const totalValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);
    const totalItems = products.length;
    const totalQuantity = products.reduce((acc, p) => acc + p.stock, 0);
    return { totalValue, totalItems, totalQuantity };
  }, [products]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      price: Number(formData.price) || 0,
      stock: Number(formData.stock) || 0
    };

    if (editingId) {
      onUpdate({ ...finalData, id: editingId } as Product);
      setEditingId(null);
    } else {
      onAdd({ ...finalData, id: Date.now().toString() } as Product);
    }
    setFormData({ name: '', category: 'Bread', price: '', stock: '', unit: 'pcs', barcode: '' });
    setIsAdding(false);
  };

  const handleWastageSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (wastageModalProduct && wastageQty !== '') {
      onMarkWastage(wastageModalProduct, Number(wastageQty), wastageReason);
      setWastageModalProduct(null);
      setWastageQty('');
      setWastageReason('Expired');
    }
  };

  const handleEdit = (p: Product) => {
    setFormData({
      name: p.name,
      category: p.category,
      price: p.price,
      stock: p.stock,
      unit: p.unit,
      barcode: p.barcode || ''
    });
    setEditingId(p.id);
    setIsAdding(true);
  };

  const executeDelete = () => {
    if (confirmDeleteId) {
      onDelete(confirmDeleteId);
      setConfirmDeleteId(null);
      if (editingId === confirmDeleteId) {
        setIsAdding(false);
        setEditingId(null);
      }
    }
  };

  const filteredProducts = products
    .filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    )
    .sort((a, b) => {
      if (sortBy === 'name_asc') return a.name.localeCompare(b.name);
      if (sortBy === 'name_desc') return b.name.localeCompare(a.name);
      if (sortBy === 'price_asc') return a.price - b.price;
      if (sortBy === 'price_desc') return b.price - a.price;
      return 0;
    });

  const units = ['pcs', 'kg', 'gm', 'pkt', 'ltr', 'box'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Stock Value Summary Card */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
        <div className="md:col-span-4 bg-emerald-600 p-8 rounded-[2.5rem] shadow-lg shadow-emerald-500/20 text-white border-4 border-white/10 relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-110 transition-transform duration-500">
             <Banknote size={180} />
          </div>
          <div className="relative z-10">
            <h4 className="text-emerald-100 font-bold text-xs mb-2 uppercase tracking-widest flex items-center gap-2">
               <Banknote size={16} /> Total Stock Value
            </h4>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-bold">৳</span>
              <span className="text-5xl font-black tracking-tighter">{stockSummary.totalValue.toLocaleString()}</span>
            </div>
            <p className="mt-4 text-emerald-100/70 text-[10px] font-bold uppercase tracking-widest">মজুদ মালের মোট মূল্য</p>
          </div>
        </div>

        <div className="md:col-span-8 bg-white dark:bg-[#161d31] p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-6">
           <div className="flex-1">
              <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Inventory Analysis</h2>
              <p className="text-slate-500 dark:text-slate-400 text-sm max-w-md">Currently tracking <span className="text-orange-500 font-bold">{stockSummary.totalItems} unique products</span> with a total quantity of {stockSummary.totalQuantity.toLocaleString()} units.</p>
           </div>
           <div className="flex gap-4 w-full sm:w-auto">
             <div className="flex-1 sm:flex-none p-4 px-6 bg-slate-50 dark:bg-[#0a1120] rounded-2xl border border-slate-200 dark:border-slate-800 text-center">
                <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Items</div>
                <div className="text-xl font-black text-slate-900 dark:text-white">{stockSummary.totalItems}</div>
             </div>
             <div className="flex-1 sm:flex-none p-4 px-6 bg-slate-50 dark:bg-[#0a1120] rounded-2xl border border-slate-200 dark:border-slate-800 text-center">
                <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Qty</div>
                <div className="text-xl font-black text-slate-900 dark:text-white">{stockSummary.totalQuantity}</div>
             </div>
           </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-1">Product List (মজুদ তালিকা)</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm">Manage your bakery items and individual stock levels.</p>
        </div>
        <button 
          onClick={() => {
            setFormData({ name: '', category: 'Bread', price: '', stock: '', unit: 'pcs', barcode: '' });
            setEditingId(null);
            setIsAdding(true);
          }}
          className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3.5 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg active:scale-95"
        >
          <Plus size={20} /> Add New Product
        </button>
      </div>

      <div className="bg-white dark:bg-[#1a2236] p-4 rounded-3xl border border-slate-200 dark:border-slate-800 flex flex-col md:flex-row gap-4 items-center shadow-sm">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
          <input 
            type="text" 
            placeholder="Search products by name or barcode..." 
            className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-orange-500/50 text-slate-900 dark:text-white placeholder-slate-400 focus:ring-2 focus:ring-orange-500/30 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Sort By:</span>
          <select 
            className="bg-slate-50 dark:bg-[#212a3e]/50 border border-slate-200 dark:border-slate-700 p-3.5 px-6 rounded-xl text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/30 cursor-pointer w-full md:w-48 text-sm"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
          >
            <option value="name_asc">Name (A-Z)</option>
            <option value="name_desc">Name (Z-A)</option>
            <option value="price_asc">Price (Low-High)</option>
            <option value="price_desc">Price (High-Low)</option>
          </select>
        </div>
      </div>

      {/* Wastage Modal */}
      {wastageModalProduct && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 backdrop-blur-md z-[120] flex items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-md animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold flex items-center gap-3 text-slate-900 dark:text-white">
                   <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                     <Trash size={20} />
                   </div>
                   Mark Wastage (নষ্ট মাল)
                </h3>
                <button onClick={() => setWastageModalProduct(null)} className="text-slate-400 hover:text-red-500 transition-colors">
                  <X size={24} />
                </button>
              </div>
              <form handleWastageSubmit={handleWastageSubmit} className="space-y-6">
                 <div className="p-4 bg-orange-500/5 rounded-2xl border border-orange-500/10">
                    <p className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-1">Product</p>
                    <p className="text-lg font-black text-slate-900 dark:text-white">{wastageModalProduct.name}</p>
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase px-1">Quantity ({wastageModalProduct.unit})</label>
                    <input 
                      required 
                      type="number" 
                      step="any"
                      max={wastageModalProduct.stock}
                      className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white font-black text-2xl outline-none" 
                      value={wastageQty} 
                      onChange={e => setWastageQty(e.target.value === '' ? '' : Number(e.target.value))} 
                    />
                 </div>
                 <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase px-1">Reason (কারণ)</label>
                    <select className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white outline-none" value={wastageReason} onChange={e => setWastageReason(e.target.value)}>
                      <option value="Expired">Expired (মেয়াদ শেষ)</option>
                      <option value="Damaged">Damaged (ভেঙে গেছে)</option>
                      <option value="Burnt">Burnt (পুড়ে গেছে)</option>
                      <option value="Other">Other</option>
                    </select>
                 </div>
                 <button type="submit" className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-4 rounded-2xl shadow-lg shadow-orange-500/20 transition-all active:scale-95">
                    Confirm Wastage
                 </button>
              </form>
           </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {confirmDeleteId && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-black/80 backdrop-blur-md z-[110] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-[#1a2236] p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-md animate-in zoom-in duration-300 text-center">
            <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-6 text-red-500">
              <AlertTriangle size={48} />
            </div>
            <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2">আপনি কি নিশ্চিত?</h3>
            <p className="text-slate-500 dark:text-slate-400 mb-8">
              এই প্রোডাক্টটি ("{products.find(p => p.id === confirmDeleteId)?.name}") ডিলিট করলে এটি চিরতরে মুছে যাবে। আপনি কি নিশ্চিত যে আপনি এটি মুছে ফেলতে চান?
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={executeDelete}
                className="w-full bg-red-500 hover:bg-red-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-red-500/20 transition-all active:scale-95"
              >
                হ্যাঁ, ডিলিট করুন
              </button>
              <button 
                onClick={() => setConfirmDeleteId(null)}
                className="w-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-300 font-bold py-4 rounded-2xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-all"
              >
                না, ফিরে যান
              </button>
            </div>
          </div>
        </div>
      )}

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-[#0a1120]/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold flex items-center gap-3 text-slate-900 dark:text-white">
                 <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                   <Package size={20} />
                 </div>
                 {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={() => {setIsAdding(false); setEditingId(null);}} className="text-slate-400 hover:text-red-500 transition-colors">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Product Name</label>
                <input required type="text" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="e.g. Milk Bread" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Category</label>
                <select className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                  <option value="Bread">Bread</option>
                  <option value="Cake">Cake</option>
                  <option value="Cookies">Cookies</option>
                  <option value="Pastry">Pastry</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Price (৳) per {formData.unit}</label>
                <input required type="number" step="any" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value === '' ? '' : Number(e.target.value)})} placeholder="0.00" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Stock & Unit</label>
                <div className="flex gap-2">
                  <input required type="number" step="any" className="flex-1 p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.stock} onChange={e => setFormData({...formData, stock: e.target.value === '' ? '' : Number(e.target.value)})} placeholder="0" />
                  <div className="relative w-32">
                    <select 
                      className="w-full h-full p-4 pl-4 pr-10 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none appearance-none cursor-pointer" 
                      value={formData.unit} 
                      onChange={e => setFormData({...formData, unit: e.target.value})}
                    >
                      {units.map(u => <option key={u} value={u}>{u}</option>)}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
                  </div>
                </div>
              </div>
              <div className="space-y-2 md:col-span-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1 flex items-center gap-2">
                  <Barcode size={14} /> Barcode (Optional)
                </label>
                <input 
                  type="text" 
                  className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" 
                  value={formData.barcode} 
                  onChange={e => setFormData({...formData, barcode: e.target.value})} 
                  placeholder="Scan or type barcode" 
                />
              </div>
              <div className="md:col-span-2 flex justify-between items-center mt-6">
                {editingId && (
                  <button 
                    type="button" 
                    onClick={() => setConfirmDeleteId(editingId)}
                    className="flex items-center gap-2 text-red-500 font-bold hover:bg-red-50 dark:hover:bg-red-500/10 px-4 py-2 rounded-xl transition-all"
                  >
                    <Trash2 size={18} /> Delete Item
                  </button>
                )}
                <div className="flex gap-4 ml-auto">
                  <button type="button" onClick={() => {setIsAdding(false); setEditingId(null);}} className="px-8 py-3 text-slate-400 font-semibold hover:text-orange-500 transition-colors">Cancel</button>
                  <button type="submit" className="bg-orange-500 hover:bg-orange-600 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg transition-all active:scale-95">
                    {editingId ? 'Update Product' : 'Save Product'}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredProducts.map(p => (
          <div 
            key={p.id} 
            className={`bg-white dark:bg-[#1a2236] p-8 rounded-[1.5rem] border relative group transition-all shadow-sm hover:shadow-md ${
              p.stock < 10 
                ? 'border-red-500 dark:border-red-500/50 ring-2 ring-red-500/10' 
                : 'border-slate-200 dark:border-slate-800 hover:border-orange-500/30'
            }`}
          >
            <div className="flex items-center justify-between mb-4">
              <span className="bg-slate-100 dark:bg-[#212a3e] text-slate-500 dark:text-slate-400 px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                {p.category}
              </span>
              <div className="flex gap-2">
                <button 
                  onClick={() => setWastageModalProduct(p)} 
                  className="p-2.5 text-orange-500 hover:text-white bg-orange-50 dark:bg-orange-500/10 hover:bg-orange-500 border border-orange-100 dark:border-orange-500/20 hover:border-orange-500 transition-all rounded-xl shadow-sm active:scale-90"
                  title="Mark Wastage (নষ্ট মাল)"
                >
                  <Trash size={16} />
                </button>
                <button 
                  onClick={() => handleEdit(p)} 
                  className="p-2.5 text-slate-400 hover:text-orange-500 transition-all bg-white dark:bg-[#0a1120] rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm active:scale-90"
                  title="Edit Product"
                >
                  <Edit3 size={16} />
                </button>
                <button 
                  onClick={() => setConfirmDeleteId(p.id)} 
                  className="p-2.5 text-red-500 hover:text-white bg-red-50 dark:bg-red-500/10 hover:bg-red-500 border border-red-100 dark:border-red-500/20 hover:border-red-500 transition-all rounded-xl shadow-sm active:scale-90"
                  title="Delete Product (মুছে ফেলুন)"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            <div className="absolute top-20 right-8 text-right">
               <div className="flex items-baseline justify-end gap-1 text-orange-500 dark:text-orange-400">
                 <span className="text-lg font-bold">৳</span>
                 <span className="text-3xl font-black">{p.price}</span>
               </div>
               <div className="text-[10px] text-slate-400 font-bold uppercase">per {p.unit || 'pcs'}</div>
            </div>

            <div className="mb-6 mt-2">
              <h4 className="text-2xl font-bold text-slate-900 dark:text-white group-hover:text-orange-500 transition-colors">
                {p.name}
              </h4>
              {p.barcode && (
                <div className="flex items-center gap-1 text-slate-400 font-bold text-[10px] uppercase mt-1">
                  <Barcode size={12} /> {p.barcode}
                </div>
              )}
              {p.stock < 10 && (
                <div className="flex items-center gap-1 text-red-500 font-black text-[10px] uppercase animate-pulse mt-1">
                  <AlertCircle size={12} /> Low Stock (মজুদ কম)
                </div>
              )}
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-400 font-semibold">Available Stock</span>
                <span className={`font-bold ${p.stock < 10 ? 'text-red-500' : 'text-slate-900 dark:text-white'}`}>
                  {p.stock} {p.unit || 'pcs'}
                </span>
              </div>
              <div className="h-3 w-full bg-slate-100 dark:bg-[#0a1120] rounded-full overflow-hidden border border-slate-200 dark:border-slate-800/50">
                <div 
                  className={`h-full transition-all duration-1000 ${p.stock < 10 ? 'bg-red-500' : 'bg-orange-500'}`} 
                  style={{ width: `${Math.min(100, (p.stock / 100) * 100)}%` }} 
                />
              </div>
            </div>
          </div>
        ))}
        {filteredProducts.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white dark:bg-[#1a2236] border border-slate-200 dark:border-slate-800 rounded-[2rem]">
             <Package size={48} className="mx-auto mb-4 opacity-10 text-slate-400" />
             <p className="text-slate-500 font-medium text-lg">No products found in inventory.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Product, Sale, DailyClosing, SaleItem } from '../types';
import { 
  ShoppingCart, 
  User, 
  Phone, 
  Wallet, 
  Trash2, 
  Plus, 
  Minus, 
  Package, 
  Search, 
  Printer, 
  X, 
  History as HistoryIcon, 
  PlusCircle, 
  RotateCcw, 
  Filter,
  CheckCircle2,
  Trash,
  ChevronRight,
  Barcode,
  Scan
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
  closings?: DailyClosing[];
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale, closings = [] }) => {
  const [activeTab, setActiveTab] = useState<'pos' | 'history'>('pos');
  const [searchQuery, setSearchQuery] = useState('');
  const [barcodeInput, setBarcodeInput] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);
  const [historySearch, setHistorySearch] = useState('');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');
  const [historyPaymentFilter, setHistoryPaymentFilter] = useState<'All' | 'Cash' | 'Mobile Payment'>('All');

  const barcodeRef = useRef<HTMLInputElement>(null);

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['All', ...cats];
  }, [products]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || (p.barcode && p.barcode.includes(searchQuery));
      const matchCat = selectedCategory === 'All' || p.category === selectedCategory;
      return matchSearch && matchCat;
    });
  }, [products, searchQuery, selectedCategory]);

  const totalPrice = cart.reduce((acc, item) => acc + item.subTotal, 0);

  useEffect(() => {
    if (totalPrice > 0) setAmountPaid(totalPrice);
    else setAmountPaid('');
  }, [totalPrice]);

  // Focus barcode input on mount and whenever we are in POS tab
  useEffect(() => {
    if (activeTab === 'pos' && barcodeRef.current) {
      barcodeRef.current.focus();
    }
  }, [activeTab]);

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput) return;

    const product = products.find(p => p.barcode === barcodeInput);
    if (product) {
      updateCartQuantity(product.id, 1);
      // Play a small beep sound or visual confirmation
      setBarcodeInput('');
    } else {
      alert("পণ্যটি খুঁজে পাওয়া যায়নি!");
      setBarcodeInput('');
    }
  };

  const dueAmount = Math.max(0, totalPrice - (Number(amountPaid) || 0));
  const changeAmount = Math.max(0, (Number(amountPaid) || 0) - totalPrice);

  const updateCartQuantity = (productId: string, delta: number) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId);
      if (existing) {
        const newQty = existing.quantity + delta;
        if (newQty <= 0) return prev.filter(item => item.productId !== productId);
        if (newQty > product.stock) {
          alert(`দুঃখিত! স্টকে মাত্র ${product.stock} ${product.unit} আছে।`);
          return prev;
        }
        return prev.map(item => item.productId === productId ? { ...item, quantity: newQty, subTotal: newQty * item.pricePerUnit } : item);
      } else if (delta > 0) {
        if (product.stock < 1) { alert("স্টকে নেই!"); return prev; }
        return [...prev, { productId: product.id, productName: product.name, quantity: 1, unit: product.unit, pricePerUnit: product.price, subTotal: product.price }];
      }
      return prev;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;
    if (dueAmount > 0.01 && !customerName) {
      alert("বাকি বিক্রয়ের ক্ষেত্রে কাস্টমারের নাম অবশ্যই দিতে হবে।");
      return;
    }
    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount,
      customerName: customerName || undefined,
      customerPhone: customerPhone || undefined,
      paymentMethod,
      date: new Date().toISOString()
    };
    onAddSale(newSale);
    setActiveReceipt(newSale); 
    setCart([]);
    setAmountPaid('');
    setPaymentMethod('Cash');
    setCustomerName('');
    setCustomerPhone('');
  };

  const filteredHistory = useMemo(() => {
    return [...sales].filter(sale => {
      const query = historySearch.toLowerCase();
      const matchSearch = !historySearch || (sale.customerName?.toLowerCase().includes(query)) || (sale.customerPhone?.includes(query)) || (sale.items.some(item => item.productName.toLowerCase().includes(query)));
      const saleDate = new Date(sale.date); saleDate.setHours(0, 0, 0, 0);
      let matchDate = true;
      if (historyStartDate) { const start = new Date(historyStartDate); start.setHours(0,0,0,0); if (saleDate < start) matchDate = false; }
      if (historyEndDate) { const end = new Date(historyEndDate); end.setHours(0,0,0,0); if (saleDate > end) matchDate = false; }
      const matchPayment = historyPaymentFilter === 'All' || sale.paymentMethod === historyPaymentFilter;
      return matchSearch && matchDate && matchPayment;
    }).reverse();
  }, [sales, historySearch, historyStartDate, historyEndDate, historyPaymentFilter]);

  const handlePrint = () => { window.print(); };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">
      <div className="flex bg-white dark:bg-[#1a2236] p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm w-fit no-print">
        <button onClick={() => setActiveTab('pos')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'pos' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-orange-500'}`}><PlusCircle size={18} /> New Order</button>
        <button onClick={() => setActiveTab('history')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'history' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-orange-500'}`}><HistoryIcon size={18} /> History</button>
      </div>

      {activeTab === 'pos' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start no-print">
          <div className="lg:col-span-8 space-y-6">
            {/* Barcode Scanner Input - Hidden but always active for hardware scanners */}
            <form onSubmit={handleBarcodeSubmit} className="bg-orange-500/5 dark:bg-orange-500/10 p-6 rounded-[2rem] border border-orange-500/20 flex flex-col md:flex-row gap-4 items-center shadow-sm">
                <div className="flex items-center gap-4 flex-1 w-full">
                    <div className="p-3 bg-orange-500 rounded-2xl text-white shadow-lg">
                        <Scan size={24} />
                    </div>
                    <div className="flex-1 relative">
                        <Barcode className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
                        <input 
                            ref={barcodeRef}
                            type="text" 
                            placeholder="Scan Product Barcode..." 
                            className="w-full pl-12 pr-4 py-4 rounded-xl bg-white dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-black tracking-widest uppercase"
                            value={barcodeInput}
                            onChange={e => setBarcodeInput(e.target.value)}
                        />
                    </div>
                </div>
                <div className="text-[10px] font-black text-orange-500 uppercase tracking-widest hidden md:block">
                    Quick Add Mode Active
                </div>
            </form>

            <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
                <input type="text" placeholder="Search product by name..." className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 dark:bg-[#2e374d] border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-orange-500/50" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
              </div>
              <div className="flex flex-wrap gap-2 overflow-x-auto pb-2 custom-scrollbar">
                {categories.map(cat => (
                  <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2 rounded-full text-xs font-bold transition-all border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-500' : 'bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700'}`}>{cat}</button>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4 max-h-[650px] overflow-y-auto pr-2 custom-scrollbar">
              {filteredProducts.map(p => (
                <button key={p.id} disabled={p.stock <= 0} onClick={() => updateCartQuantity(p.id, 1)} className={`flex flex-col items-center justify-center p-6 bg-white dark:bg-[#1a2236] rounded-3xl border transition-all text-center relative group active:scale-95 ${p.stock <= 0 ? 'opacity-50 grayscale cursor-not-allowed border-slate-200 dark:border-slate-800' : 'border-slate-200 dark:border-slate-800 hover:border-orange-500'}`}>
                  <div className="w-16 h-16 bg-orange-500/10 rounded-2xl flex items-center justify-center mb-4 text-orange-500 group-hover:scale-110 transition-transform"><Package size={32} /></div>
                  <h4 className="font-bold text-slate-900 dark:text-white text-sm leading-tight mb-1">{p.name}</h4>
                  <p className="text-orange-500 font-black text-base">৳{p.price}</p>
                  <div className="mt-2 text-[9px] font-black uppercase tracking-widest text-slate-400">Stock: {p.stock} {p.unit}</div>
                  {p.stock <= 0 && <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-3xl"><span className="bg-red-500 text-white text-[10px] font-black px-2 py-1 rounded">STOCK OUT</span></div>}
                  {cart.find(item => item.productId === p.id) && <div className="absolute -top-2 -right-2 w-8 h-8 bg-orange-500 text-white rounded-full flex items-center justify-center font-black text-xs shadow-lg ring-4 ring-white dark:ring-[#1a2236]">{cart.find(item => item.productId === p.id)?.quantity}</div>}
                </button>
              ))}
            </div>
          </div>
          <div className="lg:col-span-4 space-y-6">
            <div className="bg-white dark:bg-[#1a2236] rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden flex flex-col h-[750px]">
              <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-transparent">
                <h3 className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2"><ShoppingCart size={20} className="text-orange-500" /> Current Order</h3>
                <button onClick={() => setCart([])} className="text-[10px] font-black text-red-500 uppercase">Clear All</button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                {cart.map(item => (
                  <div key={item.productId} className="p-4 bg-slate-50 dark:bg-black/20 rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center gap-4 group">
                    <div className="flex-1"><h4 className="font-bold text-slate-900 dark:text-white text-sm truncate">{item.productName}</h4><p className="text-[10px] text-slate-500 font-bold">৳{item.pricePerUnit} / {item.unit}</p></div>
                    <div className="flex items-center gap-3">
                      <button onClick={() => updateCartQuantity(item.productId, -1)} className="w-8 h-8 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-slate-500 hover:text-red-500 transition-colors"><Minus size={14} /></button>
                      <span className="font-black text-slate-900 dark:text-white w-4 text-center">{item.quantity}</span>
                      <button onClick={() => updateCartQuantity(item.productId, 1)} className="w-8 h-8 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-slate-500 hover:text-emerald-500 transition-colors"><Plus size={14} /></button>
                    </div>
                    <div className="text-right min-w-[60px]"><span className="font-black text-slate-900 dark:text-white text-sm">৳{item.subTotal}</span></div>
                  </div>
                ))}
              </div>
              <div className="p-6 bg-slate-50 dark:bg-black/40 border-t border-slate-200 dark:border-slate-800 space-y-4">
                <div className="flex justify-between items-center mb-2"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Grand Total</span><span className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter">৳{totalPrice.toLocaleString()}</span></div>
                <div className="grid grid-cols-2 gap-2">
                   <button type="button" onClick={() => setPaymentMethod('Cash')} className={`py-2 rounded-xl font-bold text-xs border ${paymentMethod === 'Cash' ? 'bg-orange-500 text-white border-orange-500' : 'bg-white dark:bg-slate-800 text-slate-400 border-slate-200'}`}>Cash</button>
                   <button type="button" onClick={() => setPaymentMethod('Mobile Payment')} className={`py-2 rounded-xl font-bold text-xs border ${paymentMethod === 'Mobile Payment' ? 'bg-orange-500 text-white border-orange-500' : 'bg-white dark:bg-slate-800 text-slate-400 border-slate-200'}`}>Mobile Pay</button>
                </div>
                <div className="space-y-3">
                  <input type="number" placeholder="Received Amount" className="w-full p-4 rounded-xl bg-white dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white font-black text-xl outline-none" value={amountPaid} onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value))} />
                  {dueAmount > 0.01 && <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl space-y-2"><div className="flex justify-between text-red-500 text-[10px] font-black uppercase"><span>Due:</span><span>৳{dueAmount.toLocaleString()}</span></div><input required type="text" placeholder="Customer Name *" className="w-full p-2 rounded-lg bg-white dark:bg-slate-800 text-xs outline-none" value={customerName} onChange={e => setCustomerName(e.target.value)} /></div>}
                  {changeAmount > 0.01 && <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-xl flex justify-between text-emerald-500 text-[10px] font-black uppercase"><span>Change:</span><span>৳{changeAmount.toLocaleString()}</span></div>}
                </div>
                <button onClick={handleSubmit} disabled={cart.length === 0} className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-black py-5 rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 text-lg"><CheckCircle2 size={24} /> Complete & Print</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-6 no-print">
          <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
            <div className="flex flex-col md:flex-row gap-4 items-center">
              <div className="relative flex-1 w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={18} /><input type="text" placeholder="Search..." className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 text-slate-900 dark:text-white outline-none" value={historySearch} onChange={e => setHistorySearch(e.target.value)} /></div>
              <div className="w-full md:w-48"><select className="w-full p-3.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 text-slate-900 dark:text-white outline-none" value={historyPaymentFilter} onChange={e => setHistoryPaymentFilter(e.target.value as any)}><option value="All">All Payments</option><option value="Cash">Cash Only</option><option value="Mobile Payment">Mobile Pay</option></select></div>
            </div>
          </div>
          <div className="bg-white dark:bg-[#1a2236] rounded-[2rem] border border-slate-200 dark:border-slate-800 overflow-hidden"><div className="overflow-x-auto custom-scrollbar"><table className="w-full text-left"><thead><tr className="text-[10px] uppercase text-slate-400 font-bold bg-slate-50 dark:bg-transparent border-b border-slate-100 dark:border-slate-800"><th className="px-8 py-5">Date & ID</th><th className="px-8 py-5">Customer</th><th className="px-8 py-5 text-right">Total</th><th className="px-8 py-5 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{filteredHistory.map(sale => (<tr key={sale.id} className="hover:bg-slate-50 dark:hover:bg-white/5 transition-colors"><td className="px-8 py-5"><div className="flex flex-col"><span className="font-bold text-slate-900 dark:text-slate-200 text-xs">{new Date(sale.date).toLocaleDateString()}</span><span className="text-[10px] text-slate-400">#{sale.id.slice(-6)}</span></div></td><td className="px-8 py-5"><span className="font-black text-slate-700 dark:text-slate-300 text-xs">{sale.customerName || 'Walk-in'}</span></td><td className="px-8 py-5 text-right font-black text-slate-900 dark:text-white">৳{sale.totalPrice.toLocaleString()}</td><td className="px-8 py-5 text-right"><div className="flex justify-end gap-2"><button onClick={() => setActiveReceipt(sale)} className="p-2 text-slate-300 hover:text-orange-500 transition-colors bg-slate-50 dark:bg-slate-800 rounded-lg"><Printer size={14} /></button><button onClick={() => onCancelSale(sale.id)} className="p-2 text-slate-300 hover:text-red-500 transition-colors bg-slate-50 dark:bg-slate-800 rounded-lg"><Trash size={14} /></button></div></td></tr>))}</tbody></table></div></div>
        </div>
      )}

      {activeReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 no-print">
          <div className="bg-white dark:bg-[#1a2236] w-full max-w-sm rounded-[2rem] shadow-2xl overflow-hidden animate-in zoom-in duration-300">
             <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                <h3 className="font-black text-slate-900 dark:text-white flex items-center gap-2 uppercase text-sm tracking-widest"><Printer size={18} className="text-orange-500" /> Sale Memo</h3>
                <button onClick={() => setActiveReceipt(null)} className="p-2 text-slate-400 hover:text-red-500"><X size={20} /></button>
             </div>

             {/* Thermal Receipt Styling for Print Area */}
             <div id="print-area">
                <div className="p-8 bg-white text-black font-mono text-[11px] leading-tight text-center">
                   <h2 className="text-lg font-black uppercase mb-1">Sweet Live Bakery</h2>
                   <p className="text-[9px]">Road-04, Block-A, Mirpur, Dhaka</p>
                   <p className="text-[9px]">Phone: +880 1XXX-XXXXXX</p>
                   <div className="border-b border-dashed border-black my-2"></div>

                   <div className="flex justify-between text-left mb-2">
                      <span>Inv: #{activeReceipt.id.slice(-8)}</span>
                      <span>{new Date(activeReceipt.date).toLocaleDateString()}</span>
                   </div>

                   <table className="w-full mb-3">
                      <thead>
                         <tr className="border-b border-black">
                            <th className="text-left py-1">Item</th>
                            <th className="text-right py-1">Qty</th>
                            <th className="text-right py-1">Total</th>
