                </div>
             </div>

             <div className="p-6 bg-slate-50 dark:bg-black/20 flex gap-3">
                <button onClick={handlePrint} className="flex-1 bg-orange-500 hover:bg-orange-600 text-white font-black py-4 rounded-xl shadow-lg transition-all active:scale-95 flex items-center justify-center gap-2"><Printer size={18} /> Print Receipt</button>
                <button onClick={() => setActiveReceipt(null)} className="px-6 py-4 bg-slate-200 dark:bg-slate-800 text-slate-600 font-bold rounded-xl">Close</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SalesView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Product, Sale, DailyClosing, SaleItem } from '../types';
import { Html5Qrcode } from 'html5-qrcode';
import { 
  ShoppingCart, 
  User, 
  Phone, 
  Wallet, 
  Trash2, 
  Plus, 
  Minus, 
  Package, 
  Search, 
  Printer, 
  X, 
  History as HistoryIcon, 
  PlusCircle, 
  RotateCcw, 
  Filter,
  CheckCircle2,
  Trash,
  ChevronRight,
  Barcode,
  Scan,
  Camera,
  Loader2,
  Zap
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
  closings?: DailyClosing[];
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale, closings = [] }) => {
  const [activeTab, setActiveTab] = useState<'pos' | 'history'>('pos');
  const [searchQuery, setSearchQuery] = useState('');
  const [barcodeInput, setBarcodeInput] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);

  // Camera Scanner States
  const [isCameraScanning, setIsCameraScanning] = useState(false);
  const [scannerLoading, setScannerLoading] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);

  const [historySearch, setHistorySearch] = useState('');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');
  const [historyPaymentFilter, setHistoryPaymentFilter] = useState<'All' | 'Cash' | 'Mobile Payment'>('All');

  const barcodeRef = useRef<HTMLInputElement>(null);

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['All', ...cats];
  }, [products]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const q = searchQuery.toLowerCase();
      const matchSearch = p.name.toLowerCase().includes(q) || (p.barcode && p.barcode.includes(q));
      const matchCat = selectedCategory === 'All' || p.category === selectedCategory;
      return matchSearch && matchCat;
    });
  }, [products, searchQuery, selectedCategory]);

  const totalPrice = cart.reduce((acc, item) => acc + item.subTotal, 0);

  useEffect(() => {
    if (totalPrice > 0) setAmountPaid(totalPrice);
    else setAmountPaid('');
  }, [totalPrice]);

  // Focus barcode input on mount and whenever we are in POS tab
  useEffect(() => {
    if (activeTab === 'pos' && barcodeRef.current && !isCameraScanning) {
      barcodeRef.current.focus();
    }
  }, [activeTab, isCameraScanning]);

  // Scanner Logic
  const startCameraScanner = async () => {
    setScannerLoading(true);
    setIsCameraScanning(true);

    // Slight delay to allow DOM to render
    setTimeout(async () => {
      try {
        const scanner = new Html5Qrcode("barcode-reader");
        html5QrCodeRef.current = scanner;

        await scanner.start(
          { facingMode: "environment" },
          {
            fps: 15,
            qrbox: { width: 280, height: 180 }
          },
          (decodedText) => {
            handleScannedCode(decodedText);
            stopCameraScanner();
          },
          (errorMessage) => { /* Silently ignore errors */ }
        );
        setScannerLoading(false);
      } catch (err) {
        console.error("Camera error:", err);
        alert("ক্যামেরা চালু করা সম্ভব হচ্ছে না। পারমিশন চেক করুন।");
        setIsCameraScanning(false);
        setScannerLoading(false);
      }
    }, 300);
  };

  const stopCameraScanner = async () => {
    if (html5QrCodeRef.current) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current = null;
      } catch (e) {
        console.error("Stop scanner error:", e);
      }
    }
    setIsCameraScanning(false);
  };

  const handleScannedCode = (code: string) => {
    const product = products.find(p => p.barcode === code);
    if (product) {
      updateCartQuantity(product.id, 1);
    } else {
      alert(`পণ্যটি খুঁজে পাওয়া যায়নি! বারকোড: ${code}`);
    }
  };

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput) return;
    handleScannedCode(barcodeInput);
    setBarcodeInput('');
  };

  const dueAmount = Math.max(0, totalPrice - (Number(amountPaid) || 0));
  const changeAmount = Math.max(0, (Number(amountPaid) || 0) - totalPrice);

  const updateCartQuantity = (productId: string, delta: number) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId);
      if (existing) {
        const newQty = existing.quantity + delta;
        if (newQty <= 0) return prev.filter(item => item.productId !== productId);
        if (newQty > product.stock) {
          alert(`দুঃখিত! স্টকে মাত্র ${product.stock} ${product.unit} আছে।`);
          return prev;
        }
        return prev.map(item => item.productId === productId ? { ...item, quantity: newQty, subTotal: newQty * item.pricePerUnit } : item);
      } else if (delta > 0) {
        if (product.stock < 1) { alert("স্টকে নেই!"); return prev; }
        return [...prev, { productId: product.id, productName: product.name, quantity: 1, unit: product.unit, pricePerUnit: product.price, subTotal: product.price }];
      }
      return prev;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;
    if (dueAmount > 0.01 && !customerName) {
      alert("বাকি বিক্রয়ের ক্ষেত্রে কাস্টমারের নাম অবশ্যই দিতে হবে।");
      return;
    }
    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount,
      customerName: customerName || undefined,
      customerPhone: customerPhone || undefined,
      paymentMethod,
      date: new Date().toISOString()
    };
    onAddSale(newSale);
    setActiveReceipt(newSale); 
    setCart([]);
    setAmountPaid('');
    setPaymentMethod('Cash');
    setCustomerName('');
    setCustomerPhone('');
  };

  const filteredHistory = useMemo(() => {
    return [...sales].filter(sale => {
      const query = historySearch.toLowerCase();
      const matchSearch = !historySearch || (sale.customerName?.toLowerCase().includes(query)) || (sale.customerPhone?.includes(query)) || (sale.items.some(item => item.productName.toLowerCase().includes(query)));
      const saleDate = new Date(sale.date); saleDate.setHours(0, 0, 0, 0);
      let matchDate = true;
      if (historyStartDate) { const start = new Date(historyStartDate); start.setHours(0,0,0,0); if (saleDate < start) matchDate = false; }
      if (historyEndDate) { const end = new Date(historyEndDate); end.setHours(0,0,0,0); if (saleDate > end) matchDate = false; }
      const matchPayment = historyPaymentFilter === 'All' || sale.paymentMethod === historyPaymentFilter;
      return matchSearch && matchDate && matchPayment;
    }).reverse();
  }, [sales, historySearch, historyStartDate, historyEndDate, historyPaymentFilter]);

  const handlePrint = () => { window.print(); };

  // Calculate real-time available stock
  const getAvailableStock = (product: Product) => {
    const inCart = cart.find(item => item.productId === product.id)?.quantity || 0;
    return product.stock - inCart;
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">
      <div className="flex bg-white dark:bg-[#1a2236] p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm w-fit no-print">
        <button onClick={() => setActiveTab('pos')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'pos' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-orange-500'}`}><PlusCircle size={18} /> New Order</button>
        <button onClick={() => setActiveTab('history')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'history' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-orange-500'}`}><HistoryIcon size={18} /> History</button>
      </div>

      {activeTab === 'pos' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start no-print">
          <div className="lg:col-span-8 space-y-6">

            {/* Barcode & Search Controls */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {/* Hardware Scanner Input Overlay */}
               <form onSubmit={handleBarcodeSubmit} className="bg-orange-500/5 dark:bg-orange-500/10 p-4 rounded-[2rem] border border-orange-500/20 flex gap-3 items-center shadow-sm">
                    <button 
                        type="button"
                        onClick={startCameraScanner}
                        className="p-4 bg-orange-500 hover:bg-orange-600 text-white rounded-2xl shadow-lg transition-all active:scale-90 flex items-center justify-center group"
                    >
                        <Camera size={24} className="group-hover:rotate-12 transition-transform" />
                    </button>
                    <div className="flex-1 relative">
                        <Barcode className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={18} />
                        <input 
                            ref={barcodeRef}
                            type="text" 
                            placeholder="Barcorde..." 
                            className="w-full pl-10 pr-4 py-4 rounded-xl bg-white dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-black text-sm tracking-widest uppercase"
                            value={barcodeInput}
                            onChange={e => setBarcodeInput(e.target.value)}
                        />
                    </div>
               </form>

               {/* Manual Search */}
               <div className="bg-white dark:bg-[#1a2236] p-4 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm flex items-center px-6">
                  <div className="relative w-full">
                    <Search className="absolute left-0 top-1/2 -translate-y-1/2 text-orange-500" size={18} />
                    <input type="text" placeholder="Search by name..." className="w-full pl-8 pr-4 py-2 bg-transparent text-slate-900 dark:text-white outline-none text-sm font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
                  </div>
               </div>
            </div>

            <div className="flex flex-wrap gap-2 overflow-x-auto pb-2 custom-scrollbar">
              {categories.map(cat => (
                <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2 rounded-full text-[10px] font-black tracking-widest uppercase transition-all border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-500 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700'}`}>{cat}</button>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
              {filteredProducts.map(p => {
                const available = getAvailableStock(p);
                const inCart = cart.find(item => item.productId === p.id)?.quantity || 0;

                return (
                  <button 
                    key={p.id} 
                    disabled={available <= 0} 
                    onClick={() => updateCartQuantity(p.id, 1)} 
                    className={`flex flex-col items-center justify-center p-6 bg-white dark:bg-[#1a2236] rounded-[2rem] border transition-all text-center relative group active:scale-95 shadow-sm ${available <= 0 ? 'opacity-50 grayscale cursor-not-allowed border-slate-200 dark:border-slate-800' : 'border-slate-200 dark:border-slate-800 hover:border-orange-500 hover:shadow-orange-500/10'}`}
                  >
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-4 transition-all duration-300 ${inCart > 0 ? 'bg-orange-500 text-white scale-110 shadow-lg' : 'bg-orange-500/10 text-orange-500 group-hover:scale-110'}`}>
                        {inCart > 0 ? <Zap size={28} /> : <Package size={28} />}
                    </div>
                    <h4 className="font-bold text-slate-900 dark:text-white text-xs leading-tight mb-1 truncate w-full">{p.name}</h4>
                    <p className="text-orange-500 font-black text-sm">৳{p.price}</p>
                    <div className={`mt-2 text-[8px] font-black uppercase tracking-widest ${available < 5 ? 'text-red-500 animate-pulse' : 'text-slate-400'}`}>
                      Avail: {available} {p.unit}
                    </div>
                    {available <= 0 && <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-[2rem]"><span className="bg-red-500 text-white text-[9px] font-black px-2 py-1 rounded-lg">OUT OF STOCK</span></div>}
                    {inCart > 0 && <div className="absolute -top-1 -right-1 w-7 h-7 bg-orange-500 text-white rounded-xl flex items-center justify-center font-black text-[10px] shadow-lg ring-4 ring-white dark:ring-[#1a2236]">{inCart}</div>}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="lg:col-span-4 space-y-6">
            <div className="bg-white dark:bg-[#1a2236] rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden flex flex-col h-[750px]">
              <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-transparent">
                <h3 className="text-sm font-black text-slate-900 dark:text-white flex items-center gap-2 uppercase tracking-widest"><ShoppingCart size={18} className="text-orange-500" /> Cart</h3>
                <button onClick={() => setCart([])} className="text-[10px] font-black text-red-500 uppercase tracking-widest hover:underline transition-all">Clear</button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                {cart.map(item => (
                  <div key={item.productId} className="p-4 bg-slate-50 dark:bg-black/20 rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center gap-4 group hover:border-orange-500/30 transition-all">
                    <div className="flex-1 overflow-hidden">
                        <h4 className="font-bold text-slate-900 dark:text-white text-xs truncate">{item.productName}</h4>
                        <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">৳{item.pricePerUnit} / {item.unit}</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => updateCartQuantity(item.productId, -1)} className="w-8 h-8 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-slate-500 hover:text-red-500 transition-colors shadow-sm"><Minus size={12} /></button>
                      <span className="font-black text-slate-900 dark:text-white w-4 text-center text-xs">{item.quantity}</span>
                      <button onClick={() => updateCartQuantity(item.productId, 1)} className="w-8 h-8 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-slate-500 hover:text-emerald-500 transition-colors shadow-sm"><Plus size={12} /></button>
                    </div>
                    <div className="text-right min-w-[60px]"><span className="font-black text-slate-900 dark:text-white text-xs">৳{item.subTotal}</span></div>
                  </div>
                ))}
                {cart.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center opacity-20 py-20">
                        <ShoppingCart size={64} className="mb-4" />
                        <p className="font-black uppercase tracking-widest text-[10px]">Your Cart is Empty</p>
                    </div>
                )}
              </div>
              <div className="p-8 bg-slate-50 dark:bg-black/40 border-t border-slate-200 dark:border-slate-800 space-y-5">
                <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Grand Total</span><span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">৳{totalPrice.toLocaleString()}</span></div>
                <div className="grid grid-cols-2 gap-2 p-1 bg-slate-200/50 dark:bg-slate-800/50 rounded-2xl">
                   <button type="button" onClick={() => setPaymentMethod('Cash')} className={`py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Cash' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}>Cash</button>
                   <button type="button" onClick={() => setPaymentMethod('Mobile Payment')} className={`py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${paymentMethod === 'Mobile Payment' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}>Mobile Pay</button>
                </div>
                <div className="space-y-4">
                  <input type="number" placeholder="Received..." className="w-full p-4 rounded-2xl bg-white dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white font-black text-2xl outline-none focus:border-emerald-500 transition-all shadow-sm" value={amountPaid} onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value))} />
                  {dueAmount > 0.01 && <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl space-y-3 animate-in slide-in-from-top-2"><div className="flex justify-between text-red-500 text-[10px] font-black uppercase tracking-widest"><span>Due Amount:</span><span>৳{dueAmount.toLocaleString()}</span></div><input required type="text" placeholder="Customer Name *" className="w-full p-3 rounded-xl bg-white dark:bg-slate-800 text-xs font-bold outline-none border border-red-500/20 focus:border-red-500" value={customerName} onChange={e => setCustomerName(e.target.value)} /></div>}
                  {changeAmount > 0.01 && <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl flex justify-between text-emerald-500 text-[10px] font-black uppercase tracking-widest animate-in slide-in-from-top-2"><span>Change:</span><span>৳{changeAmount.toLocaleString()}</span></div>}
                </div>
                <button onClick={handleSubmit} disabled={cart.length === 0} className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-black py-5 rounded-[1.5rem] shadow-xl shadow-emerald-500/20 transition-all active:scale-95 flex items-center justify-center gap-3 text-lg group"><CheckCircle2 size={24} className="group-hover:scale-110 transition-transform" /> Checkout</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera Scanning Modal */}
      {isCameraScanning && (
        <div className="fixed inset-0 z-[200] bg-black/95 flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
            <div className="absolute top-8 right-8 flex gap-4">
                <button 
                    onClick={stopCameraScanner}
                    className="p-4 bg-white/10 hover:bg-red-500 text-white rounded-full backdrop-blur-md transition-all active:scale-90"
                >
                    <X size={28} />
                </button>
            </div>

            <div className="w-full max-w-lg aspect-square sm:aspect-video relative rounded-[2.5rem] overflow-hidden border-4 border-orange-500/30 bg-slate-900">
                {scannerLoading && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-white">
                        <Loader2 className="animate-spin mb-4" size={48} />
                        <p className="font-black uppercase tracking-widest text-xs">Initializing Camera...</p>
                    </div>
                )}
                <div id="barcode-reader" className="w-full h-full"></div>

                {/* HUD Elements */}
                <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
                    <div className="w-64 h-48 border-2 border-white/40 rounded-3xl relative">
                        <div className="absolute -top-1 -left-1 w-8 h-8 border-t-4 border-l-4 border-orange-500 rounded-tl-xl"></div>
                        <div className="absolute -top-1 -right-1 w-8 h-8 border-t-4 border-r-4 border-orange-500 rounded-tr-xl"></div>
                        <div className="absolute -bottom-1 -left-1 w-8 h-8 border-b-4 border-l-4 border-orange-500 rounded-bl-xl"></div>
                        <div className="absolute -bottom-1 -right-1 w-8 h-8 border-b-4 border-r-4 border-orange-500 rounded-br-xl"></div>

                        {/* Scanning Line */}
                        <div className="absolute left-0 right-0 h-[2px] bg-orange-500 shadow-[0_0_15px_#F26711] animate-[scanLine_2s_infinite]"></div>
                    </div>
                    <p className="mt-8 text-white/70 font-black text-[10px] uppercase tracking-[0.3em]">Align barcode within frame</p>
                </div>
            </div>

            <div className="mt-12 text-center max-w-md">
                <h3 className="text-white text-xl font-black mb-2 uppercase tracking-tighter">Smart Scanning Active</h3>
                <p className="text-white/40 text-xs font-bold leading-relaxed px-10">Automatically detects product barcodes and adds them directly to your active cart.</p>
            </div>

            <style>{`
                @keyframes scanLine {
                    0% { top: 0; }
                    50% { top: 100%; }
                    100% { top: 0; }
                }
            `}</style>
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-6 no-print">
          <div className="bg-white dark:bg-[#1a2236] p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
            <div className="flex flex-col md:flex-row gap-4 items-center">
              <div className="relative flex-1 w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={18} /><input type="text" placeholder="Search..." className="w-full pl-12 pr-4 py-3.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 text-slate-900 dark:text-white outline-none" value={historySearch} onChange={e => setHistorySearch(e.target.value)} /></div>
              <div className="w-full md:w-48"><select className="w-full p-3.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 text-slate-900 dark:text-white outline-none" value={historyPaymentFilter} onChange={e => setHistoryPaymentFilter(e.target.value as any)}><option value="All">All Payments</option><option value="Cash">Cash Only</option><option value="Mobile Payment">Mobile Pay</option></select></div>
            </div>
          </div>
