import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { UtensilsCrossed, Lock, Mail, UserPlus, LogIn, ChevronRight, AlertCircle, Loader2 } from 'lucide-react';

interface Props {
  onLogin: (email: string) => void;
  theme: 'dark' | 'light';
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const validateEmail = (email: string) => {
    return String(email)
      .toLowerCase()
      .match(
        /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
      );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const normalizedEmail = email.trim().toLowerCase();

    if (!validateEmail(normalizedEmail)) {
      setError('সঠিক ইমেইল অ্যাড্রেস দিন।');
      return;
    }

    if (password.length < 6) {
      setError('পাসওয়ার্ড অন্তত ৬ অক্ষরের হতে হবে।');
      return;
    }

    setLoading(true);

    try {
      if (isSignup) {
        // 1. Check if user already exists
        const { data: existing, error: checkError } = await supabase
          .from('profiles')
          .select('email')
          .eq('email', normalizedEmail)
          .maybeSingle();

        if (checkError) {
          console.error("DB Check Error:", checkError);
          throw new Error(`ডাটাবেস কানেকশন এরর: ${checkError.message}`);
        }

        if (existing) {
          setError('এই ইমেইল দিয়ে ইতিমধ্যে অ্যাকাউন্ট আছে। লগইন করুন।');
          setLoading(false);
          return;
        }

        // 2. Insert new user
        const { error: insError } = await supabase
          .from('profiles')
          .insert([{ email: normalizedEmail, password: password }]);

        if (insError) {
          console.error("Supabase Insert Error Detail:", insError);
          // Special message for RLS or Missing Table
          if (insError.code === '42P01') {
            throw new Error("ডাটাবেসে 'profiles' নামে কোনো টেবিল পাওয়া যায়নি। অনুগ্রহ করে SQL রান করুন।");
          } else if (insError.message.includes('row-level security')) {
            throw new Error("RLS পলিসি ডাটা সেভ করতে বাধা দিচ্ছে। Row Level Security ডিসেবল করুন।");
          }
          throw new Error(`রেজিস্ট্রেশন সফল হয়নি: ${insError.message}`);
        }

        alert('রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন।');
        setIsSignup(false);
        setPassword('');
      } else {
        // Login Logic
        const { data: user, error: selError } = await supabase
          .from('profiles')
          .select('*')
          .eq('email', normalizedEmail)
          .eq('password', password)
          .maybeSingle();

        if (selError) {
          console.error("Login Error:", selError);
          throw new Error(`লগইন এরর: ${selError.message}`);
        }

        if (!user) {
          setError('ইমেইল অথবা পাসওয়ার্ড ভুল।');
        } else {
          onLogin(normalizedEmail);
        }
      }
    } catch (err: any) {
      setError(err.message || 'সার্ভারে কানেক্ট করা যাচ্ছে না।');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 transition-colors duration-500">
      <div className="mb-10 text-center flex flex-col items-center animate-in fade-in slide-in-from-top-4 duration-700">
        <div className="w-20 h-20 bg-white dark:bg-[#161d31] rounded-3xl flex items-center justify-center shadow-2xl mb-6 border border-slate-200 dark:border-slate-800">
           <UtensilsCrossed size={40} className="text-orange-500" />
        </div>
        <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight text-center">Sweet Live Bakery<br/><span className="text-orange-500">Manager Cloud</span></h1>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-slate-200 dark:border-slate-800 relative overflow-hidden transition-all duration-500 animate-in zoom-in duration-500">
          <div className="absolute top-0 left-0 w-full h-2 bg-orange-500"></div>

          <div className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-white">{isSignup ? 'রেজিস্ট্রেশন' : 'স্বাগতম'}</h2>
              <p className="text-slate-500 dark:text-slate-400 text-xs font-medium mt-1">
                {isSignup ? 'নতুন অ্যাকাউন্ট খুলুন' : 'লগইন করে কাজ শুরু করুন'}
              </p>
            </div>
            <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500">
              {isSignup ? <UserPlus size={28} /> : <LogIn size={28} />}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">ইমেইল অ্যাড্রেস</label>
              <div className="relative group">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                <input 
                  required 
                  type="email" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                  placeholder="name@gmail.com" 
                  value={email} 
                  onChange={e => setEmail(e.target.value)} 
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">পাসওয়ার্ড</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                <input 
                  required 
                  type="password" 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                  placeholder="••••••••" 
                  value={password} 
                  onChange={e => setPassword(e.target.value)} 
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-4 rounded-xl text-xs font-bold flex items-start gap-3 animate-pulse">
                <AlertCircle className="shrink-0 mt-0.5" size={16} /> 
                <span>{error}</span>
              </div>
            )}

            <button 
              type="submit" 
              disabled={loading} 
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-xl transition-all active:scale-95 disabled:opacity-70 flex items-center justify-center gap-3"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : (isSignup ? 'রেজিস্ট্রেশন করুন' : 'লগইন করুন')}
              {!loading && <ChevronRight size={20} />}
            </button>
          </form>

          <div className="mt-10 flex flex-col items-center gap-4">
            <button 
              onClick={() => { setIsSignup(!isSignup); setError(''); }} 
              className="text-slate-400 hover:text-orange-500 text-sm font-bold transition-colors"
            >
              {isSignup ? 'ইতিমধ্যে অ্যাকাউন্ট আছে? লগইন করুন' : "অ্যাকাউন্ট নেই? নতুন অ্যাকাউন্ট খুলুন"}
            </button>
          </div>
      </div>
    </div>
  );
};

export default Login;

