            <p className="text-slate-500 dark:text-slate-400 mb-8">This action cannot be undone.</p>
            <div className="flex flex-col gap-3">
              <button onClick={executeDelete} className="w-full bg-red-500 text-white font-bold py-4 rounded-2xl">Delete Item</button>
              <button onClick={() => setConfirmDeleteId(null)} className="w-full bg-slate-100 text-slate-500 font-bold py-4 rounded-2xl">Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Modal */}
      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-[#0a1120]/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white dark:bg-[#1a2236] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold flex items-center gap-3 text-slate-900 dark:text-white">
                 <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                   <Package size={20} />
                 </div>
                 {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={() => {setIsAdding(false); setEditingId(null);}} className="text-slate-400 hover:text-red-500 transition-colors">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Product Name</label>
                <input required type="text" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white focus:ring-2 focus:ring-orange-500/50 outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="e.g. Milk Bread" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Category</label>
                <select className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white outline-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                  <option value="Bread">Bread</option>
                  <option value="Cake">Cake</option>
                  <option value="Cookies">Cookies</option>
                  <option value="Pastry">Pastry</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Price (৳) per {formData.unit}</label>
                <input required type="number" step="any" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white outline-none" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value === '' ? '' : Number(e.target.value)})} placeholder="0.00" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1">Stock & Unit</label>
                <div className="flex gap-2">
                  <input required type="number" step="any" className="flex-1 p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white outline-none" value={formData.stock} onChange={e => setFormData({...formData, stock: e.target.value === '' ? '' : Number(e.target.value)})} placeholder="0" />
                  <select className="w-32 p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white outline-none" value={formData.unit} onChange={e => setFormData({...formData, unit: e.target.value})}>
                    {units.map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-2 md:col-span-2">
                <label className="text-xs font-bold text-slate-500 uppercase px-1 flex items-center gap-2"><Barcode size={14} /> Barcode</label>
                <input type="text" className="w-full p-4 rounded-xl bg-slate-50 dark:bg-[#0a1120] border border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white outline-none" value={formData.barcode} onChange={e => setFormData({...formData, barcode: e.target.value})} placeholder="Optional barcode..." />
              </div>
              <div className="md:col-span-2 flex justify-end gap-4 mt-6">
                <button type="button" onClick={() => {setIsAdding(false); setEditingId(null);}} className="px-8 py-3 text-slate-400 font-semibold">Cancel</button>
                <button type="submit" className="bg-orange-500 text-white px-10 py-3.5 rounded-xl font-bold shadow-lg">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

