### ডাটাবেস সেটআপ চেক লিস্ট:
যদি অ্যাপটি চালু হওয়ার পর ডাটা সেভ না হয়, তবে অনুগ্রহ করে Supabase-এর **SQL Editor**-এ গিয়ে এই কোডটি রান করুন:

```sql
-- ১. প্রোফাইল টেবিল
CREATE TABLE IF NOT EXISTS profiles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL);
ALTER TABLE profiles DISABLE ROW LEVEL SECURITY;

-- ২. বাকি সব টেবিল (এগুলো না থাকলে অ্যাপ এরর দিতে পারে)
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, username TEXT, name TEXT, category TEXT, price NUMERIC, stock NUMERIC, unit TEXT, barcode TEXT);
CREATE TABLE IF NOT EXISTS sales (id TEXT PRIMARY KEY, username TEXT, items JSONB, totalPrice NUMERIC, amountPaid NUMERIC, dueAmount NUMERIC, customerName TEXT, customerPhone TEXT, paymentMethod TEXT, date TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, username TEXT, description TEXT, amount NUMERIC, category TEXT, date TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS wastage (id TEXT PRIMARY KEY, username TEXT, productId TEXT, productName TEXT, quantity NUMERIC, unit TEXT, lossValue NUMERIC, reason TEXT, date TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, username TEXT, name TEXT, designation TEXT, monthlySalary NUMERIC, joinDate TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, username TEXT, staffId TEXT, date TEXT, status TEXT);
CREATE TABLE IF NOT EXISTS daily_closings (id TEXT PRIMARY KEY, username TEXT, date TEXT, totalSales NUMERIC, totalCashCollected NUMERIC, totalExpenses NUMERIC, totalWastage NUMERIC, systemBalance NUMERIC, actualCash NUMERIC, difference NUMERIC, closedBy TEXT, timestamp TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS deductions (id TEXT PRIMARY KEY, username TEXT, staffId TEXT, amount NUMERIC, reason TEXT, date TIMESTAMPTZ);

-- সব টেবিলের সিকিউরিটি অফ করা (যাতে অ্যাপ থেকে ডাটা সেভ হয়)
ALTER TABLE products DISABLE ROW LEVEL SECURITY;
ALTER TABLE sales DISABLE ROW LEVEL SECURITY;
ALTER TABLE expenses DISABLE ROW LEVEL SECURITY;
ALTER TABLE wastage DISABLE ROW LEVEL SECURITY;
ALTER TABLE staff DISABLE ROW LEVEL SECURITY;
ALTER TABLE attendance DISABLE ROW LEVEL SECURITY;
ALTER TABLE daily_closings DISABLE ROW LEVEL SECURITY;
ALTER TABLE deductions DISABLE ROW LEVEL SECURITY;
```

এখন অ্যাপটি রিলোড করে ট্রাই করুন। ইনভেন্টরি এরর এবং লোডিং এরর উভয়ই ঠিক হয়ে যাওয়ার কথা।

