  useEffect(() => {
    const fetchData = async () => {
      if (!isAuthenticated || !userEmail) return;

      setIsDataLoaded(false);
      setIsSyncing(true);
      setLoadError(null);

      const safeFetch = async <T,>(fetchFn: () => Promise<T[]>) => {
        try {
          return await fetchFn();
        } catch (err) {
          console.warn("Table fetch warning:", err);
          return [] as T[];
        }
      };

      try {
        const [p, s, e, w, st, att, clos, ded] = await Promise.all([
          safeFetch(() => supabaseService.getProducts(userEmail)),
          safeFetch(() => supabaseService.getSales(userEmail)),
          safeFetch(() => supabaseService.getExpenses(userEmail)),
          safeFetch(() => supabaseService.getWastage(userEmail)),
          safeFetch(() => supabaseService.getStaff(userEmail)),
          safeFetch(() => supabaseService.getAttendance(userEmail)),
          safeFetch(() => supabaseService.getClosings(userEmail)),
          safeFetch(() => supabaseService.getDeductions(userEmail))
        ]);

        setProducts(p);
        setSales(s);
        setExpenses(e);
        setWastage(w);
        setStaff(st);
        setAttendance(att);
        setDailyClosings(clos);
        setDeductions(ded);
