export default Login;

import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { UtensilsCrossed, Lock, Mail, UserPlus, LogIn, ChevronRight, AlertCircle, Loader2, Database, HelpCircle } from 'lucide-react';

interface Props {
  onLogin: (email: string) => void;
  theme: 'dark' | 'light';
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [dbError, setDbError] = useState(false);
  const [loading, setLoading] = useState(false);

  const validateEmail = (email: string) => {
    return String(email)
      .toLowerCase()
      .match(/^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setDbError(false);

    const normalizedEmail = email.trim().toLowerCase();

    if (!validateEmail(normalizedEmail)) {
      setError('সঠিক ইমেইল অ্যাড্রেস দিন।');
      return;
    }

    if (password.length < 6) {
      setError('পাসওয়ার্ড অন্তত ৬ অক্ষরের হতে হবে।');
      return;
    }

    setLoading(true);

    try {
      if (isSignup) {
        // Registration Logic
        // Including 'username' to satisfy NOT NULL constraints if the table was created with it
        const { error: insError } = await supabase
          .from('profiles')
          .insert([{ 
            email: normalizedEmail, 
            username: normalizedEmail, // Map email to username for compatibility
            password: password 
          }]);

        if (insError) {
          if (insError.message.includes('column "email" does not exist') || insError.message.includes('column "username"')) {
            setDbError(true);
          }
          throw insError;
        }

        alert('রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন।');
        setIsSignup(false);
        setPassword('');
      } else {
        // Login Logic
        // We try to match email, but if that column doesn't exist, the error catch will handle it
        const { data: user, error: selError } = await supabase
          .from('profiles')
          .select('*')
          .or(`email.eq.${normalizedEmail},username.eq.${normalizedEmail}`)
          .eq('password', password)
          .maybeSingle();

        if (selError) {
           if (selError.message.includes('column') && selError.message.includes('does not exist')) {
            setDbError(true);
          }
          throw selError;
        }

        if (!user) {
          setError('ইমেইল অথবা পাসওয়ার্ড ভুল।');
        } else {
          onLogin(normalizedEmail);
        }
      }
    } catch (err: any) {
      console.error("Login System Error:", err);
      setError(err.message || 'সার্ভারে কানেক্ট করা যাচ্ছে না।');
    } finally {
      setLoading(false);
    }
  };

  const handleDemoMode = () => {
    if (window.confirm("আপনি কি ডেমো মোডে ঢুকতে চান? এটি করলে ডাটাবেস ছাড়াই আপনি অ্যাপটি দেখতে পারবেন। (সতর্কতা: এটি শুধুমাত্র পরীক্ষার জন্য)")) {
      onLogin('demo@bakery.com');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6">
      <div className="mb-10 text-center flex flex-col items-center">
        <div className="w-20 h-20 bg-white dark:bg-[#161d31] rounded-3xl flex items-center justify-center shadow-2xl mb-6 border border-slate-200 dark:border-slate-800">
           <UtensilsCrossed size={40} className="text-orange-500" />
        </div>
        <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Sweet Live Bakery<br/><span className="text-orange-500">Manager Cloud</span></h1>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-slate-200 dark:border-slate-800 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-orange-500"></div>

          <div className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-white">{isSignup ? 'রেজিস্ট্রেশন' : 'স্বাগতম'}</h2>
              <p className="text-slate-500 dark:text-slate-400 text-xs font-medium mt-1">
                {isSignup ? 'নতুন অ্যাকাউন্ট খুলুন' : 'লগইন করে কাজ শুরু করুন'}
              </p>
            </div>
            <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500">
              {isSignup ? <UserPlus size={28} /> : <LogIn size={28} />}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">ইমেইল অ্যাড্রেস</label>
              <input 
                required 
                type="email" 
                className="w-full px-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                placeholder="name@gmail.com" 
                value={email} 
                onChange={e => setEmail(e.target.value)} 
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">পাসওয়ার্ড</label>
              <input 
                required 
                type="password" 
                className="w-full px-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                placeholder="••••••••" 
                value={password} 
                onChange={e => setPassword(e.target.value)} 
              />
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-4 rounded-xl text-xs font-bold flex flex-col gap-2">
                <div className="flex items-start gap-3">
                  <AlertCircle className="shrink-0 mt-0.5" size={16} /> 
                  <span className="leading-relaxed">{error}</span>
                </div>
                {dbError && (
                  <div className="mt-2 p-3 bg-white/50 dark:bg-black/20 rounded-lg text-[10px] font-mono leading-relaxed border border-red-500/10">
                    <p className="mb-2 font-bold uppercase text-red-600">সমাধানের জন্য SQL রান করুন:</p>
                    <code className="block bg-slate-100 dark:bg-black p-2 rounded overflow-x-auto">
                      ALTER TABLE profiles <br/>
                      ADD COLUMN IF NOT EXISTS email TEXT,<br/>
                      ADD COLUMN IF NOT EXISTS username TEXT,<br/>
                      ADD COLUMN IF NOT EXISTS password TEXT;
                    </code>
                  </div>
                )}
              </div>
            )}

            <button 
              type="submit" 
              disabled={loading} 
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-xl transition-all active:scale-95 disabled:opacity-70 flex items-center justify-center gap-3"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : (isSignup ? 'রেজিস্ট্রেশন করুন' : 'লগইন করুন')}
              {!loading && <ChevronRight size={20} />}
            </button>
          </form>

          <div className="mt-10 flex flex-col items-center gap-4">
            <button 
              onClick={() => { setIsSignup(!isSignup); setError(''); setDbError(false); }} 
              className="text-slate-400 hover:text-orange-500 text-sm font-bold transition-colors"
            >
              {isSignup ? 'ইতিমধ্যে অ্যাকাউন্ট আছে? লগইন করুন' : "অ্যাকাউন্ট নেই? নতুন অ্যাকাউন্ট খুলুন"}
            </button>

            <button 
              onClick={handleDemoMode}
              className="flex items-center gap-2 text-[10px] font-black uppercase text-orange-500/60 hover:text-orange-500 transition-all"
            >
              <HelpCircle size={14} /> ডেমো মোডে প্রবেশ করুন
            </button>
          </div>
      </div>
    </div>
  );
};

