                  </div>
                  <button onClick={() => window.location.reload()} className="w-full md:w-auto bg-red-500 hover:bg-red-600 text-white px-10 py-4 rounded-2xl font-black transition-all shadow-lg active:scale-95 whitespace-nowrap">পুনরায় চেষ্টা করুন</button>
                </div>
              )}

              <div className="animate-in fade-in duration-700">
                {currentView === View.DASHBOARD && <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} />}
