      <aside className={`w-72 bg-white dark:bg-[#0a1120] border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-transform duration-300 lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-orange-500 rounded-xl">
              <UtensilsCrossed size={24} className="text-white" />
            </div>
            <h1 className="text-xl font-black text-slate-900 dark:text-white">Sweet Live</h1>
          </div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden text-slate-400"><X size={24} /></button>
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all ${currentView === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
              <span className={currentView === item.id ? 'text-white' : 'text-orange-500'}>{item.icon}</span>
              <div className="text-left flex-1">
                <p className="text-sm font-bold">{item.label}</p>
                <p className="text-[9px] opacity-60 uppercase">{item.bangla}</p>
              </div>
              {item.notification > 0 && <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black">{item.notification}</span>}
            </button>
          ))}
        </nav>

        <div className="p-6 space-y-3 border-t border-slate-100 dark:border-slate-800">
           <div className="bg-slate-50 dark:bg-slate-800/20 p-4 rounded-2xl border border-slate-100 dark:border-slate-800">
             <div className="flex items-center gap-3 mb-1">
                <RefreshCw size={14} className={isSyncing ? "animate-spin text-orange-500" : "text-emerald-500"} />
                <span className="text-[9px] font-black uppercase text-slate-500 dark:text-slate-400">{isSyncing ? "Syncing..." : "Connected"}</span>
             </div>
             <p className="text-[9px] text-slate-400 font-bold truncate">{userEmail}</p>
           </div>

           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all font-black text-[10px] uppercase tracking-widest border border-transparent hover:border-red-500/20"
           >
             <LogOut size={18} />
             Logout (লগআউট)
           </button>
