          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-orange-500 shadow-sm transition-all active:scale-95">{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button>
          </div>
        </header>

        <div className="p-4 md:p-10 flex-1 overflow-x-hidden">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center h-[60vh]">
              <div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div>
              <p className="mt-6 font-black text-slate-400 animate-pulse uppercase text-xs tracking-[0.3em]">Sweet Live Loading...</p>
              <button onClick={() => setIsDataLoaded(true)} className="mt-8 text-[10px] font-black uppercase text-orange-500/50 hover:text-orange-500 flex items-center gap-2">Skip Loading <ArrowRight size={12}/></button>
            </div>
          ) : (
            <>
              {loadError && (
                <div className="mb-10 p-8 bg-red-500/5 border border-red-500/20 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-8 shadow-xl animate-in slide-in-from-top-4 duration-500">
