  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  Trash2,
  RefreshCw,
  Database,
  ArrowRight,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    try {
      const saved = localStorage.getItem('sweetBakery_theme');
      return (saved as 'dark' | 'light') || 'dark';
    } catch {
      return 'dark';
    }
  });

  const [isSyncing, setIsSyncing] = useState(false);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  useEffect(() => {
    const savedEmail = localStorage.getItem('sweetBakery_email');
    if (savedEmail) {
      setUserEmail(savedEmail.toLowerCase());
      setIsAuthenticated(true);
    } else {
      setIsDataLoaded(true); 
    }
  }, []);

  const fetchData = async (email: string) => {
    if (!email) {
      setIsDataLoaded(true);
      return;
    }

    setIsSyncing(true);
    setLoadError(null);

    const safeFetch = async <T,>(tableName: string, fetchFn: () => Promise<T[]>) => {
      try {
        const data = await fetchFn();
        return data || [];
      } catch (err: any) {
        console.warn(`Table "${tableName}" load error:`, err.message);
        return [] as T[];
      }
    };

    try {
      const results = await Promise.allSettled([
        safeFetch('products', () => supabaseService.getProducts(email)),
        safeFetch('sales', () => supabaseService.getSales(email)),
        safeFetch('expenses', () => supabaseService.getExpenses(email)),
        safeFetch('wastage', () => supabaseService.getWastage(email)),
        safeFetch('staff', () => supabaseService.getStaff(email)),
        safeFetch('attendance', () => supabaseService.getAttendance(email)),
        safeFetch('daily_closings', () => supabaseService.getClosings(email)),
        safeFetch('deductions', () => supabaseService.getDeductions(email))
      ]);

      const getData = (index: number) => {
        const res = results[index];
        return res.status === 'fulfilled' ? res.value : [];
      };

      setProducts(getData(0));
      setSales(getData(1));
      setExpenses(getData(2));
      setWastage(getData(3));
      setStaff(getData(4));
      setAttendance(getData(5));
      setDailyClosings(getData(6));
      setDeductions(getData(7));
    } catch (err: any) {
      console.error("Critical fetch error:", err);
    } finally {
      setIsDataLoaded(true);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && userEmail) {
      fetchData(userEmail);
    }
  }, [isAuthenticated, userEmail]);

  const handleLogin = (email: string) => {
    const normalizedEmail = email.toLowerCase();
    setUserEmail(normalizedEmail);
    setIsAuthenticated(true);
    localStorage.setItem('sweetBakery_email', normalizedEmail);
  };

  const handleLogout = () => {
    if (window.confirm("লগআউট করতে চান?")) {
      localStorage.removeItem('sweetBakery_email');
      setProducts([]);
      setSales([]);
      setExpenses([]);
      setWastage([]);
      setStaff([]);
      setAttendance([]);
      setDailyClosings([]);
      setDeductions([]);
      setUserEmail('');
      setIsAuthenticated(false);
      setIsDataLoaded(true);
      setCurrentView(View.DASHBOARD);
    }
  };

  const withSync = async (fn: () => Promise<void>) => {
    setIsSyncing(true);
    try {
      await fn();
      await fetchData(userEmail); 
    } catch (e: any) {
      alert(`ত্রুটি: ${e.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const addSale = (newSale: Sale) => withSync(async () => {
    await supabaseService.addSale(userEmail, newSale);
  });

  const addProduct = (product: Product) => withSync(async () => {
    await supabaseService.upsertProduct(userEmail, product);
  });

  const lowStockCount = useMemo(() => products.filter(p => p.stock < 10).length, [products]);

  if (!isAuthenticated) return <Login onLogin={handleLogin} theme={theme} />;

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white transition-all ${isMobileMenuOpen ? 'overflow-hidden' : ''}`}>
      {isMobileMenuOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />}

      <aside className={`w-72 bg-white dark:bg-[#0a1120] border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-transform duration-300 lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-orange-500 rounded-xl">
              <UtensilsCrossed size={24} className="text-white" />
            </div>
            <h1 className="text-xl font-black text-slate-900 dark:text-white">Sweet Live</h1>
          </div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden text-slate-400"><X size={24} /></button>
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all ${currentView === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
              <span className={currentView === item.id ? 'text-white' : 'text-orange-500'}>{item.icon}</span>
              <div className="text-left flex-1">
                <p className="text-sm font-bold">{item.label}</p>
                <p className="text-[9px] opacity-60 uppercase">{item.bangla}</p>
              </div>
              {item.notification > 0 && <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black">{item.notification}</span>}
            </button>
          ))}
        </nav>

        <div className="p-6 space-y-3 border-t border-slate-100 dark:border-slate-800">
           <div className="bg-slate-50 dark:bg-slate-800/20 p-4 rounded-2xl border border-slate-100 dark:border-slate-800">
             <div className="flex items-center gap-3 mb-1">
                <RefreshCw size={14} className={isSyncing ? "animate-spin text-orange-500" : "text-emerald-500"} />
                <span className="text-[9px] font-black uppercase text-slate-500 dark:text-slate-400">{isSyncing ? "Syncing..." : "Connected"}</span>
             </div>
             <p className="text-[9px] text-slate-400 font-bold truncate">{userEmail}</p>
           </div>

           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all font-black text-[10px] uppercase tracking-widest border border-transparent hover:border-red-500/20"
           >
             <LogOut size={18} />
             Logout (লগআউট)
           </button>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 min-h-screen flex flex-col">
        <header className="px-6 md:px-10 py-5 bg-white/80 dark:bg-dark-bg/80 backdrop-blur-xl sticky top-0 z-40 flex justify-between items-center border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl shadow-sm"><Menu size={22} className="text-orange-500" /></button>
            <h2 className="text-xl font-black uppercase tracking-tight text-slate-900 dark:text-white">{currentView.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-orange-500 shadow-sm transition-all active:scale-95">{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button>
          </div>
        </header>

        <div className="p-4 md:p-10 flex-1 overflow-x-hidden">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center h-[60vh]">
              <div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div>
              <p className="mt-6 font-black text-slate-400 animate-pulse uppercase text-xs tracking-[0.3em]">Sweet Live Loading...</p>
              <button onClick={() => setIsDataLoaded(true)} className="mt-8 text-[10px] font-black uppercase text-orange-500/50 hover:text-orange-500 flex items-center gap-2">Skip Loading <ArrowRight size={12}/></button>
            </div>
          ) : (
            <>
              {loadError && (
                <div className="mb-10 p-8 bg-red-500/5 border border-red-500/20 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-8 shadow-xl">
                  <div className="p-6 bg-red-500 rounded-3xl text-white">
                    <Database size={40} />
                  </div>
                  <div className="flex-1 text-center md:text-left">
                    <h3 className="text-2xl font-black text-red-500 uppercase tracking-tight mb-2">ডাটাবেস টেবিল পাওয়া যায়নি</h3>
                    <p className="text-sm text-slate-600 dark:text-slate-400 font-medium">আপনার Supabase প্রজেক্টে প্রয়োজনীয় টেবিলগুলো তৈরি করা হয়নি।</p>
                  </div>
                  <button onClick={() => window.location.reload()} className="w-full md:w-auto bg-red-500 text-white px-10 py-4 rounded-2xl font-black">পুনরায় চেষ্টা করুন</button>
                </div>
              )}

              <div className="animate-in fade-in duration-700">
                {currentView === View.DASHBOARD && <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} />}
                {currentView === View.INVENTORY && <Inventory products={products} onAdd={addProduct} onUpdate={addProduct} onDelete={() => {}} onMarkWastage={() => {}} />}
                {currentView === View.SALES && <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={() => {}} />}
                {currentView === View.DUES && <DuesView sales={sales} onUpdateSales={() => {}} />}
                {currentView === View.WASTAGE && <WastageView wastage={wastage} products={products} onAdd={() => {}} onDelete={() => {}} />}
                {currentView === View.EXPENSES && <ExpensesView expenses={expenses} onAdd={() => {}} />}
                {currentView === View.DAILY_CLOSING && <DailyClosingView sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onCloseDay={() => {}} onDeleteClosing={() => {}} currentUser={userEmail} />}
                {currentView === View.STAFF && <StaffView staff={staff} attendance={attendance} expenses={expenses} deductions={deductions} onAddStaff={() => {}} onUpdateAttendance={() => {}} onAddDeduction={() => {}} onPaySalary={() => {}} />}
                {currentView === View.MANAGER && <ManagerView username={userEmail} onLogout={handleLogout} stats={{ products: products.length, sales: sales.length, expenses: expenses.length, staff: staff.length }} />}
              </div>
            </>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Product, Sale, DailyClosing, SaleItem } from '../types';
import { Html5Qrcode } from 'html5-qrcode';
import { 
  ShoppingCart, 
  Trash2, 
  Plus, 
  Minus, 
  Package, 
  Search, 
  Printer, 
  X, 
  History as HistoryIcon, 
  PlusCircle, 
  CheckCircle2,
  Trash,
  Barcode,
  Camera,
  Loader2,
  Zap
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
  closings?: DailyClosing[];
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale }) => {
  const [activeTab, setActiveTab] = useState<'pos' | 'history'>('pos');
  const [searchQuery, setSearchQuery] = useState('');
  const [barcodeInput, setBarcodeInput] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);

  // Camera Scanner States
  const [isCameraScanning, setIsCameraScanning] = useState(false);
  const [scannerLoading, setScannerLoading] = useState(false);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);

  const [historySearch, setHistorySearch] = useState('');

  const barcodeRef = useRef<HTMLInputElement>(null);

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['All', ...cats];
  }, [products]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const q = searchQuery.toLowerCase();
      const matchSearch = p.name.toLowerCase().includes(q) || (p.barcode && p.barcode.includes(q));
      const matchCat = selectedCategory === 'All' || p.category === selectedCategory;
      return matchSearch && matchCat;
    });
  }, [products, searchQuery, selectedCategory]);

  const totalPrice = cart.reduce((acc, item) => acc + item.subTotal, 0);

  useEffect(() => {
    if (totalPrice > 0) setAmountPaid(totalPrice);
    else setAmountPaid('');
  }, [totalPrice]);

  useEffect(() => {
    if (activeTab === 'pos' && barcodeRef.current && !isCameraScanning) {
      barcodeRef.current.focus();
    }
  }, [activeTab, isCameraScanning]);

  const handleScannedCode = (code: string) => {
    const product = products.find(p => p.barcode === code);
    if (product) {
      updateCartQuantity(product.id, 1);
    } else {
      // Small feedback if product not found
      console.log(`Product with barcode ${code} not found.`);
    }
  };

  const startCameraScanner = async () => {
    setScannerLoading(true);
    setIsCameraScanning(true);

    setTimeout(async () => {
      try {
        const scanner = new Html5Qrcode("barcode-reader");
        html5QrCodeRef.current = scanner;

        await scanner.start(
          { facingMode: "environment" },
          {
            fps: 15,
            qrbox: { width: 280, height: 180 }
          },
          (decodedText) => {
            handleScannedCode(decodedText);
            // Optionally stop after one scan or keep scanning
            // stopCameraScanner(); 
          },
          (errorMessage) => { }
        );
        setScannerLoading(false);
      } catch (err) {
        console.error("Camera error:", err);
        alert("ক্যামেরা চালু করা সম্ভব হচ্ছে না। পারমিশন চেক করুন।");
        setIsCameraScanning(false);
        setScannerLoading(false);
      }
    }, 300);
  };

  const stopCameraScanner = async () => {
    if (html5QrCodeRef.current) {
      try {
        await html5QrCodeRef.current.stop();
        html5QrCodeRef.current = null;
      } catch (e) { }
    }
    setIsCameraScanning(false);
  };

  const handleBarcodeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput) return;
    handleScannedCode(barcodeInput);
    setBarcodeInput('');
  };

  const updateCartQuantity = (productId: string, delta: number) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId);
      if (existing) {
        const newQty = existing.quantity + delta;
        if (newQty <= 0) return prev.filter(item => item.productId !== productId);
        if (newQty > product.stock) {
          alert(`দুঃখিত! স্টকে মাত্র ${product.stock} ${product.unit} আছে।`);
          return prev;
        }
        return prev.map(item => item.productId === productId ? { ...item, quantity: newQty, subTotal: newQty * item.pricePerUnit } : item);
      } else if (delta > 0) {
        if (product.stock < 1) { alert("স্টকে নেই!"); return prev; }
        return [...prev, { productId: product.id, productName: product.name, quantity: 1, unit: product.unit, pricePerUnit: product.price, subTotal: product.price }];
      }
      return prev;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) return;
    const dueAmount = Math.max(0, totalPrice - (Number(amountPaid) || 0));
    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice,
      amountPaid: Number(amountPaid) || 0,
      dueAmount,
      customerName: customerName || undefined,
      customerPhone: customerPhone || undefined,
      paymentMethod,
      date: new Date().toISOString()
    };
    onAddSale(newSale);
    setActiveReceipt(newSale); 
    setCart([]);
    setAmountPaid('');
    setCustomerName('');
    setCustomerPhone('');
  };

  const filteredHistory = [...sales].filter(sale => {
    const query = historySearch.toLowerCase();
    return !historySearch || (sale.customerName?.toLowerCase().includes(query)) || (sale.items.some(item => item.productName.toLowerCase().includes(query)));
  }).reverse();

  const getAvailableStock = (product: Product) => {
    const inCart = cart.find(item => item.productId === product.id)?.quantity || 0;
    return product.stock - inCart;
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">
      <div className="flex bg-white dark:bg-[#1a2236] p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm w-fit no-print">
        <button onClick={() => setActiveTab('pos')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'pos' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-orange-500'}`}><PlusCircle size={18} /> New Order</button>
        <button onClick={() => setActiveTab('history')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-black text-sm transition-all ${activeTab === 'history' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-400 hover:text-orange-500'}`}><HistoryIcon size={18} /> History</button>
      </div>

      {activeTab === 'pos' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start no-print">
          <div className="lg:col-span-8 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <form onSubmit={handleBarcodeSubmit} className="bg-orange-500/5 dark:bg-orange-500/10 p-4 rounded-[2rem] border border-orange-500/20 flex gap-3 items-center shadow-sm">
                    <button 
                        type="button"
                        onClick={startCameraScanner}
                        className="p-4 bg-orange-500 hover:bg-orange-600 text-white rounded-2xl shadow-lg transition-all active:scale-90 flex items-center justify-center group"
                    >
                        <Camera size={24} className="group-hover:rotate-12 transition-transform" />
                    </button>
                    <div className="flex-1 relative">
                        <Barcode className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={18} />
                        <input 
                            ref={barcodeRef}
                            type="text" 
                            placeholder="Barcode..." 
                            className="w-full pl-10 pr-4 py-4 rounded-xl bg-white dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-black text-sm tracking-widest uppercase"
                            value={barcodeInput}
                            onChange={e => setBarcodeInput(e.target.value)}
                        />
                    </div>
               </form>
               <div className="bg-white dark:bg-[#1a2236] p-4 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm flex items-center px-6">
                  <div className="relative w-full">
                    <Search className="absolute left-0 top-1/2 -translate-y-1/2 text-orange-500" size={18} />
                    <input type="text" placeholder="Search by name..." className="w-full pl-8 pr-4 py-2 bg-transparent text-slate-900 dark:text-white outline-none text-sm font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
                  </div>
               </div>
            </div>

            <div className="flex flex-wrap gap-2 overflow-x-auto pb-2 custom-scrollbar">
              {categories.map(cat => (
                <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2 rounded-full text-[10px] font-black tracking-widest uppercase transition-all border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-500 shadow-md' : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700'}`}>{cat}</button>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
