      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-orange-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-orange-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <div className="mb-10 text-center flex flex-col items-center animate-in fade-in slide-in-from-top-4 duration-700">
        <div className="w-20 h-20 bg-white dark:bg-[#161d31] rounded-3xl flex items-center justify-center shadow-2xl mb-6 border border-slate-200 dark:border-slate-800 ring-4 ring-orange-500/10">
           <UtensilsCrossed size={40} className="text-orange-500" />
        </div>
        <h1 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">
          Sweet Live<br/>
          <span className="text-orange-500">Bakery Manager</span>
        </h1>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-slate-200 dark:border-slate-800 relative overflow-hidden animate-in zoom-in duration-500">
          <div className="absolute top-0 left-0 w-full h-2 bg-orange-500"></div>

          <div className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-white">{isSignup ? 'রেজিস্ট্রেশন' : 'স্বাগতম'}</h2>
              <p className="text-slate-500 dark:text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">
                {isSignup ? 'নতুন অ্যাকাউন্ট খুলুন' : 'লগইন করে কাজ শুরু করুন'}
              </p>
            </div>
            <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500 border border-orange-500/20">
              {isSignup ? <UserPlus size={28} /> : <LogIn size={28} />}
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1">ইমেইল অ্যাড্রেস (Email)</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required 
                  type="email" 
                  className="w-full pl-12 pr-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                  placeholder="name@gmail.com" 
                  value={email} 
                  onChange={e => setEmail(e.target.value)} 
                />
              </div>
            </div>

            {isSignup && (
              <div className="space-y-2 animate-in slide-in-from-left-4 duration-300">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1">ইউজারনেম (Username)</label>
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    required 
                    type="text" 
                    className="w-full pl-12 pr-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                    placeholder="shuvo_bakery" 
                    value={username} 
                    onChange={e => setUsername(e.target.value)} 
                  />
                </div>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1">পাসওয়ার্ড (Password)</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required 
                  type="password" 
                  className="w-full pl-12 pr-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" 
                  placeholder="••••••••" 
                  value={password} 
                  onChange={e => setPassword(e.target.value)} 
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-4 rounded-xl text-xs font-bold flex flex-col gap-2 animate-shake">
                <div className="flex items-start gap-3">
                  <AlertCircle className="shrink-0 mt-0.5" size={16} /> 
                  <span className="leading-relaxed">{error}</span>
                </div>
                {dbError && (
                  <div className="mt-2 p-3 bg-white/50 dark:bg-black/20 rounded-lg text-[10px] font-mono leading-relaxed border border-red-500/10">
                    <p className="mb-2 font-bold uppercase text-red-600">সমাধানের জন্য SQL রান করুন:</p>
                    <code className="block bg-slate-100 dark:bg-black p-2 rounded overflow-x-auto whitespace-pre">
                      {`ALTER TABLE profiles 
ADD COLUMN IF NOT EXISTS email TEXT,
ADD COLUMN IF NOT EXISTS username TEXT,
ADD COLUMN IF NOT EXISTS password TEXT;`}
                    </code>
                  </div>
                )}
              </div>
            )}

            <button 
              type="submit" 
              disabled={loading} 
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-orange-500/20 transition-all active:scale-[0.98] disabled:opacity-70 flex items-center justify-center gap-3 text-lg"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : (isSignup ? 'রেজিস্ট্রেশন করুন' : 'লগইন করুন')}
              {!loading && <ChevronRight size={20} />}
            </button>
          </form>

          <div className="mt-10 flex flex-col items-center gap-4">
            <button 
              onClick={() => { setIsSignup(!isSignup); setError(''); setDbError(false); }} 
              className="text-slate-400 hover:text-orange-500 text-sm font-bold transition-colors underline underline-offset-4 decoration-slate-200 dark:decoration-slate-800"
            >
              {isSignup ? 'ইতিমধ্যে অ্যাকাউন্ট আছে? লগইন করুন' : "অ্যাকাউন্ট নেই? নতুন অ্যাকাউন্ট খুলুন"}
            </button>

            <button 
              onClick={handleDemoMode}
              className="flex items-center gap-2 text-[10px] font-black uppercase text-orange-500/60 hover:text-orange-500 transition-all tracking-[0.2em]"
            >
              <HelpCircle size={14} /> ডেমো মোডে প্রবেশ করুন
            </button>
          </div>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction, Wastage } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { supabaseService } from './services/supabaseService';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  Trash2,
  RefreshCw,
  Database,
  ArrowRight,
  LogOut,
  Monitor
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    try {
      const saved = localStorage.getItem('sweetBakery_theme');
      return (saved as 'dark' | 'light') || 'dark';
    } catch {
      return 'dark';
    }
  });

  const [isSyncing, setIsSyncing] = useState(false);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  useEffect(() => {
    const savedEmail = localStorage.getItem('sweetBakery_email');
    if (savedEmail) {
      setUserEmail(savedEmail.toLowerCase());
      setIsAuthenticated(true);
    } else {
      setIsDataLoaded(true); 
    }
  }, []);

  const fetchData = async (email: string) => {
    if (!email) {
      setIsDataLoaded(true);
      return;
    }

    setIsSyncing(true);
    setLoadError(null);

    const safeFetch = async <T,>(tableName: string, fetchFn: () => Promise<T[]>) => {
      try {
        const data = await fetchFn();
        return data || [];
      } catch (err: any) {
        return [] as T[];
      }
    };

    try {
      const results = await Promise.allSettled([
        safeFetch('products', () => supabaseService.getProducts(email)),
        safeFetch('sales', () => supabaseService.getSales(email)),
        safeFetch('expenses', () => supabaseService.getExpenses(email)),
        safeFetch('wastage', () => supabaseService.getWastage(email)),
        safeFetch('staff', () => supabaseService.getStaff(email)),
        safeFetch('attendance', () => supabaseService.getAttendance(email)),
        safeFetch('daily_closings', () => supabaseService.getClosings(email)),
        safeFetch('deductions', () => supabaseService.getDeductions(email))
      ]);

      const getData = (index: number) => {
        const res = results[index];
        return res.status === 'fulfilled' ? res.value : [];
      };

      setProducts(getData(0));
      setSales(getData(1));
      setExpenses(getData(2));
      setWastage(getData(3));
      setStaff(getData(4));
      setAttendance(getData(5));
      setDailyClosings(getData(6));
      setDeductions(getData(7));
    } catch (err: any) {
      console.error("Critical fetch error:", err);
    } finally {
      setIsDataLoaded(true);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (isAuthenticated && userEmail) {
      fetchData(userEmail);
    }
  }, [isAuthenticated, userEmail]);

  const handleLogin = (email: string) => {
    const normalizedEmail = email.toLowerCase();
    setUserEmail(normalizedEmail);
    setIsAuthenticated(true);
    localStorage.setItem('sweetBakery_email', normalizedEmail);
  };

  const handleLogout = () => {
    if (window.confirm("লগআউট করতে চান?")) {
      localStorage.removeItem('sweetBakery_email');
      setProducts([]);
      setSales([]);
      setExpenses([]);
      setWastage([]);
      setStaff([]);
      setAttendance([]);
      setDailyClosings([]);
      setDeductions([]);
      setUserEmail('');
      setIsAuthenticated(false);
      setIsDataLoaded(true);
      setCurrentView(View.DASHBOARD);
    }
  };

  const withSync = async (fn: () => Promise<void>) => {
    setIsSyncing(true);
    try {
      await fn();
      await fetchData(userEmail); 
    } catch (e: any) {
      alert(`ত্রুটি: ${e.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const addSale = (newSale: Sale) => withSync(async () => {
    await supabaseService.addSale(userEmail, newSale);
  });

  const addProduct = (product: Product) => withSync(async () => {
    await supabaseService.upsertProduct(userEmail, product);
  });

  const lowStockCount = useMemo(() => products.filter(p => p.stock < 10).length, [products]);

  if (!isAuthenticated) return <Login onLogin={handleLogin} theme={theme} />;

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white transition-all ${isMobileMenuOpen ? 'overflow-hidden' : ''}`}>
      {isMobileMenuOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />}

      <aside className={`w-72 bg-white dark:bg-[#0a1120] border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-transform duration-300 lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 pb-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-orange-500 rounded-xl">
              <UtensilsCrossed size={24} className="text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-900 dark:text-white leading-tight">Sweet Live</h1>
              <h1 className="text-xl font-black text-slate-900 dark:text-white leading-tight">Bakery</h1>
            </div>
          </div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden text-slate-400"><X size={24} /></button>
        </div>

        <nav className="flex-1 px-4 mt-6 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all ${currentView === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
              <span className={currentView === item.id ? 'text-white' : 'text-slate-400'}>{item.icon}</span>
              <div className="text-left flex-1">
                <p className="text-sm font-bold">{item.label}</p>
                <p className="text-[10px] opacity-60">{item.bangla}</p>
              </div>
              {item.notification > 0 && <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black">{item.notification}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 space-y-3">
           <div className="bg-[#1a2236] p-4 rounded-2xl border border-slate-800 flex items-center gap-4">
              <div className="p-2 bg-orange-500/10 rounded-xl text-orange-500">
                <Monitor size={20} />
              </div>
              <div className="flex-1">
                <p className="text-[10px] font-black text-white uppercase leading-tight">Install Desktop App</p>
                <p className="text-[9px] text-slate-400 font-bold">(পিসিতে সেট করুন)</p>
              </div>
           </div>

           <div className="p-4 bg-[#161d31]/40 rounded-2xl border border-slate-800/50">
             <div className="text-[10px] font-black uppercase text-orange-400 mb-1">Bakery Status</div>
             <div className="flex items-center gap-2">
                <span className="text-xs font-black text-white">v3.1.0</span>
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                <span className="text-[10px] text-emerald-500 font-bold uppercase">Stable</span>
             </div>
             <p className="text-[9px] text-slate-500 font-bold mt-1">User: <span className="capitalize">{userEmail.split('@')[0]}</span></p>
           </div>

           <div className="text-center pb-2">
              <p className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">© 2024 MD SHAMIM</p>
           </div>
        </div>
      </aside>

      <main className="lg:ml-72 flex-1 min-h-screen flex flex-col">
        <header className="px-6 md:px-10 py-5 bg-white/80 dark:bg-dark-bg/80 backdrop-blur-xl sticky top-0 z-40 flex justify-between items-center border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl shadow-sm"><Menu size={22} className="text-orange-500" /></button>
            <div>
              <h2 className="text-2xl font-black uppercase tracking-tight text-slate-900 dark:text-white">{currentView.replace('_', ' ')}</h2>
              <div className="flex items-center gap-2">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Stable Desktop Management</span>
                <span className="text-[8px] px-1.5 py-0.5 bg-orange-500/10 text-orange-500 rounded font-black border border-orange-500/20 uppercase">Persistent Auth</span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-orange-500 shadow-sm transition-all active:scale-95">{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button>
             <button 
                onClick={handleLogout}
