              >
                <LogOut size={18} />
                Logout
              </button>
          </div>
        </header>

        <div className="p-4 md:p-10 flex-1 overflow-x-hidden">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center h-[60vh]">
              <div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div>
              <p className="mt-6 font-black text-slate-400 animate-pulse uppercase text-xs tracking-[0.3em]">Sweet Live Loading...</p>
            </div>
          ) : (
            <div className="animate-in fade-in duration-700">
              {currentView === View.DASHBOARD && <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} />}
              {currentView === View.INVENTORY && <Inventory products={products} onAdd={addProduct} onUpdate={addProduct} onDelete={() => {}} onMarkWastage={() => {}} />}
              {currentView === View.SALES && <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={() => {}} />}
              {currentView === View.DUES && <DuesView sales={sales} onUpdateSales={() => {}} />}
              {currentView === View.WASTAGE && <WastageView wastage={wastage} products={products} onAdd={() => {}} onDelete={() => {}} />}
              {currentView === View.EXPENSES && <ExpensesView expenses={expenses} onAdd={() => {}} />}
              {currentView === View.DAILY_CLOSING && <DailyClosingView sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onCloseDay={() => {}} onDeleteClosing={() => {}} currentUser={userEmail} />}
              {currentView === View.STAFF && <StaffView staff={staff} attendance={attendance} expenses={expenses} deductions={deductions} onAddStaff={() => {}} onUpdateAttendance={() => {}} onAddDeduction={() => {}} onPaySalary={() => {}} />}
              {currentView === View.MANAGER && <ManagerView username={userEmail} onLogout={handleLogout} stats={{ products: products.length, sales: sales.length, expenses: expenses.length, staff: staff.length }} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

