                       </button>
                       <button onClick={() => onCancelSale(sale.id)} className="p-2 text-slate-500 hover:text-red-500 bg-[#0a1120] rounded-lg">
                          <Trash size={14} />
                       </button>
                    </div>
                  </td>
                </tr>
              ))}
              {activeSessionSales.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-32 text-center text-slate-600 font-bold uppercase tracking-widest">
                     No sales recorded in the active session.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Receipt Modal (Print View) */}
      {activeReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 no-print">
