              {currentView === View.DUES && <DuesView sales={sales} onUpdateSales={() => {}} />}
              {currentView === View.WASTAGE && <WastageView wastage={wastage} products={products} onAdd={() => {}} onDelete={() => {}} />}
              {currentView === View.EXPENSES && <ExpensesView expenses={expenses} onAdd={() => {}} />}
              {currentView === View.DAILY_CLOSING && <DailyClosingView sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onCloseDay={() => {}} onDeleteClosing={() => {}} currentUser={userEmail} />}
              {currentView === View.STAFF && <StaffView staff={staff} attendance={attendance} expenses={expenses} deductions={deductions} onAddStaff={() => {}} onUpdateAttendance={() => {}} onAddDeduction={() => {}} onPaySalary={() => {}} />}
              {currentView === View.MANAGER && <ManagerView username={userEmail} onLogout={handleLogout} stats={{ products: products.length, sales: sales.length, expenses: expenses.length, staff: staff.length }} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Product, Sale, Expense, DailyClosing, Wastage } from '../types';
import { 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis
} from 'recharts';
import { ShoppingCart, Package, ReceiptIndianRupee, TrendingUp, UtensilsCrossed, Monitor, CalendarDays, Clock } from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  expenses: Expense[];
  wastage?: Wastage[];
  closings?: DailyClosing[];
}

const Dashboard: React.FC<Props> = ({ products = [], sales = [], expenses = [], wastage = [], closings = [] }) => {
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  const lastClosingTimestamp = useMemo(() => {
    if (!closings || closings.length === 0) return 0;
    return Math.max(...closings.map(c => new Date(c.timestamp).getTime()));
  }, [closings]);

  const monthlyStats = useMemo(() => {
    const mSales = sales.filter(s => {
      const d = new Date(s.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const mExpenses = expenses.filter(e => {
      const d = new Date(e.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const totalSales = mSales.reduce((acc, s) => acc + (s.totalPrice || 0), 0);
    const totalCash = mSales.reduce((acc, s) => acc + (s.amountPaid || 0), 0);
    const totalExp = mExpenses.reduce((acc, e) => acc + (e.amount || 0), 0);

    return {
      salesVolume: totalSales,
      cashCollected: totalCash,
      expenses: totalExp,
      balance: totalCash - totalExp
    };
  }, [sales, expenses, currentMonth, currentYear]);

  const activeSessionStats = useMemo(() => {
    const activeSales = sales.filter(s => new Date(s.date).getTime() > lastClosingTimestamp);
    const activeExpenses = expenses.filter(e => new Date(e.date).getTime() > lastClosingTimestamp);

    const totalSalesVolume = activeSales.reduce((acc, s) => acc + (s.totalPrice || 0), 0);
    const totalCashCollected = activeSales.reduce((acc, s) => acc + (s.amountPaid || 0), 0);
    const totalExpenses = activeExpenses.reduce((acc, e) => acc + (e.amount || 0), 0);

    return {
      salesVolume: totalSalesVolume,
      cashCollected: totalCashCollected,
      expenses: totalExpenses,
      mainBalance: totalCashCollected - totalExpenses,
    };
  }, [sales, expenses, lastClosingTimestamp]);

  const last7Days = useMemo(() => {
    return [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const daySales = sales
        .filter(s => s.date.startsWith(dateStr))
        .reduce((acc, curr) => acc + (curr.totalPrice || 0), 0);
      return { 
        name: d.toLocaleDateString([], { month: 'numeric', day: 'numeric' }), 
        sales: daySales 
      };
    }).reverse();
  }, [sales]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="bg-white dark:bg-[#161d31] p-8 md:p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row items-center justify-between gap-8 group">
          <div className="relative z-10 flex flex-col md:flex-row items-center gap-6">
             <div className="w-16 h-16 bg-orange-500 rounded-3xl flex items-center justify-center shadow-lg shadow-orange-500/20">
                <UtensilsCrossed size={32} className="text-white" />
             </div>
             <div>
                <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tighter">Sweet Live Bakery</h1>
                <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-[10px]">Business Management System</p>
             </div>
          </div>
          <div className="relative z-10 bg-orange-500/10 p-4 px-6 rounded-2xl border border-orange-500/20">
             <div className="text-lg font-black text-slate-900 dark:text-white flex items-center gap-2">
                <CalendarDays size={18} className="text-orange-500" /> {now.toLocaleString('default', { month: 'long', year: 'numeric' })}
             </div>
          </div>
      </div>

      <div>
        <div className="flex items-center gap-2 mb-4 px-1">
           <TrendingUp size={18} className="text-orange-500" />
           <h3 className="text-sm font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Monthly Overview</h3>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
          <StatCard title="Monthly Sales" value={monthlyStats.salesVolume} type="neutral" bangla="মাসের মোট বিক্রি" />
          <StatCard title="Total Collected" value={monthlyStats.cashCollected} type="revenue" bangla="মাসের নগদ আদায়" />
          <StatCard title="Monthly Expenses" value={monthlyStats.expenses} type="expense" bangla="মাসের মোট খরচ" />
          <StatCard title="Current Balance" value={monthlyStats.balance} type="balance" bangla="মাসের বর্তমান ব্যালেন্স" />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-6">
           <div className="bg-slate-900 p-8 rounded-[2.5rem] border border-slate-800 shadow-2xl relative overflow-hidden">
              <div className="relative z-10">
                <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2"><Clock size={20} className="text-orange-500" /> Today's Session</h3>
                <div className="space-y-4">
                   <div className="flex justify-between items-center p-4 bg-white/5 rounded-2xl border border-white/5">
                      <span className="text-[10px] text-slate-400 font-bold uppercase">Cash in Hand</span>
                      <span className="text-lg font-black text-emerald-400">৳{activeSessionStats.mainBalance.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between items-center p-4 bg-white/5 rounded-2xl border border-white/5">
                      <span className="text-[10px] text-slate-400 font-bold uppercase">Daily Sales</span>
                      <span className="text-lg font-black text-white">৳{activeSessionStats.salesVolume.toLocaleString()}</span>
                   </div>
                </div>
              </div>
           </div>
        </div>

        <div className="lg:col-span-8 bg-white dark:bg-[#161d31] p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-8">
             <h3 className="text-xl font-bold text-slate-900 dark:text-slate-200 flex items-center gap-2"><TrendingUp size={20} className="text-orange-500" /> Weekly Sales Trend</h3>
             <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full">Last 7 Days</span>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={last7Days}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <Tooltip contentStyle={{ borderRadius: '12px', fontSize: '12px' }} />
                <Line type="monotone" dataKey="sales" stroke="#F26711" strokeWidth={4} dot={{ fill: '#F26711', r: 5 }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ 
  title: string; 
  value: number; 
  type: 'revenue' | 'expense' | 'balance' | 'neutral';
  bangla: string;
}> = ({ title, value, type, bangla }) => {
  const isNegative = value < 0;
  const getStyles = () => {
    switch(type) {
      case 'revenue': return 'text-emerald-500 border-emerald-500/20';
      case 'expense': return 'text-red-500 border-red-500/20';
      case 'balance': return 'text-orange-500 border-orange-500/30 bg-orange-500/5';
      default: return 'text-slate-900 dark:text-white border-slate-200 dark:border-slate-800';
    }
  };

  return (
    <div className={`bg-white dark:bg-[#161d31] p-5 rounded-[2rem] border shadow-sm ${type === 'balance' ? 'ring-2 ring-orange-500/20 shadow-lg' : ''}`}>
      <div className="flex flex-col h-full">
        <h4 className="text-slate-400 dark:text-[#94a3b8] font-bold text-[8px] mb-1 tracking-wider uppercase">{title}</h4>
        <div className="text-[9px] font-medium text-slate-500 dark:text-slate-400 mb-3">{bangla}</div>
        <div className="mt-auto flex items-baseline gap-1">
          <span className={`text-base font-bold ${getStyles()}`}>৳</span>
          <span className={`text-xl md:text-2xl font-black tracking-tighter truncate ${getStyles()}`}>
            {isNegative ? '-' : ''}{Math.abs(value).toLocaleString()}
          </span>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Product, Sale, SaleItem } from '../types';
import { 
  ShoppingCart, 
  Printer, 
  Trash,
  User,
  Phone,
  Wallet,
  X
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale }) => {
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);

  const selectedProduct = products.find(p => p.id === selectedProductId);
  const totalBill = selectedProduct ? selectedProduct.price * (Number(quantity) || 0) : 0;
  const dueAmount = Math.max(0, totalBill - (Number(amountPaid) || 0));

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct || !quantity) return;

    if (selectedProduct.stock < Number(quantity)) {
      alert("স্টকে পর্যাপ্ত মাল নেই!");
      return;
    }

    const saleItem: SaleItem = {
      productId: selectedProduct.id,
      productName: selectedProduct.name,
      quantity: Number(quantity),
      unit: selectedProduct.unit,
      pricePerUnit: selectedProduct.price,
      subTotal: totalBill
    };

    const newSale: Sale = {
      id: Date.now().toString(),
      items: [saleItem],
      totalPrice: totalBill,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: dueAmount,
      customerName: customerName || 'Walk-in',
      customerPhone: customerPhone || '',
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setActiveReceipt(newSale);

    // Reset form
    setSelectedProductId('');
    setQuantity('');
    setAmountPaid('');
    setCustomerName('');
    setCustomerPhone('');
  };

  const activeSessionSales = [...sales].reverse();

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in duration-500">

      {/* Left: Record New Sale Form */}
      <div className="lg:col-span-5 bg-[#161d31] p-8 md:p-10 rounded-[2rem] border border-slate-800 shadow-xl">
        <h3 className="text-xl font-bold text-white mb-8 flex items-center gap-3">
          <ShoppingCart className="text-orange-500" size={24} /> Record New Sale
        </h3>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase px-1">Product</label>
            <select 
              required
              className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all appearance-none cursor-pointer"
              value={selectedProductId}
              onChange={e => setSelectedProductId(e.target.value)}
            >
              <option value="">Choose a product...</option>
              {products.map(p => (
                <option key={p.id} value={p.id}>{p.name} (Stock: {p.stock} {p.unit})</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase px-1">Quantity</label>
              <input 
                required
                type="number"
                className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all"
                value={quantity}
                onChange={e => setQuantity(e.target.value === '' ? '' : Number(e.target.value))}
                placeholder="0"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase px-1">Payment Method</label>
              <select 
                className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all appearance-none cursor-pointer"
                value={paymentMethod}
                onChange={e => setPaymentMethod(e.target.value as any)}
              >
                <option value="Cash">Cash</option>
                <option value="Mobile Payment">Mobile Pay</option>
              </select>
            </div>
          </div>

          {/* Billing Summary Section */}
          <div className="bg-[#0a1120] p-6 rounded-3xl border border-slate-800 relative overflow-hidden group">
             <div className="flex justify-between items-center mb-6">
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">TOTAL BILL</span>
                <span className="text-3xl font-black text-white">৳{totalBill.toLocaleString()}</span>
             </div>

             <div className="space-y-3">
                <label className="text-[10px] font-bold text-slate-400 uppercase px-1">AMOUNT PAID (কত দিয়েছেন)</label>
                <input 
                  type="number"
                  className="w-full p-5 rounded-2xl bg-[#161d31] border-2 border-slate-800 focus:border-emerald-500 text-white text-3xl font-black outline-none transition-all shadow-inner"
                  value={amountPaid}
                  onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value))}
                  placeholder="0.00"
                />
             </div>

             {dueAmount > 0 && (
               <div className="flex justify-between items-center mt-6 p-2 animate-in slide-in-from-top-2">
                  <span className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2">
                    <Wallet size={14} /> DUE AMOUNT (বাকি)
                  </span>
                  <span className="text-2xl font-black text-red-500">৳{dueAmount.toLocaleString()}</span>
               </div>
             )}
          </div>

          {/* Customer Details */}
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase px-1">CUSTOMER NAME (কাস্টমারের নাম)</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
