          </div>
        </div>
      )}
    </div>
  );
};

export default SalesView;

import React, { useState, useMemo } from 'react';
import { Sale } from '../types';
import { 
  Wallet, 
  Search, 
  Phone, 
  User, 
  CheckCircle2, 
  History, 
  X, 
  ChevronDown, 
  ChevronUp,
  ArrowRight,
  TrendingUp,
  CreditCard
} from 'lucide-react';

interface CustomerGroup {
  name: string;
  phone: string;
  totalDue: number;
  sales: Sale[];
}

interface Props {
  sales: Sale[];
  onUpdateSales: (updatedSales: Sale[]) => void;
}

const DuesView: React.FC<Props> = ({ sales, onUpdateSales }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [collectingCustomerKey, setCollectingCustomerKey] = useState<string | null>(null);
  const [collectionAmount, setCollectionAmount] = useState<number | ''>('');
  const [expandedCustomerKey, setExpandedCustomerKey] = useState<string | null>(null);

  // Group sales by customer name and phone
  const customerGroups = useMemo(() => {
    const groups: Record<string, CustomerGroup> = {};

    sales.forEach(s => {
      if (s.dueAmount <= 0) return;

      const key = `${(s.customerName || 'Unknown').toLowerCase()}|${s.customerPhone || 'None'}`;
      if (!groups[key]) {
        groups[key] = {
          name: s.customerName || 'Unknown',
          phone: s.customerPhone || 'None',
          totalDue: 0,
          sales: []
        };
      }
      groups[key].totalDue += s.dueAmount;
      groups[key].sales.push(s);
    });

    // Sort group sales by date oldest first for collection logic
    Object.values(groups).forEach(group => {
      group.sales.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    });

    return Object.values(groups).sort((a, b) => b.totalDue - a.totalDue);
  }, [sales]);

  const totalOutstanding = customerGroups.reduce((acc, g) => acc + g.totalDue, 0);

  const filteredGroups = customerGroups.filter(g => 
    g.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    g.phone.includes(searchTerm)
  );

  const handleCollect = (e: React.FormEvent) => {
    e.preventDefault();
    if (!collectingCustomerKey || collectionAmount === '') return;

    const group = customerGroups.find(g => `${g.name.toLowerCase()}|${g.phone}` === collectingCustomerKey);
    if (!group) return;

    let remainingPayment = Number(collectionAmount);
    if (remainingPayment > group.totalDue) {
      alert("আদায়ের পরিমাণ কাস্টমারের মোট বাকির চেয়ে বেশি হতে পারে না!");
      return;
    }

    const updatedSalesList: Sale[] = [];

    // Apply payment to oldest sales first
    for (const sale of group.sales) {
      if (remainingPayment <= 0) break;

      const amountToApply = Math.min(sale.dueAmount, remainingPayment);
      updatedSalesList.push({
        ...sale,
        amountPaid: sale.amountPaid + amountToApply,
        dueAmount: sale.dueAmount - amountToApply
      });
      remainingPayment -= amountToApply;
    }

    onUpdateSales(updatedSalesList);
    setCollectingCustomerKey(null);
    setCollectionAmount('');
  };

  const toggleExpand = (key: string) => {
    setExpandedCustomerKey(prev => prev === key ? null : key);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Stats Summary Section */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
        <div className="md:col-span-5 bg-[#161d31] p-10 rounded-[2.5rem] border border-slate-800 shadow-xl relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 opacity-5 group-hover:scale-110 transition-transform duration-500">
             <Wallet size={180} className="text-orange-500" />
          </div>
          <div className="relative z-10">
            <h4 className="text-slate-400 font-bold text-[10px] mb-2 uppercase tracking-[0.2em] flex items-center gap-2">
               <TrendingUp size={14} className="text-orange-500" /> Total Active Dues (মোট বাকি)
            </h4>
            <div className="flex items-baseline gap-1">
              <span className="text-2xl font-black text-red-500">৳</span>
              <span className="text-5xl font-black text-red-500 tracking-tighter">
                {totalOutstanding.toLocaleString()}
              </span>
            </div>
            <div className="mt-4 flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase tracking-widest">
               <User size={12} /> {customerGroups.length} Active Customers
            </div>
          </div>
        </div>

        <div className="md:col-span-7 bg-[#161d31] p-10 rounded-[2.5rem] border border-slate-800 shadow-xl flex flex-col sm:flex-row items-center justify-between gap-6">
           <div className="flex-1">
              <h2 className="text-2xl font-black text-white mb-2">Due Management</h2>
              <p className="text-slate-400 text-sm max-w-md leading-relaxed">
                আপনার কাস্টমারদের বাকি টাকা ম্যানেজ করুন। এখান থেকে পুরনো পাওনা দ্রুত কালেকশন করা সম্ভব।
              </p>
           </div>
           <div className="p-6 bg-[#0a1120] rounded-3xl border border-slate-800 flex flex-col items-center justify-center text-orange-500">
              <CreditCard size={32} />
              <span className="text-[10px] font-black mt-2 uppercase">Payment Flow</span>
           </div>
        </div>
      </div>

      {/* Search Bar Section */}
      <div className="bg-[#161d31] p-4 rounded-3xl border border-slate-800 flex flex-col md:flex-row gap-4 items-center shadow-sm">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-500" size={20} />
          <input 
            type="text" 
            placeholder="Search by customer name or phone number..." 
            className="w-full pl-12 pr-4 py-4 rounded-2xl bg-[#0a1120] border border-slate-800 text-white placeholder-slate-500 outline-none focus:border-orange-500 transition-all font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Customer List Grid */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        {filteredGroups.map(g => {
          const key = `${g.name.toLowerCase()}|${g.phone}`;
          const isExpanded = expandedCustomerKey === key;

          return (
            <div key={key} className={`bg-[#161d31] p-8 rounded-[2rem] border transition-all shadow-xl flex flex-col ${
              isExpanded ? 'border-orange-500/50 ring-2 ring-orange-500/10' : 'border-slate-800 hover:border-slate-700'
            }`}>
              <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-8">
                <div className="flex items-center gap-5">
                  <div className="w-16 h-16 rounded-2xl bg-[#0a1120] border border-slate-800 flex items-center justify-center text-orange-500 font-black text-2xl shadow-inner">
                    {g.name.charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <h4 className="text-2xl font-black text-white group-hover:text-orange-500 transition-colors tracking-tight">{g.name}</h4>
                    <div className="flex items-center gap-2 text-slate-500 text-sm font-bold mt-1 tracking-wider">
                       <Phone size={14} className="text-orange-500" /> {g.phone}
                    </div>
                  </div>
                </div>
                <div className="text-right w-full sm:w-auto p-4 bg-[#0a1120] rounded-2xl border border-slate-800">
                   <div className="text-[9px] text-slate-500 uppercase font-black tracking-widest mb-1">Due Amount (বাকি)</div>
                   <div className="text-3xl font-black text-red-500 tracking-tighter">৳{g.totalDue.toLocaleString()}</div>
                </div>
              </div>

              <div className="flex-1 space-y-3 mb-8">
                 <button 
                   onClick={() => toggleExpand(key)}
                   className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-orange-500 transition-colors mb-2 px-1"
                 >
                    {g.sales.length} Active Orders {isExpanded ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
                 </button>

                 {isExpanded && (
                   <div className="space-y-2 max-h-60 overflow-y-auto pr-2 custom-scrollbar animate-in slide-in-from-top-2">
                     {g.sales.map(s => (
                       <div key={s.id} className="flex justify-between items-center p-4 bg-[#0a1120] rounded-2xl border border-slate-800/50 hover:border-slate-700 transition-all">
                         <div className="flex flex-col">
                            <span className="text-xs font-black text-white leading-tight">
                               {s.items.map(i => i.productName).join(', ')}
                            </span>
                            <span className="text-[9px] text-slate-500 font-bold uppercase mt-1">
                              {new Date(s.date).toLocaleDateString()} • #{s.id.slice(-6)}
                            </span>
                         </div>
                         <div className="text-right">
                            <span className="text-sm font-black text-red-500">৳{s.dueAmount.toLocaleString()}</span>
                         </div>
                       </div>
                     ))}
                   </div>
                 )}
              </div>

              <div className="flex gap-4">
                <button 
                  onClick={() => setCollectingCustomerKey(key)}
                  className="flex-1 bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl transition-all shadow-xl shadow-orange-500/20 active:scale-95 flex items-center justify-center gap-3 text-sm uppercase tracking-widest"
                >
                  <CheckCircle2 size={18} /> Collect Payment
                </button>
              </div>
            </div>
          );
        })}
        {filteredGroups.length === 0 && (
          <div className="lg:col-span-2 py-32 text-center bg-[#161d31] border-2 border-dashed border-slate-800 rounded-[3rem]">
             <div className="w-24 h-24 bg-[#0a1120] rounded-full flex items-center justify-center mx-auto mb-6 border border-slate-800 shadow-xl">
                <History size={48} className="text-slate-700" />
             </div>
             <p className="text-slate-500 font-black text-2xl uppercase tracking-widest">No outstanding dues</p>
             <p className="text-slate-600 text-sm mt-3 font-bold">ক্যাশ বক্স ক্লিয়ার আছে!</p>
          </div>
        )}
      </div>

      {/* Collection Modal - Styled like Sales Entry */}
      {collectingCustomerKey && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#0a1120]/90 backdrop-blur-md animate-in fade-in duration-300">
           <div className="bg-[#161d31] p-10 rounded-[3rem] border border-slate-800 shadow-[0_40px_100px_-20px_rgba(0,0,0,0.6)] w-full max-w-md animate-in zoom-in duration-300">
              <div className="flex justify-between items-center mb-10">
                 <div className="flex items-center gap-4">
                    <div className="p-4 bg-orange-500 rounded-2xl text-white shadow-xl shadow-orange-500/20">
                      <Wallet size={24} />
                    </div>
                    <div>
                      <h3 className="text-2xl font-black text-white tracking-tight">Collect Due</h3>
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Payment Settlement</p>
                    </div>
                 </div>
                 <button onClick={() => setCollectingCustomerKey(null)} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <X size={28} />
                 </button>
              </div>

              <form onSubmit={handleCollect} className="space-y-8">
                 <div className="bg-[#0a1120] p-8 rounded-[2.5rem] border border-slate-800 shadow-inner">
                    <div className="flex justify-between items-center mb-6">
                       <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">TOTAL DEBT (মোট বাকি)</span>
                       <span className="text-3xl font-black text-red-500 tracking-tighter">
                         ৳{customerGroups.find(g => `${g.name.toLowerCase()}|${g.phone}` === collectingCustomerKey)?.totalDue.toLocaleString()}
                       </span>
                    </div>

                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">COLLECTION AMOUNT (আদায়ের পরিমাণ)</label>
                       <div className="relative">
                          <input 
                            required 
                            type="number" 
                            autoFocus
                            className="w-full p-6 rounded-2xl bg-[#161d31] border-2 border-slate-800 focus:border-emerald-500 text-white text-4xl font-black outline-none transition-all shadow-xl" 
                            value={collectionAmount} 
                            onChange={e => setCollectionAmount(e.target.value === '' ? '' : Number(e.target.value))} 
                            placeholder="0"
                          />
                          <span className="absolute right-6 top-1/2 -translate-y-1/2 text-2xl font-black text-slate-800">৳</span>
                       </div>
                    </div>
                 </div>

                 <div className="flex gap-4">
                    <button 
                      type="button" 
                      onClick={() => setCollectingCustomerKey(null)}
                      className="flex-1 bg-slate-800 hover:bg-slate-700 text-white font-bold py-5 rounded-2xl transition-all active:scale-95 uppercase text-xs tracking-widest"
                    >
                      Cancel
                    </button>
                    <button 
                      type="submit" 
                      className="flex-[2] bg-emerald-500 hover:bg-emerald-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-emerald-500/20 transition-all active:scale-95 text-sm uppercase tracking-[0.2em]"
                    >
                      Confirm Collection
                    </button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

