import React, { useState, useMemo } from 'react';
import { Product, Sale, SaleItem } from '../types';
import { 
  ShoppingCart, 
  Printer, 
  Trash,
  User,
  Phone,
  Wallet,
  X,
  Plus,
  Trash2,
  PackageCheck
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale }) => {
  // Selection states
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');

  // Cart state for multi-item sales
  const [cart, setCart] = useState<SaleItem[]>([]);

  // Customer & Payment states
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Receipt Modal
  const [activeReceipt, setActiveReceipt] = useState<Sale | null>(null);

  const selectedProduct = products.find(p => p.id === selectedProductId);

  // Add to cart logic
  const handleAddToCart = () => {
    if (!selectedProduct || !quantity || Number(quantity) <= 0) return;

    if (selectedProduct.stock < Number(quantity)) {
      alert("স্টকে পর্যাপ্ত মাল নেই!");
      return;
    }

    const existingItemIndex = cart.findIndex(item => item.productId === selectedProduct.id);

    if (existingItemIndex > -1) {
      const updatedCart = [...cart];
      const newQty = updatedCart[existingItemIndex].quantity + Number(quantity);

      if (selectedProduct.stock < newQty) {
        alert("স্টকে পর্যাপ্ত মাল নেই!");
        return;
      }

      updatedCart[existingItemIndex].quantity = newQty;
      updatedCart[existingItemIndex].subTotal = newQty * selectedProduct.price;
      setCart(updatedCart);
    } else {
      const newItem: SaleItem = {
        productId: selectedProduct.id,
        productName: selectedProduct.name,
        quantity: Number(quantity),
        unit: selectedProduct.unit,
        pricePerUnit: selectedProduct.price,
        subTotal: selectedProduct.price * Number(quantity)
      };
      setCart([...cart, newItem]);
    }

    // Reset selection inputs
    setSelectedProductId('');
    setQuantity('');
  };

  const removeFromCart = (index: number) => {
    const updatedCart = cart.filter((_, i) => i !== index);
    setCart(updatedCart);
  };

  const totalBill = useMemo(() => cart.reduce((acc, item) => acc + item.subTotal, 0), [cart]);
  const dueAmount = Math.max(0, totalBill - (Number(amountPaid) || 0));

  const handleSubmitSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) {
      alert("অন্তত একটি আইটেম যোগ করুন!");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice: totalBill,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: dueAmount,
      customerName: customerName || 'Walk-in',
      customerPhone: customerPhone || '',
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);
    setActiveReceipt(newSale);

    // Reset everything
    setCart([]);
    setAmountPaid('');
    setCustomerName('');
    setCustomerPhone('');
  };

  const activeSessionSales = [...sales].reverse();

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in duration-500">

      {/* Left Column: Form and Cart */}
      <div className="lg:col-span-5 space-y-6">

        {/* Item Selection Section */}
        <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
          <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-3">
            <PackageCheck className="text-orange-500" size={24} /> Select Products
          </h3>

          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase px-1">Product</label>
              <select 
                className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all appearance-none cursor-pointer"
                value={selectedProductId}
                onChange={e => setSelectedProductId(e.target.value)}
              >
                <option value="">Choose a product...</option>
                {products.map(p => (
                  <option key={p.id} value={p.id}>{p.name} (Stock: {p.stock} {p.unit})</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-3 gap-4 items-end">
              <div className="col-span-2 space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase px-1">Quantity</label>
                <input 
                  type="number"
                  className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all"
                  value={quantity}
                  onChange={e => setQuantity(e.target.value === '' ? '' : Number(e.target.value))}
                  placeholder="0"
                />
              </div>
              <button 
                type="button"
                onClick={handleAddToCart}
                disabled={!selectedProductId || !quantity}
                className="bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg shadow-emerald-500/20"
              >
                <Plus size={20} /> Add
              </button>
            </div>
          </div>
        </div>

        {/* Cart/Items List Section */}
        <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
          <div className="flex justify-between items-center mb-6">
             <h3 className="text-xl font-bold text-white flex items-center gap-3">
               <ShoppingCart className="text-orange-500" size={24} /> Sales List
             </h3>
             <span className="bg-[#0a1120] text-orange-500 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-slate-800">
               {cart.length} Items
             </span>
          </div>

          <div className="space-y-3 mb-8 max-h-[300px] overflow-y-auto custom-scrollbar pr-2">
            {cart.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center p-4 bg-[#0a1120] rounded-2xl border border-slate-800 group animate-in slide-in-from-left-2 transition-all">
                <div className="flex-1">
                   <div className="text-sm font-bold text-white">{item.productName}</div>
                   <div className="text-[10px] text-slate-500 font-bold uppercase">
                     {item.quantity} {item.unit} × ৳{item.pricePerUnit}
                   </div>
                </div>
                <div className="text-right flex items-center gap-4">
                   <div className="text-sm font-black text-white">৳{item.subTotal.toLocaleString()}</div>
                   <button 
                     onClick={() => removeFromCart(idx)}
                     className="p-2 text-slate-500 hover:text-red-500 bg-[#161d31] rounded-lg border border-slate-800 transition-colors"
                   >
                     <Trash2 size={14} />
                   </button>
                </div>
              </div>
            ))}
            {cart.length === 0 && (
              <div className="py-12 text-center text-slate-600 font-bold uppercase tracking-widest text-xs border-2 border-dashed border-slate-800 rounded-3xl">
                পণ্য যোগ করুন...
              </div>
            )}
          </div>

          {/* Checkout Info */}
          <form onSubmit={handleSubmitSale} className="space-y-6 border-t border-slate-800 pt-8">
            <div className="bg-[#0a1120] p-6 rounded-3xl border border-slate-800">
               <div className="flex justify-between items-center mb-6">
                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">TOTAL BILL</span>
                  <span className="text-3xl font-black text-white">৳{totalBill.toLocaleString()}</span>
               </div>

               <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-400 uppercase px-1">AMOUNT PAID (কত দিয়েছেন)</label>
                  <input 
                    type="number"
                    className="w-full p-5 rounded-2xl bg-[#161d31] border-2 border-slate-800 focus:border-emerald-500 text-white text-3xl font-black outline-none transition-all shadow-inner"
                    value={amountPaid}
                    onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value))}
                    placeholder="0"
                  />
               </div>

               {dueAmount > 0 && (
                 <div className="flex justify-between items-center mt-6 p-2 animate-in slide-in-from-top-2">
                    <span className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2">
                      <Wallet size={14} /> DUE AMOUNT (বাকি)
                    </span>
                    <span className="text-2xl font-black text-red-500">৳{dueAmount.toLocaleString()}</span>
                 </div>
               )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase px-1">Customer Name</label>
                <input 
                  type="text"
                  className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all text-sm"
                  value={customerName}
                  onChange={e => setCustomerName(e.target.value)}
                  placeholder="e.g. Rohim"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase px-1">Phone Number</label>
                <input 
                  type="tel"
                  className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all text-sm"
                  value={customerPhone}
                  onChange={e => setCustomerPhone(e.target.value)}
                  placeholder="017XXX"
                />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={cart.length === 0}
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-orange-500/20 transition-all active:scale-95 flex items-center justify-center gap-3 text-lg disabled:opacity-50"
            >
              <ShoppingCart size={24} /> Complete Sale
            </button>
          </form>
        </div>
      </div>

      {/* Right Column: History */}
      <div className="lg:col-span-7 bg-[#161d31] rounded-[2rem] border border-slate-800 shadow-xl overflow-hidden min-h-[600px] flex flex-col">
        <div className="px-10 py-8 border-b border-slate-800 flex justify-between items-center">
          <h3 className="text-xl font-bold text-white flex items-center gap-3">
             Recent Sales (Active Session)
          </h3>
          <span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Transaction History</span>
        </div>

        <div className="flex-1 overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] uppercase text-slate-600 font-black tracking-widest border-b border-slate-800">
                <th className="px-8 py-5">Date</th>
                <th className="px-8 py-5">Summary</th>
                <th className="px-8 py-5">Total</th>
                <th className="px-8 py-5">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {activeSessionSales.map(sale => (
                <tr key={sale.id} className="hover:bg-white/5 transition-colors group">
                  <td className="px-8 py-5 text-[11px] text-slate-500">
                    {new Date(sale.date).toLocaleDateString()}
                  </td>
                  <td className="px-8 py-5">
                    <div className="font-bold text-xs text-white">
                      {sale.items.length} Items • {sale.items[0]?.productName}{sale.items.length > 1 ? '...' : ''}
                    </div>
                    <div className="text-[9px] text-slate-500 font-bold uppercase">
                      {sale.customerName || 'Walk-in'} {sale.customerPhone ? `(${sale.customerPhone})` : ''}
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="font-black text-xs text-white">৳{sale.totalPrice.toLocaleString()}</div>
                    <div className="text-[9px] text-emerald-500 font-bold">Paid: ৳{sale.amountPaid.toLocaleString()}</div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex gap-2">
