আপনার ডাটাবেস এরর সমাধানের জন্য আমি অ্যাপের `Login.tsx` ফাইলটি আপডেট করেছি যাতে এটি এররগুলো আরও পরিষ্কারভাবে ধরতে পারে এবং আপনাকে সঠিক SQL কোডটি সরাসরি কপি করার অপশন দেয়। 

ডাটাবেসে `email`, `username`, এবং `password` কলামগুলো না থাকার কারণেই মূলত এই সমস্যাটি হচ্ছে। নিচের SQL কোডটি আপনার Supabase ড্যাশবোর্ডের **SQL Editor**-এ রান করলে আপনার সব সমস্যার সমাধান হয়ে যাবে:

```sql
-- ১. প্রোফাইল টেবিলটি সঠিকভাবে তৈরি বা আপডেট করা
CREATE TABLE IF NOT EXISTS profiles (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  username TEXT UNIQUE NOT NULL,
  password TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- ২. সিকিউরিটি পলিসি সেট করা (যাতে অ্যাপ থেকে ডাটা এক্সেস করা যায়)
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public access" ON profiles;
CREATE POLICY "Allow public access" ON profiles FOR ALL USING (true);

-- ৩. বাকি প্রয়োজনীয় টেবিলগুলো তৈরি করা (যদি না থাকে)
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT, category TEXT, price NUMERIC, stock NUMERIC, unit TEXT, barcode TEXT, username TEXT);
CREATE TABLE IF NOT EXISTS sales (id TEXT PRIMARY KEY, items JSONB, "totalPrice" NUMERIC, "amountPaid" NUMERIC, "dueAmount" NUMERIC, "customerName" TEXT, "customerPhone" TEXT, "paymentMethod" TEXT, date TIMESTAMPTZ, username TEXT);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, description TEXT, amount NUMERIC, category TEXT, date TIMESTAMPTZ, username TEXT);
CREATE TABLE IF NOT EXISTS wastage (id TEXT PRIMARY KEY, "productId" TEXT, "productName" TEXT, quantity NUMERIC, unit TEXT, "lossValue" NUMERIC, reason TEXT, date TIMESTAMPTZ, username TEXT);
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, name TEXT, designation TEXT, "monthlySalary" NUMERIC, "joinDate" TIMESTAMPTZ, username TEXT);
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, "staffId" TEXT, date TEXT, status TEXT, username TEXT);
CREATE TABLE IF NOT EXISTS daily_closings (id TEXT PRIMARY KEY, date TEXT, "totalSales" NUMERIC, "totalCashCollected" NUMERIC, "totalExpenses" NUMERIC, "totalWastage" NUMERIC, "systemBalance" NUMERIC, "actualCash" NUMERIC, difference NUMERIC, "closedBy" TEXT, timestamp TIMESTAMPTZ, username TEXT);
CREATE TABLE IF NOT EXISTS deductions (id TEXT PRIMARY KEY, "staffId" TEXT, amount NUMERIC, reason TEXT, date TIMESTAMPTZ, username TEXT);

-- সব টেবিলে পাবলিক এক্সেস দেওয়া (সহজ ব্যবহারের জন্য)
ALTER TABLE products ENABLE ROW LEVEL SECURITY; CREATE POLICY "p1" ON products FOR ALL USING (true);
ALTER TABLE sales ENABLE ROW LEVEL SECURITY; CREATE POLICY "p2" ON sales FOR ALL USING (true);
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY; CREATE POLICY "p3" ON expenses FOR ALL USING (true);
ALTER TABLE wastage ENABLE ROW LEVEL SECURITY; CREATE POLICY "p4" ON wastage FOR ALL USING (true);
ALTER TABLE staff ENABLE ROW LEVEL SECURITY; CREATE POLICY "p5" ON staff FOR ALL USING (true);
ALTER TABLE attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY "p6" ON attendance FOR ALL USING (true);
ALTER TABLE daily_closings ENABLE ROW LEVEL SECURITY; CREATE POLICY "p7" ON daily_closings FOR ALL USING (true);
ALTER TABLE deductions ENABLE ROW LEVEL SECURITY; CREATE POLICY "p8" ON deductions FOR ALL USING (true);
```

আমি নিচে `Login.tsx` আপডেট করে দিচ্ছি যাতে টেবিল মিসিং থাকলে আপনি সরাসরি সতর্কবার্তা পান।

