import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { UtensilsCrossed, Lock, Mail, UserPlus, LogIn, ChevronRight, AlertCircle, Loader2, User, HelpCircle, Copy, Check } from 'lucide-react';

interface Props {
  onLogin: (emailOrUsername: string) => void;
  theme: 'dark' | 'light';
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [dbError, setDbError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const fullSqlSetup = `CREATE TABLE IF NOT EXISTS profiles (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  username TEXT UNIQUE NOT NULL,
  password TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public access" ON profiles FOR ALL USING (true);`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(fullSqlSetup);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const validateEmail = (email: string) => {
    return String(email)
      .toLowerCase()
      .match(/^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setDbError(false);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedUsername = username.trim().toLowerCase();

    if (!validateEmail(normalizedEmail)) {
      setError('সঠিক ইমেইল অ্যাড্রেস দিন।');
      return;
    }

    if (isSignup && normalizedUsername.length < 3) {
      setError('ইউজারনেম অন্তত ৩ অক্ষরের হতে হবে।');
      return;
    }

    if (password.length < 6) {
      setError('পাসওয়ার্ড অন্তত ৬ অক্ষরের হতে হবে।');
      return;
    }

    setLoading(true);

    try {
      if (isSignup) {
        // Check if username is already taken
        const { data: existingUser, error: checkError } = await supabase
          .from('profiles')
          .select('username')
          .eq('username', normalizedUsername)
          .maybeSingle();

        if (checkError) {
           if (checkError.message.includes('profiles') || checkError.message.includes('column')) {
              setDbError(true);
              throw new Error('ডাটাবেস টেবিল বা কলাম খুঁজে পাওয়া যাচ্ছে না। অনুগ্রহ করে নিচের SQL রান করুন।');
           }
           throw checkError;
        }

        if (existingUser) {
          setError('এই ইউজারনেমটি ইতিমধ্যে ব্যবহার করা হয়েছে। অন্য একটি চেষ্টা করুন।');
          setLoading(false);
          return;
        }

        const { error: insError } = await supabase
          .from('profiles')
          .insert([{ 
            email: normalizedEmail, 
            username: normalizedUsername,
            password: password 
          }]);

        if (insError) {
          if (insError.message.includes('column') || insError.message.includes('relation')) {
            setDbError(true);
          }
          throw insError;
        }

        alert('রেজিস্ট্রেশন সফল হয়েছে! এখন লগইন করুন।');
        setIsSignup(false);
        setPassword('');
      } else {
        // Login Logic
        const { data: user, error: selError } = await supabase
          .from('profiles')
          .select('*')
          .eq('email', normalizedEmail)
          .eq('password', password)
          .maybeSingle();

        if (selError) {
          if (selError.message.includes('email') || selError.message.includes('profiles')) {
             setDbError(true);
             throw new Error('ডাটাবেসে "profiles" টেবিল বা "email" কলাম খুঁজে পাওয়া যায়নি।');
          }
          throw selError;
        }

        if (!user) {
          setError('ইমেইল অথবা পাসওয়ার্ড ভুল।');
        } else {
          onLogin(user.email);
        }
      }
    } catch (err: any) {
      console.error("Auth Error:", err);
      setError(err.message || 'সার্ভারে কানেক্ট করা যাচ্ছে না।');
    } finally {
      setLoading(false);
    }
  };

  const handleDemoMode = () => {
    if (window.confirm("আপনি কি ডেমো মোডে ঢুকতে চান? এটি করলে ডাটাবেস ছাড়াই আপনি অ্যাপটি দেখতে পারবেন।")) {
      onLogin('demo@bakery.com');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-orange-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-orange-500/10 rounded-full blur-[100px] pointer-events-none"></div>

