import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { UtensilsCrossed, Lock, Mail, UserPlus, LogIn, ChevronRight, AlertCircle, Loader2, User, HelpCircle, Copy, Check } from 'lucide-react';

interface Props {
  onLogin: (emailOrUsername: string) => void;
  theme: 'dark' | 'light';
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [dbError, setDbError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const fullSqlSetup = `-- ১. প্রোফাইল টেবিল
CREATE TABLE IF NOT EXISTS profiles (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, email TEXT UNIQUE NOT NULL, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
-- ২. পণ্য টেবিল
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT, category TEXT, price NUMERIC, stock NUMERIC, unit TEXT, barcode TEXT, username TEXT);
-- ৩. বিক্রয় টেবিল
CREATE TABLE IF NOT EXISTS sales (id TEXT PRIMARY KEY, items JSONB, "totalPrice" NUMERIC, "amountPaid" NUMERIC, "dueAmount" NUMERIC, "customerName" TEXT, "customerPhone" TEXT, "paymentMethod" TEXT, date TIMESTAMPTZ, username TEXT);
-- ৪. খরচ টেবিল
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, description TEXT, amount NUMERIC, category TEXT, date TIMESTAMPTZ, username TEXT);
-- ৫. নষ্ট মাল টেবিল
CREATE TABLE IF NOT EXISTS wastage (id TEXT PRIMARY KEY, "productId" TEXT, "productName" TEXT, quantity NUMERIC, unit TEXT, "lossValue" NUMERIC, reason TEXT, date TIMESTAMPTZ, username TEXT);
-- ৬. স্টাফ টেবিল
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, name TEXT, designation TEXT, "monthlySalary" NUMERIC, "joinDate" TIMESTAMPTZ, username TEXT);
-- ৭. হাজিরা টেবিল
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, "staffId" TEXT, date TEXT, status TEXT, username TEXT);
-- ৮. ক্লোজিং টেবিল
CREATE TABLE IF NOT EXISTS daily_closings (id TEXT PRIMARY KEY, date TEXT, "totalSales" NUMERIC, "totalCashCollected" NUMERIC, "totalExpenses" NUMERIC, "totalWastage" NUMERIC, "systemBalance" NUMERIC, "actualCash" NUMERIC, difference NUMERIC, "closedBy" TEXT, timestamp TIMESTAMPTZ, username TEXT);
-- ৯. সিকিউরিটি পলিসি (RLS)
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "p0" ON profiles FOR ALL USING (true);
ALTER TABLE products ENABLE ROW LEVEL SECURITY; CREATE POLICY "p1" ON products FOR ALL USING (true);
ALTER TABLE sales ENABLE ROW LEVEL SECURITY; CREATE POLICY "p2" ON sales FOR ALL USING (true);
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY; CREATE POLICY "p3" ON expenses FOR ALL USING (true);
ALTER TABLE wastage ENABLE ROW LEVEL SECURITY; CREATE POLICY "p4" ON wastage FOR ALL USING (true);
ALTER TABLE staff ENABLE ROW LEVEL SECURITY; CREATE POLICY "p5" ON staff FOR ALL USING (true);
ALTER TABLE attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY "p6" ON attendance FOR ALL USING (true);
ALTER TABLE daily_closings ENABLE ROW LEVEL SECURITY; CREATE POLICY "p7" ON daily_closings FOR ALL USING (true);`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(fullSqlSetup);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const validateEmail = (email: string) => {
    return String(email).toLowerCase().match(/^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setDbError(false);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedUsername = username.trim().toLowerCase();

    if (!validateEmail(normalizedEmail)) {
      setError('সঠিক ইমেইল অ্যাড্রেস দিন।');
      return;
    }

    if (password.length < 6) {
      setError('পাসওয়ার্ড অন্তত ৬ অক্ষরের হতে হবে।');
      return;
    }

    setLoading(true);

    try {
      if (isSignup) {
        const { data: existingUser, error: checkError } = await supabase.from('profiles').select('username').eq('username', normalizedUsername).maybeSingle();
        if (checkError) {
           if (checkError.message.includes('profiles') || checkError.message.includes('column')) {
              setDbError(true);
              throw new Error('ডাটাবেস টেবিল খুঁজে পাওয়া যাচ্ছে না। নিচের SQL রান করুন।');
           }
           throw checkError;
        }
        if (existingUser) {
          setError('এই ইউজারনেমটি ইতিমধ্যে ব্যবহার করা হয়েছে।');
          setLoading(false);
          return;
        }
        const { error: insError } = await supabase.from('profiles').insert([{ email: normalizedEmail, username: normalizedUsername, password: password }]);
        if (insError) { if (insError.message.includes('column') || insError.message.includes('relation')) setDbError(true); throw insError; }
        alert('রেজিস্ট্রেশন সফল হয়েছে!');
        setIsSignup(false);
      } else {
        const { data: user, error: selError } = await supabase.from('profiles').select('*').eq('email', normalizedEmail).eq('password', password).maybeSingle();
        if (selError) { if (selError.message.includes('email') || selError.message.includes('profiles')) setDbError(true); throw selError; }
        if (!user) setError('ইমেইল অথবা পাসওয়ার্ড ভুল।');
        else onLogin(user.email);
      }
    } catch (err: any) {
      setError(err.message || 'সার্ভারে কানেক্ট করা যাচ্ছে না।');
    } finally {
      setLoading(false);
    }
  };

  const handleDemoMode = () => {
    if (window.confirm("ডেমো মোডে ঢুকতে চান?")) onLogin('demo@bakery.com');
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-orange-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="mb-10 text-center flex flex-col items-center animate-in fade-in slide-in-from-top-4 duration-700">
        <div className="w-20 h-20 bg-white dark:bg-[#161d31] rounded-3xl flex items-center justify-center shadow-2xl mb-6 border border-slate-200 dark:border-slate-800 ring-4 ring-orange-500/10">
           <UtensilsCrossed size={40} className="text-orange-500" />
        </div>
        <h1 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">Sweet Live<br/><span className="text-orange-500">Bakery Manager</span></h1>
      </div>
      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[2.5rem] shadow-2xl p-8 md:p-12 border border-slate-200 dark:border-slate-800 relative overflow-hidden animate-in zoom-in duration-500">
          <div className="absolute top-0 left-0 w-full h-2 bg-orange-500"></div>
          <div className="flex justify-between items-center mb-10">
            <div><h2 className="text-2xl font-black text-slate-900 dark:text-white">{isSignup ? 'রেজিস্ট্রেশন' : 'স্বাগতম'}</h2><p className="text-slate-500 dark:text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">{isSignup ? 'নতুন অ্যাকাউন্ট খুলুন' : 'লগইন করে কাজ শুরু করুন'}</p></div>
            <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500 border border-orange-500/20">{isSignup ? <UserPlus size={28} /> : <LogIn size={28} />}</div>
          </div>
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1">ইমেইল</label>
              <div className="relative"><Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input required type="email" className="w-full pl-12 pr-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" value={email} onChange={e => setEmail(e.target.value)} /></div>
            </div>
            {isSignup && (
              <div className="space-y-2 animate-in slide-in-from-left-4 duration-300">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1">ইউজারনেম</label>
                <div className="relative"><User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input required type="text" className="w-full pl-12 pr-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" value={username} onChange={e => setUsername(e.target.value)} /></div>
              </div>
            )}
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] ml-1">পাসওয়ার্ড</label>
              <div className="relative"><Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input required type="password" title="password" className="w-full pl-12 pr-6 py-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent dark:border-slate-800 text-slate-900 dark:text-white outline-none focus:border-orange-500 transition-all font-medium" value={password} onChange={e => setPassword(e.target.value)} /></div>
            </div>
            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-4 rounded-xl text-xs font-bold flex flex-col gap-2">
