          </form>
          <div className="mt-10 flex flex-col items-center gap-4">
            <button onClick={() => { setIsSignup(!isSignup); setError(''); setDbError(false); }} className="text-slate-400 hover:text-orange-500 text-sm font-bold transition-colors underline underline-offset-4">{isSignup ? 'ইতিমধ্যে অ্যাকাউন্ট আছে? লগইন করুন' : "অ্যাকাউন্ট নেই? নতুন অ্যাকাউন্ট খুলুন"}</button>
