import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { supabaseService } from './services/supabaseService';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  Trash2,
  RefreshCw,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    try {
      const saved = localStorage.getItem('sweetBakery_theme');
      return (saved as 'dark' | 'light') || 'dark';
    } catch {
      return 'dark';
    }
  });

  const [isSyncing, setIsSyncing] = useState(false);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  useEffect(() => {
    const savedEmail = localStorage.getItem('sweetBakery_email');
    if (savedEmail) {
      setUserEmail(savedEmail.toLowerCase());
      setIsAuthenticated(true);
    } else {
      setIsDataLoaded(true); 
    }
  }, []);

  const fetchData = useCallback(async (email: string) => {
    if (!email) {
      setIsDataLoaded(true);
      return;
    }

    setIsSyncing(true);
    const safeFetch = async <T,>(tableName: string, fetchFn: () => Promise<T[]>) => {
      try {
        const data = await fetchFn();
        return data || [];
      } catch (err: any) {
        console.error(`Error fetching ${tableName}:`, err);
        return [] as T[];
      }
    };

    try {
      const results = await Promise.allSettled([
        safeFetch('products', () => supabaseService.getProducts(email)),
        safeFetch('sales', () => supabaseService.getSales(email)),
        safeFetch('expenses', () => supabaseService.getExpenses(email)),
        safeFetch('wastage', () => supabaseService.getWastage(email)),
        safeFetch('staff', () => supabaseService.getStaff(email)),
        safeFetch('attendance', () => supabaseService.getAttendance(email)),
        safeFetch('daily_closings', () => supabaseService.getClosings(email)),
        safeFetch('deductions', () => supabaseService.getDeductions(email))
      ]);

      const getData = (index: number) => {
        const res = results[index];
        return res.status === 'fulfilled' ? res.value : [];
      };

      setProducts(getData(0));
      setSales(getData(1));
      setExpenses(getData(2));
      setWastage(getData(3));
      setStaff(getData(4));
      setAttendance(getData(5));
      setDailyClosings(getData(6));
      setDeductions(getData(7));
    } catch (err: any) {
      console.error("Critical fetch error:", err);
    } finally {
      setIsDataLoaded(true);
      setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated && userEmail) {
      fetchData(userEmail);
    }
  }, [isAuthenticated, userEmail, fetchData]);

  const handleLogin = (email: string) => {
    const normalizedEmail = email.toLowerCase();
    setUserEmail(normalizedEmail);
    setIsAuthenticated(true);
    localStorage.setItem('sweetBakery_email', normalizedEmail);
  };

  const handleLogout = useCallback(() => {
    if (window.confirm("আপনি কি নিশ্চিত যে লগআউট করতে চান?")) {
      localStorage.removeItem('sweetBakery_email');
      window.location.reload();
    }
  }, []);

  const withSync = async (fn: () => Promise<void>) => {
    setIsSyncing(true);
    try {
      await fn();
      await fetchData(userEmail); 
    } catch (e: any) {
      alert(`ত্রুটি: ${e.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const addSale = (newSale: Sale) => {
    setSales(prev => [...prev, newSale]);
    withSync(async () => {
      await supabaseService.addSale(userEmail, newSale);
      for (const item of newSale.items) {
        const product = products.find(p => p.id === item.productId);
        if (product) {
          const updatedProduct = { ...product, stock: product.stock - item.quantity };
          await supabaseService.upsertProduct(userEmail, updatedProduct);
        }
      }
    });
  };

  const cancelSale = (saleId: string) => {
    if (!window.confirm("বিক্রয়টি বাতিল করতে চান?")) return;
    const sale = sales.find(s => s.id === saleId);
    withSync(async () => {
      await supabaseService.deleteSale(saleId);
      if (sale) {
        for (const item of sale.items) {
          const product = products.find(p => p.id === item.productId);
          if (product) {
            const updatedProduct = { ...product, stock: product.stock + item.quantity };
            await supabaseService.upsertProduct(userEmail, updatedProduct);
          }
        }
      }
    });
  };

  const addProduct = (product: Product) => withSync(async () => {
    await supabaseService.upsertProduct(userEmail, product);
  });

  const deleteProduct = (id: string) => {
    if (window.confirm("পণ্যটি মুছে ফেলতে চান?")) {
      withSync(async () => {
        await supabaseService.deleteProduct(id);
      });
    }
  };

  const addExpense = (expense: Expense) => withSync(async () => {
    await supabaseService.addExpense(userEmail, expense);
  });

  const markWastage = (w: Wastage) => {
    // Optimistic Update
    setWastage(prev => [...prev, w]);
    setProducts(prev => prev.map(p => p.id === w.productId ? { ...p, stock: p.stock - w.quantity } : p));

    withSync(async () => {
      await supabaseService.addWastage(userEmail, w);
      const product = products.find(p => p.id === w.productId);
      if (product) {
        await supabaseService.upsertProduct(userEmail, { ...product, stock: product.stock - w.quantity });
      }
    });
  };

  const deleteWastage = (id: string) => {
    if (window.confirm("নষ্ট মালের রেকর্ডটি মুছতে চান?")) {
      withSync(async () => {
        await supabaseService.deleteWastage(id);
      });
    }
  };

  const addStaff = (s: Staff) => withSync(async () => {
    await supabaseService.addStaff(userEmail, s);
  });

  const updateAttendance = (a: Attendance) => withSync(async () => {
    await supabaseService.upsertAttendance(userEmail, a);
  });

  const closeDay = (closing: DailyClosing) => withSync(async () => {
    await supabaseService.addClosing(userEmail, closing);
  });

  const deleteClosing = (id: string) => {
    if (window.confirm("ক্লোজিং রেকর্ডটি মুছতে চান?")) {
      withSync(async () => {
        await supabaseService.deleteClosing(id);
      });
    }
  };

  const updateBulkSales = (updatedSales: Sale[]) => {
    withSync(async () => {
      for (const sale of updatedSales) {
        await supabaseService.updateSale(sale);
      }
    });
  };

  const lowStockCount = useMemo(() => products.filter(p => p.stock < 10).length, [products]);

  if (!isAuthenticated) return <Login onLogin={handleLogin} theme={theme} />;

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white transition-all ${isMobileMenuOpen ? 'overflow-hidden' : ''}`}>
      {isMobileMenuOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />}
      <aside className={`w-72 bg-white dark:bg-[#0a1120] border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-transform duration-300 lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 pb-4 flex items-center justify-between">
          <div className="flex items-center gap-3"><div className="p-2 bg-orange-500 rounded-xl"><UtensilsCrossed size={24} className="text-white" /></div><div><h1 className="text-xl font-black text-slate-900 dark:text-white leading-tight">Sweet Live</h1><h1 className="text-xl font-black text-slate-900 dark:text-white leading-tight">Bakery</h1></div></div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden text-slate-400 p-2"><X size={24} /></button>
        </div>
        <nav className="flex-1 px-4 mt-6 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all ${currentView === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
              <span className={currentView === item.id ? 'text-white' : 'text-slate-400'}>{item.icon}</span>
              <div className="text-left flex-1"><p className="text-sm font-bold">{item.label}</p><p className="text-[10px] opacity-60">{item.bangla}</p></div>
              {item.notification > 0 && <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black">{item.notification}</span>}
            </button>
          ))}
        </nav>
        <div className="p-4 space-y-3"><div className="p-4 bg-[#161d31]/40 rounded-2xl border border-slate-800/50"><div className="text-[10px] font-black uppercase text-orange-400 mb-1">Bakery Status</div><div className="flex items-center gap-2"><span className="text-xs font-black text-white">v3.2.1</span><span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><span className="text-[10px] text-emerald-500 font-bold uppercase">Optimized</span></div><p className="text-[9px] text-slate-500 font-bold mt-1">User: <span className="capitalize">{userEmail.split('@')[0]}</span></p></div></div>
      </aside>
      <main className="lg:ml-72 flex-1 min-h-screen flex flex-col relative">
        {isSyncing && (
          <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-orange-500 text-white px-4 py-2 rounded-full shadow-lg text-[10px] font-black uppercase tracking-widest animate-pulse">
            <RefreshCw size={12} className="animate-spin" /> Syncing...
          </div>
        )}
        <header className="px-6 md:px-10 py-5 bg-white/80 dark:bg-dark-bg/80 backdrop-blur-xl sticky top-0 z-40 flex justify-between items-center border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-4"><button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl shadow-sm"><Menu size={22} className="text-orange-500" /></button><div><h2 className="text-2xl font-black uppercase tracking-tight text-slate-900 dark:text-white">{currentView.replace('_', ' ')}</h2></div></div>
          <div className="flex items-center gap-3"><button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-orange-500 shadow-sm transition-all active:scale-95">{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button><button onClick={handleLogout} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-red-500 shadow-sm hover:bg-red-50 dark:hover:bg-red-500/10 transition-all active:scale-95"><LogOut size={20} /></button></div>
        </header>
        <div className="p-4 md:p-10 flex-1">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center h-[60vh]"><div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div><p className="mt-6 font-black text-slate-400 animate-pulse uppercase text-xs tracking-[0.3em]">Loading Bakery Data...</p></div>
          ) : (
            <div className="animate-in fade-in duration-700">
              {currentView === View.DASHBOARD && <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} />}
              {currentView === View.INVENTORY && <Inventory products={products} onAdd={addProduct} onUpdate={addProduct} onDelete={deleteProduct} onMarkWastage={(p, qty, reason) => markWastage({ id: Date.now().toString(), productId: p.id, productName: p.name, quantity: qty, unit: p.unit, lossValue: p.price * qty, reason, date: new Date().toISOString() })} />}
              {currentView === View.SALES && <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={cancelSale} />}
              {currentView === View.DUES && <DuesView sales={sales} onUpdateSales={updateBulkSales} />}
              {currentView === View.WASTAGE && <WastageView wastage={wastage} products={products} onAdd={markWastage} onDelete={deleteWastage} closings={dailyClosings} />}
              {currentView === View.EXPENSES && <ExpensesView expenses={expenses} onAdd={addExpense} closings={dailyClosings} />}
              {currentView === View.DAILY_CLOSING && <DailyClosingView sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onCloseDay={closeDay} onDeleteClosing={deleteClosing} currentUser={userEmail} />}
              {currentView === View.STAFF && <StaffView staff={staff} attendance={attendance} expenses={expenses} deductions={deductions} onAddStaff={addStaff} onUpdateAttendance={updateAttendance} onAddDeduction={() => {}} onPaySalary={() => {}} />}
              {currentView === View.MANAGER && <ManagerView username={userEmail} onLogout={handleLogout} stats={{ products: products.length, sales: sales.length, expenses: expenses.length, staff: staff.length }} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Product, Sale, SaleItem } from '../types';
import { 
  ShoppingCart, 
  Trash,
  User,
  Phone,
  Wallet,
  X,
  Plus,
  Trash2,
  PackageCheck,
  BadgeAlert,
  CheckCircle
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale }) => {
  // Selection states
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');

  // Cart state for multi-item sales
  const [cart, setCart] = useState<SaleItem[]>([]);

  // Customer & Payment states
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  const selectedProduct = products.find(p => p.id === selectedProductId);

  const totalBill = useMemo(() => cart.reduce((acc, item) => acc + item.subTotal, 0), [cart]);
  const dueAmount = Math.max(0, totalBill - (Number(amountPaid) || 0));
  const hasDue = dueAmount > 0;

  // Add to cart logic
  const handleAddToCart = () => {
    if (!selectedProduct || !quantity || Number(quantity) <= 0) return;

    if (selectedProduct.stock < Number(quantity)) {
      alert("স্টকে পর্যাপ্ত মাল নেই!");
      return;
    }

    const existingItemIndex = cart.findIndex(item => item.productId === selectedProduct.id);

    if (existingItemIndex > -1) {
      const updatedCart = [...cart];
      const newQty = updatedCart[existingItemIndex].quantity + Number(quantity);

      if (selectedProduct.stock < newQty) {
        alert("স্টকে পর্যাপ্ত মাল নেই!");
        return;
      }

      updatedCart[existingItemIndex].quantity = newQty;
      updatedCart[existingItemIndex].subTotal = newQty * selectedProduct.price;
      setCart(updatedCart);
    } else {
      const newItem: SaleItem = {
        productId: selectedProduct.id,
        productName: selectedProduct.name,
        quantity: Number(quantity),
        unit: selectedProduct.unit,
        pricePerUnit: selectedProduct.price,
        subTotal: selectedProduct.price * Number(quantity)
      };
      setCart([...cart, newItem]);
    }

    setSelectedProductId('');
    setQuantity('');
  };

  const removeFromCart = (index: number) => {
    const updatedCart = cart.filter((_, i) => i !== index);
    setCart(updatedCart);
  };

  const handleSubmitSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) {
      alert("অন্তত একটি আইটেম যোগ করুন!");
      return;
    }

    if (hasDue && !customerName.trim()) {
      alert("বাকি থাকলে কাস্টমারের নাম দেওয়া আবশ্যিক!");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice: totalBill,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: dueAmount,
      customerName: customerName || 'Walk-in',
      customerPhone: customerPhone || '',
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);

    setCart([]);
    setAmountPaid('');
    setCustomerName('');
    setCustomerPhone('');
    alert("বিক্রয় সফল হয়েছে!");
  };

  const activeSessionSales = [...sales].reverse();

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in duration-500">

      <div className="lg:col-span-5 space-y-6">
        <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
          <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-3">
            <PackageCheck className="text-orange-500" size={24} /> Select Products
          </h3>
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase px-1">Product</label>
              <select className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 appearance-none cursor-pointer" value={selectedProductId} onChange={e => setSelectedProductId(e.target.value)}>
                <option value="">Choose a product...</option>
                {products.map(p => <option key={p.id} value={p.id}>{p.name} (Stock: {p.stock} {p.unit})</option>)}
              </select>
            </div>
            <div className="grid grid-cols-3 gap-4 items-end">
              <div className="col-span-2 space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase px-1">Quantity</label>
                <input type="number" className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500" value={quantity} onChange={e => setQuantity(e.target.value === '' ? '' : Number(e.target.value))} placeholder="0" />
              </div>
              <button type="button" onClick={handleAddToCart} disabled={!selectedProductId || !quantity} className="bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg shadow-emerald-500/20"><Plus size={20} /> Add</button>
            </div>
          </div>
        </div>

        <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
          <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-white flex items-center gap-3"><ShoppingCart className="text-orange-500" size={24} /> Cart List</h3><span className="bg-[#0a1120] text-orange-500 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-slate-800">{cart.length} Items</span></div>
          <div className="space-y-3 mb-8 max-h-[250px] overflow-y-auto custom-scrollbar pr-2">
            {cart.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center p-4 bg-[#0a1120] rounded-2xl border border-slate-800 group transition-all">
                <div className="flex-1"><div className="text-sm font-bold text-white">{item.productName}</div><div className="text-[10px] text-slate-500 font-bold uppercase">{item.quantity} {item.unit} × ৳{item.pricePerUnit}</div></div>
                <div className="text-right flex items-center gap-4"><div className="text-sm font-black text-white">৳{item.subTotal.toLocaleString()}</div><button onClick={() => removeFromCart(idx)} className="p-2 text-slate-500 hover:text-red-500 bg-[#161d31] rounded-lg border border-slate-800 transition-colors"><Trash2 size={14} /></button></div>
              </div>
            ))}
          </div>

          <form onSubmit={handleSubmitSale} className="space-y-6 border-t border-slate-800 pt-8">
            <div className="bg-[#0a1120] p-6 rounded-3xl border border-slate-800">
               <div className="flex justify-between items-center mb-6"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">TOTAL BILL</span><span className="text-3xl font-black text-white">৳{totalBill.toLocaleString()}</span></div>
               <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-400 uppercase px-1">AMOUNT PAID (নগদ গ্রহণ)</label>
                  <input type="number" className="w-full p-5 rounded-2xl bg-[#161d31] border-2 border-slate-800 focus:border-emerald-500 text-white text-3xl font-black outline-none transition-all" value={amountPaid} onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value))} placeholder="0" />
               </div>
