      <div className="lg:col-span-7 bg-[#161d31] rounded-[2rem] border border-slate-800 shadow-xl overflow-hidden min-h-[600px] flex flex-col">
        <div className="px-10 py-8 border-b border-slate-800 flex justify-between items-center"><h3 className="text-xl font-bold text-white flex items-center gap-3">Recent Sales</h3><span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Transaction History</span></div>
        <div className="flex-1 overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] uppercase text-slate-600 font-black tracking-widest border-b border-slate-800">
                <th className="px-8 py-5">Date</th>
                <th className="px-8 py-5">Customer (কাস্টমার)</th>
                <th className="px-8 py-5">Items</th>
                <th className="px-8 py-5">Total</th>
                <th className="px-8 py-5 text-right">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {activeSessionSales.map(sale => (
                <tr key={sale.id} className={`hover:bg-white/5 transition-colors ${sale.dueAmount > 0 ? 'bg-red-500/5' : ''}`}>
                  <td className="px-8 py-5 text-[10px] text-slate-500">{new Date(sale.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</td>
                  <td className="px-8 py-5">
                    <div className={`font-black text-sm ${sale.dueAmount > 0 ? 'text-orange-500' : 'text-white'}`}>
                      {sale.customerName || 'Walk-in'}
