import { supabase } from './supabaseClient';
import { Product, Sale, Expense, Wastage, Staff, Attendance, DailyClosing, Deduction } from '../types';

export const supabaseService = {
  // Authentication Helpers
  async trackLogout(email: string) {
    console.log(`User ${email} is logging out.`);
    return { success: true };
  },

  // Products
  async getProducts(email: string) {
    const { data, error } = await supabase.from('products').select('*').eq('username', email);
    if (error) throw error;
    return data as Product[];
  },
  async upsertProduct(email: string, product: Product) {
    const { error } = await supabase.from('products').upsert({ ...product, username: email });
    if (error) throw error;
  },
  async deleteProduct(id: string) {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) throw error;
  },

  // Sales
  async getSales(email: string) {
    const { data, error } = await supabase.from('sales').select('*').eq('username', email).order('date', { ascending: false });
    if (error) throw error;
    // Map database snake_case to JS camelCase
    return (data || []).map(s => ({
      ...s,
      totalPrice: s.total_price,
      amountPaid: s.amount_paid,
      dueAmount: s.due_amount,
      customerName: s.customer_name,
      customerPhone: s.customer_phone,
      paymentMethod: s.payment_method
    })) as unknown as Sale[];
  },
  async addSale(email: string, sale: Sale) {
    const dbSale = {
      id: sale.id,
      items: sale.items,
      total_price: sale.totalPrice,
      amount_paid: sale.amountPaid,
      due_amount: sale.dueAmount,
      customer_name: sale.customerName,
      customer_phone: sale.customerPhone,
      payment_method: sale.paymentMethod,
      date: sale.date,
      username: email
    };
    const { error } = await supabase.from('sales').insert(dbSale);
    if (error) throw error;
  },
  async updateSale(sale: Sale) {
    const dbSale = {
      total_price: sale.totalPrice,
      amount_paid: sale.amountPaid,
      due_amount: sale.dueAmount,
      customer_name: sale.customerName,
      customer_phone: sale.customerPhone,
    };
    const { error } = await supabase.from('sales').update(dbSale).eq('id', sale.id);
    if (error) throw error;
  },
  async deleteSale(id: string) {
    const { error } = await supabase.from('sales').delete().eq('id', id);
    if (error) throw error;
  },

  // Expenses
  async getExpenses(email: string) {
    const { data, error } = await supabase.from('expenses').select('*').eq('username', email);
    if (error) throw error;
    return data as Expense[];
  },
  async addExpense(email: string, expense: Expense) {
    const { error } = await supabase.from('expenses').insert({ ...expense, username: email });
    if (error) throw error;
  },

  // Wastage
  async getWastage(email: string) {
    const { data, error } = await supabase.from('wastage').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(w => ({
      ...w,
      productId: w.product_id,
      productName: w.product_name,
      lossValue: w.loss_value
    })) as unknown as Wastage[];
  },
  async addWastage(email: string, wastage: Wastage) {
    const dbWastage = {
      id: wastage.id,
      product_id: wastage.productId,
      product_name: wastage.productName,
      quantity: wastage.quantity,
      unit: wastage.unit,
      loss_value: wastage.lossValue,
      reason: wastage.reason,
      date: wastage.date,
      username: email
    };
    const { error } = await supabase.from('wastage').insert(dbWastage);
    if (error) throw error;
  },
  async deleteWastage(id: string) {
    const { error } = await supabase.from('wastage').delete().eq('id', id);
    if (error) throw error;
  },

  // Staff
  async getStaff(email: string) {
    const { data, error } = await supabase.from('staff').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(s => ({
      ...s,
      monthlySalary: s.monthly_salary,
      joinDate: s.join_date
    })) as unknown as Staff[];
  },
  async addStaff(email: string, staff: Staff) {
    const dbStaff = {
      id: staff.id,
      name: staff.name,
      designation: staff.designation,
      monthly_salary: staff.monthlySalary,
      join_date: staff.joinDate,
      username: email
    };
    const { error } = await supabase.from('staff').insert(dbStaff);
    if (error) throw error;
  },

  // Attendance
  async getAttendance(email: string) {
    const { data, error } = await supabase.from('attendance').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(a => ({
      ...a,
      staffId: a.staff_id
    })) as unknown as Attendance[];
  },
  async upsertAttendance(email: string, attendance: Attendance) {
    const dbAttendance = {
      id: attendance.id,
      staff_id: attendance.staffId,
      date: attendance.date,
      status: attendance.status,
      username: email
    };
    const { error } = await supabase.from('attendance').upsert(dbAttendance);
    if (error) throw error;
  },

  // Closings
  async getClosings(email: string) {
    const { data, error } = await supabase.from('daily_closings').select('*').eq('username', email).order('timestamp', { ascending: false });
    if (error) throw error;
    return (data || []).map(c => ({
      ...c,
      totalSales: c.total_sales,
      totalCashCollected: c.total_cash_collected,
      totalExpenses: c.total_expenses,
      totalWastage: c.total_wastage,
      systemBalance: c.system_balance,
      actualCash: c.actual_cash,
      closedBy: c.closed_by
    })) as unknown as DailyClosing[];
  },
  async addClosing(email: string, closing: any) {
    const { error } = await supabase.from('daily_closings').insert({ ...closing, username: email });
    if (error) throw error;
  },
  async deleteClosing(id: string) {
    const { error } = await supabase.from('daily_closings').delete().eq('id', id);
    if (error) throw error;
  },

  // Deductions
  async getDeductions(email: string) {
    const { data, error } = await supabase.from('deductions').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(d => ({
        ...d,
        staffId: d.staff_id
    })) as unknown as Deduction[];
  },
  async addDeduction(email: string, deduction: Deduction) {
    const dbDeduction = {
        id: deduction.id,
        staff_id: deduction.staffId,
        amount: deduction.amount,
        reason: deduction.reason,
        date: deduction.date,
        username: email
    };
    const { error } = await supabase.from('deductions').insert(dbDeduction);
    if (error) throw error;
  }
};

import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { UtensilsCrossed, Lock, Mail, UserPlus, LogIn, ChevronRight, AlertCircle, Loader2, User, HelpCircle, Copy, Check } from 'lucide-react';

interface Props {
  onLogin: (email: string) => void;
  theme: 'dark' | 'light';
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [dbError, setDbError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const fullSqlSetup = `-- ১. প্রোফাইল টেবিল
CREATE TABLE IF NOT EXISTS profiles (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, email TEXT UNIQUE NOT NULL, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
-- ২. পণ্য টেবিল
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT, category TEXT, price NUMERIC, stock NUMERIC, unit TEXT, barcode TEXT, username TEXT);
-- ৩. বিক্রয় টেবিল
CREATE TABLE IF NOT EXISTS sales (id TEXT PRIMARY KEY, items JSONB, total_price NUMERIC, amount_paid NUMERIC, due_amount NUMERIC, customer_name TEXT, customer_phone TEXT, payment_method TEXT, date TIMESTAMPTZ, username TEXT);
-- ৪. খরচ টেবিল
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, description TEXT, amount NUMERIC, category TEXT, date TIMESTAMPTZ, username TEXT);
-- ৫. নষ্ট মাল টেবিল
CREATE TABLE IF NOT EXISTS wastage (id TEXT PRIMARY KEY, product_id TEXT, product_name TEXT, quantity NUMERIC, unit TEXT, loss_value NUMERIC, reason TEXT, date TIMESTAMPTZ, username TEXT);
-- ৬. স্টাফ টেবিল
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, name TEXT, designation TEXT, monthly_salary NUMERIC, join_date TIMESTAMPTZ, username TEXT);
-- ৭. হাজিরা টেবিল
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, staff_id TEXT, date TEXT, status TEXT, username TEXT);
-- ৮. ক্লোজিং টেবিল
CREATE TABLE IF NOT EXISTS daily_closings (id TEXT PRIMARY KEY, date TEXT, total_sales NUMERIC, total_cash_collected NUMERIC, total_expenses NUMERIC, total_wastage NUMERIC, system_balance NUMERIC, actual_cash NUMERIC, difference NUMERIC, closed_by TEXT, timestamp TIMESTAMPTZ, username TEXT);
-- ৯. ডিডাকশন টেবিল
CREATE TABLE IF NOT EXISTS deductions (id TEXT PRIMARY KEY, staff_id TEXT, amount NUMERIC, reason TEXT, date TIMESTAMPTZ, username TEXT);
-- ১০. সিকিউরিটি পলিসি (RLS)
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "p0" ON profiles FOR ALL USING (true);
ALTER TABLE products ENABLE ROW LEVEL SECURITY; CREATE POLICY "p1" ON products FOR ALL USING (true);
ALTER TABLE sales ENABLE ROW LEVEL SECURITY; CREATE POLICY "p2" ON sales FOR ALL USING (true);
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY; CREATE POLICY "p3" ON expenses FOR ALL USING (true);
ALTER TABLE wastage ENABLE ROW LEVEL SECURITY; CREATE POLICY "p4" ON wastage FOR ALL USING (true);
ALTER TABLE staff ENABLE ROW LEVEL SECURITY; CREATE POLICY "p5" ON staff FOR ALL USING (true);
ALTER TABLE attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY "p6" ON attendance FOR ALL USING (true);
ALTER TABLE daily_closings ENABLE ROW LEVEL SECURITY; CREATE POLICY "p7" ON daily_closings FOR ALL USING (true);
ALTER TABLE deductions ENABLE ROW LEVEL SECURITY; CREATE POLICY "p8" ON deductions FOR ALL USING (true);`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(fullSqlSetup);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setDbError(false);
    setLoading(true);

    const cleanEmail = email.trim().toLowerCase();
    const cleanUsername = username.trim().toLowerCase();

    try {
      if (isSignup) {
        if (!cleanUsername) throw new Error("ইউজারনেম আবশ্যক");

        // রেজিস্ট্রেশন লজিক
        const { error: insError } = await supabase.from('profiles').insert([{ 
          email: cleanEmail, 
          username: cleanUsername, 
          password 
        }]);

        if (insError) {
          if (insError.message.includes('unique')) throw new Error("ইমেইল বা ইউজারনেম ইতিমধ্যে ব্যবহৃত হচ্ছে।");
          throw insError;
        }

        alert('অ্যাকাউন্ট সফলভাবে তৈরি হয়েছে! এখন লগইন করুন।');
        setIsSignup(false);
      } else {
        // লগইন লজিক
        const { data, error: selError } = await supabase.from('profiles')
          .select('*')
          .eq('email', cleanEmail)
          .eq('password', password)
          .maybeSingle();

        if (selError) throw selError;
        if (!data) setError('ভুল ইমেইল বা পাসওয়ার্ড।');
        else onLogin(data.email);
      }
    } catch (err: any) {
      setError(err.message);
      if (err.message.includes('relation') || err.message.includes('column')) setDbError(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a1120] flex flex-col items-center justify-center p-6 relative overflow-hidden">
      <div className="mb-10 text-center flex flex-col items-center">
        <div className="w-24 h-24 bg-white dark:bg-[#161d31] rounded-[2rem] flex items-center justify-center shadow-2xl mb-6 border border-slate-200 dark:border-slate-800">
           <UtensilsCrossed size={48} className="text-orange-500" />
        </div>
        <h1 className="text-4xl font-black text-slate-900 dark:text-white leading-tight">Sweet Live<br/><span className="text-orange-500">Bakery Manager</span></h1>
      </div>

      <div className="max-w-md w-full bg-white dark:bg-[#161d31] rounded-[3rem] shadow-2xl p-10 border border-slate-200 dark:border-slate-800 relative z-10">
          <div className="flex justify-center mb-8 bg-slate-100 dark:bg-[#0a1120] p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800">
            <button onClick={() => setIsSignup(false)} className={`flex-1 py-3 rounded-xl font-black text-xs uppercase tracking-widest transition-all ${!isSignup ? 'bg-white dark:bg-[#212a3e] text-orange-500 shadow-md' : 'text-slate-400'}`}>লগইন</button>
            <button onClick={() => setIsSignup(true)} className={`flex-1 py-3 rounded-xl font-black text-xs uppercase tracking-widest transition-all ${isSignup ? 'bg-white dark:bg-[#212a3e] text-orange-500 shadow-md' : 'text-slate-400'}`}>রেজিস্ট্রেশন</button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest flex items-center gap-2"><Mail size={12}/> ইমেইল এড্রেস</label>
              <input required type="email" className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent focus:border-orange-500 dark:border-slate-800 text-slate-900 dark:text-white outline-none transition-all" value={email} onChange={e => setEmail(e.target.value)} placeholder="example@email.com" />
            </div>

            {isSignup && (
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest flex items-center gap-2"><User size={12}/> ইউজারনেম (ইউনিক)</label>
                <input required type="text" className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent focus:border-orange-500 dark:border-slate-800 text-slate-900 dark:text-white outline-none transition-all" value={username} onChange={e => setUsername(e.target.value)} placeholder="shuvo_bakery" />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest flex items-center gap-2"><Lock size={12}/> পাসওয়ার্ড</label>
              <input required type="password" title="password" className="w-full p-4 rounded-2xl bg-slate-50 dark:bg-[#0a1120] border-2 border-transparent focus:border-orange-500 dark:border-slate-800 text-slate-900 dark:text-white outline-none transition-all" value={password} onChange={e => setPassword(e.target.value)} placeholder="••••••••" />
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 p-4 rounded-2xl text-xs font-bold animate-in shake duration-300">
                <div className="flex items-center gap-2 mb-1"><AlertCircle size={14}/> {error}</div>
                {dbError && (
                  <div className="mt-3 p-3 bg-black/20 rounded-xl overflow-hidden">
                    <div className="flex justify-between items-center mb-2">
                      <p className="text-red-600 uppercase font-black text-[9px]">SQL Table তৈরি করুন:</p>
                      <button type="button" onClick={copyToClipboard} className="text-[10px] bg-slate-800 hover:bg-slate-700 px-3 py-1 rounded-lg flex items-center gap-1 transition-colors">
                        {copied ? <Check size={10} /> : <Copy size={10} />} {copied ? 'Copied' : 'Copy SQL'}
                      </button>
                    </div>
                    <code className="block text-[8px] max-h-32 overflow-auto font-mono text-slate-400 custom-scrollbar">{fullSqlSetup}</code>
                  </div>
                )}
              </div>
            )}

            <button type="submit" disabled={loading} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-orange-500/20 transition-all disabled:opacity-70 flex items-center justify-center gap-3 text-lg active:scale-95">
              {loading ? <Loader2 className="animate-spin" size={20} /> : (isSignup ? 'অ্যাকাউন্ট তৈরি করুন' : 'লগইন করুন')}
              {!loading && <ChevronRight size={20} />}
            </button>
          </form>

          <div className="mt-8 pt-8 border-t border-slate-100 dark:border-slate-800/50 flex flex-col items-center gap-4">
             <button onClick={() => onLogin('demo@bakery.com')} className="text-[10px] font-black uppercase text-slate-400 hover:text-orange-500 tracking-[0.2em] transition-colors flex items-center gap-2"><HelpCircle size={14}/> ডেমো মোড ট্রাই করুন</button>
          </div>
      </div>

      {/* Background Decorative Circles */}
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-orange-500/5 rounded-full -translate-y-1/2 translate-x-1/2 blur-[100px]"></div>
      <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-orange-500/5 rounded-full translate-y-1/2 -translate-x-1/2 blur-[100px]"></div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Product, Sale, Expense, View, Staff, Attendance, DailyClosing, Deduction, Wastage } from './types';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import SalesView from './components/SalesView';
import ExpensesView from './components/ExpensesView';
import StaffView from './components/StaffView';
import ManagerView from './components/ManagerView';
import DailyClosingView from './components/DailyClosingView';
import DuesView from './components/DuesView';
import WastageView from './components/WastageView';
import Login from './components/Login';
import { supabaseService } from './services/supabaseService';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  ReceiptIndianRupee, 
  Users,
  UserCheck,
  Moon,
  Sun,
  UtensilsCrossed,
  Lock,
  Wallet,
  Menu,
  X,
  Trash2,
  RefreshCw,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState('');
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    try {
      const saved = localStorage.getItem('sweetBakery_theme');
      return (saved as 'dark' | 'light') || 'dark';
    } catch {
      return 'dark';
    }
  });

  const [isSyncing, setIsSyncing] = useState(false);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [wastage, setWastage] = useState<Wastage[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [attendance, setAttendance] = useState<Attendance[]>([]);
  const [dailyClosings, setDailyClosings] = useState<DailyClosing[]>([]);
  const [deductions, setDeductions] = useState<Deduction[]>([]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('sweetBakery_theme', theme);
  }, [theme]);

  useEffect(() => {
    const savedEmail = localStorage.getItem('sweetBakery_email');
    if (savedEmail) {
      setUserEmail(savedEmail.toLowerCase());
      setIsAuthenticated(true);
    } else {
      setIsDataLoaded(true); 
    }
  }, []);

  const fetchData = useCallback(async (email: string) => {
    if (!email) {
      setIsDataLoaded(true);
      return;
    }

    setIsSyncing(true);
    const safeFetch = async <T,>(tableName: string, fetchFn: () => Promise<T[]>) => {
      try {
        const data = await fetchFn();
        return data || [];
      } catch (err: any) {
        console.error(`Error fetching ${tableName}:`, err);
        return [] as T[];
      }
    };

    try {
      const results = await Promise.allSettled([
        safeFetch('products', () => supabaseService.getProducts(email)),
        safeFetch('sales', () => supabaseService.getSales(email)),
        safeFetch('expenses', () => supabaseService.getExpenses(email)),
        safeFetch('wastage', () => supabaseService.getWastage(email)),
        safeFetch('staff', () => supabaseService.getStaff(email)),
        safeFetch('attendance', () => supabaseService.getAttendance(email)),
        safeFetch('daily_closings', () => supabaseService.getClosings(email)),
        safeFetch('deductions', () => supabaseService.getDeductions(email))
      ]);

      const getData = (index: number) => {
        const res = results[index];
        return res.status === 'fulfilled' ? res.value : [];
      };

      setProducts(getData(0));
      setSales(getData(1));
      setExpenses(getData(2));
      setWastage(getData(3));
      setStaff(getData(4));
      setAttendance(getData(5));
      setDailyClosings(getData(6));
      setDeductions(getData(7));
    } catch (err: any) {
      console.error("Critical fetch error:", err);
    } finally {
      setIsDataLoaded(true);
      setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthenticated && userEmail) {
      fetchData(userEmail);
    }
  }, [isAuthenticated, userEmail, fetchData]);

  const handleLogin = (email: string) => {
    const normalizedEmail = email.toLowerCase();
    setUserEmail(normalizedEmail);
    setIsAuthenticated(true);
    localStorage.setItem('sweetBakery_email', normalizedEmail);
  };

  const handleLogout = useCallback(() => {
    if (window.confirm("আপনি কি নিশ্চিত যে লগআউট করতে চান?")) {
      localStorage.removeItem('sweetBakery_email');
      window.location.reload();
    }
  }, []);

  const withSync = async (fn: () => Promise<void>) => {
    setIsSyncing(true);
    try {
      await fn();
      // IMPORTANT: We do NOT re-fetch immediately here to avoid race conditions 
      // where the write hasn't indexed yet and fetch returns old data.
      // The optimistic UI update already keeps the session data fresh.
    } catch (e: any) {
      console.error("Sync error:", e);
      alert(`সার্ভারে তথ্য সেভ করতে সমস্যা হয়েছে: ${e.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const addSale = (newSale: Sale) => {
    // 1. Optimistic Updates for State
    setSales(prev => [...prev, newSale]);

    // Update local products immediately
    const updatedProducts = products.map(p => {
      const saleItem = newSale.items.find(item => item.productId === p.id);
      if (saleItem) {
        return { ...p, stock: p.stock - saleItem.quantity };
      }
      return p;
    });
    setProducts(updatedProducts);

    // 2. Background Sync
    withSync(async () => {
      await supabaseService.addSale(userEmail, newSale);
      for (const item of newSale.items) {
        const product = updatedProducts.find(p => p.id === item.productId);
        if (product) {
          await supabaseService.upsertProduct(userEmail, product);
        }
      }
    });
  };

  const cancelSale = (saleId: string) => {
    if (!window.confirm("বিক্রয়টি বাতিল করতে চান? এটি স্টকে পণ্য ফিরিয়ে দেবে।")) return;

    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;

    // Optimistic Update
    setSales(prev => prev.filter(s => s.id !== saleId));
    const updatedProducts = products.map(p => {
      const saleItem = sale.items.find(item => item.productId === p.id);
      if (saleItem) {
        return { ...p, stock: p.stock + saleItem.quantity };
      }
      return p;
    });
    setProducts(updatedProducts);

    withSync(async () => {
      await supabaseService.deleteSale(saleId);
      for (const item of sale.items) {
        const product = updatedProducts.find(p => p.id === item.productId);
        if (product) {
          await supabaseService.upsertProduct(userEmail, product);
        }
      }
    });
  };

  const addProduct = (product: Product) => {
    setProducts(prev => {
      const existing = prev.find(p => p.id === product.id);
      if (existing) return prev.map(p => p.id === product.id ? product : p);
      return [...prev, product];
    });
    withSync(async () => {
      await supabaseService.upsertProduct(userEmail, product);
    });
  };

  const deleteProduct = (id: string) => {
    if (window.confirm("পণ্যটি মুছে ফেলতে চান?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
      withSync(async () => {
        await supabaseService.deleteProduct(id);
      });
    }
  };

  const addExpense = (expense: Expense) => {
    setExpenses(prev => [...prev, expense]);
    withSync(async () => {
      await supabaseService.addExpense(userEmail, expense);
    });
  };

  const markWastage = (w: Wastage) => {
    setWastage(prev => [...prev, w]);
    const updatedProducts = products.map(p => p.id === w.productId ? { ...p, stock: p.stock - w.quantity } : p);
    setProducts(updatedProducts);

    withSync(async () => {
      await supabaseService.addWastage(userEmail, w);
      const product = updatedProducts.find(p => p.id === w.productId);
      if (product) {
        await supabaseService.upsertProduct(userEmail, product);
      }
    });
  };

  const deleteWastage = (id: string) => {
    if (window.confirm("নষ্ট মালের রেকর্ডটি মুছতে চান?")) {
      const record = wastage.find(w => w.id === id);
      setWastage(prev => prev.filter(w => w.id !== id));
      if (record) {
        const updatedProducts = products.map(p => p.id === record.productId ? { ...p, stock: p.stock + record.quantity } : p);
        setProducts(updatedProducts);
        withSync(async () => {
          await supabaseService.deleteWastage(id);
          const product = updatedProducts.find(p => p.id === record.productId);
          if (product) await supabaseService.upsertProduct(userEmail, product);
        });
      } else {
        withSync(async () => await supabaseService.deleteWastage(id));
      }
    }
  };

  const addStaff = (s: Staff) => {
    setStaff(prev => [...prev, s]);
    withSync(async () => {
      await supabaseService.addStaff(userEmail, s);
    });
  };

  const updateAttendance = (a: Attendance) => {
    setAttendance(prev => {
      const existingIdx = prev.findIndex(item => item.staffId === a.staffId && item.date === a.date);
      if (existingIdx > -1) {
        const newArr = [...prev];
        newArr[existingIdx] = a;
        return newArr;
      }
      return [...prev, a];
    });
    withSync(async () => {
      await supabaseService.upsertAttendance(userEmail, a);
    });
  };

  const addDeduction = (d: Deduction) => {
    setDeductions(prev => [...prev, d]);
    withSync(async () => {
      await supabaseService.addDeduction(userEmail, d);
    });
  };

  const paySalary = (staffId: string, amount: number) => {
    const staffMember = staff.find(s => s.id === staffId);
    if (!staffMember) return;
    const currentMonth = new Date().toLocaleString('default', { month: 'long' });
    const currentYear = new Date().getFullYear();
    const salaryExpense: Expense = {
      id: Date.now().toString(),
      description: `Salary Payment: ${staffMember.name} (${currentMonth} ${currentYear})`,
      amount: amount,
      category: 'Salary',
      date: new Date().toISOString()
    };
    addExpense(salaryExpense);
  };

  const closeDay = (closing: DailyClosing) => {
    setDailyClosings(prev => [...prev, closing]);
    withSync(async () => {
      await supabaseService.addClosing(userEmail, closing);
    });
  };

  const deleteClosing = (id: string) => {
    if (window.confirm("ক্লোজিং রেকর্ডটি মুছতে চান?")) {
      setDailyClosings(prev => prev.filter(c => c.id !== id));
      withSync(async () => {
        await supabaseService.deleteClosing(id);
      });
    }
  };

  const updateBulkSales = (updatedSales: Sale[]) => {
    const updatedSalesMap = new Map(updatedSales.map(s => [s.id, s]));
    setSales(prev => prev.map(s => updatedSalesMap.get(s.id) || s));
    withSync(async () => {
      for (const sale of updatedSales) {
        await supabaseService.updateSale(sale);
      }
    });
  };

  const lowStockCount = useMemo(() => products.filter(p => p.stock < 10).length, [products]);

  if (!isAuthenticated) return <Login onLogin={handleLogin} theme={theme} />;

  const navItems = [
    { id: View.DASHBOARD, label: 'Dashboard', icon: <LayoutDashboard size={20} />, bangla: 'ড্যাশবোর্ড' },
    { id: View.SALES, label: 'Sales', icon: <ShoppingCart size={20} />, bangla: 'বিক্রয়' },
    { id: View.DUES, label: 'Dues', icon: <Wallet size={20} />, bangla: 'বাকি' },
    { id: View.INVENTORY, label: 'Inventory', icon: <Package size={20} />, bangla: 'মজুদ', notification: lowStockCount },
    { id: View.WASTAGE, label: 'Wastage', icon: <Trash2 size={20} />, bangla: 'নষ্ট মাল' },
    { id: View.EXPENSES, label: 'Expenses', icon: <ReceiptIndianRupee size={20} />, bangla: 'খরচ' },
    { id: View.STAFF, label: 'Staff & Salary', icon: <Users size={20} />, bangla: 'হাজিরা ও বেতন' },
    { id: View.DAILY_CLOSING, label: 'Daily Closing', icon: <Lock size={20} />, bangla: 'ক্লোজিং' },
    { id: View.MANAGER, label: 'Manager Profile', icon: <UserCheck size={20} />, bangla: 'ম্যানেজার' },
  ];

  return (
    <div className={`min-h-screen flex bg-slate-50 dark:bg-dark-bg text-slate-900 dark:text-white transition-all ${isMobileMenuOpen ? 'overflow-hidden' : ''}`}>
      {isMobileMenuOpen && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />}
      <aside className={`w-72 bg-white dark:bg-[#0a1120] border-r border-slate-200 dark:border-slate-800 flex flex-col fixed h-full z-[70] transition-transform duration-300 lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 pb-4 flex items-center justify-between">
          <div className="flex items-center gap-3"><div className="p-2 bg-orange-500 rounded-xl"><UtensilsCrossed size={24} className="text-white" /></div><div><h1 className="text-xl font-black text-slate-900 dark:text-white leading-tight">Sweet Live</h1><h1 className="text-xl font-black text-slate-900 dark:text-white leading-tight">Bakery</h1></div></div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden text-slate-400 p-2"><X size={24} /></button>
        </div>
        <nav className="flex-1 px-4 mt-6 space-y-1 overflow-y-auto custom-scrollbar">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => { setCurrentView(item.id); setIsMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all ${currentView === item.id ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/20' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
              <span className={currentView === item.id ? 'text-white' : 'text-slate-400'}>{item.icon}</span>
              <div className="text-left flex-1"><p className="text-sm font-bold">{item.label}</p><p className="text-[10px] opacity-60">{item.bangla}</p></div>
              {item.notification > 0 && <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black">{item.notification}</span>}
            </button>
          ))}
        </nav>
        <div className="p-4 space-y-3"><div className="p-4 bg-[#161d31]/40 rounded-2xl border border-slate-800/50"><div className="text-[10px] font-black uppercase text-orange-400 mb-1">Bakery Status</div><div className="flex items-center gap-2"><span className="text-xs font-black text-white">v3.3.0</span><span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><span className="text-[10px] text-emerald-500 font-bold uppercase">Optimized</span></div><p className="text-[9px] text-slate-500 font-bold mt-1">User: <span className="capitalize">{userEmail.split('@')[0]}</span></p></div></div>
      </aside>
      <main className="lg:ml-72 flex-1 min-h-screen flex flex-col relative">
        {isSyncing && (
          <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-orange-500 text-white px-4 py-2 rounded-full shadow-lg text-[10px] font-black uppercase tracking-widest animate-pulse">
            <RefreshCw size={12} className="animate-spin" /> Syncing...
          </div>
        )}
        <header className="px-6 md:px-10 py-5 bg-white/80 dark:bg-dark-bg/80 backdrop-blur-xl sticky top-0 z-40 flex justify-between items-center border-b border-slate-200 dark:border-slate-800">
          <div className="flex items-center gap-4"><button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl shadow-sm"><Menu size={22} className="text-orange-500" /></button><div><h2 className="text-2xl font-black uppercase tracking-tight text-slate-900 dark:text-white">{currentView.replace('_', ' ')}</h2></div></div>
          <div className="flex items-center gap-3"><button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-orange-500 shadow-sm transition-all active:scale-95">{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button><button onClick={handleLogout} className="p-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-red-500 shadow-sm hover:bg-red-50 dark:hover:bg-red-500/10 transition-all active:scale-95"><LogOut size={20} /></button></div>
        </header>
        <div className="p-4 md:p-10 flex-1">
          {!isDataLoaded ? (
            <div className="flex flex-col items-center justify-center h-[60vh]"><div className="w-12 h-12 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div><p className="mt-6 font-black text-slate-400 animate-pulse uppercase text-xs tracking-[0.3em]">Loading Bakery Data...</p></div>
          ) : (
            <div className="animate-in fade-in duration-700">
              {currentView === View.DASHBOARD && <Dashboard products={products} sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} />}
              {currentView === View.INVENTORY && <Inventory products={products} onAdd={addProduct} onUpdate={addProduct} onDelete={deleteProduct} onMarkWastage={(p, qty, reason) => markWastage({ id: Date.now().toString(), productId: p.id, productName: p.name, quantity: qty, unit: p.unit, lossValue: p.price * qty, reason, date: new Date().toISOString() })} />}
              {currentView === View.SALES && <SalesView products={products} sales={sales} onAddSale={addSale} onCancelSale={cancelSale} />}
              {currentView === View.DUES && <DuesView sales={sales} onUpdateSales={updateBulkSales} />}
              {currentView === View.WASTAGE && <WastageView wastage={wastage} products={products} onAdd={markWastage} onDelete={deleteWastage} closings={dailyClosings} />}
              {currentView === View.EXPENSES && <ExpensesView expenses={expenses} onAdd={addExpense} closings={dailyClosings} />}
              {currentView === View.DAILY_CLOSING && <DailyClosingView sales={sales} expenses={expenses} wastage={wastage} closings={dailyClosings} onCloseDay={closeDay} onDeleteClosing={deleteClosing} currentUser={userEmail} />}
              {currentView === View.STAFF && <StaffView staff={staff} attendance={attendance} expenses={expenses} deductions={deductions} onAddStaff={addStaff} onUpdateAttendance={updateAttendance} onAddDeduction={addDeduction} onPaySalary={paySalary} />}
              {currentView === View.MANAGER && <ManagerView username={userEmail} onLogout={handleLogout} stats={{ products: products.length, sales: sales.length, expenses: expenses.length, staff: staff.length }} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import { supabase } from './supabaseClient';
import { Product, Sale, Expense, Wastage, Staff, Attendance, DailyClosing, Deduction } from '../types';

export const supabaseService = {
  // Authentication Helpers
  async getProfile(email: string) {
    const { data, error } = await supabase.from('profiles').select('*').eq('email', email).maybeSingle();
    if (error) throw error;
    return data;
  },

  async trackLogout(email: string) {
    console.log(`User ${email} is logging out.`);
    return { success: true };
  },

  // Products
  async getProducts(email: string) {
    const { data, error } = await supabase.from('products').select('*').eq('username', email);
    if (error) throw error;
    return data as Product[];
  },
  async upsertProduct(email: string, product: Product) {
    const { error } = await supabase.from('products').upsert({ ...product, username: email });
    if (error) throw error;
  },
  async deleteProduct(id: string) {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) throw error;
  },

  // Sales
  async getSales(email: string) {
    const { data, error } = await supabase.from('sales').select('*').eq('username', email).order('date', { ascending: false });
    if (error) throw error;
    // Map database snake_case to JS camelCase
    return (data || []).map(s => ({
      ...s,
      totalPrice: s.total_price,
      amountPaid: s.amount_paid,
      dueAmount: s.due_amount,
      customerName: s.customer_name,
      customerPhone: s.customer_phone,
      paymentMethod: s.payment_method
    })) as unknown as Sale[];
  },
  async addSale(email: string, sale: Sale) {
    const dbSale = {
      id: sale.id,
      items: sale.items,
      total_price: sale.totalPrice,
      amount_paid: sale.amountPaid,
      due_amount: sale.dueAmount,
      customer_name: sale.customerName,
      customer_phone: sale.customerPhone,
      payment_method: sale.paymentMethod,
      date: sale.date,
      username: email
    };
    const { error } = await supabase.from('sales').insert(dbSale);
    if (error) throw error;
  },
  async updateSale(sale: Sale) {
    const dbSale = {
      total_price: sale.totalPrice,
      amount_paid: sale.amountPaid,
      due_amount: sale.dueAmount,
      customer_name: sale.customerName,
      customer_phone: sale.customerPhone,
    };
    const { error } = await supabase.from('sales').update(dbSale).eq('id', sale.id);
    if (error) throw error;
  },
  async deleteSale(id: string) {
    const { error } = await supabase.from('sales').delete().eq('id', id);
    if (error) throw error;
  },

  // Expenses
  async getExpenses(email: string) {
    const { data, error } = await supabase.from('expenses').select('*').eq('username', email);
    if (error) throw error;
    return data as Expense[];
  },
  async addExpense(email: string, expense: Expense) {
    const { error } = await supabase.from('expenses').insert({ ...expense, username: email });
    if (error) throw error;
  },

  // Wastage
  async getWastage(email: string) {
    const { data, error } = await supabase.from('wastage').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(w => ({
      ...w,
      productId: w.product_id,
      productName: w.product_name,
      lossValue: w.loss_value
    })) as unknown as Wastage[];
  },
  async addWastage(email: string, wastage: Wastage) {
    const dbWastage = {
      id: wastage.id,
      product_id: wastage.productId,
      product_name: wastage.productName,
      quantity: wastage.quantity,
      unit: wastage.unit,
      loss_value: wastage.lossValue,
      reason: wastage.reason,
      date: wastage.date,
      username: email
    };
    const { error } = await supabase.from('wastage').insert(dbWastage);
    if (error) throw error;
  },
  async deleteWastage(id: string) {
    const { error } = await supabase.from('wastage').delete().eq('id', id);
    if (error) throw error;
  },

  // Staff
  async getStaff(email: string) {
    const { data, error } = await supabase.from('staff').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(s => ({
      ...s,
      monthlySalary: s.monthly_salary,
      joinDate: s.join_date
    })) as unknown as Staff[];
  },
  async addStaff(email: string, staff: Staff) {
    const dbStaff = {
      id: staff.id,
      name: staff.name,
      designation: staff.designation,
      monthly_salary: staff.monthlySalary,
      join_date: staff.joinDate,
      username: email
    };
    const { error } = await supabase.from('staff').insert(dbStaff);
    if (error) throw error;
  },

  // Attendance
  async getAttendance(email: string) {
    const { data, error } = await supabase.from('attendance').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(a => ({
      ...a,
      staffId: a.staff_id
    })) as unknown as Attendance[];
  },
  async upsertAttendance(email: string, attendance: Attendance) {
    const dbAttendance = {
      id: attendance.id,
      staff_id: attendance.staffId,
      date: attendance.date,
      status: attendance.status,
      username: email
    };
    const { error } = await supabase.from('attendance').upsert(dbAttendance);
    if (error) throw error;
  },

  // Closings
  async getClosings(email: string) {
    const { data, error } = await supabase.from('daily_closings').select('*').eq('username', email).order('timestamp', { ascending: false });
    if (error) throw error;
    return (data || []).map(c => ({
      ...c,
      totalSales: c.total_sales,
      totalCashCollected: c.total_cash_collected,
      totalExpenses: c.total_expenses,
      totalWastage: c.total_wastage,
      systemBalance: c.system_balance,
      actualCash: c.actual_cash,
      closedBy: c.closed_by
    })) as unknown as DailyClosing[];
  },
  async addClosing(email: string, closing: any) {
    const { error } = await supabase.from('daily_closings').insert({ ...closing, username: email });
    if (error) throw error;
  },
  async deleteClosing(id: string) {
    const { error } = await supabase.from('daily_closings').delete().eq('id', id);
    if (error) throw error;
  },

  // Deductions
  async getDeductions(email: string) {
    const { data, error } = await supabase.from('deductions').select('*').eq('username', email);
    if (error) throw error;
    return (data || []).map(d => ({
        ...d,
        staffId: d.staff_id
    })) as unknown as Deduction[];
  },
  async addDeduction(email: string, deduction: Deduction) {
    const dbDeduction = {
        id: deduction.id,
        staff_id: deduction.staffId,
        amount: deduction.amount,
        reason: deduction.reason,
        date: deduction.date,
        username: email
    };
    const { error } = await supabase.from('deductions').insert(dbDeduction);
    if (error) throw error;
  }
};

import React, { useState, useMemo } from 'react';
import { Product, Sale, SaleItem } from '../types';
import { 
  ShoppingCart, 
  Trash,
  User,
  Phone,
  Wallet,
  X,
  Plus,
  Trash2,
  PackageCheck,
  BadgeAlert,
  CheckCircle,
  FileDown
} from 'lucide-react';

interface Props {
  products: Product[];
  sales: Sale[];
  onAddSale: (sale: Sale) => void;
  onCancelSale: (saleId: string) => void;
}

const SalesView: React.FC<Props> = ({ products, sales, onAddSale, onCancelSale }) => {
  // Selection states
  const [selectedProductId, setSelectedProductId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');

  // Cart state for multi-item sales
  const [cart, setCart] = useState<SaleItem[]>([]);

  // Customer & Payment states
  const [amountPaid, setAmountPaid] = useState<number | ''>('');
  const [paymentMethod, setPaymentMethod] = useState<'Cash' | 'Mobile Payment'>('Cash');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  const selectedProduct = products.find(p => p.id === selectedProductId);

  const totalBill = useMemo(() => cart.reduce((acc, item) => acc + item.subTotal, 0), [cart]);
  const dueAmount = Math.max(0, totalBill - (Number(amountPaid) || 0));
  const hasDue = dueAmount > 0;

  const activeSessionSales = useMemo(() => [...sales].reverse(), [sales]);

  // Add to cart logic
  const handleAddToCart = () => {
    if (!selectedProduct || !quantity || Number(quantity) <= 0) return;

    if (selectedProduct.stock < Number(quantity)) {
      alert("স্টকে পর্যাপ্ত মাল নেই!");
      return;
    }

    const existingItemIndex = cart.findIndex(item => item.productId === selectedProduct.id);

    if (existingItemIndex > -1) {
      const updatedCart = [...cart];
      const newQty = updatedCart[existingItemIndex].quantity + Number(quantity);

      if (selectedProduct.stock < newQty) {
        alert("স্টকে পর্যাপ্ত মাল নেই!");
        return;
      }

      updatedCart[existingItemIndex].quantity = newQty;
      updatedCart[existingItemIndex].subTotal = newQty * selectedProduct.price;
      setCart(updatedCart);
    } else {
      const newItem: SaleItem = {
        productId: selectedProduct.id,
        productName: selectedProduct.name,
        quantity: Number(quantity),
        unit: selectedProduct.unit,
        pricePerUnit: selectedProduct.price,
        subTotal: selectedProduct.price * Number(quantity)
      };
      setCart([...cart, newItem]);
    }

    setSelectedProductId('');
    setQuantity('');
  };

  const removeFromCart = (index: number) => {
    const updatedCart = cart.filter((_, i) => i !== index);
    setCart(updatedCart);
  };

  const handleSubmitSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (cart.length === 0) {
      alert("অন্তত একটি আইটেম যোগ করুন!");
      return;
    }

    if (hasDue && !customerName.trim()) {
      alert("বাকি থাকলে কাস্টমারের নাম দেওয়া আবশ্যিক!");
      return;
    }

    const newSale: Sale = {
      id: Date.now().toString(),
      items: cart,
      totalPrice: totalBill,
      amountPaid: Number(amountPaid) || 0,
      dueAmount: dueAmount,
      customerName: customerName || 'Walk-in',
      customerPhone: customerPhone || '',
      paymentMethod,
      date: new Date().toISOString()
    };

    onAddSale(newSale);

    setCart([]);
    setAmountPaid('');
    setCustomerName('');
    setCustomerPhone('');
    alert("বিক্রয় সফল হয়েছে!");
  };

  const downloadSalesCSV = () => {
    if (activeSessionSales.length === 0) {
      alert("কোনো বিক্রয় রেকর্ড নেই ডাউনলোড করার জন্য।");
      return;
    }

    const headers = ["Date", "Time", "Customer", "Phone", "Items", "Total Price", "Amount Paid", "Due Amount"];
    const rows = activeSessionSales.map(sale => [
      new Date(sale.date).toLocaleDateString(),
      new Date(sale.date).toLocaleTimeString(),
      `"${sale.customerName || 'Walk-in'}"`,
      `"${sale.customerPhone || ''}"`,
      `"${sale.items.map(i => `${i.productName} (${i.quantity} ${i.unit})`).join('; ')}"`,
      sale.totalPrice,
      sale.amountPaid,
      sale.dueAmount
    ]);

    const csvContent = [
      headers.join(","),
      ...rows.map(row => row.join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `bakery_sales_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in duration-500">

      <div className="lg:col-span-5 space-y-6">
        <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
          <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-3">
            <PackageCheck className="text-orange-500" size={24} /> Select Products
          </h3>
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase px-1">Product</label>
              <select className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 appearance-none cursor-pointer" value={selectedProductId} onChange={e => setSelectedProductId(e.target.value)}>
                <option value="">Choose a product...</option>
                {products.map(p => <option key={p.id} value={p.id}>{p.name} (Stock: {p.stock} {p.unit})</option>)}
              </select>
            </div>
            <div className="grid grid-cols-3 gap-4 items-end">
              <div className="col-span-2 space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase px-1">Quantity</label>
                <input type="number" className="w-full p-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500" value={quantity} onChange={e => setQuantity(e.target.value === '' ? '' : Number(e.target.value))} placeholder="0" />
              </div>
              <button type="button" onClick={handleAddToCart} disabled={!selectedProductId || !quantity} className="bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 text-white font-black py-4 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg shadow-emerald-500/20"><Plus size={20} /> Add</button>
            </div>
          </div>
        </div>

        <div className="bg-[#161d31] p-8 rounded-[2rem] border border-slate-800 shadow-xl">
          <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold text-white flex items-center gap-3"><ShoppingCart className="text-orange-500" size={24} /> Cart List</h3><span className="bg-[#0a1120] text-orange-500 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-slate-800">{cart.length} Items</span></div>
          <div className="space-y-3 mb-8 max-h-[250px] overflow-y-auto custom-scrollbar pr-2">
            {cart.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center p-4 bg-[#0a1120] rounded-2xl border border-slate-800 group transition-all">
                <div className="flex-1"><div className="text-sm font-bold text-white">{item.productName}</div><div className="text-[10px] text-slate-500 font-bold uppercase">{item.quantity} {item.unit} × ৳{item.pricePerUnit}</div></div>
                <div className="text-right flex items-center gap-4"><div className="text-sm font-black text-white">৳{item.subTotal.toLocaleString()}</div><button onClick={() => removeFromCart(idx)} className="p-2 text-slate-500 hover:text-red-500 bg-[#161d31] rounded-lg border border-slate-800 transition-colors"><Trash2 size={14} /></button></div>
              </div>
            ))}
          </div>

          <form onSubmit={handleSubmitSale} className="space-y-6 border-t border-slate-800 pt-8">
            <div className="bg-[#0a1120] p-6 rounded-3xl border border-slate-800">
               <div className="flex justify-between items-center mb-6"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">TOTAL BILL</span><span className="text-3xl font-black text-white">৳{totalBill.toLocaleString()}</span></div>
               <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-400 uppercase px-1">AMOUNT PAID (নগদ গ্রহণ)</label>
                  <input type="number" className="w-full p-5 rounded-2xl bg-[#161d31] border-2 border-slate-800 focus:border-emerald-500 text-white text-3xl font-black outline-none transition-all" value={amountPaid} onChange={e => setAmountPaid(e.target.value === '' ? '' : Number(e.target.value)} placeholder="0" />
               </div>
               {hasDue && <div className="flex justify-between items-center mt-6 p-2 animate-pulse"><span className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2"><Wallet size={14} /> DUE (বাকি)</span><span className="text-2xl font-black text-red-500">৳{dueAmount.toLocaleString()}</span></div>}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className={`text-[10px] font-bold uppercase px-1 transition-colors ${hasDue ? 'text-red-500' : 'text-slate-400'}`}>
                  Customer Name {hasDue && '*'}
                </label>
                <div className="relative">
                  <User className={`absolute left-4 top-1/2 -translate-y-1/2 ${hasDue ? 'text-red-500' : 'text-slate-500'}`} size={16} />
                  <input type="text" className={`w-full pl-12 pr-4 py-4 rounded-xl bg-[#212a3e]/30 border text-white outline-none transition-all text-sm ${hasDue ? 'border-red-500/50 focus:border-red-500' : 'border-slate-800 focus:border-orange-500'}`} value={customerName} onChange={e => setCustomerName(e.target.value)} placeholder="e.g. Rohim" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase px-1">Phone Number</label>
                <div className="relative">
                  <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
                  <input type="tel" className="w-full pl-12 pr-4 py-4 rounded-xl bg-[#212a3e]/30 border border-slate-800 text-white outline-none focus:border-orange-500 transition-all text-sm" value={customerPhone} onChange={e => setCustomerPhone(e.target.value)} placeholder="017XXX" />
                </div>
              </div>
            </div>

            <button type="submit" disabled={cart.length === 0} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 text-lg disabled:opacity-50"><ShoppingCart size={24} /> Complete Sale</button>
          </form>
        </div>
      </div>

      <div className="lg:col-span-7 bg-[#161d31] rounded-[2rem] border border-slate-800 shadow-xl overflow-hidden min-h-[600px] flex flex-col">
        <div className="px-10 py-8 border-b border-slate-800 flex justify-between items-center">
          <h3 className="text-xl font-bold text-white flex items-center gap-3">Recent Sales</h3>
          <div className="flex items-center gap-3">
            <button 
              onClick={downloadSalesCSV}
              className="flex items-center gap-2 bg-white/5 hover:bg-white/10 text-orange-500 px-4 py-2 rounded-xl border border-slate-800 text-[10px] font-black uppercase tracking-widest transition-all active:scale-95"
            >
              <FileDown size={14} /> Export CSV
            </button>
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">History</span>
          </div>
        </div>
        <div className="flex-1 overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] uppercase text-slate-600 font-black tracking-widest border-b border-slate-800">
                <th className="px-8 py-5">Date</th>
                <th className="px-8 py-5">Customer (কাস্টমার)</th>
                <th className="px-8 py-5">Items</th>
                <th className="px-8 py-5">Total</th>
                <th className="px-8 py-5 text-right">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {activeSessionSales.map(sale => (
                <tr key={sale.id} className={`hover:bg-white/5 transition-colors ${sale.dueAmount > 0 ? 'bg-red-500/5' : ''}`}>
                  <td className="px-8 py-5 text-[10px] text-slate-500">{new Date(sale.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</td>
                  <td className="px-8 py-5">
                    <div className={`font-black text-sm ${sale.dueAmount > 0 ? 'text-orange-500' : 'text-white'}`}>
                      {sale.customerName || 'Walk-in'}
                    </div>
                    {sale.customerPhone && <div className="text-[9px] text-slate-500">{sale.customerPhone}</div>}
                  </td>
                  <td className="px-8 py-5">
                    <div className="text-[11px] text-slate-300 font-medium">
                      {sale.items.length} Items
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="font-black text-xs text-white">৳{sale.totalPrice.toLocaleString()}</div>
                    <div className="text-[9px] text-emerald-500">Paid: ৳{sale.amountPaid.toLocaleString()}</div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    {sale.dueAmount > 0 ? (
                      <div className="inline-flex items-center gap-1.5 bg-red-500/10 text-red-500 px-3 py-1 rounded-full border border-red-500/20 font-black text-[9px] uppercase tracking-widest">
                        <BadgeAlert size={12} /> Due: ৳{sale.dueAmount}
                      </div>
                    ) : (
                      <div className="inline-flex items-center gap-1.5 bg-emerald-500/10 text-emerald-500 px-3 py-1 rounded-full border border-emerald-500/20 font-black text-[9px] uppercase tracking-widest">
                        <CheckCircle size={12} /> Paid
                      </div>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

